module decoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic         decoder_data_valid_in, // Input data valid signal
    input  logic [65:0]  decoder_data_in,     // 66-bit encoded input
    output logic [63:0]  decoder_data_out,    // Decoded 64-bit data output
    output logic [7:0]   decoder_control_out, // Decoded 8-bit control output
    output logic         sync_error,          // Sync error flag
    output logic         decoder_error_out    // Type field error flag
);

    logic [1:0] sync_header;
    logic [7:0] type_field;
    logic [63:0] data_in;
    logic type_field_valid;
    logic decoder_wrong_ctrl_received;
    logic decoder_wrong_type_field;

    assign sync_header = decoder_data_in[65:64];
    assign type_field  = decoder_data_in[63:56];
    assign data_in     = decoder_data_in[55:0];

    // Control character encodings
    localparam logic [7:0] CH_I = 8'h07; // /I/ Idle
    localparam logic [7:0] CH_S = 8'hFB; // /S/ Start of Frame
    localparam logic [7:0] CH_T = 8'hFD; // /T/ End of Frame
    localparam logic [7:0] CH_E = 8'hFE; // /E/ Error
    localparam logic [7:0] CH_Q = 8'h9C; // /Q/ Ordered Set

    // Data bytes D6..D0 extracted from the 56-bit payload
    logic [7:0] D0, D1, D2, D3, D4, D5, D6;
    assign D0 = data_in[7:0];
    assign D1 = data_in[15:8];
    assign D2 = data_in[23:16];
    assign D3 = data_in[31:24];
    assign D4 = data_in[39:32];
    assign D5 = data_in[47:40];
    assign D6 = data_in[55:48];

    // Combinational decode for control/mixed mode
    logic [63:0] ctrl_data;
    logic [7:0]  ctrl_out;
    logic        tf_valid;

    always_comb begin
        tf_valid  = 1'b1;
        ctrl_out  = 8'h00;
        ctrl_data = 64'h0;
        case (type_field)
            8'h1E: begin ctrl_out = 8'b11111111; ctrl_data = {CH_E, CH_E, CH_E, CH_E, CH_E, CH_E, CH_E, CH_E}; end
            8'h33: begin ctrl_out = 8'b00011111; ctrl_data = {D6, D5, D4, CH_S, CH_I, CH_I, CH_I, CH_I}; end
            8'h78: begin ctrl_out = 8'b00000001; ctrl_data = {D6, D5, D4, D3, D2, D1, D0, CH_S}; end
            8'h87: begin ctrl_out = 8'b11111110; ctrl_data = {CH_I, CH_I, CH_I, CH_I, CH_I, CH_I, CH_I, CH_T}; end
            8'h99: begin ctrl_out = 8'b11111110; ctrl_data = {CH_I, CH_I, CH_I, CH_I, CH_I, CH_I, CH_T, D0}; end
            8'hAA: begin ctrl_out = 8'b11111100; ctrl_data = {CH_I, CH_I, CH_I, CH_I, CH_I, CH_T, D1, D0}; end
            8'hB4: begin ctrl_out = 8'b11111000; ctrl_data = {CH_I, CH_I, CH_I, CH_I, CH_T, D2, D1, D0}; end
            8'hCC: begin ctrl_out = 8'b11110000; ctrl_data = {CH_I, CH_I, CH_I, CH_T, D3, D2, D1, D0}; end
            8'hD2: begin ctrl_out = 8'b11100000; ctrl_data = {CH_I, CH_I, CH_T, D4, D3, D2, D1, D0}; end
            8'hE1: begin ctrl_out = 8'b11000000; ctrl_data = {CH_I, CH_T, D5, D4, D3, D2, D1, D0}; end
            8'hFF: begin ctrl_out = 8'b10000000; ctrl_data = {CH_T, D6, D5, D4, D3, D2, D1, D0}; end
            8'h2D: begin ctrl_out = 8'b00011111; ctrl_data = {D6, D5, D4, CH_Q, CH_I, CH_I, CH_I, CH_I}; end
            8'h4B: begin ctrl_out = 8'b11110001; ctrl_data = {CH_I, CH_I, CH_I, CH_I, D2, D1, D0, CH_Q}; end
            8'h55: begin ctrl_out = 8'b00010001; ctrl_data = {D6, D5, D4, CH_Q, D2, D1, D0, CH_Q}; end
            8'h66: begin ctrl_out = 8'b00010001; ctrl_data = {D6, D5, D4, CH_S, D2, D1, D0, CH_Q}; end
            default: begin tf_valid = 1'b0; ctrl_out = 8'h00; ctrl_data = 64'h0; end
        endcase
    end

    assign type_field_valid            = tf_valid;
    assign decoder_wrong_type_field    = ~tf_valid;
    assign decoder_wrong_ctrl_received = 1'b0;

    // Registered outputs (1-cycle latency), asynchronous active-high reset
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            decoder_data_out    <= 64'd0;
            decoder_control_out <= 8'd0;
            sync_error          <= 1'b0;
            decoder_error_out   <= 1'b0;
        end else begin
            decoder_data_out    <= 64'd0;
            decoder_control_out <= 8'd0;
            sync_error          <= 1'b0;
            decoder_error_out   <= 1'b0;
            if (decoder_data_valid_in) begin
                case (sync_header)
                    2'b01: begin // Data-only mode
                        decoder_data_out    <= decoder_data_in[63:0];
                        decoder_control_out <= 8'd0;
                    end
                    2'b10: begin // Control-only or mixed mode
                        if (type_field_valid) begin
                            decoder_data_out    <= ctrl_data;
                            decoder_control_out <= ctrl_out;
                        end else begin
                            decoder_error_out   <= 1'b1;
                        end
                    end
                    default: begin // Invalid sync header
                        sync_error <= 1'b1;
                    end
                endcase
            end
        end
    end

endmodule

module APBGlobalHistoryRegister (
    input  wire        pclk,
    input  wire        presetn,
    input  wire [9:0]  paddr,
    input  wire        pselx,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [7:0]  pwdata,
    output reg         pready,
    output reg  [7:0]  prdata,
    output reg         pslverr,
    input  wire        history_shift_valid,
    input  wire        clk_gate_en,
    output wire        history_full,
    output wire        history_empty,
    output wire        error_flag,
    output wire        interrupt_full,
    output wire        interrupt_error
);

    // -----------------------------------------------------------------
    // Glitch-free clock gating: latch the enable on the negedge of pclk
    // then AND it (inverted) with pclk. Assertion of clk_gate_en gates
    // (stops) the internal clock.
    // -----------------------------------------------------------------
    reg clk_gate_en_lat;
    always @(negedge pclk or negedge presetn) begin
        if (!presetn)
            clk_gate_en_lat <= 1'b0;
        else
            clk_gate_en_lat <= clk_gate_en;
    end
    wire gated_pclk = pclk & ~clk_gate_en_lat;

    // -----------------------------------------------------------------
    // CSR registers
    // -----------------------------------------------------------------
    reg [7:0] control_register; // 0x0 : [0]=predict_valid [1]=predict_taken
                                //       [2]=train_mispredicted [3]=train_taken
                                //       [7:4] reserved (read 0)
    reg [7:0] train_history;    // 0x1 : [6:0]=history, [7] reserved (read 0)
    reg [7:0] predict_history;  // 0x2 : shift register (read-only over APB)

    // -----------------------------------------------------------------
    // APB access + CSR update (gated clock domain)
    // -----------------------------------------------------------------
    always @(posedge gated_pclk or negedge presetn) begin
        if (!presetn) begin
            pready           <= 1'b0;
            pslverr          <= 1'b0;
            prdata           <= 8'b0;
            control_register <= 8'b0;
            train_history    <= 8'b0;
        end else begin
            // No wait states: pready always high; pslverr defaults low.
            pready  <= 1'b1;
            pslverr <= 1'b0;

            if (pselx && penable) begin   // qualified APB access phase
                if (pwrite) begin
                    case (paddr)
                        10'h0: control_register <= {4'b0, pwdata[3:0]};
                        10'h1: train_history    <= {1'b0, pwdata[6:0]};
                        10'h2: ; // predict_history is read-only: ignore writes
                        default: pslverr <= 1'b1; // invalid address
                    endcase
                end else begin
                    case (paddr)
                        10'h0: prdata <= control_register;      // reserved already 0
                        10'h1: prdata <= train_history;         // reserved already 0
                        10'h2: prdata <= predict_history;
                        default: begin
                            prdata  <= 8'b0;
                            pslverr <= 1'b1;                    // invalid address
                        end
                    endcase
                end
            end
        end
    end

    // -----------------------------------------------------------------
    // Prediction history shift register.  history_shift_valid acts as a
    // clock (checker drives it as an edge).  Misprediction has strict
    // priority over the normal LSB shift-in.
    // -----------------------------------------------------------------
    always @(posedge history_shift_valid or negedge presetn) begin
        if (!presetn) begin
            predict_history <= 8'b0;
        end else begin
            if (control_register[2]) begin
                // Misprediction: restore {train_history[6:0], train_taken}
                predict_history <= {train_history[6:0], control_register[3]};
            end else if (control_register[0]) begin
                // Normal update: shift predict_taken into the LSB
                predict_history <= {predict_history[6:0], control_register[1]};
            end
        end
    end

    // -----------------------------------------------------------------
    // Status / interrupt outputs
    // -----------------------------------------------------------------
    assign history_full    = (predict_history == 8'hFF);
    assign history_empty   = (predict_history == 8'h00);
    assign error_flag      = pslverr;
    assign interrupt_full  = history_full;
    assign interrupt_error = error_flag;

endmodule

module axi_alu (
    input  wire        axi_clk_in,
    input  wire        fast_clk_in,
    input  wire        reset_in,

    // AXI Interface
    input  wire        axi_awvalid_i,
    input  wire        axi_wvalid_i,
    input  wire        axi_bready_i,
    input  wire        axi_arvalid_i,
    input  wire        axi_rready_i,

    output wire        axi_awready_o,
    output wire        axi_wready_o,
    output wire        axi_bvalid_o,
    output wire        axi_arready_o,
    output wire        axi_rvalid_o,

    input  wire [31:0] axi_awaddr_i,
    input  wire [31:0] axi_wdata_i,
    input  wire [31:0] axi_araddr_i,

    input  wire [3:0]  axi_wstrb_i,
    output wire [31:0] axi_rdata_o,

    // Added AXI burst / response signals
    input  wire [7:0]  axi_awlen_i,
    input  wire [2:0]  axi_awsize_i,
    input  wire [1:0]  axi_awburst_i,
    input  wire        axi_wlast_i,
    input  wire [7:0]  axi_arlen_i,
    input  wire [2:0]  axi_arsize_i,
    input  wire [1:0]  axi_arburst_i,
    output wire        axi_rlast_o,
    output wire [1:0]  axi_rresp_o,
    output wire [1:0]  axi_bresp_o,

    output wire [63:0] result_o
);

    wire        clk;
    wire [31:0] operand_a, operand_b, operand_c;
    wire [1:0]  op_select;
    wire        start, clock_control;
    wire [31:0] data_a;
    wire [31:0] data_b;
    wire [31:0] data_c;
    wire [63:0] dsp_result;

    wire [31:0] operand_a_cdc, operand_b_cdc, operand_c_cdc;
    wire [1:0]  op_select_cdc;
    wire        start_cdc;
    wire [31:0] operand_a_sync, operand_b_sync, operand_c_sync;
    wire [1:0]  op_select_sync;
    wire        start_sync;

    // RAM interface between the CSR block and the memory block
    wire        ram_we;
    wire [3:0]  ram_waddr;
    wire [31:0] ram_wdata;
    wire [3:0]  ram_raddr_axi;
    wire [31:0] ram_rdata_axi;
    wire [31:0] result_address;

    // DSP result synchronized back into the AXI clock domain when required
    wire [63:0] dsp_result_sync;
    wire [63:0] dsp_result_csr = clock_control ? dsp_result_sync : dsp_result;

    clock_control u_clock_control (
        .axi_clk_in  (axi_clk_in),
        .fast_clk_in (fast_clk_in),
        .clk_ctrl    (clock_control),
        .clk         (clk)
    );

    axi_csr_block u_axi_csr_block (
        .axi_aclk_i    (axi_clk_in),
        .axi_areset_i  (reset_in),
        .axi_awvalid_i (axi_awvalid_i),
        .axi_awready_o (axi_awready_o),
        .axi_awaddr_i  (axi_awaddr_i),
        .axi_awlen_i   (axi_awlen_i),
        .axi_awsize_i  (axi_awsize_i),
        .axi_awburst_i (axi_awburst_i),
        .axi_wvalid_i  (axi_wvalid_i),
        .axi_wready_o  (axi_wready_o),
        .axi_wdata_i   (axi_wdata_i),
        .axi_wstrb_i   (axi_wstrb_i),
        .axi_wlast_i   (axi_wlast_i),
        .axi_bvalid_o  (axi_bvalid_o),
        .axi_bready_i  (axi_bready_i),
        .axi_bresp_o   (axi_bresp_o),
        .axi_arvalid_i (axi_arvalid_i),
        .axi_arready_o (axi_arready_o),
        .axi_araddr_i  (axi_araddr_i),
        .axi_arlen_i   (axi_arlen_i),
        .axi_arsize_i  (axi_arsize_i),
        .axi_arburst_i (axi_arburst_i),
        .axi_rvalid_o  (axi_rvalid_o),
        .axi_rready_i  (axi_rready_i),
        .axi_rdata_o   (axi_rdata_o),
        .axi_rlast_o   (axi_rlast_o),
        .axi_rresp_o   (axi_rresp_o),
        .operand_a     (operand_a_cdc),
        .operand_b     (operand_b_cdc),
        .operand_c     (operand_c_cdc),
        .op_select     (op_select_cdc),
        .start         (start_cdc),
        .clock_control (clock_control),
        .ram_we_o      (ram_we),
        .ram_waddr_o   (ram_waddr),
        .ram_wdata_o   (ram_wdata),
        .ram_raddr_o   (ram_raddr_axi),
        .ram_rdata_i   (ram_rdata_axi),
        .dsp_result_i  (dsp_result_csr),
        .result_address(result_address)
    );

    // CDC selection: synchronized values only when fast clock is selected
    assign operand_a = (clock_control) ? operand_a_sync : operand_a_cdc;
    assign operand_b = (clock_control) ? operand_b_sync : operand_b_cdc;
    assign operand_c = (clock_control) ? operand_c_sync : operand_c_cdc;
    assign op_select = (clock_control) ? op_select_sync : op_select_cdc;
    assign start     = (clock_control) ? start_sync     : start_cdc;

    // CSR -> DSP CDC synchronizers (double flop into destination clk domain)
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_a (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_a_cdc), .data_out(operand_a_sync));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_b (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_b_cdc), .data_out(operand_b_sync));
    cdc_synchronizer #(.WIDTH(32)) u_cdc_operand_c (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(operand_c_cdc), .data_out(operand_c_sync));
    cdc_synchronizer #(.WIDTH(2))  u_cdc_op_select (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(op_select_cdc), .data_out(op_select_sync));
    cdc_synchronizer #(.WIDTH(1))  u_cdc_start     (.clk_src(axi_clk_in), .clk_dst(clk), .reset_in(reset_in), .data_in(start_cdc),     .data_out(start_sync));

    // DSP -> CSR CDC synchronizer (result back into AXI clk domain)
    cdc_synchronizer #(.WIDTH(64)) u_cdc_result    (.clk_src(clk), .clk_dst(axi_clk_in), .reset_in(reset_in), .data_in(dsp_result), .data_out(dsp_result_sync));

    memory_block u_memory_block (
        .axi_clk        (axi_clk_in),
        .ctrld_clk      (clk),
        .reset_in       (reset_in),
        .we             (ram_we),
        .write_address  (ram_waddr),
        .write_data     (ram_wdata),
        .address_a      (operand_a[5:0]),
        .address_b      (operand_b[5:0]),
        .address_c      (operand_c[5:0]),
        .axi_raddr      (ram_raddr_axi),
        .axi_rdata      (ram_rdata_axi),
        .data_a         (data_a),
        .data_b         (data_b),
        .data_c         (data_c),
        .result_address (result_address)
    );

    dsp_block u_dsp_block (
        .clk        (clk),
        .reset_in   (reset_in),
        .operand_a  (data_a),
        .operand_b  (data_b),
        .operand_c  (data_c),
        .op_select  (op_select),
        .start      (start),
        .result     (dsp_result)
    );

    assign result_o = dsp_result;

endmodule

// ------------------------------------------------------------------
// CDC Synchronizer Module (Double Flop Synchronization)
// ------------------------------------------------------------------
module cdc_synchronizer #(parameter WIDTH = 1) (
    input wire clk_src,  // Source clock (unused: sampling done in dst domain)
    input wire clk_dst,  // Destination clock
    input wire reset_in, // Reset signal
    input wire [WIDTH-1:0] data_in,  // Data from source domain
    output reg [WIDTH-1:0] data_out  // Synchronized data in destination domain
);
    reg [WIDTH-1:0] data_sync_1, data_sync_2;

    always @(posedge clk_dst or posedge reset_in) begin
        if (reset_in) begin
            data_sync_1 <= {WIDTH{1'b0}};
            data_sync_2 <= {WIDTH{1'b0}};
            data_out    <= {WIDTH{1'b0}};
        end else begin
            data_sync_1 <= data_in;
            data_sync_2 <= data_sync_1;
            data_out    <= data_sync_2;
        end
    end
endmodule

// ------------------------------------------------------------------
// Clock Control Module
// ------------------------------------------------------------------
module clock_control (
    input  wire axi_clk_in,
    input  wire fast_clk_in,
    input  wire clk_ctrl,
    output wire clk
);
    assign clk = clk_ctrl ? fast_clk_in : axi_clk_in;
endmodule

// ------------------------------------------------------------------
// AXI-to-CSR Register Block (with burst support + RAM + result readback)
// ------------------------------------------------------------------
module axi_csr_block (
    input  wire        axi_aclk_i,
    input  wire        axi_areset_i,

    // AXI Write Address Channel
    input  wire        axi_awvalid_i,
    output reg         axi_awready_o,
    input  wire [31:0] axi_awaddr_i,
    input  wire [7:0]  axi_awlen_i,
    input  wire [2:0]  axi_awsize_i,
    input  wire [1:0]  axi_awburst_i,

    // AXI Write Data Channel
    input  wire        axi_wvalid_i,
    output reg         axi_wready_o,
    input  wire [31:0] axi_wdata_i,
    input  wire [3:0]  axi_wstrb_i,
    input  wire        axi_wlast_i,

    // AXI Write Response Channel
    output reg         axi_bvalid_o,
    input  wire        axi_bready_i,
    output reg  [1:0]  axi_bresp_o,

    // AXI Read Address Channel
    input  wire        axi_arvalid_i,
    output reg         axi_arready_o,
    input  wire [31:0] axi_araddr_i,
    input  wire [7:0]  axi_arlen_i,
    input  wire [2:0]  axi_arsize_i,
    input  wire [1:0]  axi_arburst_i,

    // AXI Read Data Channel
    output reg         axi_rvalid_o,
    input  wire        axi_rready_i,
    output reg  [31:0] axi_rdata_o,
    output reg         axi_rlast_o,
    output reg  [1:0]  axi_rresp_o,

    // CSR Outputs
    output reg  [31:0] operand_a,
    output reg  [31:0] operand_b,
    output reg  [31:0] operand_c,
    output reg  [1:0]  op_select,
    output reg         start,
    output reg         clock_control,

    // RAM write port
    output reg         ram_we_o,
    output reg  [3:0]  ram_waddr_o,
    output reg  [31:0] ram_wdata_o,

    // RAM read-back port (combinational read from memory block)
    output reg  [3:0]  ram_raddr_o,
    input  wire [31:0] ram_rdata_i,

    // DSP result to store / read back
    input  wire [63:0] dsp_result_i,
    input  wire [31:0] result_address
);
    localparam [1:0] W_IDLE = 2'd0, W_ADDR = 2'd1, W_DATA = 2'd2, W_RESP = 2'd3;
    localparam [1:0] R_IDLE = 2'd0, R_DATA = 2'd1;

    reg [1:0]  wstate;
    reg [1:0]  rstate;
    reg [31:0] waddr;         // running write byte-address
    reg [31:0] raddr;         // running read byte-address
    reg [7:0]  rbeats;        // remaining read beats
    reg [31:0] result_reg;    // captured DSP result (low 32 bits) for readback

    // Config registers
    reg [31:0] csr_reg [0:4];

    // Decode helpers (combinational): is this a memory data register?
    wire        wr_is_mem = (waddr >= 32'h20) && (waddr <= 32'h5C);
    wire [3:0]  wr_mem_idx = waddr[5:2] - 4'd8;         // (addr-0x20)>>2

    always @(posedge axi_aclk_i or posedge axi_areset_i) begin
        if (axi_areset_i) begin
            wstate        <= W_IDLE;
            rstate        <= R_IDLE;
            waddr         <= 32'd0;
            raddr         <= 32'd0;
            rbeats        <= 8'd0;
            result_reg    <= 32'd0;
            axi_awready_o <= 1'b0;
            axi_wready_o  <= 1'b0;
            axi_bvalid_o  <= 1'b0;
            axi_bresp_o   <= 2'b00;
            axi_arready_o <= 1'b0;
            axi_rvalid_o  <= 1'b0;
            axi_rdata_o   <= 32'd0;
            axi_rlast_o   <= 1'b0;
            axi_rresp_o   <= 2'b00;
            operand_a     <= 32'd0;
            operand_b     <= 32'd0;
            operand_c     <= 32'd0;
            op_select     <= 2'd0;
            start         <= 1'b0;
            clock_control <= 1'b0;
            ram_we_o      <= 1'b0;
            ram_waddr_o   <= 4'd0;
            ram_wdata_o   <= 32'd0;
            ram_raddr_o   <= 4'd0;
            csr_reg[0]    <= 32'd0;
            csr_reg[1]    <= 32'd0;
            csr_reg[2]    <= 32'd0;
            csr_reg[3]    <= 32'd0;
            csr_reg[4]    <= 32'd0;
        end else begin
            // Defaults for pulsed signals
            ram_we_o <= 1'b0;

            // Capture DSP result for readback
            result_reg <= dsp_result_i[31:0];

            // ---------------- Write channel FSM ----------------
            case (wstate)
                W_IDLE: begin
                    axi_bvalid_o <= 1'b0;
                    if (axi_awvalid_i) begin
                        axi_awready_o <= 1'b1;
                        waddr         <= axi_awaddr_i;
                        wstate        <= W_DATA;
                        axi_wready_o  <= 1'b1;
                    end
                end
                W_DATA: begin
                    axi_awready_o <= 1'b0;
                    axi_wready_o  <= 1'b1;
                    if (axi_wvalid_i) begin
                        // write to config or RAM based on running address
                        if (wr_is_mem) begin
                            ram_we_o    <= 1'b1;
                            ram_waddr_o <= wr_mem_idx;
                            ram_wdata_o <= axi_wdata_i;
                        end else begin
                            csr_reg[waddr[4:2]] <= axi_wdata_i;
                        end
                        // INCR burst: advance address by 4 each beat
                        waddr <= waddr + 32'd4;
                        if (axi_wlast_i) begin
                            axi_wready_o <= 1'b0;
                            axi_bvalid_o <= 1'b1;
                            axi_bresp_o  <= 2'b00; // OKAY
                            wstate       <= W_RESP;
                        end
                    end
                end
                W_RESP: begin
                    if (axi_bvalid_o && axi_bready_i) begin
                        axi_bvalid_o <= 1'b0;
                        wstate       <= W_IDLE;
                    end
                end
                default: wstate <= W_IDLE;
            endcase

            // ---------------- Read channel FSM ----------------
            case (rstate)
                R_IDLE: begin
                    axi_rvalid_o <= 1'b0;
                    axi_rlast_o  <= 1'b0;
                    if (axi_arvalid_i) begin
                        axi_arready_o <= 1'b1;
                        raddr         <= axi_araddr_i;
                        rbeats        <= axi_arlen_i;
                        ram_raddr_o   <= axi_araddr_i[5:2] - 4'd8;
                        rstate        <= R_DATA;
                    end
                end
                R_DATA: begin
                    axi_arready_o <= 1'b0;
                    axi_rvalid_o  <= 1'b1;
                    axi_rresp_o   <= 2'b00;
                    ram_raddr_o   <= raddr[5:2] - 4'd8;
                    if ((raddr >= 32'h20) && (raddr <= 32'h5C))
                        axi_rdata_o <= ram_rdata_i;
                    else
                        axi_rdata_o <= csr_reg[raddr[4:2]];
                    axi_rlast_o <= (rbeats == 8'd0);
                    if (axi_rready_i) begin
                        if (rbeats == 8'd0) begin
                            axi_rvalid_o <= 1'b0;
                            axi_rlast_o  <= 1'b0;
                            rstate       <= R_IDLE;
                        end else begin
                            rbeats <= rbeats - 8'd1;
                            raddr  <= raddr + 32'd4;
                        end
                    end
                end
                default: rstate <= R_IDLE;
            endcase

            // ---------------- CSR outputs ----------------
            operand_a     <= csr_reg[0];
            operand_b     <= csr_reg[1];
            operand_c     <= csr_reg[2];
            op_select     <= csr_reg[3][1:0];
            start         <= csr_reg[3][2];
            clock_control <= csr_reg[4][0];
        end
    end
endmodule

// ------------------------------------------------------------------
// Memory Block (RAM : 16 x 32-bit)
// ------------------------------------------------------------------
module memory_block (
    input  wire        axi_clk,
    input  wire        ctrld_clk,
    input  wire        reset_in,
    // synchronous write (AXI clock domain)
    input  wire        we,
    input  wire [3:0]  write_address,
    input  wire [31:0] write_data,
    // operand reads (asynchronous)
    input  wire [5:0]  address_a,
    input  wire [5:0]  address_b,
    input  wire [5:0]  address_c,
    // AXI read-back (asynchronous)
    input  wire [3:0]  axi_raddr,
    output wire [31:0] axi_rdata,
    output wire [31:0] data_a,
    output wire [31:0] data_b,
    output wire [31:0] data_c,
    output reg  [31:0] result_address
);
    reg [31:0] ram [0:15];
    integer i;

    always @(posedge axi_clk or posedge reset_in) begin
        if (reset_in) begin
            for (i = 0; i < 16; i = i + 1)
                ram[i] <= 32'd0;
            result_address <= 32'd0;
        end else begin
            if (we)
                ram[write_address] <= write_data;
            result_address <= ram[0];
        end
    end

    // Asynchronous reads
    assign data_a    = (reset_in) ? 32'd0 : ram[address_a[3:0]];
    assign data_b    = (reset_in) ? 32'd0 : ram[address_b[3:0]];
    assign data_c    = (reset_in) ? 32'd0 : ram[address_c[3:0]];
    assign axi_rdata = ram[axi_raddr];
endmodule

// ------------------------------------------------------------------
// DSP Processing Block
// ------------------------------------------------------------------
module dsp_block (
    input  wire        clk,
    input  wire        reset_in,
    input  wire [31:0] operand_a,
    input  wire [31:0] operand_b,
    input  wire [31:0] operand_c,
    input  wire [1:0]  op_select,
    input  wire        start,
    output reg  [63:0] result
);
    always @(posedge clk or posedge reset_in) begin
        if (reset_in)
            result <= 64'd0;
        else begin
            if (start) begin
                case (op_select)
                    2'b00: result <= (operand_a + operand_b) * operand_c;    // MAC
                    2'b01: result <= operand_a * operand_b;                  // Multiplication
                    2'b10: result <= operand_a >> operand_b[4:0];            // Shift Right
                    2'b11: result <= operand_b ? operand_a / operand_b : 64'hDEADDEAD; // Division
                endcase
            end
        end
    end
endmodule

module bus_arbiter (
    input wire reset,
    input wire clk,
    input wire req1,
    input wire req2,
    output reg grant1,
    output reg grant2
);
    // State encoding using localparam
    localparam IDLE    = 3'b000,
               GRANT_1 = 3'b001,
               GRANT_2 = 3'b010,
               CLEAR   = 3'b011;

    // State registers
    reg [2:0] state;
    reg [2:0] next_state;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        // Default assignments
        next_state = state;

        case (state)
            IDLE: begin
                if (req2)      next_state = GRANT_2; // req2 has priority
                else if (req1) next_state = GRANT_1;
                else           next_state = IDLE;
            end
            GRANT_1: begin
                if (req2)       next_state = GRANT_2; // req2 preempts req1
                else if (!req1) next_state = CLEAR;   // req1 deasserted
                else            next_state = GRANT_1;
            end
            GRANT_2: begin
                if (req2)       next_state = GRANT_2; // hold while req2 asserted
                else            next_state = CLEAR;   // req2 deasserted
            end
            CLEAR: begin
                if (req2)      next_state = GRANT_2;
                else if (req1) next_state = GRANT_1;
                else           next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            grant1 <= 1'b0;
            grant2 <= 1'b0;
        end else begin
            grant1 <= (next_state == GRANT_1);
            grant2 <= (next_state == GRANT_2);
        end
    end

endmodule

module cont_adder #(
  parameter DATA_WIDTH = 32,
  parameter signed THRESHOLD_VALUE_1 = 50,
  parameter signed THRESHOLD_VALUE_2 = 100,
  parameter signed THRESHOLD_VALUE_3 = 150,
  parameter ACCUM_MODE = 0,
  parameter WEIGHT = 1,
  parameter signed SAT_MAX = (2**(DATA_WIDTH-1))-1,
  parameter signed SAT_MIN = -(2**(DATA_WIDTH-1))
) (
  input  logic                         clk,
  input  logic                         reset,
  input  logic                         accum_clear,
  input  logic                         enable,
  input  logic signed [DATA_WIDTH-1:0] data_in,
  input  logic                         data_valid,
  input  logic [15:0]                  window_size,
  output logic signed [DATA_WIDTH-1:0] sum_out,
  output logic signed [DATA_WIDTH-1:0] avg_out,
  output logic                         threshold_1,
  output logic                         threshold_2,
  output logic                         threshold_3,
  output logic                         sum_ready,
  output logic                         busy
);

  typedef enum logic [1:0] {IDLE, ACCUM, DONE} state_t;
  state_t state;
  logic signed [DATA_WIDTH-1:0] sum_accum;
  logic [15:0] sample_count;
  logic signed [DATA_WIDTH-1:0] weighted_in_reg;
  logic signed [DATA_WIDTH-1:0] sat_sum;

  logic signed [DATA_WIDTH-1:0] add_result;
  assign add_result = sum_accum + weighted_in_reg;

  localparam signed MIN_THRESH =
      (THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_2)
        ? ((THRESHOLD_VALUE_1 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_1 : THRESHOLD_VALUE_3)
        : ((THRESHOLD_VALUE_2 <= THRESHOLD_VALUE_3) ? THRESHOLD_VALUE_2 : THRESHOLD_VALUE_3);

  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      weighted_in_reg <= 0;
    else if (enable && data_valid)
      weighted_in_reg <= (WEIGHT == 1) ? data_in : data_in * WEIGHT;
  end

  always_ff @(posedge clk or posedge reset) begin
    if (reset)
      sat_sum <= 0;
    else if (enable && data_valid)
      sat_sum <= add_result;
  end

  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (accum_clear) begin
      state <= IDLE;
      sum_accum <= 0;
      sample_count <= 0;
    end else if (enable && data_valid) begin
      case (state)
        IDLE: begin
          state <= ACCUM;
          sum_accum <= sat_sum;
          sample_count <= 1;
        end
        ACCUM: begin
          sum_accum <= sat_sum;
          sample_count <= sample_count + 1;
          if (ACCUM_MODE == 1) begin
            if ((sample_count + 1) >= window_size)
              state <= DONE;
          end else begin
            if ((sat_sum >= MIN_THRESH) || (sat_sum <= -MIN_THRESH))
              state <= DONE;
          end
        end
        DONE: begin
          state <= IDLE;
          sum_accum <= 0;
          sample_count <= 0;
        end
        default: state <= IDLE;
      endcase
    end
  end

  always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
      sum_out <= 0;
      avg_out <= 0;
      sum_ready <= 0;
      threshold_1 <= 0;
      threshold_2 <= 0;
      threshold_3 <= 0;
      busy <= 0;
    end else begin
      busy <= (state == ACCUM);
      if (state == DONE) begin
        sum_out <= sum_accum;
        avg_out <= (ACCUM_MODE == 1) ? (sum_accum / sample_count) : 0;
        sum_ready <= 1;
        threshold_1 <= (sum_accum >= THRESHOLD_VALUE_1) || (sum_accum <= -THRESHOLD_VALUE_1);
        threshold_2 <= (sum_accum >= THRESHOLD_VALUE_2) || (sum_accum <= -THRESHOLD_VALUE_2);
        threshold_3 <= (sum_accum >= THRESHOLD_VALUE_3) || (sum_accum <= -THRESHOLD_VALUE_3);
      end else begin
        sum_out <= 0;
        avg_out <= 0;
        sum_ready <= 0;
        threshold_1 <= 0;
        threshold_2 <= 0;
        threshold_3 <= 0;
      end
    end
  end

endmodule

module divider #
(
    parameter WIDTH = 32
)
(
    input  wire                  clk,
    input  wire                  rst_n,      // Active-low asynchronous reset
    input  wire                  start,      // Start signal for new operation
    input  wire [WIDTH-1 : 0]    dividend,   // Dividend (numerator)
    input  wire [WIDTH-1 : 0]    divisor,    // Divisor (denominator)
    output wire [WIDTH-1 : 0]    quotient,   // Result of the division
    output wire [WIDTH-1 : 0]    remainder,  // Remainder after division
    output wire                  valid       // Indicates output is valid
);

    localparam AW = WIDTH + 1;
    // Simple 3-state FSM
    localparam IDLE = 2'b00;
    localparam BUSY = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state_reg, state_next;

    // A+Q combined into one WIDTH + 1 + WIDTH register:
    reg [AW+WIDTH-1 : 0] aq_reg,   aq_next;

    // Divisor register
    reg [AW-1 : 0]       m_reg,    m_next;

    // Iterate exactly WIDTH times
    reg [$clog2(WIDTH)-1:0] n_reg, n_next;

    // Final outputs
    reg [WIDTH-1:0] quotient_reg, quotient_next;
    reg [WIDTH-1:0] remainder_reg, remainder_next;
    reg valid_reg, valid_next;

    // Assign the top-level outputs
    assign quotient  = quotient_reg;
    assign remainder = remainder_reg;
    assign valid     = valid_reg;

    // Combinational helpers (one non-restoring iteration)
    reg [AW+WIDTH-1:0] aq_shift;   // shifted A:Q
    reg [AW-1:0]       a_shifted;  // A part after shift-left
    reg [AW-1:0]       a_op;       // A after add/sub
    reg [AW-1:0]       a_final;    // A after end-of-loop correction
    reg [WIDTH-1:0]    q_part;     // Q part after shift-left
    reg                sign_pre;   // sign of A BEFORE the shift

    always @(*) begin
        // defaults: hold state
        state_next     = state_reg;
        aq_next        = aq_reg;
        m_next         = m_reg;
        n_next         = n_reg;
        quotient_next  = quotient_reg;
        remainder_next = remainder_reg;
        valid_next     = valid_reg;

        // non-restoring iteration datapath (only meaningful in BUSY)
        sign_pre  = aq_reg[AW+WIDTH-1];              // MSB of A = sign
        aq_shift  = aq_reg << 1;                     // shift A:Q left by 1
        a_shifted = aq_shift[AW+WIDTH-1 -: AW];      // top AW bits -> A
        q_part    = aq_shift[WIDTH-1:0];             // low WIDTH bits -> Q
        // A<0 -> add M ; A>=0 -> subtract M
        a_op      = sign_pre ? (a_shifted + m_reg) : (a_shifted - m_reg);
        a_final   = a_op;

        case (state_reg)
            IDLE: begin
                valid_next = 1'b0;
                if (start) begin
                    // load: A=0, Q=dividend ; M={0,divisor} ; N=WIDTH
                    aq_next        = { {AW{1'b0}}, dividend };
                    m_next         = { 1'b0, divisor };
                    n_next         = WIDTH - 1;
                    quotient_next  = {WIDTH{1'b0}};
                    remainder_next = {WIDTH{1'b0}};
                    state_next     = BUSY;
                end
            end

            BUSY: begin
                // Q[0] = ~sign(A_new)
                q_part[0] = ~a_op[AW-1];
                aq_next   = {a_op, q_part};

                if (n_reg == {$clog2(WIDTH){1'b0}}) begin
                    // last of exactly WIDTH iterations: mandatory correction
                    if (a_op[AW-1])
                        a_final = a_op + m_reg;
                    quotient_next  = q_part;
                    remainder_next = a_final[WIDTH-1:0];
                    state_next     = DONE;
                    valid_next     = 1'b1;
                end
                else begin
                    n_next = n_reg - 1'b1;
                end
            end

            DONE: begin
                valid_next = 1'b1;
                if (!start) begin
                    state_next = IDLE;
                    valid_next = 1'b0;
                end
            end

            default: state_next = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg     <= IDLE;
            aq_reg        <= {(AW+WIDTH){1'b0}};
            m_reg         <= {AW{1'b0}};
            n_reg         <= {$clog2(WIDTH){1'b0}};
            quotient_reg  <= {WIDTH{1'b0}};
            remainder_reg <= {WIDTH{1'b0}};
            valid_reg     <= 1'b0;
        end
        else begin
            state_reg     <= state_next;
            aq_reg        <= aq_next;
            m_reg         <= m_next;
            n_reg         <= n_next;
            quotient_reg  <= quotient_next;
            remainder_reg <= remainder_next;
            valid_reg     <= valid_next;
        end
    end

endmodule

module interrupt_controller (
    input wire clk,
    input wire rst_n,
    input wire reset_interrupts,
    input wire [9:0] interrupt_requests,
    input wire interrupt_ack,
  	input wire interrupt_trig,
    input wire [9:0] interrupt_mask,
    input wire [3:0] priority_override,
    input wire [3:0] override_interrupt_id,
    input wire priority_override_en,
    output reg [3:0] interrupt_id,
    output reg interrupt_valid,
    output reg [9:0] interrupt_status,
    output reg [9:0] missed_interrupts,
    output reg starvation_detected
);

    parameter STARVATION_THRESHOLD = 5;

    localparam [2:0]
        IDLE = 3'b000,
        PRIORITY_CALC = 3'b001,
        SERVICE_PREP = 3'b010,
        SERVICING = 3'b011,
        COMPLETION = 3'b100,
        ERROR = 3'b111;

    // Service-timeout threshold (cycles the controller waits for an ack
    // before flagging a timeout error).
    localparam [3:0] SERVICE_TIMEOUT = 4'd12;

    reg [2:0] current_state, next_state;
    reg [9:0] pending_interrupts;
    reg [3:0] wait_counters [0:9];
    reg [4:0] effective_priority [0:9];
    reg [9:0] active_mask;
    reg [3:0] service_timer;
    reg timeout_error;
    reg [3:0] next_interrupt_id;
    reg [4:0] max_priority;

    integer idx;
    integer j;
    reg arb_found;

    // ---------------------------------------------------------------
    // Combinational priority arbitration over the effective pending set
    // (pending AND enabled by the mask). Effective priority = base index,
    // boosted by a fixed amount when the interrupt has starved, or replaced
    // by priority_override when the override is enabled for that index.
    // Highest effective priority wins; ties resolve to the lowest index.
    // ---------------------------------------------------------------
    always @(*) begin
        next_interrupt_id = 4'd0;
        max_priority      = 5'd0;
        arb_found         = 1'b0;
        for (idx = 0; idx < 10; idx = idx + 1) begin
            effective_priority[idx] = idx[4:0];
            if (wait_counters[idx] >= STARVATION_THRESHOLD)
                effective_priority[idx] = idx[4:0] + 5'd10;   // starvation boost
            if (priority_override_en && (override_interrupt_id == idx[3:0]))
                effective_priority[idx] = {1'b0, priority_override};
            if (pending_interrupts[idx] && active_mask[idx]) begin
                if (!arb_found || (effective_priority[idx] > max_priority)) begin
                    max_priority      = effective_priority[idx];
                    next_interrupt_id = idx[3:0];
                    arb_found         = 1'b1;
                end
            end
        end
    end

    // ---------------------------------------------------------------
    // Next-state logic (purely combinational, self-holding default)
    // ---------------------------------------------------------------
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE:
                if ((pending_interrupts & active_mask) != 10'd0)
                    next_state = PRIORITY_CALC;
            PRIORITY_CALC:
                next_state = SERVICE_PREP;
            SERVICE_PREP:
                next_state = SERVICING;
            SERVICING: begin
                if (interrupt_ack)
                    next_state = COMPLETION;
                else if (service_timer >= SERVICE_TIMEOUT)
                    next_state = ERROR;
            end
            COMPLETION:
                next_state = IDLE;
            ERROR:
                next_state = IDLE;
            default:
                next_state = IDLE;
        endcase
    end

    // ---------------------------------------------------------------
    // Sequential datapath
    // ---------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state       <= IDLE;
            pending_interrupts  <= 10'd0;
            interrupt_status    <= 10'd0;
            missed_interrupts   <= 10'd0;
            interrupt_id        <= 4'd0;
            interrupt_valid     <= 1'b0;
            starvation_detected <= 1'b0;
            service_timer       <= 4'd0;
            timeout_error       <= 1'b0;
            active_mask         <= 10'd0;
            for (j = 0; j < 10; j = j + 1)
                wait_counters[j] <= 4'd0;
        end else if (reset_interrupts) begin
            current_state       <= IDLE;
            pending_interrupts  <= 10'd0;
            interrupt_status    <= 10'd0;
            missed_interrupts   <= 10'd0;
            interrupt_id        <= 4'd0;
            interrupt_valid     <= 1'b0;
            starvation_detected <= 1'b0;
            service_timer       <= 4'd0;
            timeout_error       <= 1'b0;
            for (j = 0; j < 10; j = j + 1)
                wait_counters[j] <= 4'd0;
        end else begin
            current_state <= next_state;
            active_mask   <= interrupt_mask;

            // Latch a fresh set of requests when triggered. Requests on enabled
            // lines become pending; requests on masked-off lines are recorded as
            // missed.
            if (interrupt_trig) begin
                pending_interrupts <= pending_interrupts |
                                      (interrupt_requests & interrupt_mask);
                missed_interrupts  <= missed_interrupts |
                                      (interrupt_requests & ~interrupt_mask);
            end

            // Age every pending, not-yet-serviced interrupt to detect starvation.
            for (j = 0; j < 10; j = j + 1) begin
                if (pending_interrupts[j] && !interrupt_status[j]) begin
                    if (wait_counters[j] != 4'hF)
                        wait_counters[j] <= wait_counters[j] + 4'd1;
                end
            end

            // Starvation flag: any pending interrupt aged past the threshold.
            starvation_detected <= 1'b0;
            for (j = 0; j < 10; j = j + 1)
                if (pending_interrupts[j] && (wait_counters[j] >= STARVATION_THRESHOLD))
                    starvation_detected <= 1'b1;

            case (current_state)
                IDLE: begin
                    interrupt_valid <= 1'b0;
                    timeout_error   <= 1'b0;
                    service_timer   <= 4'd0;
                end
                PRIORITY_CALC: begin
                    // winner computed combinationally (next_interrupt_id)
                    interrupt_valid <= 1'b0;
                end
                SERVICE_PREP: begin
                    interrupt_id                       <= next_interrupt_id;
                    interrupt_valid                    <= 1'b1;
                    interrupt_status[next_interrupt_id]<= 1'b1;
                    service_timer                      <= 4'd0;
                end
                SERVICING: begin
                    service_timer <= service_timer + 4'd1;
                end
                COMPLETION: begin
                    interrupt_valid                <= 1'b0;
                    pending_interrupts[interrupt_id] <= 1'b0;
                    interrupt_status[interrupt_id]   <= 1'b0;
                    wait_counters[interrupt_id]      <= 4'd0;
                end
                ERROR: begin
                    interrupt_valid                <= 1'b0;
                    timeout_error                  <= 1'b1;
                    pending_interrupts[interrupt_id] <= 1'b0;
                    interrupt_status[interrupt_id]   <= 1'b0;
                    wait_counters[interrupt_id]      <= 4'd0;
                end
                default: begin
                    interrupt_valid <= 1'b0;
                end
            endcase
        end
    end

endmodule

module perceptron_gates (
   input  logic clk,// Posedge clock
   input  logic rst_n,// Negedge reset
   input  logic signed [3:0] x1, // First Input of the Perceptron
   input  logic signed [3:0] x2, // Second Input of the Perceptron
   input  logic learning_rate, // Learning rate (alpha)
   input  logic signed [3:0] threshold, // Threshold value
   input  logic [1:0] gate_select, // Gate selection for target values
   output logic signed [3:0] percep_w1, // Trained Weight 1
   output logic signed [3:0] percep_w2, // Trained Weight 2
   output logic signed [3:0] percep_bias, // Trained Bias
   output logic [3:0] present_addr, // Current address in microcode ROM
   output logic stop, // Condition to indicate no learning has occurred(i.e. no weight change between iterations)
   output logic [2:0] input_index,// Vector to track the selection of target for a given input combination for a gate
   output logic signed [3:0] y_in, // Calculated Response
   output logic signed [3:0] y, // Calculated Response obtained by comparing y_in against a threshold value
   output logic signed [3:0] prev_percep_wt_1,//Value of Weight 1 during a previous iteration
   output logic signed [3:0] prev_percep_wt_2,//Value of Weight 2 during a previous iteration
   output logic signed [3:0] prev_percep_bias, // Value of Bias during a previous iteration
   // ----- Testing control unit diagnostic outputs -----
   output logic        [3:0] test_percep_present_state, // Present state of the Testing microcode ROM
   output logic signed [3:0] expected_percep_output,    // Expected output from predefined vector
   output logic signed [3:0] test_percep_output,        // Actual output from Testing unit
   output logic signed [3:0] test_percep_result,        // Number of matches
   output logic signed [3:0] test_percep_done,          // Testing completion flag
   output logic signed [3:0] test_percep_x1,            // Test input extracted from vector
   output logic signed [3:0] test_percep_x2             // Test input extracted from vector
);

   logic [15:0] microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;


   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 16'b0001_0000_0000_0000;
      microcode_rom[1] = 16'b0010_0001_0000_0000;
      microcode_rom[2] = 16'b0011_0010_0000_0000;
      microcode_rom[3] = 16'b0100_0011_0000_0000;
      microcode_rom[4] = 16'b0101_0100_0000_0000;
      microcode_rom[5] = 16'b0000_0101_0000_0000;
   end

   always@(*) begin
      microinstruction = microcode_rom[microcode_addr];
      next_addr        = microinstruction[15:12];
      train_action     = microinstruction[11:8];
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr    <= 4'd0;
         microcode_addr  <= 4'd0;
         percep_wt_1_reg <= 4'd0;
         percep_wt_2_reg <= 4'd0;
         percep_bias_reg <= 4'd0;
         input_index     <= 2'd0;
         stop            <= 1'b0;
      end else begin
         present_addr    <= next_addr;
         microcode_addr  <= present_addr;
      end
   end

   always_comb begin
      case (train_action)
         4'd0:  begin
                   percep_wt_1_reg = 4'd0;
                   percep_wt_2_reg = 4'd0;
                   percep_bias_reg = 4'd0;
                   stop = 1'b0;
                   next_addr = next_addr + 4'd0;
                   y_in = 4'd0;
                   y    = 4'd0;
                   prev_wt1_update = 4'd0;
                   prev_wt2_update = 4'd0;
                   prev_bias_update = 4'd0;
                   input_index = 0;
                   target = 0;
                   wt1_update = 0;
                   wt2_update = 0;
                   bias_update = 0;
                   epoch_counter = 0;
                end
         4'd1 : begin
                   y_in = percep_bias_reg + (x1 * percep_wt_1_reg) + (x2 * percep_wt_2_reg);
                   if (y_in > threshold)
                      y = 4'd1;
                   else if (y_in >= -threshold && y_in <= threshold)
                      y = 4'd0;
                   else
                      y = -4'd1;

                   percep_wt_1_reg  = percep_wt_1_reg  + 4'd0;
                   percep_wt_2_reg  = percep_wt_2_reg  + 4'd0;
                   percep_bias_reg  = percep_bias_reg  + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   stop = stop + 1'b0;
                   target = target + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd2 : begin
                   if(input_index == 0)
                        target = t1;
                   else if(input_index == 1)
                        target = t2;
                   else if(input_index == 2)
                        target = t3;
                   else if(input_index == 3)
                        target = t4;
                   else begin
                        input_index = 0;
                        target = 0;
                   end
                   stop = stop + 1'b0;
                   input_index = input_index + 0;
                   next_addr = next_addr + 4'd0;
                   target = target + 4'd0;
                   prev_wt1_update  = prev_wt1_update  + 4'd0;
                   prev_wt2_update  = prev_wt2_update  + 4'd0;
                   prev_bias_update = prev_bias_update + 4'd0;

                   percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                   percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                   percep_bias_reg = percep_bias_reg + 4'd0;
                   y_in = y_in + 4'd0;
                   y = y + 4'd0;
                   wt1_update = wt1_update + 4'd0 ;
                   wt2_update = wt2_update + 4'd0 ;
                   bias_update = bias_update + 4'd0 ;
                   epoch_counter = epoch_counter + 0;
                end
         4'd3 : begin
                   if (y != target) begin
                        wt1_update = learning_rate * x1 * target ;
                        wt2_update = learning_rate * x2 * target ;
                        bias_update = learning_rate * target ;
                    end else begin
                        wt1_update = 0 ;
                        wt2_update = 0 ;
                        bias_update = 0 ;
                    end
                    percep_wt_1_reg = percep_wt_1_reg + wt1_update;
                    percep_wt_2_reg = percep_wt_2_reg + wt2_update;
                    percep_bias_reg = percep_bias_reg + bias_update;
                    prev_wt1_update  = prev_wt1_update  + 4'd0;
                    prev_wt2_update  = prev_wt2_update  + 4'd0;
                    prev_bias_update = prev_bias_update + 4'd0;
                    y_in = y_in + 4'd0;
                    y = y + 4'd0;
                    stop = stop + 1'b0;
                    input_index = input_index + 0;
                    next_addr = next_addr + 4'd0;
                    target = target + 4'd0;
                    epoch_counter = epoch_counter + 0;
                end
         4'd4 : begin
                  if ((prev_wt1_update == wt1_update) & (prev_wt2_update == wt2_update) & (input_index == 4'd3)) begin
                          epoch_counter = 0;
                          stop = 1'b1;
                          input_index = 0;
                          next_addr = 4'd0;
                          percep_wt_1_reg = 0;
                          percep_wt_2_reg = 0;
                          percep_bias_reg = 0;
                          prev_wt1_update =  0;
                          prev_wt2_update =  0;
                          prev_bias_update = 0;
                          y_in = 0;
                          y = 0;
                          target = 0;
                          wt1_update = 0 ;
                          wt2_update = 0 ;
                          bias_update = 0 ;
                  end else begin
                          stop = 1'b0;
                          input_index = input_index + 0;
                          epoch_counter = epoch_counter + 1;
                          next_addr = 4'd5;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                  end
                end
         4'd5 : begin
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update  = wt1_update;
                          prev_wt2_update  = wt2_update;
                          prev_bias_update = bias_update;
                          next_addr = 4'd1;
                          input_index = input_index + 1;
                          stop = stop + 1'b0;
                          epoch_counter = epoch_counter + 0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0;
                          wt2_update = wt2_update + 4'd0;
                          bias_update = bias_update + 4'd0;
                end
      default : begin
                          next_addr = next_addr + 4'd0;
                          percep_wt_1_reg = percep_wt_1_reg + 4'd0;
                          percep_wt_2_reg = percep_wt_2_reg + 4'd0;
                          percep_bias_reg = percep_bias_reg + 4'd0;
                          prev_wt1_update = prev_wt1_update + 4'd0;
                          prev_wt2_update = prev_wt2_update + 4'd0;
                          prev_bias_update = prev_bias_update + 4'd0;
                          stop = stop + 1'b0;
                          y_in = y_in + 4'd0;
                          y = y + 4'd0;
                          input_index = input_index + 0;
                          target = target + 4'd0;
                          wt1_update = wt1_update + 4'd0 ;
                          wt2_update = wt2_update + 4'd0 ;
                          bias_update = bias_update + 4'd0 ;
                          epoch_counter = epoch_counter + 0;
                end
      endcase
   end
   assign percep_w1 = percep_wt_1_reg;
   assign percep_w2 = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

   // =====================================================================
   //  Testing microcode control unit
   //  Runs after training reaches the stop condition. Walks the four test
   //  vectors for the selected gate, computes test_calc = w1*x1 + w2*x2 +
   //  bias, thresholds it to {-1,0,1}, and counts matches vs the expected
   //  output stored in the predefined vector arrays.
   // =====================================================================
   localparam logic [3:0] T_IDLE = 4'd0,
                          T_LOAD = 4'd1,
                          T_CALC = 4'd2,
                          T_CMP  = 4'd3,
                          T_NEXT = 4'd4,
                          T_DONE = 4'd5;

   logic [3:0]        test_state;
   logic [3:0]        test_percep_index;
   logic [3:0]        test_base;
   logic [2:0]        test_count;
   logic signed [9:0] test_calc;

   // Predefined test-vector arrays : 16 deep (4 gates x 4 input combos)
   logic signed [3:0] test_inputs_x1        [0:15];
   logic signed [3:0] test_inputs_x2        [0:15];
   logic signed [3:0] test_expected_outputs [0:15];

   integer k;
   initial begin
      // combos per gate : (1,1) (1,-1) (-1,1) (-1,-1)
      for (k = 0; k < 4; k = k + 1) begin
         test_inputs_x1[k*4 + 0] =  4'sd1;  test_inputs_x2[k*4 + 0] =  4'sd1;
         test_inputs_x1[k*4 + 1] =  4'sd1;  test_inputs_x2[k*4 + 1] = -4'sd1;
         test_inputs_x1[k*4 + 2] = -4'sd1;  test_inputs_x2[k*4 + 2] =  4'sd1;
         test_inputs_x1[k*4 + 3] = -4'sd1;  test_inputs_x2[k*4 + 3] = -4'sd1;
      end
      // AND (base 0)
      test_expected_outputs[0]  =  4'sd1; test_expected_outputs[1]  = -4'sd1;
      test_expected_outputs[2]  = -4'sd1; test_expected_outputs[3]  = -4'sd1;
      // OR (base 4)
      test_expected_outputs[4]  =  4'sd1; test_expected_outputs[5]  =  4'sd1;
      test_expected_outputs[6]  =  4'sd1; test_expected_outputs[7]  = -4'sd1;
      // NAND (base 8)
      test_expected_outputs[8]  = -4'sd1; test_expected_outputs[9]  =  4'sd1;
      test_expected_outputs[10] =  4'sd1; test_expected_outputs[11] =  4'sd1;
      // NOR (base 12)
      test_expected_outputs[12] = -4'sd1; test_expected_outputs[13] = -4'sd1;
      test_expected_outputs[14] = -4'sd1; test_expected_outputs[15] =  4'sd1;
   end

   // Starting index for the selected gate
   always_comb begin
      case (gate_select)
         2'b00:   test_base = 4'd0;
         2'b01:   test_base = 4'd4;
         2'b10:   test_base = 4'd8;
         default: test_base = 4'd12;
      endcase
   end

   assign test_calc = (percep_wt_1_reg * test_percep_x1)
                    + (percep_wt_2_reg * test_percep_x2)
                    + percep_bias_reg;

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         test_state                <= T_IDLE;
         test_percep_present_state <= T_IDLE;
         test_percep_index         <= 4'd0;
         test_count                <= 3'd0;
         test_percep_result        <= 4'sd0;
         test_percep_output        <= 4'sd0;
         test_percep_done          <= 4'sd0;
         expected_percep_output    <= 4'sd0;
         test_percep_x1            <= 4'sd0;
         test_percep_x2            <= 4'sd0;
      end else begin
         test_percep_present_state <= test_state;
         case (test_state)
            T_IDLE: begin
               if (stop) begin
                  test_percep_index  <= test_base;
                  test_count         <= 3'd0;
                  test_percep_result <= 4'sd0;
                  test_percep_done   <= 4'sd0;
                  test_state         <= T_LOAD;
               end
            end
            T_LOAD: begin
               test_percep_x1         <= test_inputs_x1[test_percep_index];
               test_percep_x2         <= test_inputs_x2[test_percep_index];
               expected_percep_output <= test_expected_outputs[test_percep_index];
               test_state             <= T_CALC;
            end
            T_CALC: begin
               if (test_calc > threshold)
                  test_percep_output <= 4'sd1;
               else if (test_calc >= -threshold && test_calc <= threshold)
                  test_percep_output <= 4'sd0;
               else
                  test_percep_output <= -4'sd1;
               test_state <= T_CMP;
            end
            T_CMP: begin
               if (test_percep_output == expected_percep_output)
                  test_percep_result <= test_percep_result + 4'sd1;
               test_state <= T_NEXT;
            end
            T_NEXT: begin
               if (test_count == 3'd3) begin
                  test_percep_done <= 4'sd1;
                  test_state       <= T_DONE;
               end
               else begin
                  test_count        <= test_count + 3'd1;
                  test_percep_index <= test_percep_index + 4'd1;
                  test_state        <= T_LOAD;
               end
            end
            T_DONE: begin
               test_percep_done <= 4'sd1;
               test_state       <= T_DONE;
            end
            default: test_state <= T_IDLE;
         endcase
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
          2'b01 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b10 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b11 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
        default : begin
                    o_1 =  0;
                    o_2 =  0;
                    o_3 =  0;
                    o_4 =  0;
                  end
        endcase
   end
endmodule

// parallel_run_length : parameterized multi-stream run-length encoder.
// Derived by parallelising the single-stream run_length module across
// NUM_STREAMS independent streams, each gated by stream_enable[i].
module parallel_run_length
#(
    parameter DATA_WIDTH  = 8,   // Max run length per stream (>=1)
    parameter NUM_STREAMS = 4    // Number of parallel streams
)
(
    input  wire                                                clk,
    input  wire                                                reset_n,        // async active-low
    input  wire [NUM_STREAMS-1:0]                              data_in,        // one bit per stream
    input  wire [NUM_STREAMS-1:0]                              stream_enable,  // per-stream enable
    output wire [NUM_STREAMS-1:0]                              data_out,       // last value of terminated run
    output wire [(NUM_STREAMS*($clog2(DATA_WIDTH)+1))-1:0]     run_value,      // packed run lengths
    output wire [NUM_STREAMS-1:0]                              valid           // per-stream valid
);

    localparam RW = $clog2(DATA_WIDTH) + 1;   // run-length field width per stream

    genvar gi;
    generate
    for (gi = 0; gi < NUM_STREAMS; gi = gi + 1) begin : gen_stream

        reg [RW-1:0] run_length;
        reg [RW-1:0] run_value_r;
        reg          prev_data_in;
        reg          data_out_r;
        reg          valid_r;

        // Run-length tracking (per stream)
        always @(posedge clk or negedge reset_n) begin
            if (!reset_n) begin
                run_length   <= {RW{1'b0}};
                run_value_r  <= {RW{1'b0}};
                prev_data_in <= 1'b0;
            end else if (!stream_enable[gi]) begin
                // disabled stream: reset its logic/outputs to default
                run_length   <= {RW{1'b0}};
                run_value_r  <= {RW{1'b0}};
                prev_data_in <= 1'b0;
            end else begin
                if (data_in[gi] == prev_data_in) begin
                    if (run_length == DATA_WIDTH) begin
                        run_value_r <= run_length;
                    end
                    if (run_length < DATA_WIDTH) begin
                        run_length <= run_length + 1'b1;
                    end else begin
                        run_length <= 1'b1;   // saturate -> start new run of 1
                    end
                end else begin
                    run_value_r <= run_length; // value change -> emit prior run length
                    run_length  <= 1'b1;
                end
                prev_data_in <= data_in[gi];
            end
        end

        // Valid / data_out generation (per stream)
        always @(posedge clk or negedge reset_n) begin
            if (!reset_n) begin
                valid_r    <= 1'b0;
                data_out_r <= 1'b0;
            end else if (!stream_enable[gi]) begin
                valid_r    <= 1'b0;
                data_out_r <= 1'b0;
            end else begin
                if (run_length == DATA_WIDTH || data_in[gi] != prev_data_in) begin
                    valid_r    <= 1'b1;
                    data_out_r <= prev_data_in;
                end else begin
                    valid_r    <= 1'b0;
                    data_out_r <= 1'b0;
                end
            end
        end

        assign data_out[gi]                 = data_out_r;
        assign valid[gi]                    = valid_r;
        assign run_value[(gi*RW) +: RW]     = run_value_r;

    end
    endgenerate

endmodule

module vending_machine (
    input            clk,
    input            rst,             // asynchronous, active-high
    input            item_button,     // rising-edge toggle to start selection
    input      [2:0] item_selected,   // valid 3'b001..3'b100
    input      [3:0] coin_input,      // valid 1, 2, 5, 10
    input            cancel,          // rising-edge toggle to cancel
    output reg       dispense_item,
    output reg       return_change,
    output reg [4:0] item_price,
    output reg [4:0] change_amount,
    output reg [2:0] dispense_item_id,
    output reg       error,
    output reg       return_money
);

    localparam [2:0] IDLE               = 3'd0,
                     ITEM_SELECTION     = 3'd1,
                     PAYMENT_VALIDATION = 3'd2,
                     DISPENSING_ITEM    = 3'd3,
                     RETURN_CHANGE      = 3'd4,
                     RETURN_MONEY       = 3'd5;

    reg [2:0] state;
    reg [4:0] coins_accumulated;
    reg       item_button_prev;
    reg       cancel_prev;

    // Rising-edge detect for the toggle inputs
    wire item_button_rise = item_button & ~item_button_prev;
    wire cancel_rise      = cancel      & ~cancel_prev;

    // Item price lookup (four items, id 1..4)
    function [4:0] price_of;
        input [2:0] item;
        begin
            case (item)
                3'b001:  price_of = 5'd5;
                3'b010:  price_of = 5'd10;
                3'b011:  price_of = 5'd15;
                3'b100:  price_of = 5'd20;
                default: price_of = 5'd0;
            endcase
        end
    endfunction

    // Coin value validity (1, 2, 5, 10)
    function is_valid_coin;
        input [3:0] c;
        begin
            is_valid_coin = (c == 4'd1) || (c == 4'd2) ||
                            (c == 4'd5) || (c == 4'd10);
        end
    endfunction

    wire        valid_item   = (item_selected >= 3'b001) && (item_selected <= 3'b100);
    wire        coin_present = |coin_input;
    wire        valid_coin   = is_valid_coin(coin_input);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state             <= IDLE;
            coins_accumulated <= 5'd0;
            dispense_item     <= 1'b0;
            return_change     <= 1'b0;
            item_price        <= 5'd0;
            change_amount     <= 5'd0;
            dispense_item_id  <= 3'd0;
            error             <= 1'b0;
            return_money      <= 1'b0;
            item_button_prev  <= 1'b0;
            cancel_prev       <= 1'b0;
        end else begin
            // edge-detect history
            item_button_prev <= item_button;
            cancel_prev      <= cancel;

            // one-cycle pulse defaults
            dispense_item <= 1'b0;
            return_change <= 1'b0;
            error         <= 1'b0;
            return_money  <= 1'b0;

            case (state)
                IDLE: begin
                    if (item_button_rise) begin
                        state <= ITEM_SELECTION;
                    end else if (coin_present) begin
                        // coins inserted without selecting an item
                        error <= 1'b1;
                        state <= RETURN_MONEY;
                    end
                end

                ITEM_SELECTION: begin
                    if (cancel_rise) begin
                        error <= 1'b1;
                        state <= RETURN_MONEY;
                    end else if (valid_item) begin
                        item_price       <= price_of(item_selected);
                        dispense_item_id <= item_selected;
                        state            <= PAYMENT_VALIDATION;
                    end else if (item_selected != 3'b000) begin
                        // invalid item id selected
                        error <= 1'b1;
                        state <= RETURN_MONEY;
                    end
                end

                PAYMENT_VALIDATION: begin
                    if (cancel_rise) begin
                        error <= 1'b1;
                        state <= RETURN_MONEY;
                    end else if (coin_present && !valid_coin) begin
                        // invalid coin value
                        error <= 1'b1;
                        state <= RETURN_MONEY;
                    end else if (coin_present && valid_coin) begin
                        coins_accumulated <= coins_accumulated + 5'(coin_input);
                        if ((coins_accumulated + coin_input) >= item_price)
                            state <= DISPENSING_ITEM;
                    end
                end

                DISPENSING_ITEM: begin
                    dispense_item <= 1'b1;
                    if (coins_accumulated > item_price) begin
                        change_amount <= coins_accumulated - item_price;
                        state         <= RETURN_CHANGE;
                    end else begin
                        coins_accumulated <= 5'd0;
                        state             <= IDLE;
                    end
                end

                RETURN_CHANGE: begin
                    return_change     <= 1'b1;
                    coins_accumulated <= 5'd0;
                    state             <= IDLE;
                end

                RETURN_MONEY: begin
                    if (coins_accumulated > 5'd0)
                        return_money <= 1'b1;
                    coins_accumulated <= 5'd0;
                    state             <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module encoder_64b66b (
    input  logic         clk_in,              // Clock signal
    input  logic         rst_in,              // Asynchronous reset (active high)
    input  logic [63:0]  encoder_data_in,     // 64-bit data input
    input  logic [7:0]   encoder_control_in,  // 8-bit control input
    output logic [65:0]  encoder_data_out     // 66-bit encoded output
);

    // Registered outputs (one clock cycle latency preserved)
    logic [1:0]  sync_word;
    logic [63:0] encoded_data;
    logic [1:0]  sync_ctrl_word;
    logic [7:0]  type_field;
    logic [55:0] encoded_ctrl_words;

    // ------------------------------------------------------------------
    // All-data path (used when encoder_control_in == 0)
    // ------------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            sync_word    <= 2'b00;
            encoded_data <= 64'b0;
        end else if (encoder_control_in == 8'b00000000) begin
            sync_word    <= 2'b01;
            encoded_data <= encoder_data_in;
        end else begin
            sync_word    <= 2'b10;
            encoded_data <= 64'b0;
        end
    end

    // ------------------------------------------------------------------
    // Shared control decode.  The original design decoded the same
    // (data,control) patterns TWICE: once in the get_output() function
    // (-> type_field) and once in the encoded_ctrl_words case().  Both
    // decoders are collapsed here into a single case so the pattern
    // comparators are shared, reducing cell/wire utilization while
    // keeping the emitted type_field / encoded_ctrl_words / sync_ctrl_word
    // bit-identical to the original for every input.
    // ------------------------------------------------------------------
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            sync_ctrl_word     <= 2'b00;
            type_field         <= 8'b0;
            encoded_ctrl_words <= 56'b0;
        end else begin
            // defaults (match get_output else -> 0 and case default -> 0)
            type_field         <= 8'h00;
            encoded_ctrl_words <= 56'h0;
            if (encoder_control_in != 8'b00000000)
                sync_ctrl_word <= 2'b10;   // else: holds previous value

            case (encoder_control_in)
                8'b11111111: begin
                    if (encoder_data_in == 64'h0707070707070707) begin
                        type_field         <= 8'h1e;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,7'h00,7'h00,7'h00,7'h00};
                    end else if (encoder_data_in == 64'hFEFEFEFEFEFEFEFE) begin
                        type_field         <= 8'h1e;
                        encoded_ctrl_words <= {7'h1E,7'h1E,7'h1E,7'h1E,7'h1E,7'h1E,7'h1E,7'h1E};
                    end else if (encoder_data_in == 64'h07070707070707FD) begin
                        type_field         <= 8'h87;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,7'h00,7'h00,7'h00,7'h00};
                    end
                end
                8'b00011111: begin
                    if (encoder_data_in[39:0] == 40'hFB07070707) begin
                        type_field         <= 8'h33;
                        encoded_ctrl_words <= {encoder_data_in[63:40], 4'h0, 7'h00, 7'h00, 7'h00, 7'h00};
                    end else if (encoder_data_in[39:0] == 40'h9C07070707) begin
                        type_field         <= 8'h2d;
                        encoded_ctrl_words <= {encoder_data_in[63:40], 4'hF, 7'h00, 7'h00, 7'h00, 7'h00};
                    end
                end
                8'b00000001: begin
                    if (encoder_data_in[7:0] == 8'hFB) begin
                        type_field         <= 8'h78;
                        encoded_ctrl_words <= {encoder_data_in[63:8]};
                    end
                end
                8'b11111110: begin
                    if (encoder_data_in[63:8] == 56'h070707070707FD) begin
                        type_field         <= 8'h99;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,7'h00,7'h00,6'b000000,encoder_data_in[7:0]};
                    end
                end
                8'b11111100: begin
                    if (encoder_data_in[63:16] == 48'h0707070707FD) begin
                        type_field         <= 8'haa;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,7'h00,5'b00000,encoder_data_in[15:0]};
                    end
                end
                8'b11111000: begin
                    if (encoder_data_in[63:24] == 40'h07070707FD) begin
                        type_field         <= 8'hb4;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,4'b0000,encoder_data_in[23:0]};
                    end
                end
                8'b11110000: begin
                    if (encoder_data_in[63:32] == 32'h070707FD) begin
                        type_field         <= 8'hcc;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,3'b000,encoder_data_in[31:0]};
                    end else begin
                        encoded_ctrl_words <= 56'hFFFFFFF; // preserve original quirk
                    end
                end
                8'b11100000: begin
                    if (encoder_data_in[63:40] == 24'h0707FD) begin
                        type_field         <= 8'hd2;
                        encoded_ctrl_words <= {7'h00,7'h00,2'b00,encoder_data_in[39:0]};
                    end
                end
                8'b11000000: begin
                    if (encoder_data_in[63:48] == 16'h07FD) begin
                        type_field         <= 8'he1;
                        encoded_ctrl_words <= {7'h00,1'b0,encoder_data_in[47:0]};
                    end
                end
                8'b10000000: begin
                    if (encoder_data_in[63:56] == 8'hFD) begin
                        type_field         <= 8'hff;
                        encoded_ctrl_words <= encoder_data_in[55:0];
                    end
                end
                8'b11110001: begin
                    if ({encoder_data_in[63:32], encoder_data_in[7:0]} == 40'h070707079C) begin
                        type_field         <= 8'h4b;
                        encoded_ctrl_words <= {7'h00,7'h00,7'h00,7'h00,encoder_data_in[31:8],4'b1111};
                    end
                end
                8'b00010001: begin
                    if ({encoder_data_in[39:32], encoder_data_in[7:0]} == 16'h9C9C) begin
                        type_field         <= 8'h55;
                        encoded_ctrl_words <= {encoder_data_in[63:40], 8'hFF, encoder_data_in[31:8]};
                    end else if ({encoder_data_in[39:32], encoder_data_in[7:0]} == 16'hFB9C) begin
                        type_field         <= 8'h66;
                        encoded_ctrl_words <= {encoder_data_in[63:40], 8'h0F, encoder_data_in[31:8]};
                    end
                end
                default: ; // type_field=0, encoded_ctrl_words=0 (defaults above)
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Output mux (unchanged, combinational select on live control)
    // ------------------------------------------------------------------
    always_comb begin
        if (|encoder_control_in)
            encoder_data_out = {sync_ctrl_word, type_field, encoded_ctrl_words};
        else
            encoder_data_out = {sync_word, encoded_data};
    end

endmodule

module pseudo_lru_nmru_policy #(
    NWAYS = 4,
    NINDEXES = 32
) (
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

localparam WSEL = $clog2(NWAYS);
localparam [NWAYS-1:0] ONE = {{(NWAYS-1){1'b0}}, 1'b1};

reg [NWAYS-1:0] recency [NINDEXES-1:0];

// Combinational victim selection: the way with the smallest index whose
// recency bit is zero.  When multiple bits are zero this naturally points at
// the lowest free slot first (NMRU); when only one bit is zero it points at
// that single way (LRU).  Default 0 when no bit is zero.
function automatic [WSEL-1:0] lowest_zero (input [NWAYS-1:0] r);
    integer w;
    begin
        lowest_zero = {WSEL{1'b0}};
        for (w = NWAYS-1; w >= 0; w = w - 1) begin
            if (r[w] == 1'b0) lowest_zero = w[WSEL-1:0];
        end
    end
endfunction

assign way_replace = lowest_zero(recency[index]);

integer reset_counter;

// The way that is "touched" this access: the hit way on a hit, otherwise the
// victim way being (re)filled on a miss.  Its recency bit is set to one.  If
// that set makes every bit one (it was the last zero), the whole set is reset
// leaving only the touched way marked recent (second-chance wrap-around).
reg [WSEL-1:0]  used_way;
reg [NWAYS-1:0] next_rec;

always_ff @ (posedge clock or posedge reset) begin
    if (reset) begin
        for (reset_counter = 0; reset_counter < NINDEXES; reset_counter = reset_counter + 1) begin
            recency[reset_counter] <= {NWAYS{1'b0}};
        end
    end else begin
        if (access) begin
            used_way = hit ? way_select : lowest_zero(recency[index]);
            next_rec = recency[index] | (ONE << used_way);
            if (&next_rec)
                recency[index] <= (ONE << used_way);
            else
                recency[index] <= next_rec;
        end
    end
end

endmodule : pseudo_lru_nmru_policy

module pseudo_lru_tree_policy #(
    parameter NWAYS = 4,
    parameter NINDEXES = 32
)(
    input clock,
    input reset,
    input [$clog2(NINDEXES)-1:0] index,
    input [$clog2(NWAYS)-1:0] way_select,
    input access,
    input hit,
    output [$clog2(NWAYS)-1:0] way_replace
);

    localparam int unsigned NBITS_TREE = NWAYS - 1;
    localparam int unsigned DEPTH      = $clog2(NWAYS);

    // Recency array to track next way to be replaced
    reg [NBITS_TREE-1:0] recency [NINDEXES-1:0];

    wire [NBITS_TREE-1:0] recency_updated;
    wire [$clog2(NWAYS)-1:0] pseudo_lru_slot;

    integer i;

    // Sequential logic for reset and recency updates
    always_ff @ (posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 0; i < NINDEXES; i++) begin
                recency[i] <= NBITS_TREE'(0);
            end
        end else begin
            if (access) begin
                recency[index] <= recency_updated;
            end
        end
    end

    // The way that becomes most-recently-used after this access:
    //   - on a hit  : the accessed way  (way_select)
    //   - on a miss : the replaced way  (pseudo_lru_slot); way_select is
    //                 meaningless on a miss.
    wire [$clog2(NWAYS)-1:0] mru_way = hit ? way_select : pseudo_lru_slot;

    // Update recency tree: every internal node on the path to the MRU way
    // is set so that it points toward that way's child (stored-bit-points-to-MRU
    // convention). Off-path nodes are left untouched.
    function automatic [NBITS_TREE-1:0] update_tree
        (input [NBITS_TREE-1:0] cur, input [$clog2(NWAYS)-1:0] way);
        integer d;
        integer pos;
        logic   b;
        begin
            update_tree = cur;
            pos = 0;
            for (d = 0; d < DEPTH; d = d + 1) begin
                // direction toward `way` at this depth (way MSB = depth 0)
                b = way[DEPTH-1-d];
                // node at depth d, position pos lives at index (2^d - 1) + pos
                // Update recency tree to mark the accessed/replaced way as MRU
                update_tree[(1 << d) - 1 + pos] = b;
                pos = (pos << 1) | b;
            end
        end
    endfunction

    // Implement the code for recency_updated wire
    assign recency_updated = update_tree(recency[index], mru_way);

    // Select the Pseudo LRU slot
    slot_select_pseudo_lru_tree #(
        .NWAYS (NWAYS)
    ) slot_select_unit (
        .array (recency[index]),
        .index (pseudo_lru_slot)
    );

    assign way_replace = pseudo_lru_slot;

endmodule : pseudo_lru_tree_policy

module slot_select_pseudo_lru_tree #(
    parameter NWAYS = 4
)(
    input [NWAYS-2:0] array,
    output logic [$clog2(NWAYS)-1:0] index
);

    localparam int unsigned MAX_DEPTH = $clog2(NWAYS);

    integer depth;
    integer pos;
    logic   direction;

    always_comb begin
        // Find the Pseudo LRU way index: descend the tree taking the
        // COMPLEMENT of each stored bit (opposite of the MRU-marking path),
        // so we walk toward the least-recently-used leaf.
        pos   = 0;
        index = '0;
        for (depth = 0; depth < MAX_DEPTH; depth = depth + 1) begin
            // node at depth, position pos -> array index (2^depth - 1) + pos
            direction = ~array[(1 << depth) - 1 + pos];
            index = (index << 1) | direction;
            pos   = (pos << 1) | direction;
        end
    end

endmodule : slot_select_pseudo_lru_tree

module data_bus_controller #(
  parameter AFINITY = 0
  )(
  input         clk      ,
  input         rst_n    ,

  output        m0_read  ,
  input         m0_valid ,
  input [31:0]  m0_data  ,

  output        m1_read  ,
  input         m1_valid ,
  input [31:0]  m1_data  ,

  input         s_read   ,
  output        s_valid  ,
  output [31:0] s_data
);

  // ---------------------------------------------------------------
  // Arbitration : pick which master is forwarded to the slave.
  //   - only m0 valid          -> m0
  //   - only m1 valid          -> m1
  //   - both valid same cycle  -> AFINITY (0 -> m0, 1 -> m1)
  // ---------------------------------------------------------------
  wire sel_m0 = m0_valid & (~m1_valid | (AFINITY == 0));
  wire sel_m1 = m1_valid & (~m0_valid | (AFINITY == 1));

  // Slave ready is transferred to the selected master's ready.
  assign m0_read = s_read & sel_m0;
  assign m1_read = s_read & sel_m1;

  // ---------------------------------------------------------------
  // One-cycle-latency registered forward of the accepted transaction.
  // ---------------------------------------------------------------
  reg        s_valid_r;
  reg [31:0] s_data_r;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      s_valid_r <= 1'b0;
      s_data_r  <= 32'b0;
    end else begin
      s_valid_r <= (sel_m0 & m0_read) | (sel_m1 & m1_read);
      if (sel_m1)
        s_data_r <= m1_data;
      else
        s_data_r <= m0_data;
    end
  end

  assign s_valid = s_valid_r;
  assign s_data  = s_data_r;

endmodule

module lcm_3_ip #(
   parameter WIDTH = 4                    // Input bit-width
   )(
   input                         clk,
   input                         rst,
   input  [WIDTH-1:0]            A,
   input  [WIDTH-1:0]            B,
   input  [WIDTH-1:0]            C,
   input                         go,
   output logic  [3 * WIDTH-1:0] OUT,   // Updated output width
   output logic                  done
);

   logic [2*WIDTH-1:0]      gcd_result;     // GCD result
   logic [3*WIDTH-1:0]      product;        // Intermediate product
   logic                    gcd_done;
   logic                    product_ready;
   logic [2*WIDTH-1:0]      A_int;
   logic [2*WIDTH-1:0]      B_int;
   logic [2*WIDTH-1:0]      C_int;

   always_comb begin
      A_int = A*B;
      B_int = B*C;
      C_int = C*A;
   end

   // Calculate GCD of A, B, and C
   gcd_3_ip #(
      .WIDTH(2*WIDTH)
   ) gcd_inst (
      .clk   (clk),
      .rst   (rst),
      .A     (A_int),
      .B     (B_int),
      .C     (C_int),
      .go    (go),
      .OUT   (gcd_result),
      .done  (gcd_done)
   );

   // Sequential logic for LCM computation
   always_ff @(posedge clk) begin
      if (rst) begin
         OUT <= 0;
         done <= 0;
         product_ready <= 0;
      end else begin
         if (gcd_done) begin
            // Compute |A * B * C|
            product <= A * B * C;
            product_ready <= 1;
         end

         if (product_ready) begin
            // Compute LCM = |A * B * C| / GCD
            OUT <= product / gcd_result;
            done <= 1;
            product_ready <= 0;
         end else begin
            done <= 0;
         end
      end
   end
endmodule

module gcd_3_ip #(
   parameter WIDTH = 4
   )(
   input                     clk,
   input                     rst,
   input  [WIDTH-1:0]        A,
   input  [WIDTH-1:0]        B,
   input  [WIDTH-1:0]        C,
   input                     go,
   output logic  [WIDTH-1:0] OUT,
   output logic              done
);

logic [WIDTH-1:0] gcd_ab;
logic [WIDTH-1:0] gcd_bc;
logic             go_abc;
logic             done_ab;
logic             done_bc;
logic             done_ab_latched;
logic             done_bc_latched;

// GCD is calculated for AB and BC in parallel. The GCD for two numbers is lower than the numbers themselves in most cases.
// And calculating GCD for smaller numbers is comparatively faster using the implemented algorithm.
// Hence in order to reduce GCD computation latency the calculation is broken up in this fashion.

gcd_top
#( .WIDTH(WIDTH)
) gcd_A_B_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (A),
   .B             (B),
   .go            (go),
   .OUT           (gcd_ab),
   .done          (done_ab)
);

gcd_top
#( .WIDTH(WIDTH)
) gcd_B_C_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (B),
   .B             (C),
   .go            (go),
   .OUT           (gcd_bc),
   .done          (done_bc)
);

gcd_top
#( .WIDTH(WIDTH)
) gcd_ABC_inst (
   .clk           (clk),
   .rst           (rst),
   .A             (gcd_ab),
   .B             (gcd_bc),
   .go            (go_abc),
   .OUT           (OUT),
   .done          (done)
);

always_ff @ (posedge clk) begin
   if (rst) begin
      done_ab_latched    <= 0;
      done_bc_latched    <= 0;
   end else begin
      if(done_ab) begin
         done_ab_latched <= done_ab;
      end else if (go_abc) begin
         done_ab_latched <= 0;
      end

      if(done_bc) begin
         done_bc_latched <= done_bc;
      end else if (go_abc) begin
         done_bc_latched <= 0;
      end
   end
end

assign go_abc = done_ab_latched & done_bc_latched;

endmodule

module gcd_top #(
   parameter WIDTH = 4              // Parameter to define the bit-width of the input and output data
   )(
   input                     clk,   // Clock signal
   input                     rst,   // Active High Synchronous reset signal
   input  [WIDTH-1:0]        A,     // Input operand A
   input  [WIDTH-1:0]        B,     // Input operand B
   input                     go,    // Start signal to begin GCD computation
   output logic  [WIDTH-1:0] OUT,   // Output for the GCD result
   output logic              done   // Signal to indicate completion of computation
);

   // Internal signals to communicate between control path and data path
   logic equal;                     // Signal indicating A == B
   logic greater_than;              // Signal indicating A > B
   logic [1:0] controlpath_state;   // Current state of the control FSM

   // Instantiate the control path module
   gcd_controlpath gcd_controlpath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .go                (go),                // Connect go signal
      .equal             (equal),             // Connect equal signal from datapath
      .greater_than      (greater_than),      // Connect greater_than signal from datapath
      .controlpath_state (controlpath_state), // Output current state to datapath
      .done              (done)               // Output done signal
   );

   // Instantiate the data path module
   gcd_datapath
   #( .WIDTH(WIDTH)
   ) gcd_datapath_inst (
      .clk               (clk),               // Connect clock signal
      .rst               (rst),               // Connect reset signal
      .A                 (A),                 // Connect input A
      .B                 (B),                 // Connect input B
      .controlpath_state (controlpath_state), // Connect current state from control path
      .equal             (equal),             // Output equal signal to control path
      .greater_than      (greater_than),      // Output greater_than signal to control path
      .OUT               (OUT)                // Output GCD result
   );
endmodule


// Datapath module for GCD computation
module gcd_datapath  #(
   parameter WIDTH = 4                           // Bit-width of operands
   )(
   input                     clk,                // Clock signal
   input                     rst,                // Active High Synchronous reset
   input  [WIDTH-1:0]        A,                  // Input operand A
   input  [WIDTH-1:0]        B,                  // Input operand B
   input  [1:0]              controlpath_state,  // Current state from control path
   output logic              equal,              // Signal indicating A_ff == B_ff
   output logic              greater_than,       // Signal indicating A_ff > B_ff
   output logic  [WIDTH-1:0] OUT                 // Output GCD result
);

   // Registers to hold intermediate values of A and B
   logic [WIDTH-1:0] A_ff;
   logic [WIDTH-1:0] B_ff;

   // State encoding for control signals
   localparam S0 = 2'd0;    // State 0: Initialization state
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff, subtract B_ff from A_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff, subtract A_ff from B_ff

   // Sequential logic to update registers based on controlpath_state
   always_ff @ (posedge clk) begin
      if (rst) begin
         // On reset, initialize registers to zero
         A_ff <= 'b0;
         B_ff <= 'b0;
         OUT  <= 'b0;
      end else begin
         case (controlpath_state)
            S0: begin
                // In state S0, load input values into registers
                A_ff <= A;
                B_ff <= B;
             end
            S1: begin
                // In state S1, computation is done, output the result
                OUT  <= A_ff;
             end
            S2: begin
                // In state S2, A_ff > B_ff, subtract B_ff from A_ff
                if (greater_than)
                   A_ff <= A_ff - B_ff;
             end
            S3: begin
                // In state S3, B_ff > A_ff, subtract A_ff from B_ff
                if (!equal & !greater_than)
                   B_ff <= B_ff - A_ff;
             end
            default: begin
                A_ff <= 'b0;
                B_ff <= 'b0;
                OUT <= 'b0;
            end
         endcase
      end
   end

   // Generating control response signals for the control path FSM
   always_comb begin
      case(controlpath_state)
         S0: begin
            // In state S0, compare initial input values A and B
            equal        = (A == B)? 1'b1 : 1'b0;
            greater_than = (A >  B)? 1'b1 : 1'b0;
          end
          default: begin
            // In other states, compare the current values in registers A_ff and B_ff
            equal        = (A_ff == B_ff)? 1'b1 : 1'b0;
            greater_than = (A_ff >  B_ff)? 1'b1 : 1'b0;
          end
      endcase
   end
endmodule

// Control path module for GCD computation FSM
module gcd_controlpath (
   input                    clk,               // Clock signal
   input                    rst,               // Active High Synchronous reset
   input                    go,                // Start GCD calculation signal
   input                    equal,             // From Datapath: A_ff equals B_ff
   input                    greater_than,      // From Datapath: A_ff is greater than B_ff
   output logic [1:0]       controlpath_state, // Current state to Datapath
   output logic             done               // Indicates completion of GCD calculation
);

   // Internal state registers
   logic [1:0] curr_state;  // Current state of FSM
   logic [1:0] next_state;  // Next state of FSM

   // State encoding
   localparam S0 = 2'd0;    // State 0: Initialization or waiting for 'go' signal
   localparam S1 = 2'd1;    // State 1: Computation complete
   localparam S2 = 2'd2;    // State 2: A_ff > B_ff
   localparam S3 = 2'd3;    // State 3: B_ff > A_ff

   // State latching logic: Update current state on clock edge
   always_ff @ (posedge clk) begin
      if (rst) begin
         curr_state   <= S0;   // On reset, set state to S0
      end else begin
         curr_state   <= next_state;   // Transition to next state
      end
   end

   // State transition logic: Determine next state based on current state and inputs
   always_comb begin
      case(curr_state)
         S0: begin
             // State S0: Waiting for 'go' signal
             if(!go)
                next_state = S0;         // Remain in S0 until 'go' is asserted
             else if (equal)
                next_state = S1;         // If A == B, computation is complete
             else if (greater_than)
                next_state = S2;         // If A > B, go to state S2
             else
                next_state = S3;         // If B > A, go to state S3
         end
         S1: begin
             // State S1: Computation complete, output the result
             next_state = S0;           // Return to S0 after completion
         end
         S2: begin
             // State S2: A_ff > B_ff, subtract B_ff from A_ff
             if(equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, stay in S2
             else
                next_state = S3;         // If B_ff > A_ff, go to S3
         end
         S3: begin
             // State S3: B_ff > A_ff, subtract A_ff from B_ff
             if (equal)
                next_state = S1;         // If A_ff == B_ff after subtraction, go to S1
             else if (greater_than)
                next_state = S2;         // If A_ff > B_ff, go to S2
             else
                next_state = S3;         // If B_ff > A_ff, stay in S3
         end
         default: begin
             next_state = S0;
         end
      endcase
   end

   // Output logic: Generate 'done' signal when computation is complete
   always_ff @ (posedge clk) begin
     if(rst) begin
        done <= 1'b0;             // On reset, 'done' is low
     end else begin
        done <= (curr_state == S1); // 'done' is asserted when in state S1
     end
   end

   // Assign current state to output for datapath
   assign controlpath_state = curr_state;

endmodule

// SystemVerilog RTL for a Priority-Based Interrupt Controller with APB Interface

module interrupt_controller_apb #(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8
    )
    (
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0] interrupt_service,
    output logic                      cpu_interrupt,
    input  logic                      cpu_ack,
    output  logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]     interrupt_vector,

    // APB Interface Signals
    input  logic                      pclk,
    input  logic                      presetn,
    input  logic                      psel,
    input  logic                      penable,
    input  logic                      pwrite,
    input  logic [ADDR_WIDTH-1:0]     paddr,
    input  logic [31:0]               pwdata,
    output logic [31:0]               prdata,
    output logic                      pready
);

    logic [NUM_INTERRUPTS-1:0] interrupt_mask;
    logic servicing;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;

    // Insert the logic here

    localparam IDX_W = $clog2(NUM_INTERRUPTS);

    // Register address map
    localparam REG_PRIORITY_MAP   = 8'h0;
    localparam REG_INTERRUPT_MASK = 8'h1;
    localparam REG_VECTOR_TABLE   = 8'h2;
    localparam REG_PENDING        = 8'h3;
    localparam REG_CURRENT_INT    = 8'h4;

    // Configurable register banks
    logic [23:0]            priority_map [NUM_INTERRUPTS-1:0];
    logic [ADDR_WIDTH-1:0]  vector_table [NUM_INTERRUPTS-1:0];
    logic [IDX_W-1:0]       current_interrupt;
    logic [IDX_W-1:0]       current_interrupt_synced;

    integer j;

    // ---------------------------------------------------------------
    // APB register interface (pclk / presetn domain), single-cycle,
    // no wait states.
    // ---------------------------------------------------------------
    always_ff @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            for (j = 0; j < NUM_INTERRUPTS; j = j + 1) begin
                priority_map[j] <= j[23:0];               // 0,1,2,...
                vector_table[j] <= (j*4);                 // 0x0,0x4,0x8,...
            end
            interrupt_mask <= {NUM_INTERRUPTS{1'b1}};      // all enabled
            prdata         <= 32'd0;
            pready         <= 1'b0;
        end else begin
            if (psel && penable) begin
                pready <= 1'b1;                            // no wait states
                if (pwrite) begin
                    case (paddr)
                        REG_PRIORITY_MAP  : priority_map[pwdata[IDX_W-1:0]] <= pwdata[31:8];
                        REG_INTERRUPT_MASK: interrupt_mask <= pwdata[NUM_INTERRUPTS-1:0];
                        REG_VECTOR_TABLE  : vector_table[pwdata[IDX_W-1:0]] <= pwdata[8 +: ADDR_WIDTH];
                        default           : ; // read-only / unmapped
                    endcase
                end else begin
                    case (paddr)
                        REG_INTERRUPT_MASK: prdata <= {{(32-NUM_INTERRUPTS){1'b0}}, interrupt_mask};
                        REG_PENDING       : prdata <= {{(32-NUM_INTERRUPTS){1'b0}}, pending_interrupts};
                        REG_CURRENT_INT   : prdata <= {{(32-IDX_W){1'b0}}, current_interrupt_synced};
                        REG_PRIORITY_MAP  : prdata <= {8'd0, priority_map[0]};
                        REG_VECTOR_TABLE  : prdata <= {{(32-ADDR_WIDTH){1'b0}}, vector_table[0]};
                        default           : prdata <= 32'd0;
                    endcase
                end
            end else begin
                pready <= 1'b0;
            end
        end
    end

    // ---------------------------------------------------------------
    // Priority arbitration over the effective pending set
    // (pending AND mask). Lowest priority value wins; ties resolve
    // to the lowest index (strict '<').
    // ---------------------------------------------------------------
    logic [IDX_W-1:0] sel_idx;
    logic             sel_valid;
    logic [23:0]      best_pri;

    always_comb begin
        sel_valid = 1'b0;
        sel_idx   = {IDX_W{1'b0}};
        best_pri  = {24{1'b1}};
        for (j = 0; j < NUM_INTERRUPTS; j = j + 1) begin
            if ((pending_interrupts[j] & interrupt_mask[j]) && (priority_map[j] < best_pri)) begin
                best_pri  = priority_map[j];
                sel_idx   = j[IDX_W-1:0];
                sel_valid = 1'b1;
            end
        end
    end

    // ---------------------------------------------------------------
    // Interrupt handling FSM (clk / rst_n domain)
    // ---------------------------------------------------------------
    logic [NUM_INTERRUPTS-1:0] req_meta, req_sync;      // 2FF request synchronizer
    logic [IDX_W-1:0]          serviced_idx;
    logic [NUM_INTERRUPTS-1:0] serviced_onehot;

    assign serviced_onehot = ({{(NUM_INTERRUPTS-1){1'b0}}, 1'b1} << serviced_idx);

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            req_meta                 <= {NUM_INTERRUPTS{1'b0}};
            req_sync                 <= {NUM_INTERRUPTS{1'b0}};
            pending_interrupts       <= {NUM_INTERRUPTS{1'b0}};
            servicing                <= 1'b0;
            cpu_interrupt            <= 1'b0;
            interrupt_service        <= {NUM_INTERRUPTS{1'b0}};
            interrupt_idx            <= {IDX_W{1'b0}};
            interrupt_vector         <= {ADDR_WIDTH{1'b0}};
            current_interrupt        <= {IDX_W{1'b1}};   // invalid (-1)
            current_interrupt_synced <= {IDX_W{1'b1}};
            serviced_idx             <= {IDX_W{1'b0}};
        end else begin
            // Synchronize the asynchronous requests before use
            req_meta <= interrupt_requests;
            req_sync <= req_meta;

            // Keep a synced copy of the serviced index for glitch-free CPU read
            current_interrupt_synced <= current_interrupt;

            if (servicing) begin
                if (cpu_ack) begin
                    // Clear the acked (serviced) bit FIRST, then OR-in fresh
                    // requests so a same-cycle re-request is not lost.
                    pending_interrupts <= (pending_interrupts & ~serviced_onehot) |
                                          (req_sync & interrupt_mask);
                    servicing         <= 1'b0;
                    cpu_interrupt     <= 1'b0;
                    interrupt_service <= {NUM_INTERRUPTS{1'b0}};
                    current_interrupt <= {IDX_W{1'b1}};
                end else begin
                    pending_interrupts <= pending_interrupts | (req_sync & interrupt_mask);
                end
            end else begin
                pending_interrupts <= pending_interrupts | (req_sync & interrupt_mask);
                if (sel_valid) begin
                    servicing         <= 1'b1;
                    serviced_idx      <= sel_idx;
                    interrupt_idx     <= sel_idx;
                    current_interrupt <= sel_idx;
                    interrupt_vector  <= vector_table[sel_idx];
                    interrupt_service <= ({{(NUM_INTERRUPTS-1){1'b0}}, 1'b1} << sel_idx);
                    cpu_interrupt     <= 1'b1;
                end
            end
        end
    end

endmodule

module perceptron_gates (
   input  logic clk,
   input  logic rst_n,
   input  logic signed [3:0] x1,
   input  logic signed [3:0] x2,
   input  logic learning_rate,
   input  logic signed [3:0] threshold,
   input  logic [1:0] gate_select,
   output logic signed [3:0] percep_w1,
   output logic signed [3:0] percep_w2,
   output logic signed [3:0] percep_bias,
   output logic [3:0] present_addr,
   output logic stop,
   output logic [2:0] input_index,
   output logic signed [3:0] y_in,
   output logic signed [3:0] y,
   output logic signed [3:0] prev_percep_wt_1,
   output logic signed [3:0] prev_percep_wt_2,
   output logic signed [3:0] prev_percep_bias
);

   logic [7:0] microcode_rom [0:5];
   logic [3:0]  next_addr;
   logic [3:0]  train_action;
   logic [3:0]  microcode_addr;
   logic [15:0] microinstruction;
   logic signed [3:0] t1, t2, t3, t4;

   gate_target dut (
       .gate_select(gate_select),
       .o_1(t1),
       .o_2(t2),
       .o_3(t3),
       .o_4(t4)
   );

   logic signed [3:0] percep_wt_1_reg;
   logic signed [3:0] percep_wt_2_reg;
   logic signed [3:0] percep_bias_reg;

   logic signed [3:0] target;
   logic signed [3:0] prev_wt1_update;
   logic signed [3:0] prev_wt2_update;
   logic signed [3:0] prev_bias_update;

   logic signed [3:0] wt1_update;
   logic signed [3:0] wt2_update;
   logic signed [3:0] bias_update;
   logic [7:0] epoch_counter;

   logic [3:0] mca_prev;   // previous microcode_addr (first-cycle detect for the 2-stage PC)

   assign  prev_percep_wt_1 = prev_wt1_update;
   assign  prev_percep_wt_2 = prev_wt2_update;
   assign  prev_percep_bias = prev_bias_update;

   initial begin
      microcode_rom[0] = 8'b0001_0000;
      microcode_rom[1] = 8'b0010_0001;
      microcode_rom[2] = 8'b0011_0010;
      microcode_rom[3] = 8'b0100_0011;
      microcode_rom[4] = 8'b0101_0100;
      microcode_rom[5] = 8'b0000_0101;
   end

   // stop condition: current-iteration deltas equal previous-iteration deltas
   logic stop_cond;
   assign stop_cond = (wt1_update  == prev_wt1_update) &&
                      (wt2_update  == prev_wt2_update) &&
                      (bias_update == prev_bias_update);

   always @(*) begin
      microinstruction = microcode_rom[microcode_addr];
      train_action     = microinstruction[3:0];
      // The ROM next_addr field is the default; actions 4/5 sequence dynamically.
      case (train_action)
         4'd4:    next_addr = stop_cond ? 4'd0 : 4'd5; // stop -> re-init, else continue
         4'd5:    next_addr = 4'd1;                     // loop back to compute y_in
         default: next_addr = microinstruction[7:4];
      endcase
   end

   // Combinational helpers (sign-extended datapath)
   logic signed [11:0] yin_calc;
   logic signed [3:0]  u1, u2, ub;
   always @(*) begin
      yin_calc = $signed(percep_bias_reg) + ($signed(x1) * $signed(percep_wt_1_reg))
                                          + ($signed(x2) * $signed(percep_wt_2_reg));
      u1 = learning_rate ? ($signed(x1) * $signed(target)) : 4'sd0;
      u2 = learning_rate ? ($signed(x2) * $signed(target)) : 4'sd0;
      ub = learning_rate ? $signed(target) : 4'sd0;
   end

   always_ff @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
         present_addr     <= 4'd0;
         microcode_addr   <= 4'd0;
         mca_prev         <= 4'hF;
         percep_wt_1_reg  <= 4'd0;
         percep_wt_2_reg  <= 4'd0;
         percep_bias_reg  <= 4'd0;
         input_index      <= 3'd0;
         stop             <= 1'b0;
         y_in             <= 4'd0;
         y                <= 4'd0;
         target           <= 4'd0;
         wt1_update       <= 4'd0;
         wt2_update       <= 4'd0;
         bias_update      <= 4'd0;
         prev_wt1_update  <= 4'd0;
         prev_wt2_update  <= 4'd0;
         prev_bias_update <= 4'd0;
         epoch_counter    <= 8'd0;
      end else if (!stop) begin
         // Program counter (2-stage as specified); frozen once stop is asserted so
         // the trained weights/bias are preserved at the outputs.
         present_addr   <= next_addr;
         microcode_addr <= present_addr;
         mca_prev       <= microcode_addr;

         // Execute each microcode action once, on the first cycle it is presented
         if (microcode_addr != mca_prev) begin
            case (train_action)
               4'd0: begin  // initialize
                  percep_wt_1_reg  <= 4'd0;
                  percep_wt_2_reg  <= 4'd0;
                  percep_bias_reg  <= 4'd0;
                  stop             <= 1'b0;
                  y_in             <= 4'd0;
                  y                <= 4'd0;
                  prev_wt1_update  <= 4'd0;
                  prev_wt2_update  <= 4'd0;
                  prev_bias_update <= 4'd0;
                  wt1_update       <= 4'd0;
                  wt2_update       <= 4'd0;
                  bias_update      <= 4'd0;
                  epoch_counter    <= 8'd0;
               end
               4'd1: begin  // compute y_in and y
                  y_in <= yin_calc[3:0];
                  if (yin_calc > $signed(threshold))
                     y <= 4'sd1;
                  else if (yin_calc >= -$signed(threshold) && yin_calc <= $signed(threshold))
                     y <= 4'sd0;
                  else
                     y <= -4'sd1;
               end
               4'd2: begin  // select target for this iteration
                  case (input_index)
                     3'd0: target <= t1;
                     3'd1: target <= t2;
                     3'd2: target <= t3;
                     3'd3: target <= t4;
                     default: begin
                        input_index <= 3'd0;   // wrap to start a new epoch
                        target      <= 4'sd0;
                     end
                  endcase
               end
               4'd3: begin  // compute weight/bias changes and apply them
                  if (y != target) begin
                     wt1_update      <= u1;
                     wt2_update      <= u2;
                     bias_update     <= ub;
                     percep_wt_1_reg <= percep_wt_1_reg + u1;
                     percep_wt_2_reg <= percep_wt_2_reg + u2;
                     percep_bias_reg <= percep_bias_reg + ub;
                  end else begin
                     wt1_update  <= 4'sd0;
                     wt2_update  <= 4'sd0;
                     bias_update <= 4'sd0;
                  end
               end
               4'd4: begin  // compare against previous-iteration deltas
                  if (wt1_update == prev_wt1_update &&
                      wt2_update == prev_wt2_update &&
                      bias_update == prev_bias_update) begin
                     stop <= 1'b1;
                  end else begin
                     stop          <= 1'b0;
                     epoch_counter <= epoch_counter + 8'd1;
                  end
               end
               4'd5: begin  // save deltas, advance iteration counter
                  prev_wt1_update  <= wt1_update;
                  prev_wt2_update  <= wt2_update;
                  prev_bias_update <= bias_update;
                  input_index      <= input_index + 3'd1;
               end
               default: ;
            endcase
         end
      end
   end

   assign percep_w1 = percep_wt_1_reg;
   assign percep_w2 = percep_wt_2_reg;
   assign percep_bias = percep_bias_reg;

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b01 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b10 : begin
                    o_1 =  4'b0001;
                    o_2 =  4'b0001;
                    o_3 =  4'b0001;
                    o_4 = -4'b0001;
                  end
          2'b11 : begin
                    o_1 =  4'b0001;
                    o_2 = -4'b0001;
                    o_3 = -4'b0001;
                    o_4 = -4'b0001;
                  end
        default : begin
                    o_1 =  4'b0000;
                    o_2 =  4'b0000;
                    o_3 =  4'b0000;
                    o_4 =  4'b0000;
                  end
        endcase
   end
endmodule

{"code": [{"rtl/inter_block.sv": "module inter_block #(
    parameter ROW_COL_WIDTH = 16,
    parameter SUB_BLOCKS    = 4,
    parameter DATA_WIDTH    = ROW_COL_WIDTH*ROW_COL_WIDTH
)(
    input  logic clk,
    input  logic rst_n,
    input  logic i_valid,
    input  logic [DATA_WIDTH-1:0] in_data, // Input: 256 bits
    output logic [DATA_WIDTH-1:0] out_data // Output: 256 bits rearranged
);

localparam CHUNK = 8;
localparam NBW_COUNTER = $clog2(SUB_BLOCKS) + 1;
localparam NBW_COUNTER_SUB_OUT = 2;
localparam OUT_CYCLES = 32;
logic [NBW_COUNTER-1:0] counter_sub_blocks;
logic [NBW_COUNTER_SUB_OUT-1:0] counter_sub_out;

logic [DATA_WIDTH-1:0] in_data_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_intra_block_reg [SUB_BLOCKS-1:0];
logic [DATA_WIDTH-1:0] out_data_aux [SUB_BLOCKS-1:0];
logic start_intra;

always_ff @(posedge clk or negedge rst_n ) begin
   if(!rst_n) begin
      counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      start_intra <= 0;
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         in_data_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(i_valid) begin
         in_data_reg[counter_sub_blocks] <= in_data;

         if(counter_sub_blocks == SUB_BLOCKS) begin
            counter_sub_blocks <= {NBW_COUNTER{1'b0}};
         end
         else begin
            start_intra <= 0;
            counter_sub_blocks <= counter_sub_blocks + 1;
         end
      end
      else if(counter_sub_blocks == SUB_BLOCKS) begin
         start_intra        <= 1;
         counter_sub_blocks <= {NBW_COUNTER{1'b0}};
      end
   end
end

genvar k;
generate
   for(k = 0; k < SUB_BLOCKS; k++) begin
      intra_block uu_intra_block (
         .in_data(in_data_reg[k]),
         .out_data(out_data_intra_block[k])
      );
   end
endgenerate

always_ff @(posedge clk or negedge rst_n) begin
   if(!rst_n) begin
      for(int i = 0; i < SUB_BLOCKS; i++) begin
         out_data_intra_block_reg[i] <= {DATA_WIDTH{1'b0}};
      end
   end
   else begin
      if(start_intra) begin
         for(int i = 0; i < SUB_BLOCKS; i++) begin
            out_data_intra_block_reg[i] <= out_data_intra_block[i];
         end
      end
   end
end

// Combinational rearrangement network, expressed as continuous assignments so
// it is purely combinational (no blocking assignments -> no mixing with the
// registered output path below).
genvar gi;
generate
   for(gi = 0; gi < 32; gi++) begin : gen_rearrange
      assign out_data_aux[0][(gi+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[gi%4][((gi+1)*CHUNK)-1-:CHUNK];
      assign out_data_aux[1][(gi+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[gi%4][(((gi+1)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
      assign out_data_aux[2][(gi+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[gi%4][(((gi+2)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
      assign out_data_aux[3][(gi+1)*CHUNK-1-:CHUNK] = out_data_intra_block_reg[gi%4][(((gi+3)%OUT_CYCLES+1)*CHUNK)-1-:CHUNK];
