       for(int i = 0; i < 256; i++) begin
         if (i < 128) begin
            r_prime[i] = (i - 2 * (i / 16)) % 16;
            c_prime[i] = (i -     (i / 16)) % 16;
         end
         else begin
            r_prime[i] = (i - 2 * (i / 16) - 1) % 16;
            c_prime[i] = (i - (i / 16) - 1) % 16;
         end
       end
    end
    int j, k;
    logic [7:0] output_index[256];
    always_comb begin
      for (j = 0; j < 256; j++) begin
           output_index[j] = r_prime[j] * 16 + c_prime[j];
           out_data[j]     = in_data[output_index[j]];
        end
    end
endmodule"}]}

module sorting_engine #(
    parameter N = 8,          // number of elements to sort
    parameter WIDTH = 8       // bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-----------------------------------------------------
    // State machine definitions
    //-----------------------------------------------------
    localparam [3:0]
        S_IDLE         = 4'd0,
        S_LOAD_INPUT   = 4'd1,
        S_FIND_MAX     = 4'd2,
        S_COUNT        = 4'd3,
        S_PREFIX_SUM   = 4'd4,
        S_BUILD_OUTPUT = 4'd5,
        S_COPY_OUTPUT  = 4'd6,
        S_DONE         = 4'd7;

    //-----------------------------------------------------
    // Registered signals (updated in sequential always)
    //-----------------------------------------------------
    reg [3:0]           current_state;
    reg [WIDTH-1:0]     data_array [0:N-1];
    reg [WIDTH-1:0]     out_array  [0:N-1];
    reg [$clog2(N):0]   count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     max_val;
    reg [$clog2(N):0]   load_cnt;
    reg [$clog2(N):0]   find_cnt;
    reg [$clog2(N):0]   count_cnt;
    reg [WIDTH-1:0]     prefix_cnt;
    reg [$clog2(N):0]   build_cnt;
    reg [$clog2(N):0]   copy_cnt;

    //-----------------------------------------------------
    // Wires/reg for "next" values (computed combinationally)
    //-----------------------------------------------------
    reg [3:0]           next_state;

    // Arrays get "shadow copies" for combinational updates
    reg [WIDTH-1:0]     next_data_array [0:N-1];
    reg [WIDTH-1:0]     next_out_array  [0:N-1];
    reg [$clog2(N):0]   next_count_array[0:(1<<WIDTH)-1];

    reg [WIDTH-1:0]     next_max_val;
    reg [$clog2(N):0]   next_load_cnt;
    reg [$clog2(N):0]   next_find_cnt;
    reg [$clog2(N):0]   next_count_cnt;
    reg [WIDTH-1:0]     next_prefix_cnt;
    reg [$clog2(N):0]   next_build_cnt;
    reg [$clog2(N):0]   next_copy_cnt;

    reg                 next_done;
    reg [N*WIDTH-1:0]   next_out_data;
    integer rev_idx;
    reg [WIDTH-1:0] val;
    reg [$clog2(N):0] pos;

    integer i;
    always @(*) begin
        // -------- default: hold all state (no latches) --------
        next_state      = current_state;
        next_max_val    = max_val;
        next_load_cnt   = load_cnt;
        next_find_cnt   = find_cnt;
        next_count_cnt  = count_cnt;
        next_prefix_cnt = prefix_cnt;
        next_build_cnt  = build_cnt;
        next_copy_cnt   = copy_cnt;
        next_done       = 1'b0;              // done is a one-cycle pulse
        next_out_data   = out_data;
        val             = {WIDTH{1'b0}};
        pos             = {($clog2(N)+1){1'b0}};
        rev_idx         = 0;
        for (i = 0; i < N; i = i + 1) begin
            next_data_array[i] = data_array[i];
            next_out_array[i]  = out_array[i];
        end
        for (i = 0; i < (1<<WIDTH); i = i + 1) begin
            next_count_array[i] = count_array[i];
        end

        case (current_state)
            //-------------------------------------------------
            S_IDLE: begin
                // (1 clock) wait for start, then move to load; clear working
                // state for a fresh sort. out_data is preserved until the new
                // result is ready (S_COPY_OUTPUT).
                if (start) begin
                    next_state    = S_LOAD_INPUT;
                    next_load_cnt  = 0;
                    next_find_cnt  = 0;
                    next_count_cnt = 0;
                    next_build_cnt = 0;
                    next_copy_cnt  = 0;
                    next_max_val   = {WIDTH{1'b0}};
                    for (i = 0; i < N; i = i + 1)
                        next_out_array[i] = {WIDTH{1'b0}};
                    for (i = 0; i < (1<<WIDTH); i = i + 1)
                        next_count_array[i] = {($clog2(N)+1){1'b0}};
                end
            end

            //-------------------------------------------------
            S_LOAD_INPUT: begin
                // N clocks to load, then 1 clock to transition.
                if (load_cnt < N) begin
                    next_data_array[load_cnt] = in_data[load_cnt*WIDTH +: WIDTH];
                    next_load_cnt = load_cnt + 1;
                end else begin
                    next_state    = S_FIND_MAX;
                    next_find_cnt = 0;
                end
            end

            //-------------------------------------------------
            S_FIND_MAX: begin
                // N clocks to find the maximum, then 1 clock to transition.
                if (find_cnt < N) begin
                    if (data_array[find_cnt] > max_val)
                        next_max_val = data_array[find_cnt];
                    next_find_cnt = find_cnt + 1;
                end else begin
                    next_state     = S_COUNT;
                    next_count_cnt = 0;
                end
            end

            //-------------------------------------------------
            S_COUNT: begin
                // N clocks to build the histogram, then 1 clock to transition.
                if (count_cnt < N) begin
                    val = data_array[count_cnt];
                    next_count_array[val] = count_array[val] + 1'b1;
                    next_count_cnt = count_cnt + 1;
                end else begin
                    next_state      = S_PREFIX_SUM;
                    next_prefix_cnt = max_val;   // process index max_val-1 first
                end
            end

            //-------------------------------------------------
            S_PREFIX_SUM: begin
                // max_val clocks to build the cumulative (suffix) histogram,
                // then 1 clock to transition. count_array[v] becomes the number
                // of elements with value >= v, which places the largest element
                // at index 0 (descending), matching the worked examples.
                if (prefix_cnt > 0) begin
                    next_count_array[prefix_cnt-1] =
                        count_array[prefix_cnt-1] + count_array[prefix_cnt];
                    next_prefix_cnt = prefix_cnt - 1;
                end else begin
                    next_state     = S_BUILD_OUTPUT;
                    next_build_cnt = 0;
                end
            end

            //-------------------------------------------------
            S_BUILD_OUTPUT: begin
                // N clocks to place values (scan last->first for stability),
                // then 1 clock to transition.
                if (build_cnt < N) begin
                    val = data_array[(N-1)-build_cnt];
                    pos = count_array[val];
                    next_out_array[pos-1] = val;
                    next_count_array[val] = pos - 1'b1;
                    next_build_cnt = build_cnt + 1;
                end else begin
                    next_state    = S_COPY_OUTPUT;
                    next_copy_cnt = 0;
                end
            end

            //-------------------------------------------------
            S_COPY_OUTPUT: begin
                // 1 clock: pack the unpacked out_array into the out_data bus.
                for (i = 0; i < N; i = i + 1)
                    next_out_data[i*WIDTH +: WIDTH] = out_array[i];
                next_state = S_DONE;
            end

            //-------------------------------------------------
            S_DONE: begin
                // 1 clock: assert done and return to idle. out_data was made
                // stable the cycle before, so a checker sampling on done reads
                // the valid sorted result.
                next_done  = 1'b1;
                next_state = S_IDLE;
            end

            default: next_state = S_IDLE;
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // synchronous reset
            current_state <= S_IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            max_val       <= {WIDTH{1'b0}};

            load_cnt      <= 0;
            find_cnt      <= 0;
            count_cnt     <= 0;
            prefix_cnt    <= 0;
            build_cnt     <= 0;
            copy_cnt      <= 0;

            // Clear arrays
            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= {WIDTH{1'b0}};
                out_array[i]  <= {WIDTH{1'b0}};
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= {($clog2(N)+1){1'b0}};
            end

        end else begin
            // commit the combinationally-computed "next" values
            current_state <= next_state;
            done          <= next_done;
            out_data      <= next_out_data;
            max_val       <= next_max_val;

            load_cnt      <= next_load_cnt;
            find_cnt      <= next_find_cnt;
            count_cnt     <= next_count_cnt;
            prefix_cnt    <= next_prefix_cnt;
            build_cnt     <= next_build_cnt;
            copy_cnt      <= next_copy_cnt;

            for (i = 0; i < N; i = i + 1) begin
                data_array[i] <= next_data_array[i];
                out_array[i]  <= next_out_array[i];
            end
            for (i = 0; i < (1<<WIDTH); i = i + 1) begin
                count_array[i] <= next_count_array[i];
            end
        end
    end

endmodule

module virtual2physical_tlb #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, TLB_SIZE = 4, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    output [PAGE_WIDTH-1:0] physical_address,
    output hit, miss
);
    wire tlb_write_enable, flush, ready;
    wire [PAGE_WIDTH-1:0] page_table_entry;
    TLB #(.TLB_SIZE(TLB_SIZE), .ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH)) tlb (
        .clk(clk),
        .reset(reset),
        .virtual_address(virtual_address),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush),
        .page_table_entry(page_table_entry),
        .physical_address(physical_address),
        .hit(hit),
        .miss(miss)
    );

    PageTableHandler #(.ADDR_WIDTH(ADDR_WIDTH), .PAGE_WIDTH(PAGE_WIDTH), .PAGE_TABLE_SIZE(PAGE_TABLE_SIZE)) page_table_handler(
        .clk(clk),
        .reset(reset),
        .miss(miss),
        .virtual_page(virtual_address),
        .page_table_entry(page_table_entry),
        .ready(ready)
    );

    ControlUnit control_unit (
        .clk(clk),
        .reset(reset),
        .hit(hit),
        .miss(miss),
        .ready(ready),
        .tlb_write_enable(tlb_write_enable),
        .flush(flush)
    );
endmodule

module TLB #(parameter TLB_SIZE = 4, ADDR_WIDTH = 8, PAGE_WIDTH = 8) (
    input clk,
    input reset,
    input [ADDR_WIDTH-1:0] virtual_address,
    input tlb_write_enable,
    input flush,
    input [PAGE_WIDTH-1:0] page_table_entry,
    output reg [PAGE_WIDTH-1:0] physical_address,
    output reg hit,
    output reg miss
);
    // TLB Storage
    reg [ADDR_WIDTH-1:0] virtual_tags[TLB_SIZE-1:0];
    reg [PAGE_WIDTH-1:0] physical_pages[TLB_SIZE-1:0];
    reg [TLB_SIZE-1:0] valid_bits;
    reg [$clog2(TLB_SIZE)-1:0] replacement_index; // Index for the next replacement
    integer i;
    integer j;

    // Update TLB with a new page table entry using a round-robin replacement policy.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < TLB_SIZE; i = i + 1) begin
                virtual_tags[i]   <= {ADDR_WIDTH{1'b0}};
                physical_pages[i] <= {PAGE_WIDTH{1'b0}};
            end
            valid_bits        <= {TLB_SIZE{1'b0}};
            replacement_index <= {$clog2(TLB_SIZE){1'b0}};
        end
        else if (flush) begin
            // Invalidate every entry on a flush request.
            valid_bits        <= {TLB_SIZE{1'b0}};
            replacement_index <= {$clog2(TLB_SIZE){1'b0}};
        end
        else if (tlb_write_enable) begin
            // Install the freshly fetched translation into the next slot.
            virtual_tags[replacement_index]   <= virtual_address;
            physical_pages[replacement_index] <= page_table_entry;
            valid_bits[replacement_index]     <= 1'b1;
            replacement_index                 <= replacement_index + 1'b1;
        end
    end

    // Combinational lookup : assert hit when a valid tag matches.
    always_comb begin
        hit = 0;
        miss = 1;
        physical_address = 0;

        for (j = 0; j < TLB_SIZE; j = j + 1) begin
            if (valid_bits[j] && (virtual_tags[j] == virtual_address)) begin
                hit = 1'b1;
                miss = 1'b0;
                physical_address = physical_pages[j];
            end
        end
    end
endmodule

module PageTableHandler #(parameter ADDR_WIDTH = 8, PAGE_WIDTH = 8, PAGE_TABLE_SIZE = 16) (
    input clk,
    input reset,
    input miss,
    input [ADDR_WIDTH-1:0] virtual_page,
    output reg [PAGE_WIDTH-1:0] page_table_entry,
    output reg ready
);
    // Parameterized Page Table Memory
    reg [PAGE_WIDTH-1:0] page_table_memory [0:PAGE_TABLE_SIZE-1];
 assign   page_table_entry = page_table_memory[virtual_page];
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize Page Table Memory during reset
            page_table_memory[0] <= 8'h0;
            page_table_memory[1] <= 8'h1;
            page_table_memory[2] <= 8'h2;
            page_table_memory[3] <= 8'h3;
            page_table_memory[4] <= 8'h4;
            page_table_memory[5] <= 8'h5;
            page_table_memory[6] <= 8'h6;
            page_table_memory[7] <= 8'h7;
            page_table_memory[8] <= 8'h8;
            page_table_memory[9] <= 8'h9;
            page_table_memory[10] <= 8'hA;
            page_table_memory[11] <= 8'hB;
            page_table_memory[12] <= 8'hC;
            page_table_memory[13] <= 8'hD;
            page_table_memory[14] <= 8'hE;
            page_table_memory[15] <= 8'hF;
            ready = 0;
        end else if (miss) begin
            // Fetch the physical page number from the simulated page table
            ready <= 1; // Indicate the entry is ready
        end else begin
            ready <= 0;
        end
    end
endmodule
module ControlUnit (
    input clk,
    input reset,
    input hit,
    input miss,
    input ready,
    output reg tlb_write_enable,
    output reg flush
);
    reg [1:0] state;

    localparam IDLE = 2'b00,
               FETCH = 2'b01,
               UPDATE = 2'b10;

    // Sequential control : on a miss wait for the page-table handler to become
    // ready, then move through UPDATE for exactly one cycle to install the entry.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end
        else begin
            case (state)
                IDLE:   if (miss)  state <= FETCH;
                FETCH:  if (ready) state <= UPDATE;
                UPDATE:            state <= IDLE;
                default:           state <= IDLE;
            endcase
        end
    end

    // Moore outputs : the TLB write strobe is asserted only in UPDATE, so the
    // translation is latched exactly once and the next lookup is a hit.
    always_comb begin
        tlb_write_enable = (state == UPDATE);
        flush            = 1'b0;
    end

endmodule

// glitch_free_mux : glitch-free switch between two synchronous clocks.
// Cross-coupled per-clock enable registers implement a break-before-make
// handshake so the two clock enables are never asserted at the same time,
// and each enable is retimed in its own clock domain so the AND-gate mask
// only ever toggles while its clock is at the idle (low) level.
module glitch_free_mux (
    input  wire clk1,
    input  wire clk2,
    input  wire sel,     // 0 -> clkout=clk1 , 1 -> clkout=clk2
    input  wire rst_n,   // async active-low, forces clkout low
    output wire clkout
);

    // clk1-domain enable path (2-stage synchroniser of ~sel & ~clk2_en)
    reg q1_meta, q1_en;
    // clk2-domain enable path (2-stage synchroniser of  sel & ~clk1_en)
    reg q2_meta, q2_en;

    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n) begin
            q1_meta <= 1'b0;
            q1_en   <= 1'b0;
        end else begin
            q1_meta <= ~sel & ~q2_en;  // enable clk1 only when sel=0 and clk2 disabled
            q1_en   <= q1_meta;
        end
    end

    always @(posedge clk2 or negedge rst_n) begin
        if (!rst_n) begin
            q2_meta <= 1'b0;
            q2_en   <= 1'b0;
        end else begin
            q2_meta <= sel & ~q1_en;   // enable clk2 only when sel=1 and clk1 disabled
            q2_en   <= q2_meta;
        end
    end

    // Enable de-asserts on the rising edge of its own clock (clock is going
    // high while enable drops -> the previous low phase already ended, so no
    // runt pulse); enable asserts coincident with its clock rising edge.
    assign clkout = (clk1 & q1_en) | (clk2 & q2_en);

endmodule

module axis_resize (

  input                                           clk,          //Global clock signal: Signals are sampled on the rising edge of clk
  input                                           resetn,       //The global reset signal: resetn is synchronous active-LOW reset.

  input                                           s_valid,      //The s_axis_valid signal indicates that the slave is driving a valid transfer.
  output  reg                                     s_ready,      //The s_axis_ready indicates that the slave can accept a transfer in the current cycle.
  input       [15:0]  s_data,                                   //The s_axis_data is the primary payload data from slave.

  output  reg                                     m_valid,      //The m_axis_valid indicates that the master is driving a valid transfer.
  input                                           m_ready,      //The m_axis_ready indicates that the slave can accept a transfer in the current cycle.
  output  reg [7:0] m_data                                      //The m_axis_data is the primary payload data to master.
);

  // A 16-bit slave word is split into two 8-bit master beats.
  // Byte order: high byte first, then low byte.
  reg [15:0] data_hold;   // captured wide word
  reg        phase;       // 0 = first (high) beat, 1 = second (low) beat
  reg        busy;        // draining the two beats

  always @(posedge clk) begin
    if (!resetn) begin
      s_ready   <= 1'b1;
      m_valid   <= 1'b0;
      m_data    <= 8'h00;
      data_hold <= 16'h0000;
      phase     <= 1'b0;
      busy      <= 1'b0;
    end else begin
      if (!busy) begin
        // Idle / ready to accept a new slave word.
        s_ready <= 1'b1;
        if (s_valid && s_ready) begin
          data_hold <= s_data;
          m_data    <= s_data[15:8];   // high byte first
          m_valid   <= 1'b1;
          phase     <= 1'b0;
          busy      <= 1'b1;
          s_ready   <= 1'b0;           // deassert while draining
        end else begin
          m_valid <= 1'b0;
        end
      end else begin
        // Draining the two output beats; do not accept new words.
        s_ready <= 1'b0;
        if (m_valid && m_ready) begin
          if (phase == 1'b0) begin
            m_data  <= data_hold[7:0]; // low byte second
            m_valid <= 1'b1;
            phase   <= 1'b1;
          end else begin
            m_valid <= 1'b0;
            busy    <= 1'b0;
            s_ready <= 1'b1;
          end
        end
      end
    end
  end

endmodule

module clock_jitter_detection_module #(
    parameter JITTER_THRESHOLD = 5    // Threshold (in clock cycles) for detecting jitter
)(
    input logic clk,               // Input clock
    input logic system_clk,        // Input system clock
    input logic rst,               // Active high reset
    output logic jitter_detected   // Output flag indicating jitter detection
);

    // Internal signals
    logic [31:0] edge_count, edge_count_r;   // Counters to measure time between rising edges
    logic prev_system_clk;                   // To store the previous clock state (rising edge detection)
    logic edge_detected;                     // Flag for detecting rising edges
    logic start_counter;                     // High once counting has begun (after first edge)

    // Rising edge detection logic (detects when clock transitions from 0 to 1)
    always @(posedge clk) begin
        if (rst) begin
            edge_count      <= 32'd0;
            edge_count_r    <= 32'd0;
            prev_system_clk <= 1'b0;
            edge_detected   <= 1'b0;
            start_counter   <= 1'b0;
            jitter_detected <= 1'b0;
        end else begin
            prev_system_clk <= system_clk;

            // Detect a rising edge of system_clk
            if (system_clk && !prev_system_clk) begin
                edge_detected <= 1'b1;
                // Store the just-measured period, then restart the counter
                edge_count_r  <= edge_count;
                edge_count    <= 32'd0;
                start_counter <= 1'b1;

                // Compare the measured period against the threshold.  Jitter is
                // flagged when the measured number of clk cycles deviates from
                // JITTER_THRESHOLD by more than one clock cycle.  The first
                // (incomplete) interval is skipped via start_counter.
                if (start_counter &&
                    ((edge_count > (JITTER_THRESHOLD + 1)) ||
                     (edge_count < (JITTER_THRESHOLD - 1))))
                    jitter_detected <= 1'b1;
                else
                    jitter_detected <= 1'b0;
            end else begin
                edge_detected   <= 1'b0;
                if (start_counter)
                    edge_count <= edge_count + 32'd1;   // count clk cycles between edges
                jitter_detected <= 1'b0;                // one-cycle pulse only
            end
        end
    end

endmodule

module dig_stopwatch #(
    parameter CLK_FREQ = 50000000  // Default clock frequency is 50 MHz
)(
    input  wire clk,                // Input clock (parameterized frequency)
    input  wire reset,              // Reset signal (async, active high)
    input  wire start_stop,         // Start/Stop control
    input  wire load,               // Async active-high load
    input  wire [4:0] load_hours,   // Hours to load   (0-23)
    input  wire [5:0] load_minutes, // Minutes to load (0-59)
    input  wire [5:0] load_seconds, // Seconds to load (0-59)
    output reg  [5:0] seconds,      // Seconds counter (0-59)
    output reg  [5:0] minutes,      // Minutes counter (0-59)
    output reg  [4:0] hour          // Hours counter   (0-23)
);

    localparam COUNTER_MAX = CLK_FREQ - 1;  // Calculate max counter value
    reg [$clog2(COUNTER_MAX):0] counter;    // Clock divider counter width based on CLK_FREQ
    reg one_sec_pulse;                      // One second pulse signal

    // Clock divider to create a 1 Hz clock pulse from the parameterized frequency.
    // The divider only advances while start_stop is asserted; when paused it
    // holds its progress toward the current one-second interval.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            one_sec_pulse <= 0;
        end else begin
            if (start_stop) begin
                if (counter == COUNTER_MAX) begin
                    counter <= 0;
                    one_sec_pulse <= 1'b1;        // Generate a pulse every second
                end else begin
                    counter <= counter + 1;
                    one_sec_pulse <= 1'b0;
                end
            end else begin
                one_sec_pulse <= 1'b0;           // Ensure one_sec_pulse is cleared if paused
            end
        end
    end

    // Countdown timer logic.
    // - reset (async) forces 00:00:00 and overrides everything.
    // - load  (async) loads the (range-clamped) preset values.
    // - otherwise the timer decrements once per one_sec_pulse while running,
    //   holding at 00:00:00.
    always @(posedge clk or posedge reset or posedge load) begin
        if (reset) begin
            seconds <= 6'd0;
            minutes <= 6'd0;
            hour    <= 5'd0;
        end else if (load) begin
            hour    <= (load_hours   > 5'd23) ? 5'd23 : load_hours;
            minutes <= (load_minutes > 6'd59) ? 6'd59 : load_minutes;
            seconds <= (load_seconds > 6'd59) ? 6'd59 : load_seconds;
        end else if (start_stop && one_sec_pulse) begin
            if (!(hour == 5'd0 && minutes == 6'd0 && seconds == 6'd0)) begin
                if (seconds != 6'd0) begin
                    seconds <= seconds - 6'd1;
                end else begin
                    seconds <= 6'd59;
                    if (minutes != 6'd0) begin
                        minutes <= minutes - 6'd1;
                    end else begin
                        minutes <= 6'd59;
                        hour    <= hour - 5'd1;  // hour > 0 guaranteed here
                    end
                end
            end
        end
    end

endmodule

module halfband_fir #(
    parameter LGNTAPS = 7,
    parameter IW      = 16,
    parameter TW      = 12,
    parameter OW      = IW + TW + LGNTAPS,
    parameter [LGNTAPS:0] NTAPS        = 107,
    parameter [0:0]       FIXED_TAPS   = 1'b0,
    parameter           INITIAL_COEFFS = "",
    parameter [0:0]       OPT_HILBERT  = 1'b0,
    localparam LGNMEM  = LGNTAPS - 1,
    localparam LGNCOEF = LGNMEM - 1,
    localparam [LGNTAPS-1:0] HALFTAPS = NTAPS[LGNTAPS:1],
    localparam [LGNTAPS-2:0] QTRTAPS  = HALFTAPS[LGNTAPS-1:1] + 1,
    localparam DMEMSZ = (1 << LGNMEM),
    localparam CMEMSZ = (1 << LGNCOEF)
)(
    input  wire i_clk,
    input  wire i_reset,
    input  wire i_tap_wr,
    input  wire [(TW-1):0] i_tap,
    input  wire i_ce,
    input  wire [(IW-1):0] i_sample,
    output reg  o_ce,
    output reg  [(OW-1):0] o_result
);

    reg [3:0] messy_flag;

    reg [TW-1:0] coef_mem_messy [0:CMEMSZ-1];


    reg [IW-1:0] dmem1_messy [0:DMEMSZ-1];
    reg [IW-1:0] dmem2_messy [0:DMEMSZ-1];

    reg [LGNMEM-1:0] write_idx, left_idx, right_idx;
    reg [LGNCOEF-1:0] tap_idx;
    reg signed [IW-1:0] sample_left, sample_right, mid_sample_messy;
    reg signed [IW:0]   sum_data;
    reg clk_en, data_en, sum_en;
    reg signed [IW+TW-1:0] mult_result;
    reg signed [OW-1:0]    acc_result;

    // Control wires:
    wire last_tap_warn, last_data_warn;
    wire [LGNTAPS-2:0] remaining_taps;

    generate
      if (FIXED_TAPS || (INITIAL_COEFFS != "")) begin : LOAD_COEFFS
         initial begin
             $readmemh(INITIAL_COEFFS, coef_mem_messy);
         end
      end else begin : DYNAMIC_COEFFS
         reg [LGNCOEF-1:0] tap_wr_idx;
         initial tap_wr_idx = 0;
         always @(posedge i_clk)
            if (i_reset)
                tap_wr_idx <= 0;
            else if (i_tap_wr)
                tap_wr_idx <= tap_wr_idx + 1'b1;
         always @(posedge i_clk)
            if (i_tap_wr)
                coef_mem_messy[tap_wr_idx] <= i_tap;
      end
    endgenerate


    initial write_idx = 0;
    always @(posedge i_clk) begin
        if (i_ce)
            write_idx <= write_idx + 1;
    end

    always @(posedge i_clk)
      if (i_ce) begin
         dmem1_messy[write_idx] <= i_sample;
         dmem2_messy[write_idx] <= mid_sample_messy;
      end

    always @(posedge i_clk)
    begin
      if (i_reset)
         mid_sample_messy <= 0;
      else if (i_ce)
         mid_sample_messy <= sample_left;
    end

    assign remaining_taps = QTRTAPS - tap_idx;
    assign last_tap_warn = (remaining_taps <= 1);
    assign last_data_warn = (QTRTAPS - tap_idx <= 2);


    initial messy_flag = 4'b0;
    always @(posedge i_clk) begin
      if (i_reset)
        messy_flag[0] <= 1'b0;
      else if (i_ce)
        messy_flag[0] <= 1'b1;
      else if (messy_flag[0] && !last_tap_warn)
        messy_flag[0] <= 1'b1;
      else if (!clk_en)
        messy_flag[0] <= 1'b0;
    end

    always @(posedge i_clk)
      if (i_reset)
         messy_flag[3:1] <= 3'b0;
      else
         messy_flag[3:1] <= { messy_flag[2:1], (clk_en || (messy_flag[0] && !last_tap_warn)) };


    initial begin
      left_idx = 0;
      right_idx = 0;
    end

    always @(posedge i_clk) begin
      if (i_reset) begin
        left_idx <= 0;
        right_idx <= 0;
      end else if (i_ce) begin
        left_idx <= write_idx;
        right_idx <= write_idx - (HALFTAPS[LGNMEM-1:0]) + 1;
      end else if (clk_en || !last_data_warn) begin
        left_idx <= left_idx - 2;
        right_idx <= right_idx + 2;
      end
    end


    initial tap_idx = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         tap_idx <= 0;
      else if (clk_en)
         tap_idx <= 0;
      else if (!last_tap_warn)
         tap_idx <= tap_idx + 1;
    end


    initial clk_en = 1'b0;
    always @(posedge i_clk) begin
      clk_en <= (i_ce && !i_reset);
    end


    initial begin
        sample_left  = 0;
        sample_right = 0;
    end

    always @(posedge i_clk) begin
      sample_left  <= dmem1_messy[left_idx];
      sample_right <= dmem2_messy[right_idx];
    end

    // --- Data Enable Update ---
    initial data_en = 1'b0;
    always @(posedge i_clk)
       data_en <= (clk_en && !i_reset);

    // --- Coefficient Read and Data Sum Computation ---
    reg [TW-1:0] current_coef;
    initial current_coef = 0;
    always @(posedge i_clk)
       current_coef <= coef_mem_messy[tap_idx[LGNCOEF-1:0]];

    initial sum_data = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         sum_data <= 0;
      else if (OPT_HILBERT)
         sum_data <= sample_left - sample_right;
      else
         sum_data <= sample_left + sample_right;
    end

    // --- Summation Enable ---
    initial sum_en = 1'b0;
    always @(posedge i_clk)
       sum_en <= (data_en && !i_reset);

    // --- Multiply Operation ---
    initial mult_result = 0;
    always @(posedge i_clk)
       mult_result <= current_coef * sum_data;

       wire [OW-1:0] mid_prod;
    generate
      if (OPT_HILBERT) begin : NO_MIDPOINT
         assign mid_prod = 0;
      end else begin : GEN_MIDPOINT
         reg [OW-1:0] mid_prod_reg;
         initial mid_prod_reg = 0;
         always @(posedge i_clk) begin
            if (i_reset)
               mid_prod_reg <= 0;
            else if (clk_en)
               mid_prod_reg <= { {(OW-IW-TW+1){mid_sample_messy[IW-1]}},
                                  mid_sample_messy, {(TW-1){1'b0}} }
                              - { {(OW-IW){mid_sample_messy[IW-1]}},
                                  mid_sample_messy };
         end
         assign mid_prod = mid_prod_reg;
      end
    endgenerate

    // --- Accumulation ---
    initial acc_result = 0;
    always @(posedge i_clk) begin
      if (i_reset)
         acc_result <= 0;
      else if (sum_en)
         acc_result <= mid_prod;
      else if (messy_flag[3])
         acc_result <= acc_result + { {(OW-(IW+TW)){mult_result[IW+TW-1]}}, mult_result };
    end

    // --- Output Assignments ---
    initial o_result = 0;
    always @(posedge i_clk)
       if (sum_en)
          o_result <= acc_result;

    // --- Output Clock Enable Update ---
    initial o_ce = 1'b0;
    always @(posedge i_clk)
       o_ce <= (sum_en && !i_reset);

endmodule

module line_buffer #(
    parameter NBW_DATA  = 'd8,  // Bit width of grayscale input/output data
    parameter NS_ROW    = 'd10, // Number of rows
    parameter NS_COLUMN = 'd8,  // Number of columns
    parameter NBW_ROW   = 'd4,  // log2(NS_ROW). Bit width of i_image_row_start
    parameter NBW_COL   = 'd3,  // log2(NS_COLUMN). Bit width of i_image_col_start
    parameter NBW_MODE  = 'd3,  // Bit width of mode input
    parameter NS_R_OUT  = 'd4,  // Number of rows of the output window
    parameter NS_C_OUT  = 'd3,  // Number of columns of the output window
    parameter CONSTANT  = 'd255 // Constant value to use in PAD_CONSTANT mode
) (
    input  logic                                  clk,
    input  logic                                  rst_async_n,
    input  logic [NBW_MODE-1:0]                   i_mode,
    input  logic                                  i_valid,
    input  logic                                  i_update_window,
    input  logic [NBW_DATA*NS_COLUMN-1:0]         i_row_image,
    input  logic [NBW_ROW-1:0]                    i_image_row_start,
    input  logic [NBW_COL-1:0]                    i_image_col_start,
    output logic [NBW_DATA*NS_R_OUT*NS_C_OUT-1:0] o_image_window
);

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
logic [NBW_DATA-1:0] image_buffer_ff [NS_ROW][NS_COLUMN];
logic [NBW_DATA-1:0] row_image [NS_COLUMN];
logic [NBW_DATA-1:0] window [NS_R_OUT][NS_C_OUT];
logic [NBW_DATA*NS_R_OUT*NS_C_OUT-1:0] image_window_ff;

// ----------------------------------------
// - Output generation
// ----------------------------------------
// BUGFIX: the window row index must use `row` (mapped to the buffer row
// dimension via i_image_row_start) and the window column index must use
// `col` (mapped to the buffer column dimension via i_image_col_start).
// The original code swapped `row` and `col`, transposing every window.
// The MIRROR_BOUND column reflection also needs 2*NS_COLUMN-1 (matching
// the row reflection form) rather than NS_COLUMN-1.
always_comb begin : window_assignment
    case(i_mode)
        3'd0: begin // NO_BOUND_PROCESS
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    if(i_image_row_start + row >= NS_ROW) begin
                        window[row][col] = 0;
                    end else if (i_image_col_start + col >= NS_COLUMN) begin
                        window[row][col] = 0;
                    end else begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][i_image_col_start + col];
                    end
                end
            end
        end
        3'd1: begin // PAD_CONSTANT
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    if(i_image_row_start + row >= NS_ROW) begin
                        window[row][col] = CONSTANT;
                    end else if (i_image_col_start + col >= NS_COLUMN) begin
                        window[row][col] = CONSTANT;
                    end else begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][i_image_col_start + col];
                    end
                end
            end
        end
        3'd2: begin // EXTEND_NEAR
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    if(i_image_row_start + row >= NS_ROW) begin
                        window[row][col] = image_buffer_ff[NS_ROW-1][i_image_col_start + col];
                    end else if (i_image_col_start + col >= NS_COLUMN) begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][NS_COLUMN-1];
                    end else begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][i_image_col_start + col];
                    end
                end
            end
        end
        3'd3: begin // MIRROR_BOUND
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    if(i_image_row_start + row >= NS_ROW) begin
                        window[row][col] = image_buffer_ff[2*NS_ROW-1-(i_image_row_start + row)][i_image_col_start + col];
                    end else if (i_image_col_start + col >= NS_COLUMN) begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][2*NS_COLUMN-1-(i_image_col_start + col)];
                    end else begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][i_image_col_start + col];
                    end
                end
            end
        end
        3'd4: begin // WRAP_AROUND
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    if(i_image_row_start + row >= NS_ROW) begin
                        window[row][col] = image_buffer_ff[(i_image_row_start + row)-NS_ROW][i_image_col_start + col];
                    end else if (i_image_col_start + col >= NS_COLUMN) begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][(i_image_col_start + col)-NS_COLUMN];
                    end else begin
                        window[row][col] = image_buffer_ff[i_image_row_start + row][i_image_col_start + col];
                    end
                end
            end
        end
        default: begin
            for (int row = 0; row < NS_R_OUT; row++) begin
                for (int col = 0; col < NS_C_OUT; col++) begin
                    window[row][col] = 0;
                end
            end
        end
    endcase
end

// ----------------------------------------
// - Input control
// ----------------------------------------
generate
    for (genvar col = 0; col < NS_COLUMN; col++) begin : unpack_row_image
        assign row_image[NS_COLUMN-col-1] = i_row_image[(col+1)*NBW_DATA-1-:NBW_DATA];
    end
endgenerate

always_ff @(posedge clk or negedge rst_async_n) begin : ctrl_regs
    if(~rst_async_n) begin
        image_window_ff <= 0;
        for (int row = 0; row < NS_ROW; row++) begin
            for (int col = 0; col < NS_COLUMN; col++) begin
                image_buffer_ff[row][col] <= 0;
            end
        end
    end else begin
        if(i_valid) begin
            for (int col = 0; col < NS_COLUMN; col++) begin
                image_buffer_ff[0][col] <= row_image[col];
            end

            for (int row = 1; row < NS_ROW; row++) begin
                for (int col = 0; col < NS_COLUMN; col++) begin
                    image_buffer_ff[row][col] <= image_buffer_ff[row-1][col];
                end
            end
        end

        if(i_update_window) begin
            image_window_ff <= o_image_window;
        end
    end
end

// ----------------------------------------
// - Output packing
// ----------------------------------------
generate
    for(genvar row = 0; row < NS_R_OUT; row++) begin : out_row
        for(genvar col = 0; col < NS_C_OUT; col++) begin : out_col
            always_comb begin
                if(i_update_window) begin
                    o_image_window[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA] = window[row][col];
                end else begin
                    o_image_window[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA] = image_window_ff[(row*NS_C_OUT+col+1)*NBW_DATA-1-:NBW_DATA];
                end
            end
        end
    end
endgenerate

endmodule : line_buffer

module ping_pong_buffer (
    input logic clk,
    input logic rst_n,
    input logic write_enable,
    input logic read_enable,
    input logic [7:0] data_in,
    output logic [7:0] data_out,
    output logic buffer_full,
    output logic buffer_empty,
    output reg buffer_select
);

    localparam DEPTH = 256;
    localparam ADDR_WIDTH = 8;

    logic [ADDR_WIDTH-1:0] write_ptr, read_ptr;
    logic [7:0] data_out0, data_out1;

    // Write enable per bank: only the active (buffer_select) bank is written,
    // and only when the buffer is not full.
    logic we0, we1;
    assign we0 = write_enable & ~buffer_full & (buffer_select == 1'b0);
    assign we1 = write_enable & ~buffer_full & (buffer_select == 1'b1);

    // Dual port memories are instantiated here
    dual_port_memory memory0 (
        .clk        (clk),
        .we         (we0),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out0)
    );

    dual_port_memory memory1 (
        .clk        (clk),
        .we         (we1),
        .write_addr (write_ptr),
        .din        (data_in),
        .read_addr  (read_ptr),
        .dout       (data_out1)
    );

    // Data is read from the buffer designated by buffer_select.
    assign data_out = (buffer_select) ? data_out1 : data_out0;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            write_ptr     <= '0;
            read_ptr      <= '0;
            buffer_select <= 1'b0;
            buffer_full   <= 1'b0;
            buffer_empty  <= 1'b1;
        end else begin
            // ---------------- Write operation ----------------
            if (write_enable && !buffer_full) begin
                buffer_empty <= 1'b0;
                if (write_ptr == ADDR_WIDTH'(DEPTH-1)) begin
                    // Buffer reached capacity: mark full, wrap and toggle bank.
                    write_ptr     <= '0;
                    buffer_full   <= 1'b1;
                    buffer_select <= ~buffer_select;
                end else begin
                    write_ptr <= (write_ptr + 1'b1) % DEPTH;
                end
            end

            // ---------------- Read operation -----------------
            if (read_enable && !buffer_empty) begin
                buffer_full <= 1'b0;
                if (read_ptr == ADDR_WIDTH'(DEPTH-1)) begin
                    // End of buffer reached: wrap, toggle bank, mark empty.
                    read_ptr      <= '0;
                    buffer_empty  <= 1'b1;
                    buffer_select <= ~buffer_select;
                end else begin
                    read_ptr <= (read_ptr + 1'b1) % DEPTH;
                end
            end
        end
    end

endmodule

module dual_port_memory (
    input logic clk,
    input logic we,
    input logic [7:0] write_addr,
    input logic [7:0] din,
    input logic [7:0] read_addr,
    output logic [7:0] dout
);

    logic [7:0] mem [255:0];

    always_ff @(posedge clk) begin
        if (we) begin
            mem[write_addr] <= din;
        end
    end

    assign dout = mem[read_addr];
endmodule

module sdram_controller (clk,reset,addr,data_in,data_out,read,write,sdram_clk,sdram_cke,sdram_cs,sdram_ras,sdram_cas,sdram_we,sdram_addr,sdram_ba,sdram_dq,dq_out);

    input             clk;        // System clock
    input             reset;      // Asynchronous active-high reset
    input      [23:0] addr;       // 24-bit address for SDRAM access
    input      [15:0] data_in;    // 16-bit write data
    output reg [15:0] data_out;   // 16-bit read data
    input             read;       // Read request
    input             write;      // Write request

    output            sdram_clk;  // Clock forwarded to the SDRAM
    output reg        sdram_cke;  // Clock enable
    output reg        sdram_cs;   // Chip select
    output reg        sdram_ras;  // Row address strobe
    output reg        sdram_cas;  // Column address strobe
    output reg        sdram_we;   // Write enable
    output reg [11:0] sdram_addr; // Address bus (row / column)
    output reg [1:0]  sdram_ba;   // Bank select
    input      [15:0] sdram_dq;   // 16-bit data bus from SDRAM (read)
    output reg [15:0] dq_out;     // 16-bit data bus to SDRAM (write)

    // FSM state encoding
    localparam INIT     = 3'd0,
               IDLE     = 3'd1,
               ACTIVATE = 3'd2,
               READ     = 3'd3,
               WRITE    = 3'd4,
               REFRESH  = 3'd5;

    reg [2:0]  state;
    reg [3:0]  init_cnt;      // counts the 10-cycle init sequence
    reg [10:0] refresh_cnt;   // counts idle cycles up to 1024

    // Forward the system clock to the SDRAM
    assign sdram_clk = clk;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= INIT;
            init_cnt    <= 4'd0;
            refresh_cnt <= 11'd0;
            data_out    <= 16'd0;
            dq_out      <= 16'd0;

            sdram_cke   <= 1'b1;
            sdram_cs    <= 1'b0;
            sdram_ras   <= 1'b0;
            sdram_cas   <= 1'b0;
            sdram_we    <= 1'b0;
            sdram_addr  <= 12'd0;
            sdram_ba    <= 2'd0;
        end else begin
            // Default (NOP-like) command each cycle; states override as needed
            sdram_cke <= 1'b1;
            sdram_cs  <= 1'b0;
            sdram_ras <= 1'b0;
            sdram_cas <= 1'b0;
            sdram_we  <= 1'b0;

            case (state)
                INIT: begin
                    if (init_cnt == 4'd9) begin
                        init_cnt <= 4'd0;
                        state    <= IDLE;
                    end else begin
                        init_cnt <= init_cnt + 4'd1;
                    end
                end

                IDLE: begin
                    if (read || write) begin
                        // Activate command
                        sdram_cs   <= 1'b1;
                        sdram_ras  <= 1'b1;
                        sdram_cas  <= 1'b1;
                        sdram_ba   <= addr[23:22];
                        sdram_addr <= addr[21:10];   // row address
                        refresh_cnt <= 11'd0;
                        state      <= ACTIVATE;
                    end else if (refresh_cnt == 11'd1023) begin
                        // Auto refresh command
                        sdram_cs  <= 1'b1;
                        sdram_ras <= 1'b1;
                        sdram_cas <= 1'b1;
                        sdram_we  <= 1'b0;
                        refresh_cnt <= 11'd0;
                        state     <= REFRESH;
                    end else begin
                        refresh_cnt <= refresh_cnt + 11'd1;
                    end
                end

                ACTIVATE: begin
                    // Move to READ or WRITE based on the request
                    sdram_addr <= {2'b00, addr[9:0]}; // column address
                    sdram_ba   <= addr[23:22];
                    if (read)       state <= READ;
                    else if (write) state <= WRITE;
                    else            state <= IDLE;
                end

                READ: begin
                    // Read command
                    sdram_cs  <= 1'b1;
                    sdram_cke <= 1'b1;
                    sdram_ras <= 1'b0;
                    sdram_cas <= 1'b1;
                    sdram_we  <= 1'b0;
                    data_out  <= sdram_dq;
                    state     <= IDLE;
                end

                WRITE: begin
                    // Write command
                    sdram_cs  <= 1'b1;
                    sdram_cke <= 1'b1;
                    sdram_ras <= 1'b0;
                    sdram_cas <= 1'b1;
                    sdram_we  <= 1'b1;
                    dq_out    <= data_in;
                    state     <= IDLE;
                end

                REFRESH: begin
                    // Refresh cycle complete, return to idle
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-------------------------------------------------
    // Local Parameters & Functions
    //-------------------------------------------------
    localparam IDLE  = 0;
    localparam LOAD  = 1;
    localparam SORT  = 2;
    localparam MERGE = 3;
    // NOTE: terminal DONE state removed (area + 1-cycle latency optimization)

    // Function to compute floor(log2(value)) at compile time
    function integer clog2;
        input integer value;
        integer i;
        begin
            clog2 = 0;
            for (i = 1; i < value; i = i << 1) begin
                clog2 = clog2 + 1;
            end
        end
    endfunction

    // Area optimization: merge-sort indices never exceed 2*N (max value
    // reached is N < 2*N), so clog2(2*N) bits are provably sufficient,
    // replacing the original clog2(4*N)+1-bit / 32-bit `integer` datapath.
    localparam ADDR_WIDTH = clog2(2 * N);

    //-------------------------------------------------
    // Internal Signals
    //-------------------------------------------------
    // Only 4 states now (IDLE..MERGE) -> 2-bit state register.
    reg [1:0]                 state;

    // Internal memory of N elements
    reg [WIDTH-1:0]           data_mem [0:N-1];

    // Indices and counters with bounded bit-width
    reg [ADDR_WIDTH-1:0]      base_idx;
    reg [ADDR_WIDTH-1:0]      left_idx;
    reg [ADDR_WIDTH-1:0]      right_idx;
    reg [ADDR_WIDTH-1:0]      subarray_size;

    // Area optimization: merge_idx is always exactly (left_idx + right_idx)
    // during a merge, so it is derived combinationally instead of stored,
    // removing an entire index register.
    wire [ADDR_WIDTH-1:0]     merge_idx = left_idx + right_idx;

    // Temporary buffer for merged sub-array
    reg [WIDTH-1:0]           tmp_merge [0:N-1];

    // Temporary registers for current left/right values
    reg [WIDTH-1:0]           left_val;
    reg [WIDTH-1:0]           right_val;

    integer i, k;
    // Area optimization: bounded-width address arithmetic replaces 32-bit `integer`.
    reg [ADDR_WIDTH-1:0] left_end, right_end;
    reg [ADDR_WIDTH-1:0] l_addr,    r_addr;

    //-------------------------------------------------
    // State Machine
    //-------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset
            state         <= IDLE;
            done          <= 1'b0;
            base_idx      <= 0;
            left_idx      <= 0;
            right_idx     <= 0;
            subarray_size <= 1;
        end else begin
            case (state)

                //----------------------------------
                // IDLE: Wait for start signal
                //----------------------------------
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                //----------------------------------
                // LOAD: Copy from in_data to data_mem
                //----------------------------------
                LOAD: begin
                    for (i = 0; i < N; i = i + 1) begin
                        data_mem[i] <= in_data[i*WIDTH +: WIDTH];
                    end

                    // Initialize for sorting
                    base_idx      <= 0;
                    left_idx      <= 0;
                    right_idx     <= 0;
                    subarray_size <= 1;

                    state <= SORT;
                end

                //----------------------------------
                // SORT: Each pass merges sub-arrays of size subarray_size.
                //       On completion, assert done in the SAME cycle (the
                //       terminal DONE state has been folded in here) so the
                //       result appears one cycle earlier than the original.
                //----------------------------------
                SORT: begin
                    if (subarray_size >= N) begin
                        done  <= 1'b1;      // folded terminal output
                        state <= IDLE;
                    end else begin
                        // Prepare to merge pairs of sub-arrays
                        base_idx  <= 0;
                        left_idx  <= 0;
                        right_idx <= 0;
                        state     <= MERGE;
                    end
                end

                //----------------------------------
                // MERGE: Merge one pair of sub-arrays
                //----------------------------------
                MERGE: begin
                    // Compare/pick smaller
                    if ((l_addr <= left_end) && (r_addr <= right_end)) begin
                        if (left_val <= right_val) begin
                            tmp_merge[merge_idx] <= left_val;
                            left_idx <= left_idx + 1;
                        end else begin
                            tmp_merge[merge_idx] <= right_val;
                            right_idx <= right_idx + 1;
                        end
                    end
                    else if (l_addr <= left_end) begin
                        // Only left sub-array has data
                        tmp_merge[merge_idx] <= left_val;
                        left_idx <= left_idx + 1;
                    end
                    else if (r_addr <= right_end) begin
                        // Only right sub-array has data
                        tmp_merge[merge_idx] <= right_val;
                        right_idx <= right_idx + 1;
                    end
                    else begin
                        // Both sub-arrays are exhausted => write back merged results
                        for (k = 0; k < N; k = k + 1) begin
                            if ( (k < merge_idx) && (k < (subarray_size << 1)) && ((base_idx + k) < N) )
                            begin
                                data_mem[base_idx + k] <= tmp_merge[k];
                            end
                        end

                        // Move base_idx to next pair of sub-arrays
                        base_idx  <= base_idx + (subarray_size << 1);
                        left_idx  <= 0;
                        right_idx <= 0;

                        // If we merged all pairs in this pass, double subarray_size
                        if ((base_idx + (subarray_size << 1)) >= N) begin
                            subarray_size <= subarray_size << 1;
                            state         <= SORT;
                        end
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    //-------------------------------------------------
    // Combinational address / operand computation
    //-------------------------------------------------
    always @ (*) begin
        if (state == MERGE) begin
            left_end  = base_idx + subarray_size - 1;
            right_end = base_idx + (subarray_size << 1) - 1;

            // Boundaries of left and right sub-arrays
            if (left_end >= N) left_end = N - 1;
            if (right_end >= N) right_end = N - 1;

            // Calculate addresses
            l_addr = base_idx + left_idx;
            r_addr = base_idx + subarray_size + right_idx;

            // Safe read for left_val
            if ((l_addr <= left_end) && (l_addr < N))
                left_val = data_mem[l_addr];
            else
                left_val = {WIDTH{1'b1}};

            // Safe read for right_val
            if ((r_addr <= right_end) && (r_addr < N))
                right_val = data_mem[r_addr];
            else
                right_val = {WIDTH{1'b1}};
        end else begin
            left_end  = 0;
            right_end = 0;
            l_addr    = 0;
            r_addr    = 0;
            left_val  = 0;
            right_val = 0;
        end
    end

    //-------------------------------------------------
    // Output: driven combinationally as a fixed concatenation of the
    // sorted memory array (no output register / mux network).
    //-------------------------------------------------
    integer oi;
    always @(*) begin
        for (oi = 0; oi < N; oi = oi + 1) begin
            out_data[oi*WIDTH +: WIDTH] = data_mem[oi];
        end
    end

endmodule

// Wishbone (single-transfer master) to AHB (single-transfer slave) bridge.
module wishbone_to_ahb_bridge (
  // Wishbone slave interface (from WB master)
  input  logic        clk_i,
  input  logic        rst_i,     // active-low reset
  input  logic        cyc_i,
  input  logic        stb_i,
  input  logic [3:0]  sel_i,
  input  logic        we_i,
  input  logic [31:0] addr_i,
  input  logic [31:0] data_i,
  output logic [31:0] data_o,
  output logic        ack_o,

  // AHB master interface (to AHB slave)
  input  logic        hclk,
  input  logic        hreset_n,  // active-low reset
  input  logic [31:0] hrdata,
  input  logic [1:0]  hresp,
  input  logic        hready,
  output logic [1:0]  htrans,
  output logic [2:0]  hsize,
  output logic [2:0]  hburst,
  output logic        hwrite,
  output logic [31:0] haddr,
  output logic [31:0] hwdata
);

  // AHB HTRANS encodings
  localparam logic [1:0] HTRANS_IDLE   = 2'b00;
  localparam logic [1:0] HTRANS_BUSY   = 2'b01;
  localparam logic [1:0] HTRANS_NONSEQ = 2'b10;

  // Bridge FSM states
  localparam logic [1:0] S_IDLE = 2'b00;
  localparam logic [1:0] S_ADDR = 2'b01; // AHB address phase
  localparam logic [1:0] S_DATA = 2'b10; // AHB data phase

  // Only SINGLE bursts are generated.
  assign hburst = 3'b000;

  reg [1:0]  state;
  reg [3:0]  sel_q;
  reg [31:0] data_q;

  // Byte-enable -> AHB transfer size.
  function automatic [2:0] size_from_sel(input [3:0] s);
    case (s)
      4'b1111:          size_from_sel = 3'b010; // word
      4'b0011, 4'b1100: size_from_sel = 3'b001; // halfword
      default:          size_from_sel = 3'b000; // byte
    endcase
  endfunction

  // Byte-enable -> low address bits (address fixing).
  function automatic [1:0] alow_from_sel(input [3:0] s);
    casez (s)
      4'b???1: alow_from_sel = 2'b00;
      4'b??10: alow_from_sel = 2'b01;
      4'b?100: alow_from_sel = 2'b10;
      4'b1000: alow_from_sel = 2'b11;
      default: alow_from_sel = 2'b00;
    endcase
  endfunction

  wire bridge_rst = (~rst_i) | (~hreset_n);

  always @(posedge clk_i or posedge bridge_rst) begin
    if (bridge_rst) begin
      state   <= S_IDLE;
      htrans  <= HTRANS_IDLE;
      hsize   <= 3'b010;
      hwrite  <= 1'b0;
      haddr   <= 32'b0;
      hwdata  <= 32'b0;
      data_o  <= 32'b0;
      ack_o   <= 1'b0;
      sel_q   <= 4'b0;
      data_q  <= 32'b0;
    end else begin
      ack_o <= 1'b0; // ack is a single-cycle pulse
      case (state)
        S_IDLE: begin
          htrans <= HTRANS_IDLE;
          if (cyc_i && stb_i) begin
            // Launch the AHB address phase.
            haddr  <= {addr_i[31:2], alow_from_sel(sel_i)};
            hsize  <= size_from_sel(sel_i);
            hwrite <= we_i;
            htrans <= HTRANS_NONSEQ;
            sel_q  <= sel_i;
            data_q <= data_i;
            state  <= S_ADDR;
          end
        end

        S_ADDR: begin
          // Address phase held until the slave is ready to accept it.
          if (hready) begin
            htrans <= HTRANS_IDLE;   // single transfer -> back to IDLE trans
            hwdata <= data_q;        // drive write data in the data phase
            state  <= S_DATA;
          end
        end

        S_DATA: begin
          // Data phase completes when hready is asserted.
          if (hready) begin
            data_o <= hrdata;        // capture read data
            ack_o  <= 1'b1;          // acknowledge the Wishbone cycle
            state  <= S_IDLE;
          end
        end

        default: state <= S_IDLE;
      endcase
    end
  end

endmodule

module iir_filter (
    input logic clk,
    input logic rst,
    input logic signed [15:0] x,
    output logic signed [15:0] y
);

    parameter signed [15:0] b0 = 16'h0F00;
    parameter signed [15:0] b1 = 16'h0E00;
    parameter signed [15:0] b2 = 16'h0D00;
    parameter signed [15:0] b3 = 16'h0C00;
    parameter signed [15:0] b4 = 16'h0B00;
    parameter signed [15:0] b5 = 16'h0A00;
    parameter signed [15:0] b6 = 16'h0900;
    parameter signed [15:0] a1 = -16'h0800;
    parameter signed [15:0] a2 = -16'h0700;
    parameter signed [15:0] a3 = -16'h0600;
    parameter signed [15:0] a4 = -16'h0500;
    parameter signed [15:0] a5 = -16'h0400;
    parameter signed [15:0] a6 = -16'h0300;
    // FIX (unused parameter): `unused_param` was declared but never referenced.
    //     Removed — it drove no logic.

    logic signed [15:0] x_prev1, x_prev2, x_prev3, x_prev4, x_prev5, x_prev6;
    logic signed [15:0] y_prev1, y_prev2, y_prev3, y_prev4, y_prev5, y_prev6;

    logic signed [31:0] temp_y;
    // FIX (undriven signal): `undriven_signal` was written but never read.
    //     Removed — it was a dangling net contributing nothing to the design.

    // FIX (combinational logic in a sequential block): the multiply-accumulate
    //     that computes temp_y was performed with a blocking `=` inside the
    //     always_ff. Moved to always_comb so no latch/combinational logic hides
    //     in the clocked process. The arithmetic (all taps, the >>>16 fixed-point
    //     rescale) is preserved bit-for-bit — this is a lint fix, not a
    //     functional change.
    always_comb begin
        temp_y = (b0 * x + b1 * x_prev1 + b2 * x_prev2 + b3 * x_prev3 +
                  b4 * x_prev4 + b5 * x_prev5 + b6 * x_prev6 -
                  a1 * y_prev1 - a2 * y_prev2 - a3 * y_prev3 -
                  a4 * y_prev4 - a5 * y_prev5 - a6 * y_prev6) >>> 16;
    end

    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            x_prev1 <= 0; x_prev2 <= 0; x_prev3 <= 0;
            x_prev4 <= 0; x_prev5 <= 0; x_prev6 <= 0;
            y_prev1 <= 0; y_prev2 <= 0; y_prev3 <= 0;
            y_prev4 <= 0; y_prev5 <= 0; y_prev6 <= 0;
            // FIX (uninitialized register): `y` had no reset value. Give the
            //     output register a defined reset state.
            y       <= 16'sd0;
        end else begin
            // FIX (width mismatch): `y` (16b) was assigned from `temp_y` (32b)
            //     via an implicit truncation. Use an EXPLICIT 16-bit cast, and
            //     preserve the original saturation branch as a priority mux so
            //     the transfer function is unchanged.
            y <= (x > 16'h8000) ? 16'h7FFF : 16'(temp_y);

            x_prev6 <= x_prev5; x_prev5 <= x_prev4; x_prev4 <= x_prev3;
            x_prev3 <= x_prev2; x_prev2 <= x_prev1; x_prev1 <= x;
            y_prev6 <= y_prev5; y_prev5 <= y_prev4; y_prev4 <= y_prev3;
            y_prev3 <= y_prev2; y_prev2 <= y_prev1; y_prev1 <= y;
        end
    end

endmodule

// AXI-Stream data upsizer : upscales a single channel from 24-bit to 32-bit,
// with data-format control (offset-binary / two's-complement MSB carry and
// optional sign extension), keeping a single pipeline register stage.
module axis_upscale (
    input  wire        clk,          // Global clock
    input  wire        resetn,       // Active-low synchronous reset
    input  wire        dfmt_enable,  // Data format enable
    input  wire        dfmt_type,    // 1 = invert MSB carry, 0 = pass MSB
    input  wire        dfmt_se,      // 1 = sign extend, 0 = zero extend
    input  wire        s_axis_valid, // Slave driving a valid transfer
    input  wire [23:0] s_axis_data,  // Slave payload data
    input  wire        m_axis_ready, // Master can accept a transfer
    output wire        s_axis_ready, // Slave can accept a transfer
    output reg         m_axis_valid, // Master driving a valid transfer
    output reg  [31:0] m_axis_data   // Master payload data
);

    // Adjusted MSB that is carry-forwarded to bit [23].
    wire        msb_adj    = dfmt_type ? ~s_axis_data[23] : s_axis_data[23];

    // Upper 8 extension bits : sign-extend the adjusted MSB or fill with zeros.
    wire [7:0]  ext_bits   = dfmt_se ? {8{msb_adj}} : 8'b0;

    // Formatted output when data-format processing is enabled.
    wire [31:0] formatted  = {ext_bits, msb_adj, s_axis_data[22:0]};

    // Plain zero-extension when data-format processing is disabled.
    wire [31:0] passthrough = {8'b0, s_axis_data};

    wire [31:0] data_next  = dfmt_enable ? formatted : passthrough;

    // Ready to accept whenever the single output register is free or draining.
    assign s_axis_ready = m_axis_ready | ~m_axis_valid;

    always @(posedge clk) begin
        if (!resetn) begin
            m_axis_valid <= 1'b0;
            m_axis_data  <= 32'b0;
        end
        else if (s_axis_ready) begin
            m_axis_valid <= s_axis_valid;
            m_axis_data  <= data_next;
        end
    end

endmodule

module coffee_machine #(
    parameter NBW_DLY    = 'd5,
    parameter NBW_BEANS  = 'd2,
    parameter NS_BEANS   = 'd4,
    parameter NS_OP      = 'd3, // Fixed
    parameter NS_SENSOR  = 'd4  // Fixed
) (
    input  logic                 clk,
    input  logic                 rst_async_n,
    input  logic [NBW_DLY-1:0]   i_grind_delay,
    input  logic [NBW_DLY-1:0]   i_heat_delay,
    input  logic [NBW_DLY-1:0]   i_pour_delay,
    input  logic [NBW_BEANS-1:0] i_bean_sel,
    input  logic [NS_OP-1:0]     i_operation_sel,
    input  logic                 i_start,
    input  logic [NS_SENSOR-1:0] i_sensor,
    output logic [NS_BEANS-1:0]  o_bean_sel,
    output logic                 o_grind_beans,
    output logic                 o_use_powder,
    output logic                 o_heat_water,
    output logic                 o_pour_coffee,
    output logic                 o_error
);

// Fixed delays (bean selection and powder usage)
localparam SEL_CYCLES    = 'd3;
localparam POWDER_CYCLES = 'd2;

typedef enum logic [2:0] {
    IDLE     = 3'b000,
    BEAN_SEL = 3'b001,
    GRIND    = 3'b011,
    POWDER   = 3'b111,
    HEAT     = 3'b110,
    POUR     = 3'b100
} state_t;

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
state_t state_ff, state_nx;
logic [NBW_DLY:0]     counter_ff, counter_nx;
logic [NBW_DLY-1:0]   grind_delay_ff, heat_delay_ff, pour_delay_ff;
logic [NS_OP-1:0]     operation_sel_ff;
logic [NBW_BEANS-1:0] bean_sel_in_ff;
logic                 start_ff;

// Output assignment (error conditions)
always_comb begin : error_logic
    if(state_ff == IDLE) begin
        o_error = (i_sensor[0] | i_sensor[3]) | (&i_operation_sel[2:1]) | (i_operation_sel[1] & i_sensor[1]) | ((i_operation_sel == 3'b001 || i_operation_sel == 3'b100) & i_sensor[2]);
    end else begin
        o_error = i_sensor[3];
    end
end

// ----------------------------------------
// - Registers
// ----------------------------------------
always_ff @(posedge clk) begin : data_regs
    start_ff <= i_start & ~(i_sensor[0] | i_sensor[3]) & ~(&i_operation_sel[2:1]) & ~(i_operation_sel[1] & i_sensor[1]) & ~((i_operation_sel == 3'b100 || i_operation_sel == 3'b001) & i_sensor[2]);

    if(i_start && state_ff == IDLE) begin
        operation_sel_ff <= i_operation_sel;
        grind_delay_ff   <= i_grind_delay;
        heat_delay_ff    <= i_heat_delay;
        pour_delay_ff    <= i_pour_delay;
        bean_sel_in_ff   <= i_bean_sel;
    end

    counter_ff      <= counter_nx;
end

always_ff @(posedge clk or negedge rst_async_n) begin : reset_regs
    if(~rst_async_n) begin
        state_ff <= IDLE;
    end else begin
        state_ff <= state_nx;
    end
end

// ----------------------------------------
// - FSM update
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            counter_nx = 0;

            if(start_ff) begin
                if(~(|i_operation_sel[2:1])) begin
                    state_nx = HEAT;
                end else if(i_operation_sel[1]) begin
                    state_nx = BEAN_SEL;
                end else if(i_operation_sel[0]) begin
                    state_nx = POUR;
                end else begin
                    state_nx = POWDER;
                end
            end else begin
                state_nx = IDLE;
            end
        end
        BEAN_SEL: begin
            if(counter_ff >= (SEL_CYCLES-1)) begin
                counter_nx = 0;
                state_nx   = GRIND;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = BEAN_SEL;
            end
        end
        GRIND: begin
            if(counter_ff >= (grind_delay_ff-1)) begin
                counter_nx = 0;
                if(operation_sel_ff[0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = HEAT;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = GRIND;
            end
        end
        POWDER: begin
            if(counter_ff >= (POWDER_CYCLES-1)) begin
                counter_nx = 0;
                state_nx   = POUR;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POWDER;
            end
        end
        HEAT: begin
            if(counter_ff >= (heat_delay_ff-1)) begin
                counter_nx = 0;
                if(|operation_sel_ff[1:0]) begin
                    state_nx = POWDER;
                end else begin
                    state_nx = POUR;
                end
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = HEAT;
            end
        end
        POUR: begin
            if(counter_ff >= (pour_delay_ff-1)) begin
                counter_nx = 0;
                state_nx   = IDLE;
            end else begin
                counter_nx = counter_ff + 1'b1;
                state_nx   = POUR;
            end
        end
        default: begin
            counter_nx = 0;
            state_nx   = IDLE;
        end
    endcase

    // Generic-error (i_sensor[3]) may occur mid-operation and MUST force IDLE.
    if(state_ff != IDLE && i_sensor[3]) begin
        state_nx   = IDLE;
        counter_nx = 0;
    end
end

// ----------------------------------------
// - Controller outputs
// ----------------------------------------
always_comb begin
    case(state_ff)
        IDLE: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_use_powder    = 1'b0;
            o_grind_beans   = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        BEAN_SEL: begin
            o_bean_sel                      = 1'b0; // Set all bits to 0
            o_bean_sel[bean_sel_in_ff]      = 1'b1; // Only the position of bean_sel_ff should be 1
            o_grind_beans                   = 1'b0;
            o_use_powder                    = 1'b0;
            o_heat_water                    = 1'b0;
            o_pour_coffee                   = 1'b0;
        end
        GRIND: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b1;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        POWDER: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b1;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
        HEAT: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b1;
            o_pour_coffee   = 1'b0;
        end
        POUR: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b1;
        end
        default: begin
            o_bean_sel      = {NS_BEANS{1'b0}};
            o_grind_beans   = 1'b0;
            o_use_powder    = 1'b0;
            o_heat_water    = 1'b0;
            o_pour_coffee   = 1'b0;
        end
    endcase
end

endmodule : coffee_machine

module dot_product (
    input               clk_in,                     // Clock signal
    input               reset_in,                   // Asynchronous Reset signal, Active HIGH
    input               start_in,                   // Start computation signal
    input       [7:0]   dot_length_in,              // Length of the dot product vectors (up to 256)
    input       [31:0]  vector_a_in,                // Input vector A {Imag[31:16], Real[15:0]}
    input               vector_a_valid_in,          // Valid signal for vector A
    input       [31:0]  vector_b_in,                // Input vector B {Imag[31:16], Real[15:0]}
    input               vector_b_valid_in,          // Valid signal for vector B
    input               a_complex_in,               // 1 => vector A is complex
    input               b_complex_in,               // 1 => vector B is complex
    output reg  [31:0]  dot_product_out,            // Output dot product result (32-bit)
    output reg          dot_product_valid_out,      // Valid signal for dot product output
    output reg          dot_product_error_out       // Error: valid dropped mid-computation
);

    typedef enum logic [1:0] {
        IDLE    = 2'b00,
        COMPUTE = 2'b01,
        OUTPUT  = 2'b10,
        ERROR   = 2'b11
    } state_t;

    state_t state;

    reg  signed [31:0] acc;        // real-only accumulator
    reg  signed [31:0] acc_re;     // complex real accumulator
    reg  signed [31:0] acc_im;     // complex imaginary accumulator
    reg  [7:0] cnt;
    reg  [7:0] dot_length_reg;
    reg  a_complex_reg;
    reg  b_complex_reg;

    // Field extraction (signed 16-bit real/imag parts)
    wire signed [15:0] a_re = vector_a_in[15:0];
    wire signed [15:0] a_im = vector_a_in[31:16];
    wire signed [15:0] b_re = vector_b_in[15:0];
    wire signed [15:0] b_im = vector_b_in[31:16];

    wire both_valid = vector_a_valid_in && vector_b_valid_in;

    always @(posedge clk_in or posedge reset_in) begin
        if (reset_in) begin
            state                 <= IDLE;
            acc                   <= 0;
            acc_re                <= 0;
            acc_im                <= 0;
            cnt                   <= 0;
            dot_product_out       <= 0;
            dot_product_valid_out <= 0;
            dot_product_error_out <= 0;
            dot_length_reg        <= 0;
            a_complex_reg         <= 0;
            b_complex_reg         <= 0;
        end else begin
            case (state)
                IDLE: begin
                    dot_product_valid_out <= 0;
                    dot_product_error_out <= 0;
                    dot_length_reg        <= dot_length_in;
                    a_complex_reg         <= a_complex_in;
                    b_complex_reg         <= b_complex_in;
                    if (start_in) begin
                        state  <= COMPUTE;
                        acc    <= 0;
                        acc_re <= 0;
                        acc_im <= 0;
                        cnt    <= 0;
                    end
                end
                COMPUTE: begin
                    if (both_valid) begin
                        if (!a_complex_reg && !b_complex_reg) begin
                            // Real-only mode
                            acc <= acc + (a_re * b_re);
                        end else if (a_complex_reg && b_complex_reg) begin
                            // Complex-only mode
                            acc_re <= acc_re + (a_re * b_re - a_im * b_im);
                            acc_im <= acc_im + (a_re * b_im + a_im * b_re);
                        end else if (a_complex_reg && !b_complex_reg) begin
                            // Mixed: A complex, B real
                            acc_re <= acc_re + (a_re * b_re);
                            acc_im <= acc_im + (a_im * b_re);
                        end else begin
                            // Mixed: B complex, A real
                            acc_re <= acc_re + (a_re * b_re);
                            acc_im <= acc_im + (a_re * b_im);
                        end
                        cnt <= cnt + 1;
                        if (cnt == dot_length_reg - 1)
                            state <= OUTPUT;
                    end else if (cnt != 0) begin
                        // valid dropped mid-computation
                        state <= ERROR;
                    end
                end
                OUTPUT: begin
                    if (!a_complex_reg && !b_complex_reg)
                        dot_product_out <= acc;
                    else
                        dot_product_out <= {acc_im[15:0], acc_re[15:0]};
                    dot_product_valid_out <= 1;
                    state <= IDLE;
                end
                ERROR: begin
                    dot_product_error_out <= 1;
                    dot_product_out       <= 0;
                    dot_product_valid_out <= 0;
                    state                 <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module hebb_gates(
   input  logic               clk,
   input  logic               rst,
   input  logic               start, // To start the FSM
   input  logic  signed [3:0] a, // First Input
   input  logic  signed [3:0] b, // Second Input
   input  logic         [1:0] gate_select, // To provide the targets for a selected gate in order to train
   output logic  signed [3:0] w1, // Weight 1 obtained by training
   output logic  signed [3:0] w2, // Weight 2 obtained by training
   output logic  signed [3:0] bias,// Bias obtained by training
   output logic [3:0] present_state,// Present State of the Training FSM
   output logic [3:0] next_state, // Next_State of the Training FSM
   // Testing FSM outputs
   output logic [3:0] test_present_state, // Current state of the Testing FSM
   output logic signed [3:0] test_output, // Calculated output during testing
   output logic [3:0] test_result,        // Count of correct matches
   output logic       test_done           // Active-high testing completion flag
);
   logic signed [3:0] t1;
   logic signed [3:0] t2;
   logic signed [3:0] t3;
   logic signed [3:0] t4;

   gate_target dut(
       .gate_select(gate_select),
       .o_1        (t1),
       .o_2        (t2),
       .o_3        (t3),
       .o_4        (t4)
   );

   localparam [3:0] S0 = 4'd0;
   localparam [3:0] S1 = 4'd1;
   localparam [3:0] S2 = 4'd2;
   localparam [3:0] S3 = 4'd3;
   localparam [3:0] S4 = 4'd4;
   localparam [3:0] S5 = 4'd5;
   localparam [3:0] S6 = 4'd6;
   localparam [3:0] S7 = 4'd7;
   localparam [3:0] S8 = 4'd8;
   localparam [3:0] S9 = 4'd9;
   localparam [3:0] S10 = 4'd10;

   logic [2:0] iteration;
   logic signed [3:0] x1;
   logic signed [3:0] x2;
   logic signed [3:0] delta_w1;
   logic signed [3:0] delta_w2;
   logic signed [3:0] delta_b;
   logic signed [3:0] w1_reg;
   logic signed [3:0] w2_reg;
   logic signed [3:0] bias_reg;
   logic signed [1:0] target;
   logic delta_en;
   logic sum_en;
   logic clr_en;
   logic cap_en;
   logic done;            // Training-complete flag for the Testing FSM

   always_comb begin
     if(cap_en ) begin
        x1 = a;
        x2 = b;
     end else begin
        x1 = x1 + 4'h0;
        x2 = x2 + 4'h0;
     end

   end

   always_comb begin

     if(delta_en) begin
       delta_w1 = x1 * target;
       delta_w2 = x2 * target;
       delta_b  = target;
     end else begin
       delta_w1 = delta_w1 + 4'h0;
       delta_w2 = delta_w2 + 4'h0;
       delta_b  = delta_b + 4'h0;
   end

  end

  always_comb begin

     if(sum_en) begin
       w1_reg = w1_reg + delta_w1;
       w2_reg = w2_reg + delta_w2;
       bias_reg = bias_reg + delta_b;
     end else begin
       w1_reg = w1_reg + 4'h0;
       w2_reg = w2_reg + 4'h0;
       bias_reg = bias_reg + 4'h0;
   end
  end

   always_comb begin

     if(clr_en) begin
       w1_reg = 0;
       w2_reg = 0;
       bias_reg = 0;
     end else begin
       w1_reg = w1_reg + 4'h0;
       w2_reg = w2_reg + 4'h0;
       bias_reg = bias_reg + 4'h0;
    end
   end

   always_ff@(posedge clk or negedge rst) begin
       if(!rst) begin
          present_state <= S0;
          iteration <= 0;
        end else
          present_state <= next_state;
   end

   always_comb begin
        next_state = present_state;

     case(present_state)
             S0  : begin
                      if(start)
                         next_state = S1;
                      else
                         next_state = S0;
                   end
             S1  : begin
                         next_state = S2;
                   end
             S2  : begin
                      if(iteration == 0)
                        next_state = S3;
                     else if(iteration == 1)
                        next_state = S4;
                     else if(iteration == 2)
                        next_state = S5;
                     else
                        next_state = S6;
                   end
             S3  : begin
                         next_state = S7;

                   end
             S4  : begin
                         next_state = S7;
                  end
             S5  : begin
                         next_state = S7;
                  end
             S6  : begin
                         next_state = S7;
                  end
             S7  :begin
                         next_state = S8;
                  end
             S8  : begin
                         next_state = S9;
                  end
             S9  : begin
                      if(iteration < 4)
                         next_state = S1;
                      else
                         next_state = S10;
                   end
             S10 : begin
                      next_state = S0;
                   end
             default : ;
     endcase
   end

   always_comb begin

      case(present_state)
             S0 : begin
                    clr_en = 1;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en   = 0;
                    iteration = 0;
                    target = target + 4'h0;
                  end
             S1 : begin
                    clr_en = 0;
                    cap_en = 1;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S2 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S3 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t1;
                  end
             S4 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t2;
                  end

             S5 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t3;
                  end
             S6 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = t4;
                  end
             S7 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 1;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S8 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 1;
                    iteration = iteration + 1;
                    target = target + 4'h0;
                  end
             S9 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end
             S10 : begin
                    clr_en = 0;
                    cap_en = 0;
                    delta_en = 0;
                    sum_en = 0;
                    iteration = iteration + 0;
                    target = target + 4'h0;
                  end



           default : begin
                      clr_en = 0;
                      cap_en = 0;
                      delta_en = 0;
                      sum_en = 0;
                      iteration = 0;
                      target = target + 4'h0;
                     end
       endcase
   end
   assign w1 = w1_reg;
   assign w2 = w2_reg;
   assign bias = bias_reg;

   // -----------------------------------------------------------------
   // Training-complete flag (asserted once the training FSM reaches S10)
   // -----------------------------------------------------------------
   always_ff @(posedge clk or negedge rst) begin
      if (!rst)
         done <= 1'b0;
      else if (present_state == S10)
         done <= 1'b1;
   end

   // =================================================================
   //  Testing FSM (microcode-sequenced)
   // =================================================================
   localparam [3:0] T0 = 4'd0;  // Initialize
   localparam [3:0] T1 = 4'd1;  // Fetch test vector
   localparam [3:0] T2 = 4'd2;  // Calculate test output
   localparam [3:0] T3 = 4'd3;  // Verify / compare
   localparam [3:0] T4 = 4'd4;  // Done

   // Predefined test vectors (depth 16, 4-bit each). Bipolar encoding:
   //  +1 -> 4'd1, -1 -> 4'hF (two's-complement).  Four vectors per gate.
   logic signed [3:0] test_inputs_x1      [0:15];
   logic signed [3:0] test_inputs_x2      [0:15];
   logic signed [3:0] test_expected_outputs [0:15];

   integer gi;
   integer combo;
   initial begin
      for (gi = 0; gi < 16; gi = gi + 1) begin
         // input combination within a 4-vector group
         combo = gi % 4;
         if (combo == 0) begin
            test_inputs_x1[gi] =  4'sd1; test_inputs_x2[gi] =  4'sd1;
         end else if (combo == 1) begin
            test_inputs_x1[gi] =  4'sd1; test_inputs_x2[gi] = -4'sd1;
         end else if (combo == 2) begin
            test_inputs_x1[gi] = -4'sd1; test_inputs_x2[gi] =  4'sd1;
         end else begin
            test_inputs_x1[gi] = -4'sd1; test_inputs_x2[gi] = -4'sd1;
         end
      end
      // Expected (target) bipolar outputs per gate group, matching gate_target
      // gate 0 (indices 0-3):  1,-1,-1,-1
      test_expected_outputs[0]  =  4'sd1; test_expected_outputs[1]  = -4'sd1;
      test_expected_outputs[2]  = -4'sd1; test_expected_outputs[3]  = -4'sd1;
      // gate 1 (indices 4-7):  1, 1, 1,-1
      test_expected_outputs[4]  =  4'sd1; test_expected_outputs[5]  =  4'sd1;
      test_expected_outputs[6]  =  4'sd1; test_expected_outputs[7]  = -4'sd1;
      // gate 2 (indices 8-11): 1, 1, 1,-1
      test_expected_outputs[8]  =  4'sd1; test_expected_outputs[9]  =  4'sd1;
      test_expected_outputs[10] =  4'sd1; test_expected_outputs[11] = -4'sd1;
      // gate 3 (indices 12-15):1,-1,-1,-1
      test_expected_outputs[12] =  4'sd1; test_expected_outputs[13] = -4'sd1;
      test_expected_outputs[14] = -4'sd1; test_expected_outputs[15] = -4'sd1;
   end

   // Microcode ROM: 5 x 16-bit words.
   //   [15:12] = next-state field, [11:8] = action field, [7:0] = reserved 0.
   logic [15:0] microcode_rom [0:4];
   initial begin
      microcode_rom[0] = {T1, 4'd0, 8'd0}; // init  -> fetch
      microcode_rom[1] = {T2, 4'd1, 8'd0}; // fetch -> calc
      microcode_rom[2] = {T3, 4'd2, 8'd0}; // calc  -> verify
      microcode_rom[3] = {T1, 4'd3, 8'd0}; // verify-> fetch (loop; overridden at terminal)
      microcode_rom[4] = {T4, 4'd4, 8'd0}; // done
   end

   logic [3:0] test_next_state;
   logic [3:0] test_action;
   logic [3:0] test_index;
   logic signed [3:0] test_x1;
   logic signed [3:0] test_x2;
   logic signed [3:0] expected_output;
   logic signed [9:0] test_calc;

   wire [3:0] gate_start    = {gate_select, 2'b00};       // 0,4,8,12
   wire [3:0] gate_terminal = {gate_select, 2'b11};       // 3,7,11,15

   // Instruction fetch (continuous assign avoids memory-word part-selects
   // inside a procedural block).
   wire [15:0] cur_instr = microcode_rom[test_present_state];
   wire [3:0]  rom_next  = cur_instr[15:12];
   assign      test_action = cur_instr[11:8];

   // Instruction decode / next-state override
   always_comb begin
      test_next_state = rom_next;
      case (test_present_state)
         T0: test_next_state = done ? T1 : T0;   // wait for training-done
         T3: test_next_state = (test_index == gate_terminal) ? T4 : T1;
         T4: test_next_state = T4;               // hold in done
         default: ; // ROM-provided next state
      endcase
   end

   // Testing FSM state register
   always_ff @(posedge clk or negedge rst) begin
      if (!rst)
         test_present_state <= T0;
      else
         test_present_state <= test_next_state;
   end

   // Testing datapath
   always_ff @(posedge clk or negedge rst) begin
      if (!rst) begin
         test_index      <= 4'd0;
         test_x1         <= 4'sd0;
         test_x2         <= 4'sd0;
         expected_output <= 4'sd0;
         test_output     <= 4'd0;
         test_result     <= 4'd0;
         test_done       <= 1'b0;
      end else begin
         case (test_present_state)
            T0: begin
               // Initialize all status variables and set the start index
               test_result <= 4'd0;
               test_output <= 4'd0;
               test_done   <= 1'b0;
               test_index  <= gate_start;
            end
            T1: begin
               // Fetch inputs and expected output for the current index
               test_x1         <= test_inputs_x1[test_index];
               test_x2         <= test_inputs_x2[test_index];
               expected_output <= test_expected_outputs[test_index];
            end
            T2: begin
               // Compute weighted sum and threshold it
               test_calc   = (w1_reg * test_x1) + (w2_reg * test_x2) + bias_reg;
               test_output <= (test_calc > 0) ? 4'sd1 : -4'sd1;
            end
            T3: begin
               // Compare and update the match counter
               if (test_output == expected_output)
                  test_result <= test_result + 4'd1;
               if (test_index == gate_terminal)
                  test_done <= 1'b1;
               else
                  test_index <= test_index + 4'd1;
            end
            T4: begin
               test_done <= 1'b1;
            end
            default: ;
         endcase
      end
   end

endmodule

module gate_target(
   input  logic        [1:0] gate_select,
   output logic signed [3:0] o_1,
   output logic signed [3:0] o_2,
   output logic signed [3:0] o_3,
   output logic signed [3:0] o_4
);
   always_comb begin
     case(gate_select)
          2'b00 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
          2'b01 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b10 : begin
                    o_1 =  1;
                    o_2 =  1;
                    o_3 =  1;
                    o_4 = -1;
                  end
          2'b11 : begin
                    o_1 =  1;
                    o_2 = -1;
                    o_3 = -1;
                    o_4 = -1;
                  end
        default : begin
                    o_1 =  0;
                    o_2 =  0;
                    o_3 =  0;
                    o_4 =  0;
                  end
        endcase
   end
endmodule

module load_store_unit (
    input  logic                 clk,
    input  logic                 rst_n,

    // EX stage interface
    input  logic                 ex_if_req_i,           // LSU request
    input  logic                 ex_if_we_i,            // Write enable: 0 (load), 1 (store)
    input  logic     [ 1:0]      ex_if_type_i,          // Data type: 0x2 (word), 0x1 (halfword), 0x0 (byte)
    input  logic     [31:0]      ex_if_wdata_i,         // Data to write to memory
    input  logic     [31:0]      ex_if_addr_base_i,     // Base address
    input  logic     [31:0]      ex_if_addr_offset_i,   // Offset address
    input  logic                 ex_if_extend_mode_i,
    output logic                 ex_if_ready_o    ,


    // Writeback stage interface
    output logic     [31:0]      wb_if_rdata_o,         // Requested data
    output logic                 wb_if_rvalid_o,        // Requested data valid

    // Data memory (DMEM) interface
    output logic                 dmem_req_o,
    input  logic                 dmem_gnt_i,
    output logic     [31:0]      dmem_req_addr_o,
    output logic                 dmem_req_we_o,
    output logic     [ 3:0]      dmem_req_be_o,
    output logic     [31:0]      dmem_req_wdata_o,
    input  logic     [31:0]      dmem_rsp_rdata_i,
    input  logic                 dmem_rvalid_i
    );

  // FSM states
  localparam logic [3:0] IDLE                = 4'd0,
                         ALIGNED_WR          = 4'd1,
                         ALIGNED_RD          = 4'd2,
                         ALIGNED_RD_GNT       = 4'd3,
                         MISALIGNED_WR        = 4'd4,
                         MISALIGNED_WR_1      = 4'd5,
                         MISALIGNED_RD        = 4'd6,
                         MISALIGNED_RD_GNT    = 4'd7,
                         MISALIGNED_RD_1      = 4'd8,
                         MISALIGNED_RD_GNT_1  = 4'd9;

  logic [3:0] state;

  // Effective address
  logic [31:0] data_addr_int;
  assign data_addr_int = ex_if_addr_base_i + ex_if_addr_offset_i;

  // -------- combinational alignment / byte-enable decode --------
  // be0 = byte enables for the first (lower-address) transaction
  // be1 = byte enables for the second transaction of a misaligned access
  logic        misaligned_c;
  logic [3:0]  be0_c, be1_c;

  always_comb begin
    misaligned_c = 1'b0;
    be0_c        = 4'b0000;
    be1_c        = 4'b0000;
    case (ex_if_type_i)
      2'b00: begin // byte
        be0_c = 4'b0001 << data_addr_int[1:0];
      end
      2'b01: begin // halfword
        case (data_addr_int[1:0])
          2'b00: be0_c = 4'b0011;
          2'b01: be0_c = 4'b0110;
          2'b10: be0_c = 4'b1100;
          2'b11: begin misaligned_c = 1'b1; be0_c = 4'b1000; be1_c = 4'b0001; end
        endcase
      end
      2'b10: begin // word
        case (data_addr_int[1:0])
          2'b00: be0_c = 4'b1111;
          2'b01: begin misaligned_c = 1'b1; be0_c = 4'b1110; be1_c = 4'b0001; end
          2'b10: begin misaligned_c = 1'b1; be0_c = 4'b1100; be1_c = 4'b0011; end
          2'b11: begin misaligned_c = 1'b1; be0_c = 4'b1000; be1_c = 4'b0111; end
        endcase
      end
      default: ;
    endcase
  end

  // -------- latched request context --------
  logic        req_we_q;
  logic [31:0] req_addr0_q, req_addr1_q;
  logic [31:0] req_wdata_q;
  logic [3:0]  req_be0_q, req_be1_q;
  logic [1:0]  data_type_q;
  logic [1:0]  rdata_offset_q;
  logic        data_sign_ext_q;

  // -------- FSM sequential --------
  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      state           <= IDLE;
      req_we_q        <= 1'b0;
      req_addr0_q     <= '0;
      req_addr1_q     <= '0;
      req_wdata_q     <= '0;
      req_be0_q       <= '0;
      req_be1_q       <= '0;
      data_type_q     <= '0;
      rdata_offset_q  <= '0;
      data_sign_ext_q <= 1'b0;
    end else begin
      case (state)
        IDLE: begin
          if (ex_if_req_i) begin
            req_we_q        <= ex_if_we_i;
            req_addr0_q     <= data_addr_int;
            req_addr1_q     <= {data_addr_int[31:2], 2'b00} + 32'd4;
            req_wdata_q     <= ex_if_wdata_i;
            req_be0_q       <= be0_c;
            req_be1_q       <= be1_c;
            data_type_q     <= ex_if_type_i;
            rdata_offset_q  <= data_addr_int[1:0];
            data_sign_ext_q <= ex_if_extend_mode_i;
            if (ex_if_we_i)
              state <= misaligned_c ? MISALIGNED_WR : ALIGNED_WR;
            else
              state <= misaligned_c ? MISALIGNED_RD : ALIGNED_RD;
          end
        end

        ALIGNED_WR:          if (dmem_gnt_i)    state <= IDLE;
        ALIGNED_RD:          if (dmem_gnt_i)    state <= ALIGNED_RD_GNT;
        ALIGNED_RD_GNT:      if (dmem_rvalid_i) state <= IDLE;

        MISALIGNED_WR:       if (dmem_gnt_i)    state <= MISALIGNED_WR_1;
        MISALIGNED_WR_1:     if (dmem_gnt_i)    state <= IDLE;

        MISALIGNED_RD:       if (dmem_gnt_i)    state <= MISALIGNED_RD_GNT;
        MISALIGNED_RD_GNT:   if (dmem_rvalid_i) state <= MISALIGNED_RD_1;
        MISALIGNED_RD_1:     if (dmem_gnt_i)    state <= MISALIGNED_RD_GNT_1;
        MISALIGNED_RD_GNT_1: if (dmem_rvalid_i) state <= IDLE;

        default: state <= IDLE;
      endcase
    end
  end

  assign ex_if_ready_o = (state == IDLE);

  // -------- DMEM request drive (zeroed whenever req is deasserted) --------
  always_comb begin : dmem_req
    dmem_req_o       = 1'b0;
    dmem_req_addr_o  = 32'b0;
    dmem_req_we_o    = 1'b0;
    dmem_req_be_o    = 4'b0;
    dmem_req_wdata_o = 32'b0;
    case (state)
      ALIGNED_WR: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr0_q; dmem_req_we_o = 1'b1;
        dmem_req_be_o = req_be0_q; dmem_req_wdata_o = req_wdata_q;
      end
      ALIGNED_RD: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr0_q; dmem_req_we_o = 1'b0;
        dmem_req_be_o = req_be0_q;
      end
      MISALIGNED_WR: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr0_q; dmem_req_we_o = 1'b1;
        dmem_req_be_o = req_be0_q; dmem_req_wdata_o = req_wdata_q;
      end
      MISALIGNED_WR_1: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr1_q; dmem_req_we_o = 1'b1;
        dmem_req_be_o = req_be1_q; dmem_req_wdata_o = req_wdata_q;
      end
      MISALIGNED_RD: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr0_q; dmem_req_we_o = 1'b0;
        dmem_req_be_o = req_be0_q;
      end
      MISALIGNED_RD_1: begin
        dmem_req_o = 1'b1; dmem_req_addr_o = req_addr1_q; dmem_req_we_o = 1'b0;
        dmem_req_be_o = req_be1_q;
      end
      default: ;
    endcase
  end

  // -------- read-data sign/zero extension for ALIGNED loads --------
  logic [31:0] rdata_w_ext, rdata_h_ext, rdata_b_ext, data_rdata_ext;

  always_comb begin
    case (rdata_offset_q)
      2'b00:   rdata_w_ext = dmem_rsp_rdata_i[31:0];
      default: rdata_w_ext = '0 ;
    endcase
  end

  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:0]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[15:0]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_h_ext = {{16{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:16]};
        else                 rdata_h_ext = {16'h0000, dmem_rsp_rdata_i[31:16]};
      end
      default: rdata_h_ext = '0 ;
    endcase
  end

  always_comb begin
    case (rdata_offset_q)
      2'b00: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[7]}}, dmem_rsp_rdata_i[7:0]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[7:0]};
      end
      2'b01: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[15]}}, dmem_rsp_rdata_i[15:8]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[15:8]};
      end
      2'b10: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[23]}}, dmem_rsp_rdata_i[23:16]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[23:16]};
      end
      2'b11: begin
        if (data_sign_ext_q) rdata_b_ext = {{24{dmem_rsp_rdata_i[31]}}, dmem_rsp_rdata_i[31:24]};
        else                 rdata_b_ext = {24'h00_0000, dmem_rsp_rdata_i[31:24]};
      end
      default: rdata_b_ext = '0;
    endcase
  end

  always_comb begin
    case (data_type_q)
      2'b00:   data_rdata_ext = rdata_b_ext;
      2'b01:   data_rdata_ext = rdata_h_ext;
      2'b10:   data_rdata_ext = rdata_w_ext;
      default: data_rdata_ext = 32'b0;
    endcase
  end

  // -------- Writeback data capture --------
  // Aligned load : extended data, one rvalid pulse.
  // Misaligned load : raw dmem response forwarded per transaction (two pulses).
  logic [31:0] wb_if_rdata_q;
  logic        wb_if_rvalid_q;

  always_ff @(posedge clk, negedge rst_n) begin
    if (!rst_n) begin
      wb_if_rdata_q  <= 32'b0;
      wb_if_rvalid_q <= 1'b0;
    end else begin
      wb_if_rvalid_q <= 1'b0;
      if (dmem_rvalid_i && (state == ALIGNED_RD_GNT)) begin
        wb_if_rdata_q  <= data_rdata_ext;
        wb_if_rvalid_q <= 1'b1;
      end else if (dmem_rvalid_i && ((state == MISALIGNED_RD_GNT) ||
                                     (state == MISALIGNED_RD_GNT_1))) begin
        wb_if_rdata_q  <= dmem_rsp_rdata_i;
        wb_if_rvalid_q <= 1'b1;
      end
    end
  end

  assign wb_if_rdata_o  = wb_if_rdata_q;
  assign wb_if_rvalid_o = wb_if_rvalid_q;

endmodule

module pipeline_mac #(
    parameter DWIDTH = 16,  // Bit width for multiplicand and multiplier
    parameter N      = 4    // Number of data points to accumulate over
) (
    clk,
    rstn,
    multiplicand,
    multiplier,
    valid_i,
    result,
    valid_out
);
  // ----------------------------------------
  // - Local parameter definition
  // ----------------------------------------

      // Accumulator width: product is 2*DWIDTH bits; summing up to N of them
      // needs $clog2(N) extra carry bits to avoid overflow.
      localparam DWIDTH_ACCUMULATOR = (2*DWIDTH) + $clog2(N);

  // ----------------------------------------
  // - Interface Definitions
  // ----------------------------------------
  input logic clk;                                // Clock signal
  input logic rstn;                               // Active low reset signal
  input logic [DWIDTH-1:0] multiplicand;          // Input multiplicand
  input logic [DWIDTH-1:0] multiplier;            // Input multiplier
  input logic valid_i;                            // Input valid signal
  output logic [DWIDTH_ACCUMULATOR-1:0] result;   // Accumulated result output
  output logic valid_out;                         // Output valid signal, indicates when result is ready

  // ----------------------------------------
  // - Internal signals
  // ----------------------------------------
  logic [DWIDTH_ACCUMULATOR-1:0] mult_result_reg;    // Register to store intermediate multiplication result
  logic [DWIDTH_ACCUMULATOR-1:0] accumulation_reg;   // Register to store accumulated result
  logic [$clog2(N):0] counter;                       // Counter to track the number of accumulations
  logic [$clog2(N):0] counter_reg;                   // Register to hold the value of the counter
  logic count_rst, accumulator_rst;                  // Reset signals for counter and accumulator
  logic valid_out_s0,valid_out_s1,valid_out_s2;      // Intermediate Signals indicating that the valid output is ready
  logic valid_i_s1;                                  // Intermediate Signals indicating input valid signal
  // ----------------------------------------
  // - Procedural blocks
  // ----------------------------------------

  // Stage 1 of the pipeline: Perform multiplication (register the product and
  // a stage-matched valid). Multiply only on a valid input; hold otherwise.
  always @(posedge clk or negedge rstn) begin

     if (!rstn) begin
        mult_result_reg <= '0;
        valid_i_s1      <= 1'b0;
     end else if (valid_i) begin
        mult_result_reg <= multiplicand * multiplier;
        valid_i_s1      <= 1'b1;
     end else begin
        valid_i_s1      <= 1'b0;   // gapped valid_i: no new product this cycle
        // mult_result_reg holds its value
     end

  end

  // Stage 2 of the pipeline: Accumulation logic.
  // The window counter/valid_out are one cycle ahead of a fully-registered
  // product path, so the accumulator adds the freshly-formed product to land
  // the complete N-term sum on the exact cycle valid_out asserts.  At the
  // window boundary the accumulator restarts by LOADING the first product of
  // the next window (rather than zeroing) so no sample is dropped, exactly per
  // the MAC craft for back-to-back windows.
  always @(posedge clk or negedge rstn) begin

     if (!rstn) begin
        accumulation_reg <= '0;
     end else if (accumulator_rst) begin
        // Window boundary: seed the new window with the in-flight product.
        accumulation_reg <= valid_i ? (multiplicand * multiplier) : '0;
     end else if (valid_i) begin
        accumulation_reg <= accumulation_reg + (multiplicand * multiplier);
     end
     // else: hold (valid_i low -> freeze)

  end

  // N-bit counter to track the number of accumulations
  always @(posedge clk or negedge rstn) begin

     if (!rstn)
        counter_reg <= '0;
     else
        counter_reg <= counter;

  end

  // Register valid output for 2-stage pipeline.
  // Freeze this pipeline while valid_i is low so a gap in the input stream
  // cannot advance the output-valid detection ahead of the frozen datapath
  // (the whole MAC holds its state during gaps).
  always @(posedge clk or negedge rstn) begin

     if (!rstn) begin
        valid_out_s1 <= 1'b0;
        valid_out_s2 <= 1'b0;
     end else begin
        // s1 (the counter-derived valid) freezes during a gap so it cannot
        // assert ahead of the frozen datapath; s2 always tracks s1 so the
        // valid_out pulse self-clears and never sticks after the stream ends.
        if (valid_i)
           valid_out_s1 <= valid_out_s0;
        valid_out_s2 <= valid_out_s1;
     end

  end

  // ----------------------------------------
  // - Combinational Assignments
  // ----------------------------------------
  assign counter = count_rst ? 'b1 : (valid_i & rstn ? (counter_reg + 'd1) : counter_reg);  // Increment counter on valid input
  assign valid_out_s0 = (counter_reg == N-1);    // Assert valid_out_s0 when N accumulations are done
  assign count_rst = valid_out_s1;                  // Reset counter after N accumulations
  assign accumulator_rst = valid_out_s1;            // Reset accumulator after N accumulations
  assign result = accumulation_reg;              // Output final result assignment
  assign valid_out = valid_out_s1 & ~valid_out_s2; // Valid_out signal generation by detecting posedge of previous stages of valid out

endmodule : pipeline_mac

module soundgenerator #(
	parameter  CLOCK_HZ = 10_000_000
)(
	input wire clk,                                         //input clock signal with frequency 10Mhz
	input wire nrst,                                        //active low asynchronous reset.

	input wire start,                                       //indicate the start of the operation.
	input wire finish,                                      //indicate the end of operation.
	input wire [15:0] sond_dur_ms_i,                        //this signal indicate for how much time the sound should be generated in millisecond.
	input wire [15:0] half_period_us_i,                     //this signal indicate the frequency of the output signal by giving the half time period required for the output soundwave_o

	output wire soundwave_o,                                //output sound wave signal.
	output wire busy,                                       //indicate the system is busy.
	output wire done                                        //indicate the operation is completed.
);

	// Duration counter (in milliseconds) and half-period counter (in microseconds)
	reg [15:0] dur_cnt;
	reg [15:0] half_cnt;
	reg        sig;        // square-wave state
	reg        busy_prev;  // busy delayed by 1 clock (for done edge detection)

	// System is busy while there is remaining duration to generate.
	wire busy_int = (dur_cnt != 16'd0);

	// Millisecond and microsecond timing strobes; only run while active.
	wire tick_ms;
	wire tick_us;

	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1000)
	) TickMilli (
		.clk    (clk),
		.nrst   (nrst),
		.enable (busy_int),
		.strobe_o(tick_ms)
	);

	strob_gen #(
		.CLOCK_HZ (CLOCK_HZ),
		.PERIOD_US(1)
	) tickmicro (
		.clk    (clk),
		.nrst   (nrst),
		.enable (busy_int),
		.strobe_o(tick_us)
	);

	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			dur_cnt   <= 16'd0;
			half_cnt  <= 16'd0;
			sig       <= 1'b0;
			busy_prev <= 1'b0;
		end else begin
			if (start) begin
				// Load new operation parameters.
				dur_cnt  <= sond_dur_ms_i;
				half_cnt <= half_period_us_i;
				sig      <= 1'b0;
			end else if (finish) begin
				// Force end of operation.
				dur_cnt <= 16'd0;
			end else if (busy_int) begin
				// Duration timer decrements every millisecond tick.
				if (tick_ms && (dur_cnt != 16'd0))
					dur_cnt <= dur_cnt - 16'd1;

				// Half-period timer decrements every microsecond tick; toggles
				// the square wave when it expires.
				if (tick_us) begin
					if (half_cnt <= 16'd1) begin
						sig      <= ~sig;
						half_cnt <= half_period_us_i;
					end else begin
						half_cnt <= half_cnt - 16'd1;
					end
				end
			end
			busy_prev <= busy_int;
		end
	end

	assign busy       = busy_int;
	assign done       = busy_prev & ~busy_int;          // busy high->low transition
	assign soundwave_o = busy_int ? sig : 1'b0;         // square wave only while active

endmodule

module strob_gen #(
	parameter	CLOCK_HZ	= 10_000_000,
	parameter	PERIOD_US	= 100
)(
	input wire  clk,
	input wire  nrst,
	input wire  enable,
	output reg  strobe_o
);
	// Number of clock cycles in one strobe period.
	localparam integer CYCLES = (CLOCK_HZ / 1_000_000) * PERIOD_US;
	localparam integer DELAY  = (CYCLES > 0) ? (CYCLES - 1) : 0;

	reg [31:0] counter;

	always @(posedge clk or negedge nrst) begin
		if (!nrst) begin
			counter  <= DELAY[31:0];
			strobe_o <= 1'b0;
		end else if (enable) begin
			if (counter == 32'd0) begin
				strobe_o <= 1'b1;          // one-cycle pulse at interval
				counter  <= DELAY[31:0];   // reload
			end else begin
				strobe_o <= 1'b0;
				counter  <= counter - 32'd1;
			end
		end else begin
			counter  <= DELAY[31:0];       // idle: hold reload value, no strobe
			strobe_o <= 1'b0;
		end
	end

endmodule

module Word_Change_Pulse#(
    parameter DATA_WIDTH = 8 // Default word width
) (
    input  wire                  clk,               // Clock signal for synchronizing operations
    input  wire                  reset,             // Reset signal to initialize the module
    input  wire [DATA_WIDTH-1:0] data_in,           // Input data, width defined by parameter DATA_WIDTH
    input  wire [DATA_WIDTH-1:0] mask,              // Mask signal to enable/disable change detection for each bit
    input  wire [DATA_WIDTH-1:0] match_pattern,     // Pattern to match for generating the pulse
    input  wire                  enable,            // Enable signal to allow module operation
    input  wire                  latch_pattern,     // Signal to latch the match pattern
    output reg                   word_change_pulse, // Output signal indicating a change in any bit of data_in
    output reg                   pattern_match_pulse, // Output signal indicating a match with the pattern
    output reg [DATA_WIDTH-1:0]  latched_pattern    // Latched pattern for comparison
);

    wire [DATA_WIDTH-1:0] change_pulses;

    reg [DATA_WIDTH-1:0] masked_data_in;
    reg [DATA_WIDTH-1:0] masked_change_pulses;
    reg                  match_detected;

    genvar i;

    // Instantiate one Bit_Change_Detector per bit of the input word
    generate
        for (i = 0; i < DATA_WIDTH; i = i + 1) begin : gen_bit_detectors
            Bit_Change_Detector u_bcd (
                .clk        (clk),
                .reset      (reset),
                .bit_in     (data_in[i]),
                .change_pulse(change_pulses[i])
            );
        end
    endgenerate

       always @(posedge clk or posedge reset) begin
        if (reset) begin
            masked_data_in <= {DATA_WIDTH{1'b0}};
            masked_change_pulses <= {DATA_WIDTH{1'b0}};
            word_change_pulse <= 1'b0;
            match_detected <= 1'b0;
            pattern_match_pulse <= 1'b0;
            latched_pattern <= {DATA_WIDTH{1'b0}};
        end else if (enable) begin
            // Latch pattern if requested
            if (latch_pattern)
                latched_pattern <= match_pattern;

            // Mask data_in, detect masked changes, generate word-level pulse (1 cycle after change)
            masked_data_in      <= data_in & mask;
            masked_change_pulses <= change_pulses & mask;
            word_change_pulse   <= |(change_pulses & mask);

            // Compare masked data_in against latched_pattern (both masked) for pattern match
            match_detected      <= ((data_in & mask) == (latched_pattern & mask));
            pattern_match_pulse <= ((data_in & mask) == (latched_pattern & mask));
        end else begin
            // When disabled, hold latched_pattern, deassert pulses
            word_change_pulse   <= 1'b0;
            pattern_match_pulse <= 1'b0;
            match_detected      <= 1'b0;
        end
    end

endmodule


// Bit_Change_Detector Module
module Bit_Change_Detector (
   input  wire clk,          // Clock signal
    input  wire reset,       // Reset signal to initialize the module
    input  wire bit_in,      // Single bit input to detect changes
    output reg  change_pulse // Pulse signal indicating a change in the input bit
);


    reg bit_in_d;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_in_d <= 1'b0;
        end else begin
            bit_in_d <= bit_in;
        end
    end

    always @(*) begin
        change_pulse = (bit_in != bit_in_d);
    end
endmodule

module serial_line_code_converter #(parameter CLK_DIV = 16)(
    input  logic        clk,             // System clock
    input  logic        reset_n,         // Active-low asynchronous reset
    input  logic        serial_in,       // Serial input signal
    input  logic        enable,          // Enable signal
    input  logic [2:0]  mode,            // Mode selector
    output logic        serial_out,      // Serial output signal
    output logic        error_flag,      // Error flag (invalid serial_in)
    output logic [15:0] diagnostic_bus   // Diagnostic status bus
);

    // Internal signals
    logic [3:0] clk_counter;      // Clock divider counter
    logic       clk_pulse;        // Clock pulse for sampling
    logic       prev_serial_in;   // Previous serial input for edge detection
    logic       prev_value;       // Holds the previous value of serial_in
    logic       nrz_out;
    logic       rz_out;
    logic       diff_out;
    logic       inv_nrz_out;
    logic       alt_invert_out;
    logic       alt_invert_state;
    logic       parity_out;
    logic       scrambled_out;
    logic       edge_triggered_out;
    logic [7:0] error_counter;    // 8-bit error counter
    logic       serial_in_invalid;
    logic       encoded_out;      // selected encoding (pre enable gating)

    // Invalid-input detection: serial_in is 'x' or 'z'
    always_comb begin
        serial_in_invalid = (serial_in === 1'bx) || (serial_in === 1'bz);
    end

    // Clock pulse generation (divide clk by CLK_DIV); paused when disabled
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            clk_counter <= 0;
            clk_pulse   <= 0;
        end else if (enable) begin
            if (clk_counter == CLK_DIV - 1) begin
                clk_counter <= 0;
                clk_pulse   <= 1;
            end else begin
                clk_counter <= clk_counter + 1;
                clk_pulse   <= 0;
            end
        end
    end

    // Previous-input tracking
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            prev_value     <= 0;
            prev_serial_in <= 0;
        end else if (enable) begin
            prev_value     <= serial_in;
            prev_serial_in <= prev_value;
        end
    end

    // Encoding registers (paused when disabled)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            nrz_out            <= 0;
            rz_out             <= 0;
            diff_out           <= 0;
            inv_nrz_out        <= 0;
            alt_invert_out     <= 0;
            alt_invert_state   <= 0;
            parity_out         <= 0;
            scrambled_out      <= 0;
            edge_triggered_out <= 0;
        end else if (enable) begin
            nrz_out            <= serial_in;
            rz_out             <= serial_in & clk_pulse;
            diff_out           <= serial_in ^ prev_serial_in;
            inv_nrz_out        <= ~serial_in;
            alt_invert_state   <= ~alt_invert_state;
            alt_invert_out     <= alt_invert_state ? ~serial_in : serial_in;
            parity_out         <= serial_in ^ parity_out;
            scrambled_out      <= serial_in ^ clk_counter[0];
            edge_triggered_out <= (serial_in & ~prev_serial_in);
        end
    end

    // Error detection: flag + accumulating counter (only while enabled)
    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            error_flag    <= 1'b0;
            error_counter <= 8'd0;
        end else if (enable) begin
            if (serial_in_invalid) begin
                error_flag    <= 1'b1;
                error_counter <= error_counter + 8'd1;
            end else begin
                error_flag    <= 1'b0;
            end
        end else begin
            error_flag <= 1'b0;   // outputs disabled
        end
    end

    // Encoding selection
    always_comb begin
        case (mode)
            3'b000: encoded_out = nrz_out;
            3'b001: encoded_out = rz_out;
            3'b010: encoded_out = diff_out;
            3'b011: encoded_out = inv_nrz_out;
            3'b100: encoded_out = alt_invert_out;
            3'b101: encoded_out = parity_out;
            3'b110: encoded_out = scrambled_out;
            3'b111: encoded_out = edge_triggered_out;
            default: encoded_out = 1'b0;
        endcase
    end

    // Output stage: forced to 0 when disabled
    assign serial_out = enable ? encoded_out : 1'b0;

    // Diagnostic bus assembly (zeroed when disabled)
    assign diagnostic_bus = enable ?
        { mode,               // [15:13] current mode
          error_flag,         // [12]    error flag
          error_counter,      // [11:4]  error counter
          clk_pulse,          // [3]     clock divider pulse
          encoded_out,        // [2]     encoded output
          alt_invert_out,     // [1]     NRZ alternating-bit-inversion output
          parity_out }        // [0]     odd parity bit
        : 16'd0;

endmodule

module axi_tap #(
    parameter ADDR_WIDTH = 32, // Width of AXI4-Lite Address
    parameter DATA_WIDTH = 32  // Width of AXI4-Lite Data
)(
    // Global Ports
    input           clk_i,
    input           rst_i,

    // Master Write Address Channel (AW)
    input           inport_awvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_awaddr_i,
    output          inport_awready_o,
    // Master Write Data Channel (W)
    input           inport_wvalid_i,
    input  [DATA_WIDTH-1:0]   inport_wdata_i,
    input  [3:0]    inport_wstrb_i,
    output          inport_wready_o,
    // Master Write Response Channel (B)
    input           inport_bready_i,
    output          inport_bvalid_o,
    output [1:0]    inport_bresp_o,
    // Master Read Address Channel (AR)
    input           inport_arvalid_i,
    input  [ADDR_WIDTH-1:0]   inport_araddr_i,
    output          inport_arready_o,
    // Master Read Data Channel (R)
    input           inport_rready_i,
    output          inport_rvalid_o,
    output [DATA_WIDTH-1:0]   inport_rdata_o,
    output [1:0]    inport_rresp_o,

    // Default AXI outport
    // Write Address Channel (AW)
    input           outport_awready_i,
    output          outport_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_awaddr_o,
    // Write Data Channel (W)
    input           outport_wready_i,
    output          outport_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_wdata_o,
    output [3:0]    outport_wstrb_o,
    // Write Response Channel (B)
    input           outport_bvalid_i,
    input  [1:0]    outport_bresp_i,
    output          outport_bready_o,
    // Read Address Channel (AR)
    input           outport_arready_i,
    output          outport_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_araddr_o,
    // Read Data Channel (R)
    input           outport_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_rdata_i,
    input  [1:0]    outport_rresp_i,
    output          outport_rready_o,

    // Peripheral 0 interface
    // Write Address Channel (AW)
    input           outport_peripheral0_awready_i,
    output          outport_peripheral0_awvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_awaddr_o,
    // Write Data Channel (W)
    input           outport_peripheral0_wready_i,
    output          outport_peripheral0_wvalid_o,
    output [DATA_WIDTH-1:0]   outport_peripheral0_wdata_o,
    output [3:0]    outport_peripheral0_wstrb_o,
    // Write Response Channel (B)
    input  [1:0]    outport_peripheral0_bresp_i,
    input           outport_peripheral0_bvalid_i,
    output          outport_peripheral0_bready_o,
    // Read Address Channel (AR)
    input           outport_peripheral0_arready_i,
    output          outport_peripheral0_arvalid_o,
    output [ADDR_WIDTH-1:0]   outport_peripheral0_araddr_o,
    // Read Data Channel (R)
    input  [1:0]    outport_peripheral0_rresp_i,
    input           outport_peripheral0_rvalid_i,
    input  [DATA_WIDTH-1:0]   outport_peripheral0_rdata_i,
    output          outport_peripheral0_rready_o,

    // Transaction timeout detection
    input  [31:0]   TIMEOUT_THRESHOLD, // Allowed transaction duration (cycles)
    output          timeout_flag       // Asserted when a transaction times out
);

`define ADDR_SEL_W           1
`define PERIPH0_ADDR         32'h80000000
`define PERIPH0_MASK         32'h80000000

//-----------------------------------------------------------------
// AXI: Read
//-----------------------------------------------------------------
reg [3:0]              read_pending_q;
reg [3:0]              read_pending_r;
reg [`ADDR_SEL_W-1:0]  read_port_q;
reg [`ADDR_SEL_W-1:0]  read_port_r;

always @ *
begin
    read_port_r = `ADDR_SEL_W'b0;
    if ((inport_araddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) read_port_r = `ADDR_SEL_W'd1;
end

wire read_incr_w = (inport_arvalid_i && inport_arready_o);
wire read_decr_w = (inport_rvalid_o && inport_rready_i);

always @ *
begin
    read_pending_r = read_pending_q;

    if (read_incr_w && !read_decr_w)
        read_pending_r = read_pending_r + 4'd1;
    else if (!read_incr_w && read_decr_w)
        read_pending_r = read_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    read_pending_q <= 4'b0;
    read_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    read_pending_q <= read_pending_r;

    // Read command accepted
    if (inport_arvalid_i && inport_arready_o)
    begin
        read_port_q <= read_port_r;
    end
end

wire read_accept_w       = (read_port_q == read_port_r && read_pending_q != 4'hF) || (read_pending_q == 4'h0);

assign outport_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd0);
assign outport_araddr_o  = inport_araddr_i;
assign outport_rready_o  = inport_rready_i;

assign outport_peripheral0_arvalid_o = inport_arvalid_i & read_accept_w & (read_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_araddr_o  = inport_araddr_i;
assign outport_peripheral0_rready_o  = inport_rready_i;

reg        outport_rvalid_r;
reg [DATA_WIDTH-1:0] outport_rdata_r;
reg [1:0]  outport_rresp_r;

always @ *
begin
    case (read_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_rvalid_r = outport_peripheral0_rvalid_i;
        outport_rdata_r  = outport_peripheral0_rdata_i;
        outport_rresp_r  = outport_peripheral0_rresp_i;
    end
    default:
    begin
        outport_rvalid_r = outport_rvalid_i;
        outport_rdata_r  = outport_rdata_i;
        outport_rresp_r  = outport_rresp_i;
    end
    endcase
end

assign inport_rvalid_o  = outport_rvalid_r;
assign inport_rdata_o   = outport_rdata_r;
assign inport_rresp_o   = outport_rresp_r;

reg inport_arready_r;
always @ *
begin
    case (read_port_r)
    `ADDR_SEL_W'd1:
        inport_arready_r = outport_peripheral0_arready_i;
    default:
        inport_arready_r = outport_arready_i;
    endcase
end

assign inport_arready_o = read_accept_w & inport_arready_r;

//-------------------------------------------------------------
// Write Request
//-------------------------------------------------------------
reg awvalid_q;
reg wvalid_q;

wire wr_cmd_accepted_w  = (inport_awvalid_i && inport_awready_o) || awvalid_q;
wire wr_data_accepted_w = (inport_wvalid_i  && inport_wready_o)  || wvalid_q;

always @ (posedge clk_i )
if (rst_i)
    awvalid_q <= 1'b0;
else if (inport_awvalid_i && inport_awready_o && (!wr_data_accepted_w))
    awvalid_q <= 1'b1;
else if (wr_data_accepted_w)
    awvalid_q <= 1'b0;

always @ (posedge clk_i )
if (rst_i)
    wvalid_q <= 1'b0;
else if (inport_wvalid_i && inport_wready_o && !wr_cmd_accepted_w)
    wvalid_q <= 1'b1;
else if (wr_cmd_accepted_w)
    wvalid_q <= 1'b0;

//-----------------------------------------------------------------
// AXI: Write
//-----------------------------------------------------------------
reg [3:0]              write_pending_q;
reg [3:0]              write_pending_r;
reg [`ADDR_SEL_W-1:0]  write_port_q;
reg [`ADDR_SEL_W-1:0]  write_port_r;

always @ *
begin
    if (inport_awvalid_i & ~awvalid_q)
    begin
        write_port_r = `ADDR_SEL_W'b0;
        if ((inport_awaddr_i & `PERIPH0_MASK) == `PERIPH0_ADDR) write_port_r = `ADDR_SEL_W'd1;
    end
    else
        write_port_r = write_port_q;
end

wire write_incr_w = (inport_awvalid_i && inport_awready_o);
wire write_decr_w = (inport_bvalid_o  && inport_bready_i);

always @ *
begin
    write_pending_r = write_pending_q;

    if (write_incr_w && !write_decr_w)
        write_pending_r = write_pending_r + 4'd1;
    else if (!write_incr_w && write_decr_w)
        write_pending_r = write_pending_r - 4'd1;
end

always @ (posedge clk_i )
if (rst_i)
begin
    write_pending_q <= 4'b0;
    write_port_q    <= `ADDR_SEL_W'b0;
end
else
begin
    write_pending_q <= write_pending_r;

    // Write command accepted
    if (inport_awvalid_i && inport_awready_o)
    begin
        write_port_q <= write_port_r;
    end
end

wire write_accept_w      = (write_port_q == write_port_r && write_pending_q != 4'hF) || (write_pending_q == 4'h0);

assign outport_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd0);
assign outport_awaddr_o  = inport_awaddr_i;
assign outport_wvalid_o  = inport_wvalid_i & ~wvalid_q & (inport_awvalid_i || awvalid_q) & (write_port_r == `ADDR_SEL_W'd0);
assign outport_wdata_o   = inport_wdata_i;
assign outport_wstrb_o   = inport_wstrb_i;
assign outport_bready_o  = inport_bready_i;

assign outport_peripheral0_awvalid_o = inport_awvalid_i & ~awvalid_q & write_accept_w & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_awaddr_o  = inport_awaddr_i;
assign outport_peripheral0_wvalid_o  = inport_wvalid_i & ~wvalid_q & ((inport_awvalid_i && write_accept_w) || awvalid_q) & (write_port_r == `ADDR_SEL_W'd1);
assign outport_peripheral0_wdata_o   = inport_wdata_i;
assign outport_peripheral0_wstrb_o   = inport_wstrb_i;
assign outport_peripheral0_bready_o  = inport_bready_i;

reg        outport_bvalid_r;
reg [1:0]  outport_bresp_r;

always @ *
begin
    case (write_port_q)
    `ADDR_SEL_W'd1:
    begin
        outport_bvalid_r = outport_peripheral0_bvalid_i;
        outport_bresp_r  = outport_peripheral0_bresp_i;
    end
    default:
    begin
        outport_bvalid_r = outport_bvalid_i;
        outport_bresp_r  = outport_bresp_i;
    end
    endcase
end

assign inport_bvalid_o  = outport_bvalid_r;
assign inport_bresp_o   = outport_bresp_r;

reg inport_awready_r;
reg inport_wready_r;

always @ *
begin
    case (write_port_r)
    `ADDR_SEL_W'd1:
    begin
        inport_awready_r = outport_peripheral0_awready_i;
        inport_wready_r  = outport_peripheral0_wready_i;
    end
    default:
    begin
        inport_awready_r = outport_awready_i;
        inport_wready_r  = outport_wready_i;
    end
    endcase
end

assign inport_awready_o = write_accept_w & ~awvalid_q & inport_awready_r;
assign inport_wready_o  = write_accept_w & ~wvalid_q & inport_wready_r;

//-----------------------------------------------------------------
// Transaction timeout detection (read AR->R and write AW->B)
//-----------------------------------------------------------------
reg [31:0] read_timer_q;
reg [31:0] write_timer_q;
reg        rd_active_q;
reg        wr_active_q;
reg        timeout_flag_q;

// A read starts on AR valid and completes on the R handshake.
wire rd_start_w = inport_arvalid_i;
wire rd_done_w  = inport_rvalid_o & inport_rready_i;
// A write starts on AW valid and completes on the B handshake.
wire wr_start_w = inport_awvalid_i;
wire wr_done_w  = inport_bvalid_o & inport_bready_i;

always @ (posedge clk_i)
if (rst_i)
begin
    read_timer_q   <= 32'd0;
    write_timer_q  <= 32'd0;
    rd_active_q    <= 1'b0;
    wr_active_q    <= 1'b0;
    timeout_flag_q <= 1'b0;
end
else
begin
    // Read timer: run while a read is outstanding, clear on completion.
    if (rd_done_w)
    begin
        rd_active_q  <= 1'b0;
        read_timer_q <= 32'd0;
    end
    else if (rd_start_w || rd_active_q)
    begin
        rd_active_q  <= 1'b1;
        read_timer_q <= read_timer_q + 32'd1;
    end

    // Write timer: run while a write is outstanding, clear on completion.
    if (wr_done_w)
    begin
        wr_active_q   <= 1'b0;
        write_timer_q <= 32'd0;
    end
    else if (wr_start_w || wr_active_q)
    begin
        wr_active_q   <= 1'b1;
        write_timer_q <= write_timer_q + 32'd1;
    end

    // Sticky timeout flag: set when either timer reaches the threshold.
    if ((rd_active_q && (read_timer_q  >= TIMEOUT_THRESHOLD)) ||
        (wr_active_q && (write_timer_q >= TIMEOUT_THRESHOLD)))
        timeout_flag_q <= 1'b1;
end

assign timeout_flag = timeout_flag_q;

endmodule

{"code": [{"rtl/elevator_control_system.sv": "/*
 * Elevator Control System
 *
 * This module implements an FSM-based elevator control system capable of managing multiple floors,
 * handling call requests, and responding to emergency stops. The elevator transitions between
 * five main states: Idle, Moving Up, Moving Down, Emergency Halt, Door Open. It prioritizes floor requests
 * based on direction, moving to the highest or lowest requested floor depending on the current direction.
 *
 * Overloading Warning feature: a new highest-priority OVERLOAD_HALT state halts all
 * elevator operation whenever `overload_detected` is asserted (from any state), and the
 * system returns to IDLE once the overload condition is cleared.
*/

module elevator_control_system #(
    parameter N = 8, //Number of floors
    parameter DOOR_OPEN_TIME_MS = 500 // Door open time in milliseconds
) (
    input wire clk,                   // 100MHz clock input
    input wire reset,                 // Active-high reset signal
    input wire [N-1:0] call_requests, // External Floor call requests
    input wire emergency_stop,        // Emergency stop signal
    input wire overload_detected,     // Asserted when the elevator load exceeds the safe threshold
    output wire [$clog2(N)-1:0] current_floor, // Current floor of the elevator
    output reg direction,             // Elevator direction: 1 = up, 0 = down
    output reg door_open,             // Door open signal
    output reg [2:0] system_status,    // Elevator system state indicator
    output wire overload_warning,      // Asserted when the elevator is in an overload condition
    output wire [6:0] seven_seg_out    // Seven-segment display output for current floor visualization
);

// State Encoding
localparam IDLE = 3'b000;          // Elevator is idle
localparam MOVING_UP = 3'b001;     // Elevator moving up
localparam MOVING_DOWN = 3'b010;   // Elevator moving down
localparam EMERGENCY_HALT = 3'b011;// Emergency halt state
localparam DOOR_OPEN = 3'b100;     // Door open state
localparam OVERLOAD_HALT = 3'b101; // Overload halt state

// Internal registers
reg [N-1:0] call_requests_internal;   // Internal copy of call requests
reg [2:0] present_state, next_state; // FSM current and next states
reg [$clog2(N)-1:0] max_request;     // Highest requested floor
reg [$clog2(N)-1:0] min_request;    // Lowest requested floor

// Door open time configuration
`ifdef SIMULATION
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam SIM_DOOR_OPEN_TIME_MS = 0.05; // Shorter door open time for simulation
    localparam DOOR_OPEN_CYCLES = (SIM_DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000); // Door open cycles for simulation
`else
    // Calculating door open cycles based on time and clock frequency
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam DOOR_OPEN_CYCLES = (DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000);   // Door open cycles for real implementation
`endif


reg [$clog2(DOOR_OPEN_CYCLES)-1:0] door_open_counter;   // Counter for door open duration

reg [$clog2(N)-1:0] current_floor_reg, current_floor_next=0;

assign current_floor = current_floor_reg;

// Overload warning is driven combinationally from the FSM state so it never
// lags the machine by a cycle.
assign overload_warning = (present_state == OVERLOAD_HALT);

// FSM state transition
always@(posedge clk or posedge reset) begin
    if(reset)begin
        present_state <= IDLE;
        system_status <= IDLE;
        current_floor_reg <= 0;
        max_request <= 0;
        min_request <= N-1;
    end else begin
        present_state <= next_state;
        system_status <= next_state;
        current_floor_reg <= current_floor_next;

        // Calculate max_request and min_request based on active requests
        max_request = 0;
        min_request = N-1;
        for (integer i = 0; i < N; i = i + 1) begin
            if (call_requests_internal[i]) begin
                if (i > max_request) max_request = i;
                if (i < min_request) min_request = i;
            end
        end
    end
end

always@(*)begin
    next_state = present_state;
    current_floor_next = current_floor_reg;

    // Overload has top priority: from ANY state, jump to OVERLOAD_HALT while the
    // overload condition persists, halting all movement.
    if (overload_detected) begin
        next_state = OVERLOAD_HALT;
    end else begin
    case(present_state)
        IDLE:begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal != 0)begin
                if(max_request > current_floor_reg)begin
                    next_state = MOVING_UP;
                end else if(min_request < current_floor_reg) begin
                    next_state = MOVING_DOWN;
                end
            end
        end

        MOVING_UP: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg+1]) begin
                current_floor_next = current_floor_reg + 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg >= max_request) begin
                // If we reach the highest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg + 1;
                next_state = MOVING_UP;
            end
        end

        MOVING_DOWN: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg-1]) begin
                current_floor_next = current_floor_reg - 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg <= min_request) begin
                // If we reach the lowest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg - 1;
                next_state = MOVING_DOWN;
            end
        end

        EMERGENCY_HALT: begin
            if (!emergency_stop) begin
                next_state = IDLE;
                current_floor_next = 0; // Optionally reset to ground floor
            end
        end

        DOOR_OPEN: begin
            if (door_open_counter == 0) begin
                next_state = IDLE;
            end else begin
                next_state = DOOR_OPEN;
            end
        end

        OVERLOAD_HALT: begin
            // Recovery: once the overload condition is cleared (guaranteed here,
            // since overload_detected is 0 in this branch) resume from IDLE.
            next_state = IDLE;
        end
    endcase
    end
end


// Door open control logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        door_open_counter <= 0;
        door_open <= 0;
    end else begin
        if (present_state == DOOR_OPEN) begin
            if (door_open_counter > 0) begin
                door_open <= 1;
                door_open_counter <= door_open_counter - 1;
            end else begin
                door_open <= 0;
                next_state = IDLE;
            end
        end else begin
            door_open <= 0;
            door_open_counter <= DOOR_OPEN_CYCLES; // Reset door open counter
        end
    end
end

// Call request management
always@(*)begin
    if(reset) begin
        call_requests_internal = 0;
    end else begin
        if(call_requests_internal[current_floor_reg])begin
            call_requests_internal[current_floor_reg] = 0;      // Clear served request
        end
        call_requests_internal = call_requests_internal | call_requests;    // Update requests
    end
end

// Direction control logic
always@(*)begin
    if(reset) begin
        direction = 1;
    end else begin
        if(present_state == MOVING_UP)begin
            direction = 1;
        end else if (present_state == MOVING_DOWN) begin
            direction = 0;
        end else begin
            direction = 1;
        end
    end
end


// Seven-segment display converter instantiation
floor_to_seven_segment #(.N(8)) floor_display_converter (
    .floor_display(current_floor_reg),
    .seven_seg_out(seven_seg_out)
);

endmodule"}, {"rtl/floor_to_seven_segment.sv": "module floor_to_seven_segment #(
    parameter N = 8 // Number of floors, assumes floors are numbered 0 to N-1
)(
    input wire [$clog2(N)-1:0] floor_display, // Binary floor number input
    output reg [6:0] seven_seg_out // Seven-segment display output: {a, b, c, d, e, f, g}
);

    always @(*) begin
        case (floor_display)
            4'd0: seven_seg_out = 7'b1111110; // 0
            4'd1: seven_seg_out = 7'b0110000; // 1
            4'd2: seven_seg_out = 7'b1101101; // 2
            4'd3: seven_seg_out = 7'b1111001; // 3
            4'd4: seven_seg_out = 7'b0110011; // 4
            4'd5: seven_seg_out = 7'b1011011; // 5
            4'd6: seven_seg_out = 7'b1011111; // 6
            4'd7: seven_seg_out = 7'b1110000; // 7
            4'd8: seven_seg_out = 7'b1111111; // 8
            4'd9: seven_seg_out = 7'b1111011; // 9
            default: seven_seg_out = 7'b0000000; // Blank display for invalid floor numbers
        endcase
    end

endmodule"}]}

// Hebbian-rule trainer : Moore FSM (11 states) applying w(new)=w(old)+x*t,
// bias(new)=bias(old)+t for a two-input bipolar logic gate.
module hebbian_rule (
    input  logic                clk,
    input  logic                rst,          // async, active-low
    input  logic                start,
    input  logic signed [3:0]   a,
    input  logic signed [3:0]   b,
    input  logic        [1:0]   gate_select,
    output logic signed [3:0]   w1,
    output logic signed [3:0]   w2,
    output logic signed [3:0]   bias,
    output logic        [3:0]   present_state,
    output logic        [3:0]   next_state
);

    // State encoding
    localparam [3:0] STATE_0  = 4'd0,   // reset / idle
                     STATE_1  = 4'd1,   // capture inputs
                     STATE_2  = 4'd2,   // target assignment
                     STATE_3  = 4'd3,
                     STATE_4  = 4'd4,
                     STATE_5  = 4'd5,
                     STATE_6  = 4'd6,
                     STATE_7  = 4'd7,   // compute deltas
                     STATE_8  = 4'd8,   // update weights and bias
                     STATE_9  = 4'd9,   // loop through iterations
                     STATE_10 = 4'd10;  // return to initial state

    logic signed [3:0] x1, x2;
    logic signed [3:0] target;
    logic signed [3:0] delta_w1, delta_w2, delta_b;

    // Target for the currently captured input combination.
    gate_target gt (
        .gate_select(gate_select),
        .x1(x1),
        .x2(x2),
        .t(target)
    );

    // Present-state register
    always_ff @(posedge clk or negedge rst) begin
        if (!rst)
            present_state <= STATE_0;
        else
            present_state <= next_state;
    end

    // Next-state logic (Moore)
    always_comb begin
        case (present_state)
            STATE_0:  next_state = start ? STATE_1 : STATE_0;
            STATE_1:  next_state = STATE_2;
            STATE_2:  next_state = STATE_3;
            STATE_3:  next_state = STATE_4;
            STATE_4:  next_state = STATE_5;
            STATE_5:  next_state = STATE_6;
            STATE_6:  next_state = STATE_7;
            STATE_7:  next_state = STATE_8;
            STATE_8:  next_state = STATE_9;
            STATE_9:  next_state = start ? STATE_1 : STATE_10;
            STATE_10: next_state = STATE_0;
            default:  next_state = STATE_0;
        endcase
    end

    // Datapath : weights/bias persist across passes (cleared only on reset).
    always_ff @(posedge clk or negedge rst) begin
        if (!rst) begin
            w1       <= 4'sd0;
            w2       <= 4'sd0;
            bias     <= 4'sd0;
            x1       <= 4'sd0;
            x2       <= 4'sd0;
            delta_w1 <= 4'sd0;
            delta_w2 <= 4'sd0;
            delta_b  <= 4'sd0;
        end
        else begin
            case (present_state)
                STATE_1: begin
                    x1 <= a;                       // capture inputs
                    x2 <= b;
                end
                STATE_7: begin
                    delta_w1 <= x1 * target;       // Hebbian deltas
                    delta_w2 <= x2 * target;
                    delta_b  <= target;
                end
                STATE_8: begin
                    w1   <= w1   + delta_w1;        // apply the update
                    w2   <= w2   + delta_w2;
                    bias <= bias + delta_b;
                end
                default: begin
                    // hold
                end
            endcase
        end
    end

endmodule

// Target generator : bipolar {-1,+1} logic-gate truth tables.
module gate_target (
    input  logic        [1:0] gate_select,
    input  logic signed [3:0] x1,
    input  logic signed [3:0] x2,
    output logic signed [3:0] t
);
    logic p1, p2;
    assign p1 = (x1 == 4'sd1);   // +1 when input is logic-1
    assign p2 = (x2 == 4'sd1);

    always_comb begin
        case (gate_select)
            2'b00: t = (p1 & p2) ?  4'sd1 : -4'sd1;   // AND
            2'b01: t = (p1 | p2) ?  4'sd1 : -4'sd1;   // OR
            2'b10: t = (p1 & p2) ? -4'sd1 :  4'sd1;   // NAND
            2'b11: t = (p1 | p2) ? -4'sd1 :  4'sd1;   // NOR
            default: t = 4'sd0;
        endcase
    end
endmodule

//======================================================================
// microcode_sequencer
//   5-bit instruction -> 4-bit control-store address, with an integrated
//   LIFO stack, program counter, bit-slice ripple-carry ALU, auxiliary
//   register, instruction decoder and result register.
//
//   Control-signal polarity / enable-combination discipline (spec):
//     active-low ports are inverted before use;
//     aux-reg write-enable = rce OR ~r_en
//     aux-reg mux-select    = rsel AND ~r_en
//     output-drive          = oe  AND ~oen
//======================================================================
module microcode_sequencer (
    input             clk,
    input             c_n_in,     // ripple-carry adder carry-in
    input             c_inc_in,   // PC incrementer carry-in
    input             r_en,       // ACTIVE LOW auxiliary register enable
    input             cc,         // ACTIVE LOW condition code
    input             ien,        // ACTIVE LOW instruction enable
    input      [3:0]  d_in,       // 4-bit data input bus
    input      [4:0]  instr_in,   // 5-bit opcode
    input             oen,        // ACTIVE LOW output enable
    output     [3:0]  d_out,      // 4-bit address output bus
    output            c_n_out,    // adder carry-out (HIGH = carry)
    output            c_inc_out,  // PC incrementer carry-out (HIGH = carry)
    output            full,       // ACTIVE HIGH stack full
    output            empty       // ACTIVE HIGH stack empty
);

    // ---------------- Opcodes ----------------
    localparam [4:0] OP_PRST  = 5'b00000; // program reset
    localparam [4:0] OP_FPC   = 5'b00001; // fetch PC
    localparam [4:0] OP_FR    = 5'b00010; // fetch aux register
    localparam [4:0] OP_FD    = 5'b00011; // fetch D
    localparam [4:0] OP_FRD   = 5'b00100; // fetch R + D
    localparam [4:0] OP_PUSH  = 5'b01011; // push PC
    localparam [4:0] OP_POP   = 5'b01110; // pop PC

    // ---------------- Architectural state ----------------
    reg [3:0] pc_reg;
    reg [3:0] aux_reg;
    reg [3:0] result_reg;
    reg [3:0] stack_ram [0:15];
    reg [4:0] stack_ptr;          // 0..16

    // ---------------- Decoder control signals ----------------
    reg [1:0] a_mux_sel;
    reg [1:0] b_mux_sel;
    reg       cen;                // carry enable for adder
    reg       rst_stack;          // reset stack pointer
    reg       inc;                // enable PC increment
    reg       pc_mux_sel;         // 1 = adder result, 0 = current PC
    reg       rsel;               // aux-reg mux select term
    reg       rce;                // aux-reg chip enable term
    reg       out_ce;             // result-register capture enable
    reg       push;               // stack push
    reg       pop;                // stack pop
    reg       stack_we;           // stack write enable
    reg       stack_re;           // stack read enable
    reg       stack_mux_sel;      // 1 = d_in, 0 = pc
    reg       oe;                 // decoder output-enable (ACTIVE HIGH)

    wire instr_enable = ~ien;     // decoder active when ien low

    // ---------------- Instruction decoder ----------------
    always @(*) begin
        // safe defaults
        a_mux_sel     = 2'b10;    // 0000
        b_mux_sel     = 2'b10;    // 0000
        cen           = 1'b0;
        rst_stack     = 1'b0;
        inc           = 1'b1;     // PC advances by default
        pc_mux_sel    = 1'b0;
        rsel          = 1'b0;
        rce           = 1'b0;
        out_ce        = 1'b0;
        push          = 1'b0;
        pop           = 1'b0;
        stack_we      = 1'b0;
        stack_re      = 1'b0;
        stack_mux_sel = 1'b0;
        oe            = 1'b0;

        if (instr_enable) begin
            case (instr_in)
                OP_PRST: begin
                    a_mux_sel  = 2'b10;   // 0000
                    b_mux_sel  = 2'b10;   // 0000
                    cen        = 1'b0;
                    rst_stack  = 1'b1;
                    pc_mux_sel = 1'b1;    // load adder(=0) [+carry] into PC
                    inc        = 1'b1;
                    oe         = 1'b1;
                end
                OP_FPC: begin
                    a_mux_sel  = 2'b10;   // 0000
                    b_mux_sel  = 2'b00;   // pc
                    oe         = 1'b1;
                end
                OP_FR: begin
                    a_mux_sel  = 2'b01;   // aux_reg
                    b_mux_sel  = 2'b10;   // 0000
                    oe         = 1'b1;
                end
                OP_FD: begin
                    a_mux_sel  = 2'b00;   // d_in
                    b_mux_sel  = 2'b10;   // 0000
                    oe         = 1'b1;
                end
                OP_FRD: begin
                    a_mux_sel  = 2'b00;   // d_in
                    b_mux_sel  = 2'b11;   // aux_reg
                    oe         = 1'b1;
                end
                OP_PUSH: begin
                    push          = 1'b1;
                    stack_we      = 1'b1;
                    stack_mux_sel = 1'b0; // pc onto stack
                    out_ce        = 1'b1;
                end
                OP_POP: begin
                    pop        = 1'b1;
                    stack_re   = 1'b1;
                    a_mux_sel  = 2'b10;   // 0000
                    b_mux_sel  = 2'b01;   // stack data
                    oe         = 1'b1;
                end
                default: begin
                    oe = 1'b0;
                end
            endcase
        end
    end

    // ---------------- Composite enables ----------------
    wire aux_we      = rce | (~r_en);       // aux-reg write enable
    wire aux_mux_sel = rsel & (~r_en);      // aux-reg mux select
    wire out_drive   = oe   & (~oen);       // output-drive enable

    // ---------------- LIFO stack read (top = ptr-1) ----------------
    wire [4:0] stack_rd_addr = (stack_ptr == 5'd0) ? 5'd0 : (stack_ptr - 5'd1);
    wire [3:0] stack_data    = stack_ram[stack_rd_addr];

    assign full  = (stack_ptr == 5'd16);
    assign empty = (stack_ptr == 5'd0);

    // ---------------- A / B input muxes ----------------
    reg [3:0] a_mux_out;
    always @(*) begin
        case (a_mux_sel)
            2'b00:   a_mux_out = d_in;
            2'b01:   a_mux_out = aux_reg;
            default: a_mux_out = 4'b0000;   // 2'b10 / 2'b11
        endcase
    end

    reg [3:0] b_mux_out;
    always @(*) begin
        case (b_mux_sel)
            2'b00:   b_mux_out = pc_reg;
            2'b01:   b_mux_out = stack_data;
            2'b10:   b_mux_out = 4'b0000;
            default: b_mux_out = aux_reg;   // 2'b11
        endcase
    end

    // ---------------- Ripple-carry full adder ----------------
    wire        cin_eff  = cen ? c_n_in : 1'b0;
    wire [4:0]  add_full = a_mux_out + b_mux_out + cin_eff;
    wire [3:0]  adder    = add_full[3:0];

    assign c_n_out = add_full[4];
    assign d_out   = out_drive ? adder : 4'b0000;

    // ---------------- PC datapath ----------------
    wire [3:0] pc_mux_out = pc_mux_sel ? adder : pc_reg;
    wire [4:0] pc_inc_full = inc ? (pc_mux_out + c_inc_in) : {1'b0, pc_mux_out};
    wire [3:0] pc_next     = pc_inc_full[3:0];
    assign c_inc_out       = pc_inc_full[4];

    // ---------------- Auxiliary-register mux ----------------
    wire [3:0] aux_mux_out = aux_mux_sel ? adder : d_in;

    // ---------------- Sequential update ----------------
    always @(posedge clk) begin
        // Program counter register
        pc_reg <= pc_next;

        // Auxiliary register
        if (aux_we)
            aux_reg <= aux_mux_out;

        // Result register
        if (out_ce)
            result_reg <= adder;

        // Stack
        if (rst_stack) begin
            stack_ptr <= 5'd0;
        end else begin
            if (stack_we && push && !full)
                stack_ram[stack_ptr] <= stack_mux_sel ? d_in : pc_reg;

            if (push && !full)
                stack_ptr <= stack_ptr + 5'd1;
            else if (pop && !empty)
                stack_ptr <= stack_ptr - 5'd1;
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    pc_reg = 0;
    aux_reg = 0;
    result_reg = 0;
  end

endmodule

module cvdp_prbs_gen #(
    parameter CHECK_MODE  = 0,   // 0 = generator, 1 = checker
    parameter POLY_LENGTH = 31,  // number of LFSR stages
    parameter POLY_TAP    = 3,   // tap position XORed with POLY_LENGTH
    parameter WIDTH       = 16   // data_in / data_out width
)(
    input                    clk,
    input                    rst,        // synchronous, active-high
    input      [WIDTH-1:0]   data_in,
    output reg [WIDTH-1:0]   data_out
);

    // PRBS shift register, conceptually 1-indexed 1..POLY_LENGTH so the
    // spec's "positions POLY_TAP and POLY_LENGTH" map directly to bit indices.
    reg [POLY_LENGTH:1] prbs;

    reg [POLY_LENGTH:1] prbs_v;
    reg [WIDTH-1:0]     out_v;
    reg                 feedback;
    integer             i;

    always @(posedge clk) begin
        if (rst) begin
            prbs     <= {POLY_LENGTH{1'b1}};   // seed = all ones
            data_out <= {WIDTH{1'b1}};
        end else begin
            prbs_v = prbs;
            for (i = 0; i < WIDTH; i = i + 1) begin
                // Word-wide LFSR: unroll the single-bit recurrence WIDTH times.
                feedback = prbs_v[POLY_TAP] ^ prbs_v[POLY_LENGTH];
                if (CHECK_MODE == 0)
                    out_v[i] = feedback;               // generated PRBS bit
                else
                    out_v[i] = feedback ^ data_in[i];  // error = expected XOR received
                // shift right, insert feedback bit at the MSB (POLY_LENGTH)
                prbs_v = {feedback, prbs_v[POLY_LENGTH:2]};
            end
            prbs     <= prbs_v;
            data_out <= out_v;
        end
    end

endmodule

module reed_solomon_encoder #(
    parameter DATA_WIDTH = 8,   // Width of input data symbols
    parameter N = 255,         // Total number of symbols in the codeword
    parameter K = 223          // Number of data symbols
) (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [DATA_WIDTH-1:0] data_in,
    input wire valid_in,
    output reg [DATA_WIDTH-1:0] codeword_out,
    output reg valid_out,
    output reg [DATA_WIDTH-1:0] parity_0,
    output reg [DATA_WIDTH-1:0] parity_1
);

    localparam PARITY_SYMBOLS = N - K;// Number of parity symbols

    // Internal registers for shift-register based encoding
    reg [DATA_WIDTH-1:0] feedback;

    // The feedback term is the current data symbol XORed with the previous
    // (highest-order) parity value, and it is then combined with the
    // generator-polynomial coefficients to update the parity registers.
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all registers
            parity_0     <= 0;
            parity_1     <= 0;
            codeword_out <= 0;
            valid_out    <= 0;
            feedback     <= 0;
        end else if (enable && valid_in) begin
            // Feedback from the last stage of the shift register
            feedback     <= data_in ^ parity_1;
            // New parity symbols: feedback combined with the generator
            // polynomial coefficients and XORed with the previous parity.
            parity_0     <= (data_in ^ parity_1) ^ generator_polynomial(0);
            parity_1     <= parity_0 ^ ((data_in ^ parity_1) ^ generator_polynomial(1));
            // Codeword streams out the data symbol together with parity
            codeword_out <= data_in;
            valid_out    <= 1'b1;
        end else begin
            valid_out    <= 1'b0;
        end
    end

    // Generator polynomial coefficients: selects 8'h1D or 8'h33 by index
    function [DATA_WIDTH-1:0] generator_polynomial(input integer index);
        begin
            if (index == 0)
                generator_polynomial = 8'h1D;
            else
                generator_polynomial = 8'h33;
        end
    endfunction

endmodule

module secure_read_write_register_bank #(
    parameter p_address_width = 8,
    parameter p_data_width    = 8,
    parameter p_unlock_code_0 = 8'hAB,
    parameter p_unlock_code_1 = 8'hCD
)(
    input  wire [p_address_width-1:0] i_addr,             // target address
    input  wire [p_data_width-1:0]    i_data_in,          // write data
    input  wire                       i_read_write_enable,// 0=write, 1=read
    input  wire                       i_capture_pulse,    // rising edge = operation (acts as clock)
    input  wire                       i_rst_n,            // async active-low reset (unlock SM)
    output reg  [p_data_width-1:0]    o_data_out          // read data
);

    localparam integer DEPTH = (1 << p_address_width);

    // Unlock state machine
    localparam [1:0] S_LOCKED   = 2'd0,
                     S_GOT0     = 2'd1,   // correct code written to address 0
                     S_UNLOCKED = 2'd2;

    reg [1:0] state;
    reg [p_data_width-1:0] mem [0:DEPTH-1];

    // i_capture_pulse behaves as the clock for the register bank; i_rst_n is an
    // asynchronous active-low reset of the unlock state machine.
    always @(posedge i_capture_pulse or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state      <= S_LOCKED;
            o_data_out <= {p_data_width{1'b0}};
        end else begin
            // ---- default read output ----
            // o_data_out is 0 for writes, for locked reads, and for reads of the
            // write-only addresses 0 and 1.
            if (i_read_write_enable && (state == S_UNLOCKED) &&
                (i_addr > {{(p_address_width-1){1'b0}}, 1'b1})) begin
                o_data_out <= mem[i_addr];
            end else begin
                o_data_out <= {p_data_width{1'b0}};
            end

            // ---- unlock sequence + write handling ----
            if (!i_read_write_enable) begin
                // WRITE operation
                if (i_addr == {p_address_width{1'b0}}) begin
                    // address 0 : must receive unlock code 0
                    if (i_data_in == p_unlock_code_0)
                        state <= S_GOT0;
                    else
                        state <= S_LOCKED;
                end else if (i_addr == {{(p_address_width-1){1'b0}}, 1'b1}) begin
                    // address 1 : must receive unlock code 1 while in S_GOT0
                    if ((i_data_in == p_unlock_code_1) && (state == S_GOT0))
                        state <= S_UNLOCKED;
                    else
                        state <= S_LOCKED;
                end else begin
                    // other addresses : writable only when unlocked; an
                    // intervening write to a normal address breaks a pending
                    // unlock sequence.
                    if (state == S_UNLOCKED)
                        mem[i_addr] <= i_data_in;
                    else
                        state <= S_LOCKED;
                end
            end else begin
                // READ operation.  A read while a sequence is pending (S_GOT0)
                // breaks the required back-to-back addr0/addr1 writes.
                if (state == S_GOT0)
                    state <= S_LOCKED;
            end
        end
    end

endmodule

module sipo_top#(parameter DATA_WIDTH = 16,                                   // Width of the shift register
                 parameter SHIFT_DIRECTION = 1,                               // Determines Left or right shift
                 parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1),  // Encoded width
                 parameter CRC_WIDTH = DATA_WIDTH/2,                          // CRC width
                 parameter [7:0] POLY = 8'b10101010                          // CRC polynomial
                 ) (

   input clk,                                   // Clock input
   input reset_n,                               // Reset input
   input serial_in,                             // Serial input to SIPO
   input shift_en,                              // Shift enable
   input [CODE_WIDTH-1:0] received,             // Received encoded data
   input [CRC_WIDTH-1:0]  received_crc,         // Received CRC
   output done,                                 // Done signal indicating completion of shift
   output [DATA_WIDTH-1:0] data_out,            // corrected output of ecc block
   output [CODE_WIDTH-1:0] encoded,             // Encoded output
   output error_detected,                       // Error detected flag
   output error_corrected,                      // Error corrected  flag
   output [CRC_WIDTH-1:0]  crc_out,             // CRC generator output
   output crc_error                             // Compares received_crc and crc_out

   );

wire [DATA_WIDTH-1:0] parallel_out;
wire [DATA_WIDTH-1:0] sipo_out_ecc_in;

serial_in_parallel_out_8bit  #(.WIDTH(DATA_WIDTH), .SHIFT_DIRECTION(SHIFT_DIRECTION)) uut_sipo (
        .clk           (clk),               // Clock input
        .reset_n       (reset_n),           // Reset input
        .sin           (serial_in),         // Serial input to SIPO
        .shift_en      (shift_en),          // Shift enable for SIPO
        .done          (done),              // Done signal from SIPO
        .parallel_out  (parallel_out)       // Parallel output from SIPO
    );

//assign sipo_out_ecc_in = (done)? parallel_out: {DATA_WIDTH{1'b0}};

onebit_ecc#(.DATA_WIDTH(DATA_WIDTH),.CODE_WIDTH(CODE_WIDTH)) uut_onebit_ecc1 (

    .data_in(parallel_out),
    .encoded(encoded),
    .received(received),
    .data_out(data_out),
    .error_detected(error_detected),
    .error_corrected(error_corrected)
    );

crc_generator #(.DATA_WIDTH(DATA_WIDTH), .CRC_WIDTH(CRC_WIDTH), .POLY(POLY)) uut_crc (
    .clk     (clk),
    .rst     (reset_n),
    .data_in (parallel_out),
    .crc_out (crc_out)
    );

assign crc_error = (received_crc != crc_out);

endmodule

module serial_in_parallel_out_8bit  #(
    parameter WIDTH = 64,               // Width of the shift register
    parameter SHIFT_DIRECTION = 1       // Determines if shifting
)(
    input clk,                          // Clock signal
    input reset_n,                      // Active low reset
    input sin,                          // Serial input
    input shift_en,                     // Shift enable signal
    output reg done,                    // Done signal indicating completion of shift
    output reg [WIDTH-1:0] parallel_out // Parallel output
);

    localparam COUNT_WIDTH = $clog2(WIDTH); // Calculate width for shift_count

    reg [COUNT_WIDTH:0] shift_count;        // Parameterized counter to track number of shifts


    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            parallel_out     <= {WIDTH{1'b0}};
            done             <= 1'b0;
            shift_count      <= {COUNT_WIDTH{1'b0}};
        end else begin
            if (shift_en) begin
                if (SHIFT_DIRECTION) begin
                    parallel_out    <= {parallel_out[WIDTH-2:0], sin};
                end else begin
                    parallel_out    <= {sin, parallel_out[WIDTH-1:1]};
                end
                shift_count   <= shift_count + 1;
            end

            if (shift_count == (WIDTH - 1)) begin
                done         <= 1'b1;
                shift_count  <= {COUNT_WIDTH{1'b0}};
            end else begin
                done         <= 1'b0;
            end
        end
    end
endmodule


module onebit_ecc #(
    parameter DATA_WIDTH = 4,                                  // Width of the data input
    parameter CODE_WIDTH = DATA_WIDTH + $clog2(DATA_WIDTH + 1) // Encoded width
)(
    input [DATA_WIDTH-1:0] data_in,                     // Input data
    output reg [CODE_WIDTH-1:0] encoded,                // Encoded output
    input [CODE_WIDTH-1:0] received,                    // Received encoded data
    output reg [DATA_WIDTH-1:0] data_out,               // Corrected output
    output reg error_detected,                          // Error detected flag
    output reg error_corrected                          // Error corrected flag
);

    localparam PARITY_BITS = CODE_WIDTH - DATA_WIDTH;   // Number of parity bits

    reg [PARITY_BITS-1:0] syndrome;                     // Syndrome for error detection
    reg [CODE_WIDTH-1:0] corrected_data;                // Corrected received data


    integer idx_i, idx_j, idx_k;
    integer idx_m, idx_n;
    integer idx_p, idx_q;


    always @(*) begin
        encoded = 0;
        idx_k = 0;


        for (idx_i = 0; idx_i < CODE_WIDTH; idx_i = idx_i + 1) begin
            if ((idx_i + 1) & (idx_i)) begin
                encoded[idx_i] = data_in[idx_k];
                idx_k = idx_k + 1;
            end
        end


        for (idx_i = 0; idx_i < PARITY_BITS; idx_i = idx_i + 1) begin
            encoded[(1 << idx_i) - 1] = 0;
            for (idx_j = 0; idx_j < CODE_WIDTH; idx_j = idx_j + 1) begin
                if (((idx_j + 1) & (1 << idx_i)) && ((idx_j + 1) != (1 << idx_i))) begin
                    encoded[(1 << idx_i) - 1] = encoded[(1 << idx_i) - 1] ^ encoded[idx_j];
                end
            end
        end
    end


    always @(*) begin
        syndrome = 0;
        for (idx_m = 0; idx_m < PARITY_BITS; idx_m = idx_m + 1) begin
            for (idx_n = 0; idx_n < CODE_WIDTH; idx_n = idx_n + 1) begin
                if ((idx_n + 1) & (1 << idx_m)) begin
                    syndrome[idx_m] = syndrome[idx_m] ^ received[idx_n];
                end
            end
        end
    end


    always @(*) begin
        error_detected = |syndrome;
    end


    always @(*) begin
        corrected_data = received;
        if (error_detected) begin
            corrected_data[syndrome - 1] = ~corrected_data[syndrome - 1];
        end
    end


    always @(*) begin
        idx_q = 0;
        for (idx_p = 0; idx_p < CODE_WIDTH; idx_p = idx_p + 1) begin
            if ((idx_p + 1) & (idx_p)) begin
                data_out[idx_q] = corrected_data[idx_p];
                idx_q = idx_q + 1;
            end
        end
    end


    always @(*) begin
        error_corrected = error_detected;
    end

endmodule


module crc_generator #(
    parameter DATA_WIDTH = 16,
    parameter CRC_WIDTH  = DATA_WIDTH/2,
    parameter [7:0] POLY = 8'b10101010
)(
    input                        clk,
    input                        rst,      // Active-low synchronous reset (tied to reset_n)
    input      [DATA_WIDTH-1:0]  data_in,
    output reg [CRC_WIDTH-1:0]   crc_out
);

    integer i;
    reg [CRC_WIDTH-1:0] crc_reg;

    // Combinational MSB-first CRC over all DATA_WIDTH bits (MSB processed first)
    always @(*) begin
        crc_reg = {CRC_WIDTH{1'b0}};
        for (i = DATA_WIDTH-1; i >= 0; i = i - 1) begin
            if (crc_reg[CRC_WIDTH-1] ^ data_in[i])
                crc_reg = (crc_reg << 1) ^ POLY[CRC_WIDTH-1:0];
            else
                crc_reg = (crc_reg << 1);
        end
    end

    // Registered output with synchronous active-low reset
    always @(posedge clk) begin
        if (!rst)
            crc_out <= {CRC_WIDTH{1'b0}};
        else
            crc_out <= crc_reg;
    end

endmodule

module sprite_controller_fsm#(
   parameter MEM_ADDR_WIDTH = 16,
   parameter PIXEL_WIDTH = 24,
   parameter SPRITE_WIDTH = 16,
   parameter SPRITE_HEIGHT = 16,
   parameter WAIT_WIDTH    = 4,
   parameter N_ROM         = 256
)(
   input  logic clk,
   input  logic rst_n,
   input  logic [WAIT_WIDTH-1:0] i_wait,
   output logic rw,
   output logic [MEM_ADDR_WIDTH-1:0] write_addr,
   output logic [PIXEL_WIDTH-1:0] write_data,
   output logic [SPRITE_WIDTH-1:0] x_pos,
   output logic [SPRITE_HEIGHT-1:0] y_pos,
   input  logic [PIXEL_WIDTH-1:0] pixel_out,
   output logic done
);

 typedef enum logic [2:0] {
       IDLE,
       INIT_WRITE,
       WRITE,
       INIT_READ,
       READ,
       WAIT,
       DONE
   } state_t;

   state_t current_state, next_state;

   logic [MEM_ADDR_WIDTH-1:0] addr_counter;
   logic [PIXEL_WIDTH-1:0] data_counter;
   logic [WAIT_WIDTH-1:0] wait_counter;

  // ---------------------------------------------------------------
  // Sequential: state + counters
  // ---------------------------------------------------------------
  always_ff @(posedge clk or negedge rst_n) begin
     if (!rst_n) begin
        current_state <= IDLE;
        addr_counter  <= '0;
        data_counter  <= '0;
        wait_counter  <= '0;
     end else begin
        case (current_state)
           IDLE: begin
              // reset counters, move to INIT_WRITE on the next cycle
              addr_counter <= '0;
              data_counter <= '0;
              wait_counter <= '0;
              current_state <= INIT_WRITE;
           end

           INIT_WRITE: begin
              addr_counter  <= '0;
              current_state <= WRITE;
           end

           WRITE: begin
              if (addr_counter == N_ROM - 1) begin
                 current_state <= INIT_READ;
              end else begin
                 addr_counter <= addr_counter + 1'b1;
                 data_counter <= data_counter + 1'b1;
              end
           end

           INIT_READ: begin
              addr_counter  <= '0;
              current_state <= READ;
           end

           READ: begin
              if (addr_counter == N_ROM - 1) begin
                 current_state <= WAIT;
              end else begin
                 addr_counter <= addr_counter + 1'b1;
              end
           end

           WAIT: begin
              if (wait_counter == i_wait) begin
                 current_state <= DONE;
              end else begin
                 wait_counter <= wait_counter + 1'b1;
              end
           end

           DONE: begin
              current_state <= IDLE;
           end

           default: current_state <= IDLE;
        endcase
     end
  end

  // ---------------------------------------------------------------
  // Combinational output generation
  // ---------------------------------------------------------------
  always_comb begin
     next_state = current_state;               // (unused successor, kept for clarity)
     rw         = (current_state == WRITE);
     write_addr = addr_counter;
     x_pos      = addr_counter % SPRITE_WIDTH;  // horizontal position (masked to width)
     y_pos      = addr_counter / SPRITE_WIDTH;  // vertical   position (masked to width)
     done       = (current_state == DONE);

     if (current_state == INIT_WRITE)
        write_data = 24'hFF0000;
     else
        write_data = data_counter;
  end

endmodule

module ahb_clock_counter #(
    parameter ADDR_WIDTH = 32, // Width of the address bus
    parameter DATA_WIDTH = 32  // Width of the data bus
)(
    input wire HCLK,                       // AHB Clock
    input wire HRESETn,                    // AHB Reset (Active Low)
    input wire HSEL,                       // AHB Select
    input wire [ADDR_WIDTH-1:0] HADDR,     // AHB Address
    input wire HWRITE,                     // AHB Write Enable
    input wire [DATA_WIDTH-1:0] HWDATA,    // AHB Write Data
    input wire HREADY,                     // AHB Ready Signal
    output reg [DATA_WIDTH-1:0] HRDATA,    // AHB Read Data
    output reg HRESP,                      // AHB Response
    output reg [DATA_WIDTH-1:0] COUNTER    // Counter Output
);

    // Memory-mapped register addresses (DATA_WIDTH-wide comparison)
    localparam [DATA_WIDTH-1:0] ADDR_START    = 'h00; // write 1 -> start/resume
    localparam [DATA_WIDTH-1:0] ADDR_STOP     = 'h04; // write 1 -> stop
    localparam [DATA_WIDTH-1:0] ADDR_COUNTER  = 'h08; // read counter value
    localparam [DATA_WIDTH-1:0] ADDR_OVERFLOW = 'h0C; // read overflow flag
    localparam [DATA_WIDTH-1:0] ADDR_MAXCNT   = 'h10; // write max count

    reg                   counting;   // enable flag
    reg                   overflow;   // sticky overflow flag
    reg [DATA_WIDTH-1:0]  max_count;  // configured maximum count value

    // Synchronous logic, asynchronous active-low reset
    always @(posedge HCLK or negedge HRESETn) begin
        if (!HRESETn) begin
            COUNTER   <= {DATA_WIDTH{1'b0}};
            overflow  <= 1'b0;
            counting  <= 1'b0;
            max_count <= {DATA_WIDTH{1'b0}};
        end else begin
            // Write transactions
            if (HSEL && HWRITE && HREADY) begin
                case (HADDR)
                    ADDR_START:  if (HWDATA[0]) counting <= 1'b1;
                    ADDR_STOP:   if (HWDATA[0]) counting <= 1'b0;
                    ADDR_MAXCNT: max_count <= HWDATA;
                    default: ;
                endcase
            end

            // Counting with overflow handling
            if (counting && !overflow) begin
                if (COUNTER >= max_count) begin
                    overflow <= 1'b1;          // reached max -> set (sticky) overflow
                end else begin
                    COUNTER <= COUNTER + 1'b1; // resume/continue counting
                end
            end
        end
    end

    // Combinational read + OKAY response
    always @(*) begin
        HRESP = 1'b0; // always OKAY
        case (HADDR)
            ADDR_COUNTER:  HRDATA = COUNTER;
            ADDR_OVERFLOW: HRDATA = {{(DATA_WIDTH-1){1'b0}}, overflow};
            ADDR_MAXCNT:   HRDATA = max_count;
            default:       HRDATA = {DATA_WIDTH{1'b0}};
        endcase
    end

endmodule : ahb_clock_counter

// APB DSP Operation Module
module apb_dsp_op #(
    parameter ADDR_WIDTH = 'd8,
    parameter DATA_WIDTH = 'd32
) (
    input  logic                  clk_dsp,    // Faster clock to DSP operation
    input  logic                  en_clk_dsp, // Enable DSP operation with faster clock
    input  logic                  PCLK,       // APB clock
    input  logic                  PRESETn,    // Active low asynchronous APB Reset
    input  logic [ADDR_WIDTH-1:0] PADDR,      // APB address
    input  logic                  PWRITE,     // Write/Read enable
    input  logic [DATA_WIDTH-1:0] PWDATA,     // Write data
    input  logic                  PSEL,       // DSP selector
    input  logic                  PENABLE,    // APB enable
    output logic [DATA_WIDTH-1:0] PRDATA,     // Read data
    output logic                  PREADY,     // Ready signal
    output logic                  PSLVERR     // Error signal
);

    // Internal registers address map
    localparam ADDRESS_A         = 32'h0;  // 0x00
    localparam ADDRESS_B         = 32'h4;  // 0x04
    localparam ADDRESS_C         = 32'h8;  // 0x08
    localparam ADDRESS_O         = 32'hC;  // 0x0C
    localparam ADDRESS_CONTROL   = 32'h10; // 0x10
    localparam ADDRESS_WDATA     = 32'h14; // 0x14
    localparam ADDRESS_SRAM_ADDR = 32'h18; // 0x18

    // Control modes
    localparam SRAM_WRITE     = 32'd1;
    localparam SRAM_READ      = 32'd2;
    localparam DSP_READ_OP_A  = 32'd3;
    localparam DSP_READ_OP_B  = 32'd4;
    localparam DSP_READ_OP_C  = 32'd5;
    localparam DSP_WRITE_OP_O = 32'd6;

    localparam SRAM_DEPTH = 64;

    // Internal signals
    logic [DATA_WIDTH-1:0] reg_operand_a;
    logic [DATA_WIDTH-1:0] reg_operand_b;
    logic [DATA_WIDTH-1:0] reg_operand_c;
    logic [DATA_WIDTH-1:0] reg_operand_o;
    logic [DATA_WIDTH-1:0] reg_control;
    logic [DATA_WIDTH-1:0] reg_wdata_sram;
    logic [DATA_WIDTH-1:0] reg_addr_sram;

    logic signed [DATA_WIDTH-1:0] wire_op_a;
    logic signed [DATA_WIDTH-1:0] wire_op_b;
    logic signed [DATA_WIDTH-1:0] wire_op_c;
    logic signed [DATA_WIDTH-1:0] wire_op_o;
    logic        [DATA_WIDTH-1:0] sram_data_in;
    logic                         sram_we;
    logic        [DATA_WIDTH-1:0] sram_addr;
    logic        [DATA_WIDTH-1:0] sram_data_out;

    // ------------------------------------------------------------------
    // CDC: synchronize the APB-domain enable into the DSP clock domain
    // (dual-flop synchronizer) before it is used by clk_dsp logic.
    // ------------------------------------------------------------------
    logic en_clk_dsp_meta, en_clk_dsp_sync;
    always_ff @(posedge clk_dsp or negedge PRESETn) begin
        if (!PRESETn) begin
            en_clk_dsp_meta <= 1'b0;
            en_clk_dsp_sync <= 1'b0;
        end else begin
            en_clk_dsp_meta <= en_clk_dsp;
            en_clk_dsp_sync <= en_clk_dsp_meta;
        end
    end

    // ------------------------------------------------------------------
    // Glitch-free clock multiplexer between PCLK and clk_dsp.
    // Replaces the discouraged combinational MUX ( en ? clk_dsp : PCLK ).
    // Select PCLK by default; switch to clk_dsp when the enable is set.
    // ------------------------------------------------------------------
    logic dsp_clk_sel;
    logic sel_pclk_q1, sel_pclk_q2;
    logic sel_dsp_q1,  sel_dsp_q2;
    wire  sel = en_clk_dsp;              // quasi-static enable

    // PCLK side (active when sel == 0)
    always_ff @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) sel_pclk_q1 <= 1'b1;
        else          sel_pclk_q1 <= ~sel & ~sel_dsp_q2;
    always_ff @(negedge PCLK or negedge PRESETn)
        if (!PRESETn) sel_pclk_q2 <= 1'b1;
        else          sel_pclk_q2 <= sel_pclk_q1;

    // clk_dsp side (active when sel == 1)
    always_ff @(posedge clk_dsp or negedge PRESETn)
        if (!PRESETn) sel_dsp_q1 <= 1'b0;
        else          sel_dsp_q1 <= sel & ~sel_pclk_q2;
    always_ff @(negedge clk_dsp or negedge PRESETn)
        if (!PRESETn) sel_dsp_q2 <= 1'b0;
        else          sel_dsp_q2 <= sel_dsp_q1;

    assign dsp_clk_sel = (sel_pclk_q2 & PCLK) | (sel_dsp_q2 & clk_dsp);

    // ------------------------------------------------------------------
    // Address / access validity for PSLVERR generation
    // ------------------------------------------------------------------
    logic addr_valid;
    logic sram_active;
    logic sram_oob;

    always_comb begin
        case (PADDR)
            ADDRESS_A[ADDR_WIDTH-1:0],
            ADDRESS_B[ADDR_WIDTH-1:0],
            ADDRESS_C[ADDR_WIDTH-1:0],
            ADDRESS_O[ADDR_WIDTH-1:0],
            ADDRESS_CONTROL[ADDR_WIDTH-1:0],
            ADDRESS_WDATA[ADDR_WIDTH-1:0],
            ADDRESS_SRAM_ADDR[ADDR_WIDTH-1:0] : addr_valid = 1'b1;
            default                           : addr_valid = 1'b0;
        endcase

        sram_active = (reg_control == SRAM_WRITE)    || (reg_control == SRAM_READ)    ||
                      (reg_control == DSP_READ_OP_A) || (reg_control == DSP_READ_OP_B)||
                      (reg_control == DSP_READ_OP_C) || (reg_control == DSP_WRITE_OP_O);

        sram_oob = sram_active && (sram_addr >= SRAM_DEPTH);
    end

    // APB interface logic
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            reg_operand_a  <= 'd0;
            reg_operand_b  <= 'd0;
            reg_operand_c  <= 'd0;
            reg_operand_o  <= 'd0;
            reg_control    <= 'd0;
            reg_wdata_sram <= 'd0;
            reg_addr_sram  <= 'd0;
            PREADY  <= 1'b0;
            PSLVERR <= 1'b0;
        end else if (PENABLE & PSEL) begin
            PREADY  <= 1'b1;
            // Flag the transaction as an error on invalid address / OOB SRAM access
            PSLVERR <= (~addr_valid) | sram_oob;
            if (PWRITE) begin
                case (PADDR)
                    ADDRESS_A         : reg_operand_a  <= PWDATA;
                    ADDRESS_B         : reg_operand_b  <= PWDATA;
                    ADDRESS_C         : reg_operand_c  <= PWDATA;
                    ADDRESS_O         : reg_operand_o  <= PWDATA;
                    ADDRESS_CONTROL   : reg_control    <= PWDATA;
                    ADDRESS_WDATA     : reg_wdata_sram <= PWDATA;
                    ADDRESS_SRAM_ADDR : reg_addr_sram  <= PWDATA;
                endcase
            end else begin
                if (reg_control == SRAM_READ) begin
                    PRDATA <= sram_data_out_sync;
                end else begin
                    case (PADDR)
                        ADDRESS_A         : PRDATA <= reg_operand_a;
                        ADDRESS_B         : PRDATA <= reg_operand_b;
                        ADDRESS_C         : PRDATA <= reg_operand_c;
                        ADDRESS_O         : PRDATA <= reg_operand_o;
                        ADDRESS_CONTROL   : PRDATA <= reg_control;
                        ADDRESS_WDATA     : PRDATA <= reg_wdata_sram;
                        ADDRESS_SRAM_ADDR : PRDATA <= reg_addr_sram;
                    endcase
                end
            end
        end else begin
            PREADY  <= 1'b0;
            PSLVERR <= 1'b0;
        end
    end

    // SRAM logic (kept in the DSP clock domain so memory operations are consistent)
    logic [DATA_WIDTH-1:0] mem [SRAM_DEPTH-1:0];

    always_comb begin
        sram_data_in = (reg_control == SRAM_WRITE) ? reg_wdata_sram : wire_op_o;

        if ((reg_control == SRAM_WRITE) || (reg_control == DSP_WRITE_OP_O)) begin
            sram_we = 1'b1;
        end else begin
            sram_we = 1'b0;
        end

        case (reg_control)
            DSP_READ_OP_A  : sram_addr = reg_operand_a;
            DSP_READ_OP_B  : sram_addr = reg_operand_b;
            DSP_READ_OP_C  : sram_addr = reg_operand_c;
            DSP_WRITE_OP_O : sram_addr = reg_operand_o;
            default        : sram_addr = reg_addr_sram;
        endcase
    end

    always_ff @(posedge dsp_clk_sel) begin
        if (sram_we) begin
            mem[sram_addr[5:0]] <= sram_data_in;
        end else begin
            sram_data_out <= mem[sram_addr[5:0]];
        end
    end

    // CDC: synchronize SRAM read data back into the APB (PCLK) domain
    logic [DATA_WIDTH-1:0] sram_data_out_meta, sram_data_out_sync;
    always_ff @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            sram_data_out_meta <= 'd0;
            sram_data_out_sync <= 'd0;
        end else begin
            sram_data_out_meta <= sram_data_out;
            sram_data_out_sync <= sram_data_out_meta;
        end
    end

    // DSP operation
    always_ff @(posedge dsp_clk_sel) begin
        case (reg_control)
            DSP_READ_OP_A  : wire_op_a <= sram_data_out;
            DSP_READ_OP_B  : wire_op_b <= sram_data_out;
            DSP_READ_OP_C  : wire_op_c <= sram_data_out;
        endcase
    end

    assign wire_op_o = (wire_op_a * wire_op_b) + wire_op_c;


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    PRDATA = 0;
  end

endmodule

module axis_image_border_gen_with_resizer #(
    parameter IMG_WIDTH_IN  = 640,          // Input image width
    parameter IMG_HEIGHT_IN = 480,          // Input image height
    parameter IMG_WIDTH_OUT = 320,          // Resized image width
    parameter IMG_HEIGHT_OUT = 240,         // Resized image height
    parameter BORDER_COLOR  = 16'hFFFF,     // Border pixel color
    parameter DATA_WIDTH    = 16            // Pixel data width
)(
    input  wire                clk,          // Clock signal
    input  wire                resetn,       // Active-low reset
    input  wire [DATA_WIDTH-1:0] s_axis_tdata, // Input pixel data
    input  wire                s_axis_tvalid, // Input valid signal
    output wire                s_axis_tready, // Input ready signal
    input  wire                s_axis_tlast,  // Input end-of-row signal
    input  wire                s_axis_tuser,  // Input start-of-frame signal
    output wire [DATA_WIDTH-1:0] m_axis_tdata, // Output pixel data
    output wire                m_axis_tvalid, // Output valid signal
    input  wire                m_axis_tready, // Output ready signal
    output wire                m_axis_tlast,  // Output end-of-row signal
    output wire                m_axis_tuser   // Output start-of-frame signal
);

    // Interconnect between the resizer output and the border generator input
    wire [DATA_WIDTH-1:0] rsz_tdata;
    wire                  rsz_tvalid;
    wire                  rsz_tready;
    wire                  rsz_tlast;
    wire                  rsz_tuser;

    axis_image_resizer #(
        .IMG_WIDTH_IN  (IMG_WIDTH_IN),
        .IMG_HEIGHT_IN (IMG_HEIGHT_IN),
        .IMG_WIDTH_OUT (IMG_WIDTH_OUT),
        .IMG_HEIGHT_OUT(IMG_HEIGHT_OUT),
        .DATA_WIDTH    (DATA_WIDTH)
    ) u_resizer (
        .clk          (clk),
        .resetn       (resetn),
        .s_axis_tdata (s_axis_tdata),
        .s_axis_tvalid(s_axis_tvalid),
        .s_axis_tready(s_axis_tready),
        .s_axis_tlast (s_axis_tlast),
        .s_axis_tuser (s_axis_tuser),
        .m_axis_tdata (rsz_tdata),
        .m_axis_tvalid(rsz_tvalid),
        .m_axis_tready(rsz_tready),
        .m_axis_tlast (rsz_tlast),
        .m_axis_tuser (rsz_tuser)
    );

    axis_image_border_gen #(
        .IMG_WIDTH   (IMG_WIDTH_OUT),
        .IMG_HEIGHT  (IMG_HEIGHT_OUT),
        .BORDER_COLOR(BORDER_COLOR),
        .DATA_MASK   (16'h0000)
    ) u_border_gen (
        .clk          (clk),
        .resetn       (resetn),
        .s_axis_tdata (rsz_tdata),
        .s_axis_tvalid(rsz_tvalid),
        .s_axis_tready(rsz_tready),
        .s_axis_tlast (rsz_tlast),
        .s_axis_tuser (rsz_tuser),
        .m_axis_tdata (m_axis_tdata),
        .m_axis_tvalid(m_axis_tvalid),
        .m_axis_tready(m_axis_tready),
        .m_axis_tlast (m_axis_tlast),
        .m_axis_tuser (m_axis_tuser)
    );

endmodule

module axis_image_resizer #
(
    parameter IMG_WIDTH_IN  = 640,
    parameter IMG_HEIGHT_IN = 480,
    parameter IMG_WIDTH_OUT = 320,
    parameter IMG_HEIGHT_OUT = 240,
    parameter DATA_WIDTH    = 16
)
(
    input  wire                  clk,
    input  wire                  resetn,
    input  wire [DATA_WIDTH-1:0] s_axis_tdata,
    input  wire                  s_axis_tvalid,
    output                       s_axis_tready,
    input  wire                  s_axis_tlast,
    input  wire                  s_axis_tuser,

    output reg [DATA_WIDTH-1:0]  m_axis_tdata,
    output reg                   m_axis_tvalid,
    input  wire                  m_axis_tready,
    output reg                   m_axis_tlast,
    output reg                   m_axis_tuser
);

    // Internal counters for input and output
    reg [15:0] x_count_in, y_count_in;
    reg [15:0] x_count_out, y_count_out;

    // Downsampling factors
    localparam X_SCALE = IMG_WIDTH_IN  / IMG_WIDTH_OUT;
    localparam Y_SCALE = IMG_HEIGHT_IN / IMG_HEIGHT_OUT;

    // Control logic for input and output data
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            x_count_in <= 0;
            y_count_in <= 0;
            x_count_out <= 0;
            y_count_out <= 0;
            m_axis_tvalid <= 0;
            m_axis_tlast <= 0;
            m_axis_tuser <= 0;
            m_axis_tdata <= 0;
        end else if (s_axis_tvalid && s_axis_tready) begin
            // Default: no output this beat unless the pixel is on the grid
            m_axis_tvalid <= 1'b0;
            m_axis_tlast  <= 1'b0;
            m_axis_tuser  <= 1'b0;

            // Keep only pixels that align with the downsampling grid
            if (((x_count_in % X_SCALE) == 0) && ((y_count_in % Y_SCALE) == 0)) begin
                m_axis_tdata  <= s_axis_tdata;
                m_axis_tvalid <= 1'b1;
                m_axis_tuser  <= ((x_count_in == 0) && (y_count_in == 0)) ? 1'b1 : 1'b0;
                m_axis_tlast  <= (x_count_out == (IMG_WIDTH_OUT-1));
                if (x_count_out == (IMG_WIDTH_OUT-1)) begin
                    x_count_out <= 0;
                    if (y_count_out == (IMG_HEIGHT_OUT-1))
                        y_count_out <= 0;
                    else
                        y_count_out <= y_count_out + 1'b1;
                end else begin
                    x_count_out <= x_count_out + 1'b1;
                end
            end

            // Advance input counters
            if (s_axis_tlast || (x_count_in == (IMG_WIDTH_IN-1))) begin
                x_count_in <= 0;
                if (y_count_in == (IMG_HEIGHT_IN-1))
                    y_count_in <= 0;
                else
                    y_count_in <= y_count_in + 1'b1;
            end else begin
                x_count_in <= x_count_in + 1'b1;
            end
        end else begin
            // Hold if downstream stalls; clear valid once consumed
            if (m_axis_tvalid && m_axis_tready)
                m_axis_tvalid <= 1'b0;
        end
    end

    // Ready to accept a new input pixel whenever the single output register is
    // free (either empty, or being consumed this cycle by the border generator).
    // This lets the resizer form and hold its first (start-of-frame) pixel so the
    // downstream border-gen FSM can observe s_axis_tuser and leave its idle state,
    // rather than stalling forever behind the border-generation phase.
    assign s_axis_tready = (~m_axis_tvalid) | m_axis_tready;

endmodule

`timescale 1ps / 1ps

module axis_image_border_gen #
(
    parameter IMG_WIDTH  = 336,               // Image width (X resolution)
    parameter IMG_HEIGHT = 256,               // Image height (Y resolution)
    parameter BORDER_COLOR = 16'hFFFF,      // Border pixel value
    parameter DATA_MASK    = 16'h0000       // Mask for input pixels
)
(
    input  wire            clk,              // AXI clock
    input  wire            resetn,           // Active-low reset

    input  wire [15:0]     s_axis_tdata,     // Input stream data
    input  wire            s_axis_tvalid,    // Input data valid
    output wire            s_axis_tready,    // Output ready
    input  wire            s_axis_tlast,     // Input last signal
    input  wire            s_axis_tuser,     // Frame start signal

    output wire [15:0]     m_axis_tdata,     // Output stream data
    output wire            m_axis_tvalid,    // Output data valid
    input  wire            m_axis_tready,    // input ready
    output wire            m_axis_tlast,     // Output last signal
    output wire            m_axis_tuser      // Frame start signal
);

    // State Definitions
    localparam ST_IDLE          = 3'd0;
    localparam ST_ROW_FIRST     = 3'd1;
    localparam ST_PROCESS_ROW   = 3'd2;
    localparam ST_BORDER_ROW    = 3'd3;
    localparam ST_ROW_LAST      = 3'd4;

    // State and Counter Registers
    reg [2:0] state, next_state;
    reg [15:0] x_count, y_count;
    reg border_valid;

    // Internal Control Signals
    wire is_top_row     = (y_count == 16'd0);
    wire is_bottom_row  = (y_count == IMG_HEIGHT + 1);
    wire is_left_border  = (x_count == 16'd0);
    wire is_right_border = (x_count == IMG_WIDTH + 1);
    wire is_border_pixel = (is_top_row || is_bottom_row || is_left_border || is_right_border);


    // Output Control Signals
    assign m_axis_tdata  = (is_border_pixel) ? BORDER_COLOR : (s_axis_tdata);
    assign m_axis_tvalid = (is_border_pixel) ? border_valid : s_axis_tvalid;
    assign m_axis_tlast  = (x_count == IMG_WIDTH + 1);
    assign m_axis_tuser  = s_axis_tuser;

    // Ready: accept upstream pixels only for interior (non-border) positions,
    // and only when the downstream sink can accept data.
    assign s_axis_tready = (~is_border_pixel) & m_axis_tready;

    // FSM and Counter Logic
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state   <= ST_IDLE;
            x_count <= 16'd0;
            y_count <= 16'd0;
        end else begin
            state <= next_state;
            if(state == ST_IDLE) begin
                x_count <= 16'd0;
                y_count <= 16'd0;
            end
            else if (m_axis_tvalid && m_axis_tready) begin
                if (x_count == IMG_WIDTH + 1) begin
                    x_count <= 16'd0;
                    y_count <= y_count + 1'b1;
                end else begin
                    x_count <= x_count + 1'b1;
                end
            end
        end
    end

    // Next State Logic
    always @(*) begin
        case (state)
            ST_IDLE: begin
                if (s_axis_tuser) begin
                    next_state = ST_ROW_FIRST;
                end else begin
                    next_state = ST_IDLE;
                end
            end
            ST_ROW_FIRST: begin
                if (x_count == IMG_WIDTH + 1) begin
                    next_state = ST_PROCESS_ROW;
                end else begin
                    next_state = ST_ROW_FIRST;
                end
            end
            ST_PROCESS_ROW: begin
                if (x_count == IMG_WIDTH + 1 && y_count == IMG_HEIGHT) begin
                    next_state = ST_BORDER_ROW;
                end else begin
                    next_state = ST_PROCESS_ROW;
                end
            end
            ST_BORDER_ROW: begin
                if (x_count == IMG_WIDTH + 1) begin
                    next_state = ST_ROW_LAST;
                end else begin
                    next_state = ST_BORDER_ROW;
                end
            end
            ST_ROW_LAST: begin
                next_state = ST_IDLE;
            end
            default: next_state = ST_IDLE;
        endcase
    end

    // Border pixels are valid whenever the frame is being generated.
    always @(*) begin
        border_valid = (state != ST_IDLE);
    end

endmodule

module enhanced_fsm_signal_processor (
  input  wire       i_clk,
  input  wire       i_rst_n,
  input  wire       i_enable,
  input  wire       i_clear,
  input  wire       i_ack,
  input  wire       i_fault,
  input  wire [4:0] i_vector_1,
  input  wire [4:0] i_vector_2,
  input  wire [4:0] i_vector_3,
  input  wire [4:0] i_vector_4,
  input  wire [4:0] i_vector_5,
  input  wire [4:0] i_vector_6,
  output reg        o_ready,
  output reg        o_error,
  output wire [1:0] o_fsm_status,
  output reg  [7:0] o_vector_1,
  output reg  [7:0] o_vector_2,
  output reg  [7:0] o_vector_3,
  output reg  [7:0] o_vector_4
);

  localparam [1:0] IDLE    = 2'b00,
                   PROCESS = 2'b01,
                   READY   = 2'b10,
                   FAULT   = 2'b11;

  reg [1:0] state, next_state;

  // Concatenate six 5-bit vectors (MSB..LSB) into 30 bits and append two 1s
  // at the LSB to form a 32-bit bus.
  wire [31:0] cat_bus = {i_vector_1, i_vector_2, i_vector_3,
                         i_vector_4, i_vector_5, i_vector_6, 2'b11};

  // o_fsm_status always reflects the current state (updates only on clk edges).
  assign o_fsm_status = state;

  // Next-state logic. i_fault has precedence over every other input.
  always @(*) begin
    next_state = state;
    case (state)
      IDLE:    if (i_fault)          next_state = FAULT;
               else if (i_enable)    next_state = PROCESS;
      PROCESS: if (i_fault)          next_state = FAULT;
               else                  next_state = READY;
      READY:   if (i_fault)          next_state = FAULT;
               else if (i_ack)       next_state = IDLE;
      FAULT:   if (i_clear && !i_fault) next_state = IDLE;
      default:                       next_state = IDLE;
    endcase
  end

  // Registered (synchronous) outputs.
  always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
      state      <= IDLE;
      o_ready    <= 1'b0;
      o_error    <= 1'b0;
      o_vector_1 <= 8'b0;
      o_vector_2 <= 8'b0;
      o_vector_3 <= 8'b0;
      o_vector_4 <= 8'b0;
    end else begin
      state   <= next_state;
      o_ready <= (next_state == READY);
      o_error <= (next_state == FAULT);

      if (next_state == READY) begin
        // Compute the split outputs on entry to READY (from PROCESS); hold
        // them while waiting for i_ack.
        if (state == PROCESS) begin
          o_vector_1 <= cat_bus[31:24];
          o_vector_2 <= cat_bus[23:16];
          o_vector_3 <= cat_bus[15:8];
          o_vector_4 <= cat_bus[7:0];
        end
      end else begin
        // IDLE / PROCESS / FAULT -> outputs at default.
        o_vector_1 <= 8'b0;
        o_vector_2 <= 8'b0;
        o_vector_3 <= 8'b0;
        o_vector_4 <= 8'b0;
      end
    end
  end

endmodule

module fan_controller (
    input wire clk,                 // System clock
    input wire reset,               // Reset signal
    output reg fan_pwm_out,         // PWM output for fan control

    //APB signals
    input  wire         psel,       // Slave select
    input  wire         penable,    // Enable signal
    input  wire         pwrite,     // Write control
    input  wire [7:0]   paddr,      // Address bus
    input  wire [7:0]   pwdata,     // Write data bus
    output reg  [7:0]   prdata,     // Read data bus
    output reg          pready,      // Ready signal
    output reg          pslverr     // Slave error
);

    // Parameters for temperature thresholds
    reg [7:0] TEMP_LOW ;      // Low temperature threshold
    reg [7:0] TEMP_MED ;      // Medium temperature threshold
    reg [7:0] TEMP_HIGH;      // High temperature threshold
    reg [7:0]  temp_adc_in;   // Temperature sensor input (0-255)

    reg setup;
    // APB Protocol States
    always @(posedge clk or posedge reset)
	begin
        if (reset)
        begin
            prdata   <= 8'b0;
            pready   <= 1'b0;
            pslverr  <= 1'b0;
            TEMP_LOW <= 8'd30;
            TEMP_MED <= 8'd60;
            TEMP_HIGH <=8'd90;
            setup  <= 1'b0;
        end
        else
        begin
            if (psel && !penable && !setup)
            begin
                // Setup phase: Indicate the slave is not yet ready
                pready <= 1'b0;
                setup  <= 1'b1;

            end
            else if (psel && penable && setup)
            begin
                // Access phase: Perform read/write operation and indicate ready
                pready <= 1'b1; // Slave is ready for the current operation
                setup  <= 1'b0;
                if (pwrite)
                 begin
                    // Write Operation
                    case(paddr)
                          8'h0a: begin
                                  TEMP_LOW    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0b: begin
                                  TEMP_MED    <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0c: begin
                                  TEMP_HIGH   <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          8'h0f: begin
                                  temp_adc_in <= pwdata;
                                  pslverr     <= 1'b0;
                                  end
                          default:pslverr     <= 1'b1;
                    endcase
                end
                else
                begin
                    // Read Operation
                    case(paddr)
                          8'h0a: begin
                                  prdata   <= TEMP_LOW ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0b: begin
                                  prdata   <= TEMP_MED ;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0c: begin
                                  prdata   <= TEMP_HIGH;
                                  pslverr  <= 1'b0;
                                  end
                          8'h0f: begin
                                  prdata   <= temp_adc_in;
                                  pslverr  <= 1'b0;
                                  end
                          default:pslverr  <= 1'b1;
                    endcase
                end
            end
            else
            begin
                // Default case: Clear ready signal when not selected
                pready <= 1'b0;
                setup  <= 1'b0;
            end
        end
    end

    // PWM control
    reg [7:0] pwm_duty_cycle;    // Duty cycle (0-255)
    reg [7:0] pwm_counter;       // Counter for PWM generation

    // AREA OPTIMIZATION (combinational logic only): the original design first
    // decoded the temperature into an intermediate 3-bit `speed_control` net via
    // a comparator ternary, then RE-decoded that code back into a duty value with
    // a separate case statement. That double-decode wastes the 3-bit net plus the
    // case-mux cells. Collapse it into a SINGLE priority ternary that maps the
    // temperature thresholds directly onto the duty value. Functionally identical:
    //   temp < TEMP_LOW  -> 64  (was speed 1)
    //   temp < TEMP_MED  -> 128 (was speed 2)
    //   temp < TEMP_HIGH -> 192 (was speed 3)
    //   else             -> 255 (was speed 4 / default)
    // The registered interface timing, reset defaults and the free-running PWM
    // comparator are left bit-identical.
    always @(posedge clk or posedge reset) begin
        if (reset)
        begin
            pwm_duty_cycle <= 8'd0;  // Fan off by default
        end
        else
        begin
            pwm_duty_cycle <= (temp_adc_in < TEMP_LOW ) ? 8'd64  :
                              (temp_adc_in < TEMP_MED ) ? 8'd128 :
                              (temp_adc_in < TEMP_HIGH) ? 8'd192 : 8'd255;
        end
    end

    // PWM generation logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_counter <= 8'd0;
            fan_pwm_out <= 1'b0;
        end else begin
            pwm_counter <= pwm_counter + 1;
            fan_pwm_out <= (pwm_counter < pwm_duty_cycle) ? 1'b1 : 1'b0;
        end
    end

endmodule

module hill_cipher (
    input logic clk,
    input logic reset,
    input logic start,
    input logic [14:0] plaintext,   // 3 letters, 5 bits each
    input logic [44:0] key,         // 9 elements, 5 bits each
    output logic [14:0] ciphertext, // 3 letters, 5 bits each
    output logic done
);

    logic [4:0] P0, P1, P2;
    logic [4:0] K00, K01, K02;
    logic [4:0] K10, K11, K12;
    logic [4:0] K20, K21, K22;

    // LINT FIX: temp registers must be wide enough to hold the sum of three
    // per-term mod-26 products (each 0..25, sum up to 75). The original [5:0]
    // width truncated the accumulator (bit-truncation) and did not match the
    // 12-bit reset constants (declared-width vs assigned-constant mismatch).
    logic [11:0] temp0, temp1, temp2;
    logic [4:0] C0_reg, C1_reg, C2_reg;

    typedef enum logic [1:0] {
        IDLE        = 2'b00,
        COMPUTE     = 2'b01,
        COMPUTE_MOD = 2'b10,
        DONE        = 2'b11
    } state_t;

    state_t current_state, next_state;

    assign P0 = plaintext[14:10];
    assign P1 = plaintext[9:5];
    assign P2 = plaintext[4:0];

    assign K00 = key[44:40];
    assign K01 = key[39:35];
    assign K02 = key[34:30];
    assign K10 = key[29:25];
    assign K11 = key[24:20];
    assign K12 = key[19:15];
    assign K20 = key[14:10];
    assign K21 = key[9:5];
    assign K22 = key[4:0];

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always_comb begin
        next_state = current_state;
        done = 1'b0;

        case (current_state)
            IDLE: begin
                if (start)
                    next_state = COMPUTE;
            end
            COMPUTE: begin
                next_state = COMPUTE_MOD;
            end
            COMPUTE_MOD: begin
                next_state = DONE;
            end
            DONE: begin
                done = 1'b1;
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            temp0 <= 12'b0;
            temp1 <= 12'b0;
            temp2 <= 12'b0;
            C0_reg <= 5'b0;
            C1_reg <= 5'b0;
            C2_reg <= 5'b0;
        end
        else begin
            case (current_state)
                COMPUTE: begin
                    temp0 <= (K00 * P0)%26 + (K01 * P1)%26 + (K02 * P2)%26;
                    temp1 <= (K10 * P0)%26 + (K11 * P1)%26 + (K12 * P2)%26;
                    temp2 <= (K20 * P0)%26 + (K21 * P1)%26 + (K22 * P2)%26;
                end
                COMPUTE_MOD: begin
                    C0_reg <= temp0%26;
                    C1_reg <= temp1%26;
                    C2_reg <= temp2%26;
                end
                default: begin
                    temp0 <= 12'b0;
                    temp1 <= 12'b0;
                    temp2 <= 12'b0;
                    C0_reg <= 5'b0;
                    C1_reg <= 5'b0;
                    C2_reg <= 5'b0;
                end
            endcase
        end
    end

    assign ciphertext = {C0_reg, C1_reg, C2_reg};

endmodule

module cvdp_copilot_register_file_2R1W #(
    parameter DATA_WIDTH = 32,  // Configurable data width
    parameter DEPTH      = 32   // Number of register entries
) (
    // Inputs
    input  logic [DATA_WIDTH-1:0] din,    // Input data
    input  logic [4:0] wad1,              // Write address
    input  logic [4:0] rad1,              // Read address 1
    input  logic [4:0] rad2,              // Read address 2
    input  logic wen1,                    // Write-enable signal
    input  logic ren1,                    // Read-enable signal 1
    input  logic ren2,                    // Read-enable signal 2
    input  logic clk,                     // Clock signal
    input  logic resetn,                  // Active-low reset
    input  logic test_mode,               // BIST activation (high = run BIST)

    // Outputs
    output logic [DATA_WIDTH-1:0] dout1,   // Output data 1
    output logic [DATA_WIDTH-1:0] dout2,   // Output data 2
    output logic collision,                // Collision flag
    output logic bist_done,                // BIST sequence complete
    output logic bist_fail                 // BIST detected a mismatch
);

    // -------------------------------
    // Internal Registers and Wires
    // -------------------------------
    logic [DATA_WIDTH-1:0] rf_mem [0:DEPTH-1];
    logic [DEPTH-1:0]      rf_valid;
    integer i;

    // -------------------------------
    // BIST FSM
    // -------------------------------
    localparam BW = 2;
    localparam [BW-1:0] B_IDLE  = 2'd0,
                        B_WRITE = 2'd1,
                        B_READ  = 2'd2,
                        B_DONE  = 2'd3;

    logic [BW-1:0]           bist_state;
    logic [$clog2(DEPTH):0]  bist_addr;
    logic [DATA_WIDTH-1:0]   bist_pattern;
    logic [DATA_WIDTH-1:0]   read_data_reg;
    logic [DATA_WIDTH-1:0]   expected_pattern_reg;

    // Deterministic, address-derived test pattern
    function automatic [DATA_WIDTH-1:0] pat (input [$clog2(DEPTH):0] a);
        pat = a;   // zero-extend (or truncate) the address to the data width
    endfunction

    // BIST control state machine
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            bist_state           <= B_IDLE;
            bist_addr            <= '0;
            bist_pattern         <= '0;
            read_data_reg        <= '0;
            expected_pattern_reg <= '0;
            bist_done            <= 1'b0;
            bist_fail            <= 1'b0;
        end else if (test_mode) begin
            case (bist_state)
                B_IDLE: begin
                    bist_done    <= 1'b0;
                    bist_fail    <= 1'b0;
                    bist_addr    <= '0;
                    bist_pattern <= pat('0);
                    bist_state   <= B_WRITE;
                end
                B_WRITE: begin
                    // rf_mem[bist_addr] <= bist_pattern happens in the memory block
                    bist_pattern <= pat(bist_addr + 1'b1);
                    if (bist_addr == (DEPTH-1)) begin
                        bist_addr  <= '0;
                        bist_state <= B_READ;
                    end else begin
                        bist_addr  <= bist_addr + 1'b1;
                    end
                end
                B_READ: begin
                    read_data_reg        <= rf_mem[bist_addr[$clog2(DEPTH)-1:0]];
                    expected_pattern_reg <= pat(bist_addr);
                    // Verify the value written for this address
                    if (rf_mem[bist_addr[$clog2(DEPTH)-1:0]] !== pat(bist_addr)) begin
                        bist_fail <= 1'b1;
                    end
                    if (bist_addr == (DEPTH-1)) begin
                        bist_addr  <= '0;
                        bist_state <= B_DONE;
                    end else begin
                        bist_addr  <= bist_addr + 1'b1;
                    end
                end
                B_DONE: begin
                    bist_done  <= 1'b1;
                    bist_state <= B_DONE;   // halt here
                end
                default: bist_state <= B_IDLE;
            endcase
        end else begin
            // test_mode deasserted -> BIST idle, flags cleared
            bist_state <= B_IDLE;
            bist_addr  <= '0;
            bist_done  <= 1'b0;
            bist_fail  <= 1'b0;
        end
    end

    // -------------------------------
    // Memory array : single synchronous driver (ungated clk)
    // BIST writes when test_mode, normal write otherwise.
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                rf_mem[i] <= {DATA_WIDTH{1'b0}};
            end
            rf_valid <= '0;
        end else if (test_mode) begin
            if (bist_state == B_WRITE) begin
                rf_mem[bist_addr[$clog2(DEPTH)-1:0]]   <= bist_pattern;
                rf_valid[bist_addr[$clog2(DEPTH)-1:0]] <= 1'b1;
            end
        end else if (wen1) begin
            rf_mem[wad1]   <= din;
            rf_valid[wad1] <= 1'b1;
        end
    end

    // -------------------------------
    // Read ports (normal operation disabled during test_mode)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            dout1 <= '0;
        end else if (!test_mode) begin
            if (ren1)
                dout1 <= rf_valid[rad1] ? rf_mem[rad1] : '0;
            else
                dout1 <= '0;
        end
    end

    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            dout2 <= '0;
        end else if (!test_mode) begin
            if (ren2)
                dout2 <= rf_valid[rad2] ? rf_mem[rad2] : '0;
            else
                dout2 <= '0;
        end
    end

    // -------------------------------
    // Collision Detection (forced off during test_mode)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            collision <= 1'b0;
        end else if (test_mode) begin
            collision <= 1'b0;
        end else begin
            collision <= (
                (ren1 && ren2 && (rad1 == rad2)) ||
                (wen1 && ren1 && (wad1 == rad1)) ||
                (wen1 && ren2 && (wad1 == rad2))
            );
        end
    end

endmodule

module sigma_delta_audio
(
  input   clk_sig,
  input   clk_en_sig,
  input  [14:0] load_data_sum,
  input  [14:0] read_data_sum,
  output  reg left_sig=0,
  output  reg right_sig=0
);

localparam DATA_WIDTH = 15;
localparam READ_WIDTH  = 4;
localparam A1_WIDTH = 2;
localparam A2_WIDTH = 5;

wire [DATA_WIDTH+2+0  -1:0] l_er0, r_er0;
reg  [DATA_WIDTH+2+0  -1:0] l_er0_prev=0, r_er0_prev=0;
wire [DATA_WIDTH+A1_WIDTH+2-1:0] l_aca1,  r_aca1;
wire [DATA_WIDTH+A2_WIDTH+2-1:0] l_aca2,  r_aca2;
reg  [DATA_WIDTH+A1_WIDTH+2-1:0] l_ac1=0, r_ac1=0;
reg  [DATA_WIDTH+A2_WIDTH+2-1:0] l_ac2=0, r_ac2=0;
wire [DATA_WIDTH+A2_WIDTH+3-1:0] l_quant, r_quant;

reg [24-1:0] seed_1 = 24'h654321;
reg [19-1:0] seed_2 = 19'h12345;
reg [24-1:0] s_sum=0, s_prev=0, s_out=0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_1)
      seed_1 <= 24'h654321;
    else
      seed_1 <= {seed_1[22:0], ~(seed_1[23] ^ seed_1[22] ^ seed_1[21] ^ seed_1[16])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_2)
      seed_2 <= 19'h12345;
    else
      seed_2 <= {seed_2[17:0], ~(seed_2[18] ^ seed_2[17] ^ seed_2[16] ^ seed_2[13] ^ seed_2[0])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    s_sum  <= seed_1 + {5'b0, seed_2};
    s_prev <= s_sum;
    s_out  <= s_sum - s_prev;
  end
end

localparam INPUT_DATA=4;
reg  [INPUT_DATA+0-1:0] integer_count = 0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    integer_count <= integer_count + 4'd1;
  end
end

reg  [DATA_WIDTH+0-1:0] ldata_current=0, ldata_previous=0;
reg  [DATA_WIDTH+0-1:0] rdata_current=0, rdata_previous=0;
wire [DATA_WIDTH+1-1:0] load_data_step, read_data_step;
reg  [DATA_WIDTH+INPUT_DATA-1:0] load_data_int=0, read_data_int=0;
wire [DATA_WIDTH+0-1:0] load_data_int_out, read_data_int_out;
assign load_data_step = {ldata_current[DATA_WIDTH-1], ldata_current} - {ldata_previous[DATA_WIDTH-1], ldata_previous};
assign read_data_step = {rdata_current[DATA_WIDTH-1], rdata_current} - {rdata_previous[DATA_WIDTH-1], rdata_previous};
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (~|integer_count) begin
      ldata_previous <= ldata_current;
      ldata_current  <= load_data_sum;
      rdata_previous <= rdata_current;
      rdata_current  <= read_data_sum;
      load_data_int  <= {ldata_current, {INPUT_DATA{1'b0}}};
      read_data_int  <= {rdata_current, {INPUT_DATA{1'b0}}};
    end else begin
      load_data_int  <= load_data_int + {{(INPUT_DATA-1){load_data_step[DATA_WIDTH+1-1]}}, load_data_step};
      read_data_int  <= read_data_int + {{(INPUT_DATA-1){read_data_step[DATA_WIDTH+1-1]}}, read_data_step};
    end
  end
end
assign load_data_int_out = load_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];
assign read_data_int_out = read_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];

wire [DATA_WIDTH+2-1:0] load_data_gain, read_data_gain;
assign load_data_gain = {load_data_int_out[DATA_WIDTH-1], load_data_int_out, 1'b0} + {{(2){load_data_int_out[DATA_WIDTH-1]}}, load_data_int_out};
assign read_data_gain = {read_data_int_out[DATA_WIDTH-1], read_data_int_out, 1'b0} + {{(2){read_data_int_out[DATA_WIDTH-1]}}, read_data_int_out};

assign l_aca1 = {{(A1_WIDTH){load_data_gain[DATA_WIDTH+2-1]}}, load_data_gain} - {{(A1_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} + l_ac1;
assign r_aca1 = {{(A1_WIDTH){read_data_gain[DATA_WIDTH+2-1]}}, read_data_gain} - {{(A1_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} + r_ac1;
assign l_aca2 = {{(A2_WIDTH-A1_WIDTH){l_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, l_aca1} - {{(A2_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} - {{(A2_WIDTH+1){l_er0_prev[DATA_WIDTH+2-1]}}, l_er0_prev[DATA_WIDTH+2-1:1]} + l_ac2;
assign r_aca2 = {{(A2_WIDTH-A1_WIDTH){r_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, r_aca1} - {{(A2_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} - {{(A2_WIDTH+1){r_er0_prev[DATA_WIDTH+2-1]}}, r_er0_prev[DATA_WIDTH+2-1:1]} + r_ac2;

always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    l_ac1 <= l_aca1;
    r_ac1 <= r_aca1;
    l_ac2 <= l_aca2;
    r_ac2 <= r_aca2;
  end
end

assign l_quant = {l_ac2[DATA_WIDTH+A2_WIDTH+2-1], l_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};
assign r_quant = {r_ac2[DATA_WIDTH+A2_WIDTH+2-1], r_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};

assign l_er0 = l_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};
assign r_er0 = r_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};

always @ (posedge clk_sig)
begin
  if (clk_en_sig)
  begin
    if (~|load_data_gain)
    begin
      left_sig <= ~left_sig;
    end
    else
    begin
      left_sig <= ~l_er0[DATA_WIDTH+2-1];
    end

    if (~|read_data_gain)
    begin
      right_sig <= ~right_sig;
    end
    else
    begin
      right_sig <= ~r_er0[DATA_WIDTH+2-1];
    end
  end
end
endmodule

`timescale 1ns / 1ps

module sync_lifo #(
    parameter DATA_WIDTH = 8,  // Width of the data
    parameter ADDR_WIDTH = 3   // Number of bits for the address (determines the depth)
)(
    input wire clock,                         // System clock
    input wire reset,                         // Synchronous reset
    input wire write_en,                      // Write enable
    input wire read_en,                       // Read enable
    input wire [DATA_WIDTH-1:0] data_in,      // Data input to be written into LIFO
    output wire empty,                        // Indicates if LIFO is empty
    output wire full,                         // Indicates if LIFO is full
    output wire [DATA_WIDTH-1:0] data_out,    // Data output from LIFO
    output wire error,                        // High on invalid op (read-empty / write-full)
    output wire valid                         // High when data_out holds valid read data
);

    // Calculate depth of the LIFO using the address width
    localparam DEPTH = (1 << ADDR_WIDTH);      // Depth = 2^ADDR_WIDTH

    // Registers for LIFO logic
    reg [DEPTH-1:0] ptr;                       // Pointer for write/read operations
    reg [DEPTH-1:0] lifo_counter;              // Counter to track the number of elements in the LIFO
    reg [DATA_WIDTH-1:0] memory [DEPTH-1:0];   // Memory array to store LIFO data
    reg [DATA_WIDTH-1:0] temp_data_out;        // Temporary register for output data
    integer i;

    // Status registers for error / valid indication
    reg error_r;
    reg valid_r;

    // Output assignments for empty and full flags
    assign empty = (lifo_counter == 0) ? 1'b1 : 1'b0;                  // LIFO is empty if counter is zero
    assign full  = (lifo_counter == DEPTH)? 1'b1 : 1'b0;               // LIFO is full if counter equals DEPTH

    // Counter logic to track the number of elements in LIFO
    always @(posedge clock) begin
        if (reset) begin
            lifo_counter <= 0;                                          // Reset the counter when reset signal is active
        end else if (!full && write_en) begin
            lifo_counter <= lifo_counter + 1;                           // Increment counter on write if LIFO is not full
        end else if (!empty && read_en) begin
            lifo_counter <= lifo_counter - 1;                           // Decrement counter on read if LIFO is not empty
        end
    end

    // Memory write logic: writes data into the LIFO
    always @(posedge clock) begin
        if (reset) begin
            ptr <= {ADDR_WIDTH {1'b0}};                                  // Reset pointer to zero on reset
        end else if (write_en && !full) begin
            memory[ptr] <= data_in;                                      // Write input data into memory at current pointer
            ptr <= ptr + 1;                                              // Increment pointer to next memory location
        end
    end

    // Memory read logic: reads data from the LIFO
    always @(posedge clock) begin
        if (reset) begin
            temp_data_out <= {DATA_WIDTH{1'b0}};                         // Clear output data on reset
        end else if (read_en && !empty) begin
            temp_data_out <= memory[ptr - 1'b1];                         // Read data from memory at (pointer - 1)
            ptr <= ptr - 1;                                              // Decrement pointer after reading
        end
    end

    // Error / valid status logic
    // error : asserted when an invalid operation is attempted, i.e. a write
    //         while full (overflow) or a read while empty (underflow).  In both
    //         cases the memory and pointer are left unchanged by the logic above.
    // valid : asserted the cycle data_out presents freshly read data, i.e. one
    //         cycle after a successful read (aligned with temp_data_out update).
    always @(posedge clock) begin
        if (reset) begin
            error_r <= 1'b0;
            valid_r <= 1'b0;
        end else begin
            if ((write_en && full) || (read_en && empty))
                error_r <= 1'b1;
            else
                error_r <= 1'b0;

            if (read_en && !empty)
                valid_r <= 1'b1;
            else
                valid_r <= 1'b0;
        end
    end

    // Assign the outputs
    assign data_out = temp_data_out;                                     // Assign temp data output to the actual output
    assign error    = error_r;
    assign valid    = valid_r;

endmodule

// Source-synchronous serial link: parallel -> serial (TX) and serial -> parallel (RX).
// serial_clk is a gated data-valid strobe: it is asserted (high) only while a real
// bit is on serial_out, so RX samples in the clk domain whenever serial_clk is high.
// The assembled parallel word / done are presented one cycle after the final bit is
// captured (registered-out -> registered-in pipeline).

module tx_block (
    input  wire        clk,
    input  wire        reset_n,      // active-low async reset
    input  wire [63:0] data_in,
    input  wire [2:0]  sel,
    output reg         serial_out,
    output reg         done,
    output reg         serial_clk
);
    reg [6:0] bit_cnt;

    // number of bits to transmit for the current sel
    reg [6:0] total;
    always @(*) begin
        case (sel)
            3'h1:    total = 7'd8;
            3'h2:    total = 7'd16;
            3'h3:    total = 7'd32;
            3'h4:    total = 7'd64;
            default: total = 7'd0;
        endcase
    end

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            bit_cnt    <= 7'd0;
            serial_out <= 1'b0;
            serial_clk <= 1'b0;
            done       <= 1'b0;
        end else begin
            if (bit_cnt < total) begin
                serial_out <= data_in[bit_cnt[5:0]]; // LSB-first
                serial_clk <= 1'b1;                   // valid strobe
                bit_cnt    <= bit_cnt + 7'd1;
            end else begin
                serial_out <= 1'b0;
                serial_clk <= 1'b0;                   // gated off, no data
                done       <= 1'b1;
            end
        end
    end
endmodule


module rx_block (
    input  wire        clk,
    input  wire        reset_n,      // active-low async reset
    input  wire        data_in,      // serial input
    input  wire [2:0]  sel,
    input  wire        serial_clk,   // valid strobe from TX
    output reg  [63:0] data_out,
    output reg         done
);
    reg [6:0]  rx_cnt;
    reg [63:0] rx_shift;
    reg        finished;

    reg [6:0] total;
    always @(*) begin
        case (sel)
            3'h1:    total = 7'd8;
            3'h2:    total = 7'd16;
            3'h3:    total = 7'd32;
            3'h4:    total = 7'd64;
            default: total = 7'd0;
        endcase
    end

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rx_cnt   <= 7'd0;
            rx_shift <= 64'd0;
            data_out <= 64'd0;
            done     <= 1'b0;
            finished <= 1'b0;
        end else begin
            done <= 1'b0;                              // default: 1-cycle pulse
            if (serial_clk) begin
                rx_shift[rx_cnt[5:0]] <= data_in;      // capture while strobe active
                rx_cnt <= rx_cnt + 7'd1;
            end else if (!finished && (total != 7'd0) && (rx_cnt == total)) begin
                // one cycle after the final captured bit
                case (sel)
                    3'h1:    data_out <= {56'h0, rx_shift[7:0]};
                    3'h2:    data_out <= {48'h0, rx_shift[15:0]};
                    3'h3:    data_out <= {32'h0, rx_shift[31:0]};
                    3'h4:    data_out <= rx_shift[63:0];
                    default: data_out <= 64'h0;
                endcase
                done     <= 1'b1;
                finished <= 1'b1;
            end
        end
    end
endmodule


module sync_serial_communication_top (
    input  wire        clk,
    input  wire        reset_n,
    input  wire [63:0] data_in,
    input  wire [2:0]  sel,
    output wire [63:0] data_out,
    output wire        done
);
    wire serial_out;
    wire serial_clk;
    wire tx_done;

    tx_block u_tx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (data_in),
        .sel        (sel),
        .serial_out (serial_out),
        .done       (tx_done),
        .serial_clk (serial_clk)
    );

    rx_block u_rx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (serial_out),
        .sel        (sel),
        .serial_clk (serial_clk),
        .data_out   (data_out),
        .done       (done)
    );
endmodule

module apb_dsp_unit (
    input  wire        pclk,
    input  wire        presetn,     // active-low async reset
    input  wire [9:0]  paddr,
    input  wire        pselx,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [7:0]  pwdata,
    output reg         pready,
    output reg  [7:0]  prdata,
    output reg         pslverr,
    output reg         sram_valid
);

    // ---------------- Register (CSR) addresses -----------------
    localparam [9:0] ADDR_OP1   = 10'h0;  // r_operand_1  : addr of operand 1
    localparam [9:0] ADDR_OP2   = 10'h1;  // r_operand_2  : addr of operand 2
    localparam [9:0] ADDR_EN    = 10'h2;  // r_Enable     : mode
    localparam [9:0] ADDR_WADDR = 10'h3;  // r_write_address
    localparam [9:0] ADDR_WDATA = 10'h4;  // r_write_data
    localparam [9:0] ADDR_RES   = 10'h5;  // computed result (read-only)

    // ---------------- Configuration registers ------------------
    reg [7:0] r_operand_1;
    reg [7:0] r_operand_2;
    reg [7:0] r_Enable;
    reg [7:0] r_write_address;
    reg [7:0] r_write_data;

    // ---------------- 1 KB SRAM (1024 x 8) ---------------------
    reg [7:0] mem [0:1023];

    // ---------------- APB FSM ----------------------------------
    localparam [1:0] IDLE = 2'd0, ACCESS = 2'd1;
    reg [1:0] state;

    // ---------------- Combinational ALU result (served at 0x5) --
    reg [7:0] result;
    always @(*) begin
        case (r_Enable)
            8'd1:    result = mem[r_operand_1] + mem[r_operand_2]; // addition
            8'd2:    result = mem[r_operand_1] * mem[r_operand_2]; // multiplication (low byte)
            default: result = 8'h00;
        endcase
    end

    // Edge detect for entering data-writing mode (r_Enable == 3)
    reg prev_en3;

    integer j;
    always @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            pready          <= 1'b0;
            pslverr         <= 1'b0;
            prdata          <= 8'h00;
            sram_valid      <= 1'b0;
            r_operand_1     <= 8'h00;
            r_operand_2     <= 8'h00;
            r_Enable        <= 8'h00;
            r_write_address <= 8'h00;
            r_write_data    <= 8'h00;
            state           <= IDLE;
            prev_en3        <= 1'b0;
        end else begin
            // no wait states: PREADY held high
            pready <= 1'b1;

            case (state)
                IDLE: begin
                    pslverr <= 1'b0;
                    if (pselx && !penable) begin
                        state <= ACCESS;   // SETUP seen -> go handle ACCESS
                    end
                end

                ACCESS: begin
                    if (pselx && penable) begin
                        if (pwrite) begin
                            // ----------- WRITE -----------
                            pslverr <= 1'b0;
                            case (paddr)
                                ADDR_OP1:   r_operand_1     <= pwdata;
                                ADDR_OP2:   r_operand_2     <= pwdata;
                                ADDR_EN:    r_Enable        <= pwdata;
                                ADDR_WADDR: r_write_address <= pwdata;
                                ADDR_WDATA: r_write_data    <= pwdata;
                                ADDR_RES:   pslverr         <= 1'b1; // read-only
                                default:    mem[paddr]      <= pwdata; // SRAM fall-through
                            endcase
                        end else begin
                            // ----------- READ ------------
                            pslverr <= 1'b0;
                            case (paddr)
                                ADDR_OP1:   prdata <= r_operand_1;
                                ADDR_OP2:   prdata <= r_operand_2;
                                ADDR_EN:    prdata <= r_Enable;
                                ADDR_WADDR: prdata <= r_write_address;
                                ADDR_WDATA: prdata <= r_write_data;
                                ADDR_RES:   prdata <= result;
                                default:    prdata <= mem[paddr]; // SRAM fall-through
                            endcase
                        end
                    end
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase

            // ---- Data-writing mode: on entry to r_Enable==3, latch
            //      r_write_data into SRAM[r_write_address] and pulse
            //      sram_valid for the checker's SRAM interface. ----
            if ((r_Enable == 8'd3) && !prev_en3) begin
                mem[r_write_address] <= r_write_data;
                sram_valid           <= 1'b1;
            end else begin
                sram_valid           <= 1'b0;
            end
            prev_en3 <= (r_Enable == 8'd3);
        end
    end

endmodule

module binary_search_tree_sort #(
    parameter DATA_WIDTH = 32,
    parameter ARRAY_SIZE = 8
) (
    input clk,
    input reset,
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Sub-FSM state parameters
    localparam INIT       = 2'b00, TRAVERSE = 2'b01, COMPLETE = 2'b10; // BUILD_TREE
    localparam S_INIT     = 2'b00, S_PUSHLEFT = 2'b01, S_POP = 2'b10, S_DONE = 2'b11; // SORT_TREE

    localparam PTR_W    = $clog2(ARRAY_SIZE)+1;
    localparam [PTR_W-1:0] NULL_PTR = {PTR_W{1'b1}};

    // Registers for FSM states
    reg [1:0] top_state, build_state, sort_state;

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register

    // Latched copy of the input array (input changes mid-operation are ignored)
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_latched;

    // Top-of-stack node (combinational helper for the pop stage)
    wire [PTR_W-1:0] sort_top_node = stack[(sp-1)*PTR_W +: PTR_W];

    // Initialize all variables
    integer i;

    // Latch the input array at the moment sorting starts.
    always @(posedge clk or posedge reset) begin
        if (reset)
            data_latched <= 0;
        else if ((top_state == IDLE) && start)
            data_latched <= data_in;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;

            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; ; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            done <= 0;

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    input_index <= 0;
                    output_index <= 0;
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; ; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    if (start) begin
                        // Load input data into input array
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                    end
                end

                BUILD_TREE: begin
                    case (build_state)

                        INIT: begin
                            if (input_index == ARRAY_SIZE) begin
                                build_state <= COMPLETE;
                            end else begin
                                temp_data <= data_latched[input_index*DATA_WIDTH +: DATA_WIDTH];
                                if (root == NULL_PTR) begin
                                    // Tree empty: insert the first key as the root node
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= data_latched[input_index*DATA_WIDTH +: DATA_WIDTH];
                                    root           <= next_free_node;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index    <= input_index + 1'b1;
                                end else begin
                                    // Start traversal from the root
                                    current_node <= root;
                                    build_state  <= TRAVERSE;
                                end
                            end
                        end

                        TRAVERSE: begin
                            if (temp_data > keys[current_node*DATA_WIDTH +: DATA_WIDTH]) begin
                                // Go right
                                if (right_child[current_node*PTR_W +: PTR_W] == NULL_PTR) begin
                                    right_child[current_node*PTR_W +: PTR_W] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index    <= input_index + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= right_child[current_node*PTR_W +: PTR_W];
                                end
                            end else begin
                                // Go left (keys less than or equal)
                                if (left_child[current_node*PTR_W +: PTR_W] == NULL_PTR) begin
                                    left_child[current_node*PTR_W +: PTR_W] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index    <= input_index + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= left_child[current_node*PTR_W +: PTR_W];
                                end
                            end
                        end

                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end

                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)

                        S_INIT: begin
                            current_node <= root;
                            sp           <= 0;
                            output_index <= 0;
                            sort_state   <= S_PUSHLEFT;
                        end

                        S_PUSHLEFT: begin
                            if (current_node != NULL_PTR) begin
                                // Push current node, descend to its left child
                                stack[sp*PTR_W +: PTR_W] <= current_node;
                                sp                       <= sp + 1'b1;
                                current_node             <= left_child[current_node*PTR_W +: PTR_W];
                            end else begin
                                sort_state <= S_POP;
                            end
                        end

                        S_POP: begin
                            if (sp == 0) begin
                                sort_state <= S_DONE;
                            end else begin
                                // Pop, emit key, then explore the right subtree
                                sp           <= sp - 1'b1;
                                sorted_out[output_index*DATA_WIDTH +: DATA_WIDTH] <= keys[sort_top_node*DATA_WIDTH +: DATA_WIDTH];
                                output_index <= output_index + 1'b1;
                                current_node <= right_child[sort_top_node*PTR_W +: PTR_W];
                                sort_state   <= S_PUSHLEFT;
                            end
                        end

                        S_DONE: begin
                            done      <= 1'b1;
                            top_state <= IDLE;
                        end

                    endcase
                end
            endcase
        end
    end

  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    sorted_out = 0;
  end

endmodule

module advanced_decimator_with_adaptive_peak_detection #(
    parameter N          = 8,
    parameter DATA_WIDTH = 16,
    parameter DEC_FACTOR = 4
)(
    input  wire                               clk,
    input  wire                               reset,      // async, active high
    input  wire                               valid_in,
    input  wire [DATA_WIDTH*N-1:0]            data_in,    // N packed signed samples
    output wire                               valid_out,
    output wire [DATA_WIDTH*(N/DEC_FACTOR)-1:0] data_out,
    output wire [DATA_WIDTH-1:0]              peak_value
);

    localparam integer M = N / DEC_FACTOR;   // number of decimated samples

    // ------------------------------------------------------------------
    // 1) Input registering (data bus AND valid together) -> 1-cycle latency
    // ------------------------------------------------------------------
    reg [DATA_WIDTH*N-1:0] data_reg;
    reg                    valid_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg  <= {DATA_WIDTH*N{1'b0}};
            valid_reg <= 1'b0;
        end else begin
            data_reg  <= data_in;
            valid_reg <= valid_in;
        end
    end

    assign valid_out = valid_reg;

    // ------------------------------------------------------------------
    // 2) Combinational decimation + peak-detect + packing, from data_reg.
    //    Indexing follows the spec worked example:
    //      in  = {s0, s1, ... s(N-1)}  (first listed element is sample 0)
    //      out = {d0, d1, ...}         with d_q = sample (q*DEC_FACTOR)
    //    i.e. sample s lives in the high-order slice, MSB-first.
    // ------------------------------------------------------------------
    reg  [DATA_WIDTH-1:0]         dec   [0:M-1];
    reg  signed [DATA_WIDTH-1:0]  peak_r;
    reg  [DATA_WIDTH*M-1:0]       out_r;
    integer q;

    always @(*) begin
        // Unpack + decimate (MSB-first sample indexing)
        for (q = 0; q < M; q = q + 1) begin
            dec[q] = data_reg[(N-1-(q*DEC_FACTOR))*DATA_WIDTH +: DATA_WIDTH];
        end

        // Signed peak (maximum) over the decimated samples
        peak_r = $signed(dec[0]);
        for (q = 1; q < M; q = q + 1) begin
            if ($signed(dec[q]) > peak_r) begin
                peak_r = $signed(dec[q]);
            end
        end

        // Pack decimated samples MSB-first (d0 in the high-order slice)
        for (q = 0; q < M; q = q + 1) begin
            out_r[(M-1-q)*DATA_WIDTH +: DATA_WIDTH] = dec[q];
        end
    end

    assign data_out   = out_r;
    assign peak_value = peak_r;

endmodule

module sgd_linear_regression #(
    parameter DATA_WIDTH = 16,
    parameter LEARNING_RATE = 3'd1
) (
    input  logic clk,                               // Clock
    input  logic reset,                             // Asynchronous reset
    input  logic signed [DATA_WIDTH-1:0] x_in,      // Input data (x)
    input  logic signed [DATA_WIDTH-1:0] y_true,    // True output (target)
    output logic signed [DATA_WIDTH-1:0] w,     // Trained weight
    output logic signed [DATA_WIDTH-1:0] b      // Trained bias
);
    localparam NBW_PRED  = 2*DATA_WIDTH + 1;
    localparam NBW_ERROR = NBW_PRED + 1;
    localparam NBW_DELTA = 3 + NBW_ERROR + DATA_WIDTH;

    // Signed representation of the learning rate so the products stay signed
    localparam signed [NBW_DELTA-1:0] LR = LEARNING_RATE;

    // Intermediate values
    logic signed [NBW_PRED-1:0] y_pred;
    logic signed [NBW_ERROR-1:0] error;
    logic signed [NBW_DELTA-1:0] delta_w;
    logic signed [NBW_DELTA-1:0] delta_b;

    // Predicted output caculation
    always_comb begin
      y_pred = (w * x_in) + b;
    end

    // Error calculation (combinational)
    always_comb begin
      error = y_true - y_pred;
    end

    // Weight and bias update terms (combinational)
    always_comb begin
      delta_w = LR * error * x_in;
      delta_b = LR * error;
    end

    // Register update: w and b receive the DATA_WIDTH LSBs of the sums
    always_ff @(posedge clk or posedge reset) begin
      if (reset) begin
        w <= '0;
        b <= '0;
      end else begin
        w <= w + delta_w;
        b <= b + delta_b;
      end
    end

endmodule

// Asynchronous (dual-clock) FIFO with Gray-coded pointers and 2-flop CDC
// synchronizers.  Full/empty are derived from the Gray pointers so a single
// bit in transit through the synchronizer can never mis-decode.
module fifo_async #(
    parameter DATA_WIDTH = 8,
    parameter DEPTH      = 16
)(
    input  wire                  w_clk,
    input  wire                  w_rst,
    input  wire                  w_inc,
    input  wire [DATA_WIDTH-1:0] w_data,
    input  wire                  r_clk,
    input  wire                  r_rst,
    input  wire                  r_inc,
    output wire                  w_full,
    output wire                  r_empty,
    output wire [DATA_WIDTH-1:0] r_data
);

    localparam ADDR_WIDTH = $clog2(DEPTH);

    // storage
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // ---- write-clock domain ----
    reg  [ADDR_WIDTH:0] wbin, wgray;
    wire [ADDR_WIDTH:0] wbin_next  = wbin + (w_inc & ~w_full);
    wire [ADDR_WIDTH:0] wgray_next = (wbin_next >> 1) ^ wbin_next;

    // ---- read-clock domain ----
    reg  [ADDR_WIDTH:0] rbin, rgray;
    wire [ADDR_WIDTH:0] rbin_next  = rbin + (r_inc & ~r_empty);
    wire [ADDR_WIDTH:0] rgray_next = (rbin_next >> 1) ^ rbin_next;

    // ---- CDC synchronizers (two flops in series) ----
    reg [ADDR_WIDTH:0] wq1, wq2;   // write Gray pointer -> read domain
    reg [ADDR_WIDTH:0] rq1, rq2;   // read  Gray pointer -> write domain

    // write pointer registers
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            wbin  <= '0;
            wgray <= '0;
        end else begin
            wbin  <= wbin_next;
            wgray <= wgray_next;
        end
    end

    // read pointer registers
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            rbin  <= '0;
            rgray <= '0;
        end else begin
            rbin  <= rbin_next;
            rgray <= rgray_next;
        end
    end

    // synchronize read Gray pointer into the write domain
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            rq1 <= '0;
            rq2 <= '0;
        end else begin
            rq1 <= rgray;
            rq2 <= rq1;
        end
    end

    // synchronize write Gray pointer into the read domain
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            wq1 <= '0;
            wq2 <= '0;
        end else begin
            wq1 <= wgray;
            wq2 <= wq1;
        end
    end

    // memory write
    always @(posedge w_clk) begin
        if (w_inc & ~w_full)
            mem[wbin[ADDR_WIDTH-1:0]] <= w_data;
    end

    // memory read (first-word read of current read address)
    assign r_data = mem[rbin[ADDR_WIDTH-1:0]];

    // empty: read Gray pointer equals the synchronized write Gray pointer
    assign r_empty = (rgray == wq2);

    // full: write Gray pointer equals the synchronized read Gray pointer with
    // its TOP TWO bits inverted (Gray-domain form of "MSB differs, rest equal")
    assign w_full  = (wgray == {~rq2[ADDR_WIDTH:ADDR_WIDTH-1], rq2[ADDR_WIDTH-2:0]});

endmodule

module ping_pong_fifo_2_axi_stream #(
  parameter                                    DATA_WIDTH          = 24,
  parameter                                    STROBE_WIDTH        = DATA_WIDTH / 8,
  parameter                                    USE_KEEP            = 0,
  parameter                                    USER_IN_DATA        = 1
)(
  input  logic                                 rst,

  // Ping Pong FIFO Read Interface
  input  logic                                 i_block_fifo_rdy,
  output logic                                 o_block_fifo_act,
  input  logic [23:0]                          i_block_fifo_size,
  input  logic [(DATA_WIDTH + 1) - 1:0]        i_block_fifo_data,
  output logic                                 o_block_fifo_stb,
  input  logic [3:0]                           i_axi_user,

  // AXI Stream Output
  input  logic                                 i_axi_clk,
  output logic [3:0]                           o_axi_user,
  input  logic                                 i_axi_ready,
  output logic [DATA_WIDTH - 1:0]              o_axi_data,
  output logic                                 o_axi_last,
  output logic                                 o_axi_valid
);

// Internal signals
logic [DATA_WIDTH - 1:0] fifo_data_buffer;
logic fifo_valid_buffer;
logic fifo_last_buffer;

// The registered data/last buffers drive the AXI-Stream data path.
assign o_axi_data = fifo_data_buffer;
assign o_axi_last = fifo_last_buffer;
// Pass the user sideband through.
assign o_axi_user = i_axi_user;

// Reset Condition
always_ff @(posedge i_axi_clk or posedge rst) begin
  if (rst) begin
    o_block_fifo_act   <= 1'b0;
    o_block_fifo_stb   <= 1'b0;
    o_axi_valid        <= 1'b0;
    fifo_data_buffer   <= {DATA_WIDTH{1'b0}};
    fifo_valid_buffer  <= 1'b0;
    fifo_last_buffer   <= 1'b0;
  end else begin
    // Default: strobe is a single-cycle pulse.
    o_block_fifo_stb <= 1'b0;

    // An accepted beat frees the output slot.
    if (o_axi_valid && i_axi_ready) begin
      o_axi_valid       <= 1'b0;
      fifo_valid_buffer <= 1'b0;
    end

    // Fetch the next word when the output slot is free (or being freed this
    // cycle) and the FIFO has data available.
    if ((!o_axi_valid || (o_axi_valid && i_axi_ready)) && i_block_fifo_rdy) begin
      o_block_fifo_act  <= 1'b1;                              // take the block
      o_block_fifo_stb  <= 1'b1;                              // read strobe
      fifo_data_buffer  <= i_block_fifo_data[DATA_WIDTH-1:0]; // data payload
      fifo_last_buffer  <= i_block_fifo_data[DATA_WIDTH];     // last flag (MSB)
      fifo_valid_buffer <= 1'b1;
      o_axi_valid       <= 1'b1;
    end else if (!i_block_fifo_rdy) begin
      // No data available: drop the FIFO activate/read request.
      o_block_fifo_act <= 1'b0;
    end
  end
end

endmodule

module hmac_reg_interface #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  write_en,
    input  logic                  read_en,
    input  logic [ADDR_WIDTH-1:0] addr,
    input  logic [DATA_WIDTH-1:0] wdata,
    input  logic                  i_wait_en,
    output logic [DATA_WIDTH-1:0] rdata,
    output logic                  hmac_valid,
    output logic                  hmac_key_error
);

    // Number of registers
    localparam NUM_REGS = 1 << ADDR_WIDTH;
    localparam [DATA_WIDTH-1:0] XOR = {(DATA_WIDTH/2){2'b01}};

    // FSM States
    localparam [2:0]
        IDLE      = 3'b000,
        ANALYZE   = 3'b001,
        XOR_DATA  = 3'b010,
        WRITE     = 3'b011,
        LOST      = 3'b100,
        CHECK_KEY = 3'b101,
        TRIG_WAIT = 3'b110;

    logic [2:0] current_state, next_state;

    // Registers
    logic [DATA_WIDTH-1:0] registers [NUM_REGS-1:0];

    // HMAC data
    logic [DATA_WIDTH-1:0] hmac_key;
    logic [DATA_WIDTH-1:0] hmac_data;

    logic [DATA_WIDTH-1:0] xor_data;

    // Captured operands for the in-flight write transaction
    logic [DATA_WIDTH-1:0] proc_data;
    logic [ADDR_WIDTH-1:0] wr_addr;

    logic key_valid;
    logic wdata_msb;
    integer k;

    localparam [ADDR_WIDTH-1:0] ADDR0 = {ADDR_WIDTH{1'b0}};
    localparam [ADDR_WIDTH-1:0] ADDR1 = {{(ADDR_WIDTH-1){1'b0}}, 1'b1};

    assign wdata_msb = wdata[DATA_WIDTH-1];

    // ---- FSM next-state (purely combinational, self-holding default) ----
    always_comb begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (write_en) next_state = ANALYZE;
            end
            ANALYZE: begin
                if (wdata_msb) next_state = XOR_DATA;
                else           next_state = WRITE;
            end
            XOR_DATA: begin
                next_state = WRITE;
            end
            WRITE: begin
                if (write_en) next_state = IDLE;
                else          next_state = LOST;
            end
            LOST: begin
                if (read_en) next_state = CHECK_KEY;
            end
            CHECK_KEY: begin
                if (key_valid) next_state = TRIG_WAIT;
                else           next_state = WRITE;
            end
            TRIG_WAIT: begin
                if (!i_wait_en) begin
                    if ((hmac_data != '0) && (hmac_key != '0))
                        next_state = IDLE;
                    else
                        next_state = WRITE;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    // ---- FSM state register ----
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // ---- XOR data path + key format validation (combinational) ----
    // XOR each 2-bit group of wdata with 2'b01.
    assign xor_data = wdata ^ XOR;

    // Key is valid when its 2 MSBs and 2 LSBs are zero.
    assign key_valid      = (hmac_key[DATA_WIDTH-1 -: 2] == 2'b00) &&
                            (hmac_key[1:0] == 2'b00);
    assign hmac_key_error = ~key_valid;

    // hmac_valid asserts only while the FSM is in the WRITE state.
    assign hmac_valid = (current_state == WRITE);

    // ---- Write / Read datapath (sequential, keyed off the CURRENT state) ----
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hmac_key  <= '0;
            hmac_data <= '0;
            rdata     <= '0;
            proc_data <= '0;
            wr_addr   <= '0;
            for (k = 0; k < NUM_REGS; k = k + 1)
                registers[k] <= '0;
        end else begin
            // Capture operands for the write transaction as the FSM walks
            // through ANALYZE / XOR_DATA before landing in WRITE.
            if (current_state == ANALYZE) begin
                wr_addr   <= addr;
                proc_data <= wdata;
            end
            if (current_state == XOR_DATA) begin
                proc_data <= xor_data;
            end

            // Write in the WRITE state; addresses 0/1 map to the HMAC key/data.
            if (current_state == WRITE) begin
                if (wr_addr == ADDR0)
                    hmac_key  <= proc_data;
                else if (wr_addr == ADDR1)
                    hmac_data <= proc_data;
                else
                    registers[wr_addr] <= proc_data;
            end

            // Read is a distinct 1-cycle path, never colliding with a write
            // (only performed when the FSM is not in the WRITE state).
            if (read_en && (current_state != WRITE)) begin
                if (addr == ADDR0)
                    rdata <= hmac_key;
                else if (addr == ADDR1)
                    rdata <= hmac_data;
                else
                    rdata <= registers[addr];
            end
        end
    end

endmodule

module mux_synch (

input [7:0] data_in,   			//asynchronous data input
input req,                  		//indicating that data is available at the data_in input
input dst_clk,                 		//destination clock
input src_clk,                 		//source clock
input nrst,                    		//asynchronous reset
output reg [7:0] data_out,              //synchronized version of data_in to the destination clock domain
output ack_out );


wire syncd_req,anded_req,syncd_ack;
reg syncd_req_1,ack;
reg syncd_ack_1;                        // src-domain delayed copy for edge detection


nff  req_synch_0 (.d_in(req),.dst_clk(dst_clk),.rst(nrst),.syncd(syncd_req)) ;		//2-flop synchronizer for the enable input


always_ff @(posedge dst_clk)                     					//one clock cycle delayed synced_enable
begin
    syncd_req_1 <= syncd_req;
end

assign anded_req = (!syncd_req_1 && syncd_req);    					//posedge detector


always_ff @(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		data_out <= 1'b0;               					//forcing the output data_in to zero when an active-low asynchronous reset is detected.

	else if (anded_req==1'b1)
		data_out <= data_in;                    				//latching data_in to data_out when the enable signal is available.

	else
		data_out <= data_out;                   				//holds the data till next req comes.
end


// BUG FIX (CDC pulse loss): a one-dst_clk-cycle ack pulse can fall entirely
// between two active edges of the slower src_clk and be missed by the 2-flop
// synchronizer. Convert the acknowledgment into a TOGGLE (a level that flips on
// every accepted transfer and is HELD until the next one). The stable level is
// always captured by the 2-flop synchronizer regardless of the clock ratio, and
// an edge detector in the source domain regenerates a clean one-cycle ack_out.
always_ff@(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		ack <= 1'b0;

	else if (anded_req==1'b1)
		ack <= ~ack;                    				//toggle on each accepted transfer

	else
		ack <= ack;                     				//hold the level between events
end

//changing the clock domain of the ack signal (level/toggle crossing)
nff  enable_synch_1 (.d_in(ack),.dst_clk(src_clk),.rst(nrst),.syncd(syncd_ack)) ;

//edge detector circuit : regenerate a single src_clk-wide pulse from the toggle
always_ff @(posedge src_clk or negedge nrst)
begin
	if(!nrst)
		syncd_ack_1 <= 1'b0;
	else
		syncd_ack_1 <= syncd_ack;
end

assign ack_out = syncd_ack ^ syncd_ack_1;


endmodule

module nff  (

	input d_in,   									//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     								//destination domain clock.
	input rst,         								//asynchronous active-low reset
	output reg  syncd 								//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

reg   dmeta;             								//register to hold output.



always@(posedge dst_clk or negedge rst)
begin
	if(!rst)              								//active-low asynchronous reset
  begin
    syncd <= 1'b0;      								//resetting the synced register to 0
    dmeta <= 1'b0;      								//resetting dmeta register to 0
  end
  else
  begin
    dmeta <= d_in;      								//passing d_in to dmeta
    syncd <= dmeta;     								//passing dmeta to syncd
  end
end

endmodule

module spi_fsm (
    input  wire         i_clk,       // System clock
    input  wire         i_rst_b,     // Active-low async reset
    input  wire [15:0]  i_data_in,   // Parallel 16-bit data to transmit
    input  wire         i_enable,    // Enable block
    input  wire         i_fault,     // Fault indicator
    input  wire         i_clear,     // Forces FSM to clear/idle

    output reg          o_spi_cs_b,  // SPI chip select (active-low)
    output reg          o_spi_clk,   // SPI clock
    output reg          o_spi_data,  // Serialized SPI data out
    output reg [4:0]    o_bits_left, // Bits left to transmit
    output reg          o_done,      // Single-cycle pulse when done or error
    output reg [1:0]    o_fsm_state  // FSM state for external monitoring
);

    // FSM state encoding
    localparam [1:0] IDLE       = 2'b00;
    localparam [1:0] TRANSMIT   = 2'b01;
    localparam [1:0] CLK_TOGGLE = 2'b10;
    localparam [1:0] ERROR      = 2'b11;

    reg [15:0] shift_reg;   // holds the data being shifted out (MSB first)

    always @(posedge i_clk or negedge i_rst_b) begin
        if (!i_rst_b) begin
            o_fsm_state <= IDLE;
            o_spi_cs_b  <= 1'b1;
            o_spi_clk   <= 1'b0;
            o_spi_data  <= 1'b0;
            o_bits_left <= 5'h10;   // 16 bits remaining
            o_done      <= 1'b0;
            shift_reg   <= 16'h0000;
        end else begin
            // Default: o_done is a single-cycle self-clearing pulse
            o_done <= 1'b0;

            // ---- Priority ladder: clear > fault > per-state behaviour ----
            if (i_clear) begin
                // Force back to idle, clear counters/outputs
                o_fsm_state <= IDLE;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= 5'h10;
                shift_reg   <= 16'h0000;
            end else if (i_fault) begin
                // Enter error state; pulse o_done once on the transition
                if (o_fsm_state != ERROR)
                    o_done <= 1'b1;
                o_fsm_state <= ERROR;
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= 5'd10;
            end else begin
                case (o_fsm_state)
                    IDLE: begin
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= 5'h10;
                        if (i_enable) begin
                            shift_reg   <= i_data_in;
                            o_fsm_state <= TRANSMIT;
                        end
                    end

                    TRANSMIT: begin
                        if (!i_enable) begin
                            // Enable deasserted -> return to idle
                            o_fsm_state <= IDLE;
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= 1'b0;
                            o_bits_left <= 5'h10;
                        end else begin
                            // Activate SPI, drive the current MSB, clock low (setup)
                            o_spi_cs_b  <= 1'b0;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= shift_reg[15];
                            o_fsm_state <= CLK_TOGGLE;
                        end
                    end

                    CLK_TOGGLE: begin
                        if (!i_enable) begin
                            o_fsm_state <= IDLE;
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_spi_data  <= 1'b0;
                            o_bits_left <= 5'h10;
                        end else begin
                            // Toggle clock high to latch data externally, shift and count.
                            // The clock stays high through the final bit so it is
                            // latched; IDLE restores idle outputs on the next cycle.
                            o_spi_clk   <= 1'b1;
                            shift_reg   <= {shift_reg[14:0], 1'b0};
                            o_bits_left <= o_bits_left - 5'd1;
                            if (o_bits_left == 5'd1) begin
                                // Last bit transmitted -> done, back to idle
                                o_done      <= 1'b1;
                                o_fsm_state <= IDLE;
                            end else begin
                                o_fsm_state <= TRANSMIT;
                            end
                        end
                    end

                    ERROR: begin
                        // Remain in error (safe outputs) until cleared or reset
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= 5'd10;
                        o_done      <= 1'b0;
                    end

                    default: begin
                        o_fsm_state <= IDLE;
                    end
                endcase
            end
        end
    end

endmodule

module cvdp_copilot_apb_gpio #(
  parameter GPIO_WIDTH = 8
)(
  // Clock and Reset Signals
  input logic pclk,       // Clock signal
  input logic preset_n,   // Active-low reset signal

  // APB Interface Inputs
  input logic psel,           // Peripheral select
  input logic [7:2] paddr,    // APB address bus (bits [7:2])
  input logic penable,        // Transfer control signal
  input logic pwrite,         // Write control signal
  input logic [31:0] pwdata,  // Write data bus

  // APB Interface Outputs
  output logic [31:0] prdata, // Read data bus
  output logic pready,        // Device ready signal
  output logic pslverr,       // Device error response

  // GPIO Interface Inputs and Outputs
  input logic [GPIO_WIDTH-1:0] gpio_in,      // GPIO input signals
  output logic [GPIO_WIDTH-1:0] gpio_out,    // GPIO output signals
  output logic [GPIO_WIDTH-1:0] gpio_enable, // GPIO output enable signals

  // Interrupt Outputs
  output logic [GPIO_WIDTH-1:0] gpio_int, // Individual interrupt outputs
  output logic comb_int                   // Combined interrupt output
);

  // Signals for Read/Write Controls
  logic read_enable;                     // Read enable signal
  logic write_enable;                    // Write enable signal
  logic write_enable_reg_04;             // Write enable for Data Output register
  logic write_enable_reg_08;             // Write enable for Output Enable register
  logic write_enable_reg_0C;             // Write enable for Interrupt Enable register
  logic write_enable_reg_10;             // Write enable for Interrupt Type register
  logic write_enable_reg_14;             // Write enable for Interrupt Polarity register
  logic write_enable_reg_18;             // Write enable for Interrupt State register
  logic write_enable_reg_1C;             // Write enable for Direction Control register
  logic write_enable_reg_20;             // Write enable for Power Management register
  logic write_enable_reg_24;             // Write enable for Interrupt Reset register
  logic [GPIO_WIDTH-1:0] read_mux;       // Read data multiplexer
  logic [GPIO_WIDTH-1:0] read_mux_d1;    // Registered read data

  // Control Registers
  logic [GPIO_WIDTH-1:0] reg_dout;       // Data Output register
  logic [GPIO_WIDTH-1:0] reg_dout_en;    // Output Enable register
  logic [GPIO_WIDTH-1:0] reg_int_en;     // Interrupt Enable register
  logic [GPIO_WIDTH-1:0] reg_int_type;   // Interrupt Type register
  logic [GPIO_WIDTH-1:0] reg_int_pol;    // Interrupt Polarity register
  logic [GPIO_WIDTH-1:0] reg_int_state;  // Interrupt State register
  logic [GPIO_WIDTH-1:0] reg_gpio_dir;   // Direction Control register (0x1C): 1=output, 0=input
  logic                  reg_pwr_down;   // Power Management register (0x20) bit[0]

  // I/O Signal Path and Interrupt Logic
  logic [GPIO_WIDTH-1:0] data_in_sync1;            // First stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_sync2;            // Second stage of input synchronization
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted;     // Polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted_dly; // Delayed version of polarity-adjusted input data
  logic [GPIO_WIDTH-1:0] edge_detect;              // Edge detection signals
  logic [GPIO_WIDTH-1:0] raw_int;                  // Raw interrupt signals
  logic [GPIO_WIDTH-1:0] int_masked;               // Masked interrupt signals
  logic [GPIO_WIDTH-1:0] clear_interrupt;          // Clear interrupt signals

  // Read and Write Control Signals
  assign read_enable = psel & (~pwrite); // Read enable
  assign write_enable = psel & (~penable) & pwrite; // Write enable

  // Write Enable Signals for Specific Registers
  assign write_enable_reg_04 = write_enable & (paddr[7:2] == 6'd1); // Address 0x04
  assign write_enable_reg_08 = write_enable & (paddr[7:2] == 6'd2); // Address 0x08
  assign write_enable_reg_0C = write_enable & (paddr[7:2] == 6'd3); // Address 0x0C
  assign write_enable_reg_10 = write_enable & (paddr[7:2] == 6'd4); // Address 0x10
  assign write_enable_reg_14 = write_enable & (paddr[7:2] == 6'd5); // Address 0x14
  assign write_enable_reg_18 = write_enable & (paddr[7:2] == 6'd6); // Address 0x18
  assign write_enable_reg_1C = write_enable & (paddr[7:2] == 6'd7); // Address 0x1C
  assign write_enable_reg_20 = write_enable & (paddr[7:2] == 6'd8); // Address 0x20
  assign write_enable_reg_24 = write_enable & (paddr[7:2] == 6'd9); // Address 0x24

  // Write Operations for Control Registers

  // Data Output Register (reg_dout)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_04)
      reg_dout <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Output Enable Register (reg_dout_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_08)
      reg_dout_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Enable Register (reg_int_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_0C)
      reg_int_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Type Register (reg_int_type)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_type <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_10)
      reg_int_type <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Polarity Register (reg_int_pol)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_pol <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_14)
      reg_int_pol <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Direction Control Register (reg_gpio_dir) at 0x1C
  //   Bit[i] = 1 -> pin i is an output, 0 -> pin i is an input.
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_gpio_dir <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_1C)
      reg_gpio_dir <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Power Management Register (reg_pwr_down) at 0x20, bit[0]
  //   1 -> power down all GPIO pins, 0 -> normal operation.
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_pwr_down <= 1'b0;
    else if (write_enable_reg_20)
      reg_pwr_down <= pwdata[0];
  end

  // Read Operation: Multiplexing Register Data Based on Address
  always_comb begin
    case (paddr[7:2])
      6'd0: read_mux = data_in_sync2;   // Input Data Register at address 0x00
      6'd1: read_mux = reg_dout;        // Data Output Register at address 0x04
      6'd2: read_mux = reg_dout_en;     // Output Enable Register at address 0x08
      6'd3: read_mux = reg_int_en;      // Interrupt Enable Register at address 0x0C
      6'd4: read_mux = reg_int_type;    // Interrupt Type Register at address 0x10
      6'd5: read_mux = reg_int_pol;     // Interrupt Polarity Register at address 0x14
      6'd6: read_mux = reg_int_state;   // Interrupt State Register at address 0x18
      6'd7: read_mux = reg_gpio_dir;    // Direction Control Register at address 0x1C
      6'd8: read_mux = {{(GPIO_WIDTH-1){1'b0}}, reg_pwr_down}; // Power Management at 0x20
      6'd9: read_mux = {GPIO_WIDTH{1'b0}}; // Interrupt Reset (write-only) at 0x24
      default: read_mux = {GPIO_WIDTH{1'b0}}; // Default to zeros if address is invalid
    endcase
  end

  // Registering Read Data for Timing Alignment
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      read_mux_d1 <= {GPIO_WIDTH{1'b0}};
    else
      read_mux_d1 <= read_mux;
  end

  // Output Read Data to APB Interface
  assign prdata = (read_enable) ? {{(32-GPIO_WIDTH){1'b0}}, read_mux_d1} : {32{1'b0}};
  assign pready = 1'b1; // Always ready
  assign pslverr = 1'b0; // No error

  // Driving GPIO Outputs and Output Enables
  //   A pin drives only when configured as an output (reg_gpio_dir) and the
  //   block is not powered down.
  assign gpio_enable = reg_gpio_dir & {GPIO_WIDTH{~reg_pwr_down}};
  assign gpio_out    = reg_dout;

  // Input Synchronization to Avoid Metastability
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_sync1 <= {GPIO_WIDTH{1'b0}};
      data_in_sync2 <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_sync1 <= gpio_in;
      data_in_sync2 <= data_in_sync1;
    end
  end

  // Interrupt Logic

  // Adjusting Input Data Based on Interrupt Polarity
  assign data_in_pol_adjusted = data_in_sync2 ^ reg_int_pol; // Polarity adjustment

  // Registering Polarity-Adjusted Input Data and Delaying for Edge Detection
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_pol_adjusted_dly <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_pol_adjusted_dly <= data_in_pol_adjusted;
    end
  end

  // Edge Detection Logic for Interrupts
  assign edge_detect = data_in_pol_adjusted & (~data_in_pol_adjusted_dly); // Rising edge detection

  // Selecting Interrupt Type (Edge or Level-Triggered)
  assign raw_int = (reg_int_type & edge_detect) | (~reg_int_type & data_in_pol_adjusted); // Interrupt source

  // Applying Interrupt Enable Mask
  assign int_masked = raw_int & reg_int_en; // Masked interrupts

  // Clear Interrupt Signals: writing 1 to the Interrupt State register (0x18)
  // or to the dedicated Interrupt Reset register (0x24) clears interrupts.
  assign clear_interrupt = pwdata[GPIO_WIDTH-1:0] &
                           {GPIO_WIDTH{write_enable_reg_18 | write_enable_reg_24}};

  // Updating Interrupt State Register
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      reg_int_state <= {GPIO_WIDTH{1'b0}};
    end else begin
      integer i;
      for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
        if (reg_int_type[i]) begin
          // Edge-triggered interrupt
          if (clear_interrupt[i]) begin
            reg_int_state[i] <= 1'b0;
          end else if (int_masked[i]) begin
            reg_int_state[i] <= 1'b1;
          end
        end else begin
          // Level-triggered interrupt
          if (clear_interrupt[i])
            reg_int_state[i] <= 1'b0;
          else
            reg_int_state[i] <= int_masked[i];
        end
      end
    end
  end

  // Connecting Interrupt Outputs
  assign gpio_int = reg_int_state;     // Individual interrupt outputs
  assign comb_int = |reg_int_state;    // Combined interrupt output

endmodule

module search_binary_search_tree #(
    parameter DATA_WIDTH = 32,         // Width of the data (of a single element)
    parameter ARRAY_SIZE = 15          // Maximum number of elements in the BST
) (

    input clk,                         // Clock signal
    input reset,                       // Reset signal
    input reg start,                   // Start signal to initiate the search
    input reg [DATA_WIDTH-1:0] search_key, // Key to search in the BST
    input reg [$clog2(ARRAY_SIZE):0] root, // Root node of the BST
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys, // Node keys in the BST
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child, // Left child pointers
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child, // Right child pointers
    output reg [$clog2(ARRAY_SIZE):0] key_position, // Position of the found key
    output reg complete_found,         // Signal indicating search completion
    output reg search_invalid          // Signal indicating invalid search
);

    localparam PW = $clog2(ARRAY_SIZE)+1;     // pointer width (index + null bit)

    // Parameters for FSM states
    parameter S_IDLE = 3'b000,                 // Idle state
              S_INIT = 3'b001,                 // Initialization state
              S_SEARCH_LEFT = 3'b010,          // Search in left subtree
              S_SEARCH_LEFT_RIGHT = 3'b011,    // Search in both left and right subtrees
              S_COMPLETE_SEARCH = 3'b100;      // Search completion state

    // Registers to store the current FSM state
    reg [2:0] search_state;

    // Variables to manage traversal
    reg [$clog2(ARRAY_SIZE):0] position;       // Position of the current node
    reg found;                                 // Indicates if the key is found

    reg left_done, right_done;                 // Flags to indicate completion of left and right subtree traversals

    // Stacks for managing traversal of left and right subtrees
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_stack;  // Stack for left subtree traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_stack; // Stack for right subtree traversal
    reg [$clog2(ARRAY_SIZE):0] sp_left;         // Stack pointer for left subtree
    reg [$clog2(ARRAY_SIZE):0] sp_right;        // Stack pointer for right subtree

    // Pointers for the current nodes in left and right subtrees
    reg [$clog2(ARRAY_SIZE):0] current_left_node;  // Current node in the left subtree
    reg [$clog2(ARRAY_SIZE):0] current_right_node; // Current node in the right subtree

    // Output indices for traversal
    reg [$clog2(ARRAY_SIZE):0] left_output_index;  // Output index for left subtree
    reg [$clog2(ARRAY_SIZE):0] right_output_index; // Output index for right subtree

    // Running in-order rank counter
    reg [$clog2(ARRAY_SIZE):0] count;

    // Integer for loop iterations
    integer i;

    // Combinational read of the current top-of-stack node (valid when sp_left != 0)
    wire [PW-1:0]         top_node  = left_stack[(sp_left-1)*PW +: PW];
    wire [DATA_WIDTH-1:0] top_key   = keys[top_node*DATA_WIDTH +: DATA_WIDTH];
    wire [PW-1:0]         top_right = right_child[top_node*PW +: PW];

    // Always block triggered on the rising edge of the clock or reset signal
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            search_state <= S_IDLE;  // Set state to IDLE
            found <= 0;              // Reset found flag
            position <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Invalid position
            complete_found <= 0;     // Reset complete_found signal
            key_position <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Invalid key position
            left_output_index <= 0;  // Reset left output index
            right_output_index <= 0; // Reset right output index
            sp_left <= 0;            // Reset left stack pointer
            sp_right <= 0;           // Reset right stack pointer
            left_done <= 0;          // Reset left_done flag
            right_done <= 0;         // Reset right_done flag
            search_state <= S_IDLE;  // Set state to IDLE
            search_invalid <= 0;        // Set invalid_key to 0
            count <= 0;
            current_left_node <= 0;
            current_right_node <= 0;

            // Clear the stacks
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            // Main FSM logic
            case (search_state)
                S_IDLE: begin
                    // Reset intermediate variables
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    complete_found <= 0;
                    search_invalid <= 0;

                    if (start) begin
                        // Start the search
                        left_output_index <= 0;
                        right_output_index <= 0;
                        sp_left <= 0;
                        sp_right <= 0;
                        left_done <= 0;
                        right_done <= 0;
                        found <= 0;
                        count <= 0;
                        position <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        key_position <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        search_state <= S_INIT; // Move to INIT state
                    end
                end

                S_INIT: begin
                    // Detect an empty tree (all keys zero and every child pointer null).
                    if ((keys == {ARRAY_SIZE*DATA_WIDTH{1'b0}}) &&
                        (&left_child) && (&right_child)) begin
                        found        <= 1'b0;
                        search_state <= S_COMPLETE_SEARCH;
                    end else begin
                        // Begin an iterative in-order traversal from the root.
                        current_left_node <= root;
                        count             <= 0;
                        sp_left           <= 0;
                        found             <= 1'b0;
                        position          <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        search_state      <= S_SEARCH_LEFT;
                    end
                end

                S_SEARCH_LEFT: begin
                    // Push the current node and descend along its left spine, one
                    // node per cycle.  When the left child is null, start visiting.
                    if (current_left_node != {PW{1'b1}}) begin
                        left_stack[sp_left*PW +: PW] <= current_left_node;
                        sp_left                      <= sp_left + 1'b1;
                        current_left_node            <= left_child[current_left_node*PW +: PW];
                    end else begin
                        search_state <= S_SEARCH_LEFT_RIGHT;
                    end
                end

                S_SEARCH_LEFT_RIGHT: begin
                    // Pop and visit the next in-order node.  A visited node's rank
                    // is the number of nodes visited before it (count).  On a match
                    // report the rank; otherwise advance to the node's right subtree.
                    if (sp_left != 0) begin
                        sp_left <= sp_left - 1'b1;
                        if (top_key == search_key) begin
                            found        <= 1'b1;
                            position     <= count;
                            search_state <= S_COMPLETE_SEARCH;
                        end else begin
                            count             <= count + 1'b1;
                            current_left_node <= top_right;
                            search_state      <= S_SEARCH_LEFT;
                        end
                    end else begin
                        // Entire tree traversed without a match.
                        found        <= 1'b0;
                        search_state <= S_COMPLETE_SEARCH;
                    end
                end

                S_COMPLETE_SEARCH: begin
                    if (found) begin
                        complete_found <= 1'b1;
                        search_invalid <= 1'b0;
                        key_position   <= position;
                    end else begin
                        complete_found <= 1'b0;
                        search_invalid <= 1'b1;
                        key_position   <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    search_state <= S_IDLE;
                end

                default: begin
                    search_state <= S_IDLE; // Default to IDLE state
                end
            endcase
        end
    end

endmodule

module cont_adder #(
    parameter DATA_WIDTH = 32,
    parameter signed THRESHOLD_VALUE_1 = 50,
    parameter signed THRESHOLD_VALUE_2 = 100,
    parameter SIGNED_INPUTS = 1,
    parameter ACCUM_MODE = 0,
    parameter WEIGHT = 1
) (
    input  logic                         clk,
    input  logic                         reset,
    input  logic signed [DATA_WIDTH-1:0] data_in,
    input  logic                         data_valid,
    input  logic [15:0]                  window_size,
    output logic signed [DATA_WIDTH-1:0] sum_out,
    output logic signed [DATA_WIDTH-1:0] avg_out,
    output logic                         threshold_1,
    output logic                         threshold_2,
    output logic                         sum_ready
);

    // Accumulator has 2 guard bits over the data width.
    localparam ACC_WIDTH = DATA_WIDTH + 2;

    // Sequential Registers
    logic signed [ACC_WIDTH-1:0] sum_accum;
    logic        [15:0]          sample_count;

    // Combinational Signals (widened to the accumulator width so that the
    // additions are width-consistent and produce no expansion/truncation lint)
    logic signed [ACC_WIDTH-1:0] data_ext;        // sign/zero-extended input per SIGNED_INPUTS
    logic signed [ACC_WIDTH-1:0] weighted_input;
    logic signed [ACC_WIDTH-1:0] new_sum;
    logic        [16:0]          next_count;       // sample_count + 1, one extra bit
    logic                        threshold_1_comb;
    logic                        threshold_2_comb;
    logic                        sum_ready_reg;

    // Combinational Logic
    always_comb begin
        sum_ready_reg = 1'b0;

        // Use SIGNED_INPUTS to select the interpretation of data_in.
        if (SIGNED_INPUTS)
            data_ext = ACC_WIDTH'(signed'(data_in));
        else
            data_ext = ACC_WIDTH'(signed'({1'b0, data_in}));

        weighted_input = data_ext * ACC_WIDTH'(signed'(WEIGHT));
        new_sum        = sum_accum + weighted_input;
        next_count     = {1'b0, sample_count} + 17'd1;

        threshold_1_comb = (new_sum >= ACC_WIDTH'(signed'(THRESHOLD_VALUE_1))) ||
                           (new_sum <= -ACC_WIDTH'(signed'(THRESHOLD_VALUE_1)));
        threshold_2_comb = (new_sum >= ACC_WIDTH'(signed'(THRESHOLD_VALUE_2))) ||
                           (new_sum <= -ACC_WIDTH'(signed'(THRESHOLD_VALUE_2)));

        if (data_valid) begin
            if (ACCUM_MODE == 0) begin
                if (threshold_1_comb || threshold_2_comb)
                    sum_ready_reg = 1'b1;
                else
                    sum_ready_reg = 1'b0;
            end else if (ACCUM_MODE == 1) begin
                if (next_count >= {1'b0, window_size})
                    sum_ready_reg = 1'b1;
                else
                    sum_ready_reg = 1'b0;
            end
        end else begin
            sum_ready_reg = 1'b0;
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            sum_accum     <= '0;
            sample_count  <= 16'd0;
            sum_ready     <= 1'b0;
            sum_out       <= '0;
            avg_out       <= '0;
            threshold_1   <= 1'b0;
            threshold_2   <= 1'b0;
        end else if (data_valid) begin
            threshold_1 <= threshold_1_comb;
            threshold_2 <= threshold_2_comb;

            if (ACCUM_MODE == 1) begin
                sum_accum    <= sum_accum + weighted_input;
                sample_count <= sample_count + 16'd1;
                if (sum_ready_reg) begin
                    sum_out      <= DATA_WIDTH'(sum_accum + weighted_input);
                    avg_out      <= DATA_WIDTH'((sum_accum + weighted_input) / signed'({1'b0, window_size}));
                    sum_ready    <= 1'b1;
                    sum_accum    <= '0;
                    sample_count <= 16'd0;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                    avg_out   <= '0;
                end
            end else begin
                sum_accum <= sum_accum + weighted_input;
                if (sum_ready_reg) begin
                    sum_out   <= DATA_WIDTH'(sum_accum + weighted_input);
                    sum_ready <= 1'b1;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                end
                avg_out <= '0;
            end
        end else begin
            sum_ready <= 1'b0;
        end
    end

endmodule

module interrupt_controller
#(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8)
(
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0] interrupt_service,
    output logic                      cpu_interrupt,
    input  logic                      cpu_ack,
    output logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]     interrupt_vector,
    input  logic [NUM_INTERRUPTS-1:0] priority_map_value [NUM_INTERRUPTS-1:0],
    input  logic                      priority_map_update,
    input  logic [ADDR_WIDTH-1:0]     vector_table_value [NUM_INTERRUPTS-1:0],
    input  logic                      vector_table_update,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_mask_value,
    input  logic                      interrupt_mask_update
);

    localparam IDX_W = $clog2(NUM_INTERRUPTS);

    // Internal state
    logic [NUM_INTERRUPTS-1:0] priority_map   [NUM_INTERRUPTS-1:0]; // per-source priority (lower = higher priority)
    logic [ADDR_WIDTH-1:0]     vector_table   [NUM_INTERRUPTS-1:0]; // per-source vector
    logic [NUM_INTERRUPTS-1:0] interrupt_mask;
    logic [NUM_INTERRUPTS-1:0] pending_interrupts;
    logic [NUM_INTERRUPTS-1:0] req_sync;      // synchronizer for async requests
    logic                      servicing;     // one interrupt in-flight

    integer k;

    // Effective (unmasked) pending set
    logic [NUM_INTERRUPTS-1:0] effective_pending;
    assign effective_pending = pending_interrupts & ~interrupt_mask;

    // Combinational priority arbitration over the effective pending set.
    // Lowest priority value wins; ties resolve to the lowest index.
    logic                any_pending_c;
    logic [IDX_W-1:0]    best_idx_c;
    logic [NUM_INTERRUPTS-1:0] best_pri_c;
    integer j;
    always_comb begin
        any_pending_c = 1'b0;
        best_idx_c    = '0;
        best_pri_c    = {NUM_INTERRUPTS{1'b1}}; // max value
        for (j = 0; j < NUM_INTERRUPTS; j = j + 1) begin
            if (effective_pending[j] && (priority_map[j] < best_pri_c)) begin
                best_pri_c    = priority_map[j];
                best_idx_c    = j;
                any_pending_c = 1'b1;
            end
        end
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (k = 0; k < NUM_INTERRUPTS; k = k + 1) begin
                priority_map[k] <= k[NUM_INTERRUPTS-1:0];        // sequential default priorities
                vector_table[k] <= (k*4);                        // vectors = multiples of 4
            end
            interrupt_mask     <= '0;
            pending_interrupts <= '0;
            req_sync           <= '0;
            servicing          <= 1'b0;
            interrupt_service  <= '0;
            cpu_interrupt      <= 1'b0;
            interrupt_idx      <= '0;
            interrupt_vector   <= '0;
        end else begin
            // Synchronize async interrupt requests, then latch into pending
            req_sync           <= interrupt_requests;
            pending_interrupts <= pending_interrupts | req_sync;

            // Dynamic updates
            if (priority_map_update) begin
                for (k = 0; k < NUM_INTERRUPTS; k = k + 1)
                    priority_map[k] <= priority_map_value[k];
            end
            if (vector_table_update) begin
                for (k = 0; k < NUM_INTERRUPTS; k = k + 1)
                    vector_table[k] <= vector_table_value[k];
            end
            if (interrupt_mask_update) begin
                interrupt_mask <= interrupt_mask_value;
            end

            // Servicing logic: one interrupt at a time
            if (!servicing) begin
                if (any_pending_c) begin
                    servicing         <= 1'b1;
                    cpu_interrupt     <= 1'b1;
                    interrupt_idx     <= best_idx_c;
                    interrupt_vector  <= vector_table[best_idx_c];
                    interrupt_service <= ('b1 << best_idx_c);
                end else begin
                    cpu_interrupt     <= 1'b0;
                    interrupt_service <= '0;
                end
            end else begin
                if (cpu_ack) begin
                    // Clear the interrupt that was actually presented to the CPU
                    pending_interrupts[interrupt_idx] <= 1'b0;
                    interrupt_service <= '0;
                    cpu_interrupt     <= 1'b0;
                    servicing         <= 1'b0;
                end
            end
        end
    end

endmodule

module nbit_swizzling #(parameter DATA_WIDTH = 64)(
    input  [DATA_WIDTH-1:0] data_in,                               // Input data of size DATA_WIDTH
    input  [1:0] sel,                                              //  2-bit selection signal
    output reg [DATA_WIDTH:0] data_out,                            // Output data of size DATA_WIDTH
    output reg [DATA_WIDTH + $clog2(DATA_WIDTH):0] ecc_out         // Hamming-encoded output (data + parity bits)
);

    localparam CLOG2_DW    = $clog2(DATA_WIDTH);
    localparam PARITY_BITS = $clog2(DATA_WIDTH + CLOG2_DW + 1);
    localparam CODE_LEN    = DATA_WIDTH + CLOG2_DW + 1;            // total ecc_out length (== DATA_WIDTH + PARITY_BITS)

    integer i;
    wire parity_bit;


    assign parity_bit = ^data_in;

    always @(*) begin
        case(sel)
            2'b00: begin
                for (i = 0; i < DATA_WIDTH; i = i + 1) begin
                    data_out[i] = data_in[DATA_WIDTH-1-i];
                end
                data_out[DATA_WIDTH] = parity_bit;
            end

            2'b01: begin
                for (i = 0; i < DATA_WIDTH/2; i = i + 1) begin
                    data_out[i]                = data_in[DATA_WIDTH/2-1-i];
                    data_out[DATA_WIDTH/2 + i] = data_in[DATA_WIDTH-1-i];
                end
                data_out[DATA_WIDTH] = parity_bit;
            end

            2'b10: begin
                for (i = 0; i < DATA_WIDTH/4; i = i + 1) begin
                    data_out[i] = data_in[DATA_WIDTH/4-1-i];
                    data_out[DATA_WIDTH/4 + i]   = data_in[DATA_WIDTH/2-1-i];
                    data_out[DATA_WIDTH/2 + i]   = data_in[3*DATA_WIDTH/4-1-i];
                    data_out[3*DATA_WIDTH/4 + i] = data_in[DATA_WIDTH-1-i];
                end
                data_out[DATA_WIDTH] = parity_bit;
            end

            2'b11: begin
                for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                    data_out[i]                  = data_in[DATA_WIDTH/8-1-i];
                    data_out[DATA_WIDTH/8 + i]   = data_in[DATA_WIDTH/4-1-i];
                    data_out[DATA_WIDTH/4 + i]   = data_in[3*DATA_WIDTH/8-1-i];
                    data_out[3*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH/2-1-i];
                    data_out[DATA_WIDTH/2 + i]   = data_in[5*DATA_WIDTH/8-1-i];
                    data_out[5*DATA_WIDTH/8 + i] = data_in[3*DATA_WIDTH/4-1-i];
                    data_out[3*DATA_WIDTH/4 + i] = data_in[7*DATA_WIDTH/8-1-i];
                    data_out[7*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH-1-i];
                end
                data_out[DATA_WIDTH] = parity_bit;
            end
            default: begin
                data_out = data_in;
                data_out[DATA_WIDTH] = parity_bit;
            end
        endcase
    end

    // ---------------------------------------------------------------
    // Hamming ECC encoder for data_in
    //   * 1-indexed code positions 1..CODE_LEN
    //   * parity bits sit at positions that are powers of two (1,2,4,8,...)
    //   * data bits fill the remaining positions, LSB-first
    //   * code position p maps to ecc_out[p-1]
    //   * even parity
    // ---------------------------------------------------------------
    integer pos, q, dbit;
    reg [CODE_LEN-1:0] codeword;
    always @(*) begin
        codeword = {CODE_LEN{1'b0}};
        dbit     = 0;
        // Place data bits at the non-power-of-two positions, LSB first
        for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
            if ((pos & (pos-1)) != 0) begin        // not a power of two -> data position
                if (dbit < DATA_WIDTH) begin
                    codeword[pos-1] = data_in[dbit];
                    dbit = dbit + 1;
                end
            end
        end
        // Compute parity bits (even parity) at the power-of-two positions
        for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
            if ((pos & (pos-1)) == 0) begin        // power of two -> parity position
                for (q = 1; q <= CODE_LEN; q = q + 1) begin
                    if ((q != pos) && ((q & pos) != 0))
                        codeword[pos-1] = codeword[pos-1] ^ codeword[q-1];
                end
            end
        end
        ecc_out = codeword;
    end

endmodule

module neuromorphic_array #(
    parameter NEURONS = 8,       // Number of neurons
    parameter INPUTS  = 8,       // Number of inputs
    parameter OUTPUTS = 8        // Number of outputs
) (
    input  logic [7:0] ui_in,    // Control input (ui_in[0] = update enable)
    input  logic [7:0] uio_in,   // Input data
    output logic [7:0] uo_out,   // Output data
    input  logic       clk,      // Clock
    input  logic       rst_n     // Active-low reset
);
    // Internal wires for neuron outputs
    logic [7:0] neuron_outputs [0:NEURONS-1];

    // Instantiate the neurons.  The first neuron takes the external input data;
    // each subsequent neuron takes the previous neuron's stored output, so the
    // array forms a sequential chain and uo_out reflects the last neuron.
    genvar i;
    generate
        for (i = 0; i < NEURONS; i = i + 1) begin : gen_neurons
            if (i == 0) begin : first_neuron
                single_neuron_dut u_neuron (
                    .clk    (clk),
                    .rst_n  (rst_n),
                    .control(ui_in[0]),
                    .seq_in (uio_in),
                    .seq_out(neuron_outputs[0])
                );
            end else begin : chained_neuron
                single_neuron_dut u_neuron (
                    .clk    (clk),
                    .rst_n  (rst_n),
                    .control(ui_in[0]),
                    .seq_in (neuron_outputs[i-1]),
                    .seq_out(neuron_outputs[i])
                );
            end
        end
    endgenerate

    // Combine outputs from the last neuron
    assign uo_out = neuron_outputs[NEURONS-1]; // Output from the last neuron

endmodule

module single_neuron_dut (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       control,    // Control signal
    input  logic [7:0] seq_in,     // Input sequence
    output logic [7:0] seq_out     // Output sequence
);
    // 8-bit internal neuron state
    logic [7:0] state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= 8'd0;      // reset clears the neuron
        else if (control)
            state <= seq_in;    // update with input data when control is high
        // else: retain previous state
    end

    assign seq_out = state;     // output the stored value

endmodule

module rounding #(
  parameter WIDTH = 24
)(
  input logic  [WIDTH-1:0] in_data      , // Input value for rounding
  input logic              sign    , // Indicates sign of input (1: negative, 0: positive)
  input logic              roundin , // Round bit
  input logic              stickyin, // Sticky bit for precision
  input logic  [2:0]       rm      , // Rounding mode
  output logic [WIDTH-1:0] out_data     , // Rounded output
  output logic             inexact , // Indicates precision loss
  output logic             cout    , // Carry-out_data signal
  output logic             r_up      // Indicates rounding up
);


  localparam RNE = 3'b000;
  localparam RTZ = 3'b001;
  localparam RUP = 3'b010;
  localparam RDN = 3'b011;
  localparam RMM = 3'b100;

  logic rounding_up;

  // Retained LSB pulled out of the always block (a constant bit-select inside
  // an always_* process is unsupported by some Icarus builds).
  wire in_lsb = in_data[0];

  always_comb begin
    case (rm)
      // Round to Nearest, Even: round up when the round bit is set AND either
      // the sticky bit is set or the retained LSB is odd (tie -> even).
      RNE: rounding_up = roundin & (stickyin | in_lsb);
      // Round Toward Zero: never round up (truncate).
      RTZ: rounding_up = 1'b0;
      // Round Toward +Inf: round up only for positive values with lost bits.
      RUP: rounding_up = (~sign) & (roundin | stickyin);
      // Round Toward -Inf: round up (in magnitude) only for negatives.
      RDN: rounding_up = sign & (roundin | stickyin);
      // Round to Nearest, Max Magnitude: round up whenever round bit is set.
      RMM: rounding_up = roundin;
      default: rounding_up = 1'b0; // Default to no rounding (RTZ behaviour)
    endcase
  end

  // WIDTH+1-bit sum captures the overflow carry-out.
  logic [WIDTH:0] sum;
  assign sum = {1'b0, in_data} + {{WIDTH{1'b0}}, rounding_up};

  // Output assignments
  assign out_data = sum[WIDTH-1:0];
  assign inexact  = roundin | stickyin;
  assign cout     = sum[WIDTH];
  assign r_up     = rounding_up;

endmodule

module pipelined_skid_buffer(
    input wire clock,
    input wire rst,

    input wire [3:0] data_i,
    input wire valid_i,
    output wire ready_o,
    output wire valid_o,
    output wire [3:0] data_o,
    input wire ready_i

    );

    // Internal handshake / data wires between the four pipeline stages:
    //   data_i -> skid_0 -> reg1 -> skid_2 -> reg3 -> data_o
    wire [3:0] s0_data;
    wire       s0_valid;
    wire       s0_ready;     // reg1.ready_out : downstream-ready for skid_0

    wire [3:0] r1_data;
    wire       r1_valid;
    wire       r1_ready;     // skid_2.o_ready : downstream-ready for reg1

    wire [3:0] s2_data;
    wire       s2_valid;
    wire       s2_ready;     // reg3.ready_out : downstream-ready for skid_2

    // Stage 0 : input skid buffer
    skid_buffer skid_0 (
        .clk    (clock),
        .reset  (rst),
        .i_data (data_i),
        .i_valid(valid_i),
        .o_ready(ready_o),
        .o_data (s0_data),
        .o_valid(s0_valid),
        .i_ready(s0_ready)
    );

    // Stage 1 : register
    register reg1 (
        .clk      (clock),
        .rst      (rst),
        .data_in  (s0_data),
        .valid_in (s0_valid),
        .ready_out(s0_ready),
        .valid_out(r1_valid),
        .data_out (r1_data),
        .ready_in (r1_ready)
    );

    // Stage 2 : intermediate skid buffer
    skid_buffer skid_2 (
        .clk    (clock),
        .reset  (rst),
        .i_data (r1_data),
        .i_valid(r1_valid),
        .o_ready(r1_ready),
        .o_data (s2_data),
        .o_valid(s2_valid),
        .i_ready(s2_ready)
    );

    // Stage 3 : output register
    register reg3 (
        .clk      (clock),
        .rst      (rst),
        .data_in  (s2_data),
        .valid_in (s2_valid),
        .ready_out(s2_ready),
        .valid_out(valid_o),
        .data_out (data_o),
        .ready_in (ready_i)
    );

endmodule

module register(
    input clk,
    input rst,

    input [3:0] data_in,
    input valid_in,
    output ready_out,
    output valid_out,
    output [3:0] data_out,
    input  ready_in
    );

    reg [3:0] mem;
    reg       data_present;

    // Accept new data when empty, or when the currently-held beat is being
    // consumed by the downstream this cycle (full-throughput elastic stage).
    assign ready_out = ~data_present | ready_in;
    assign valid_out = data_present;
    assign data_out  = mem;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mem          <= 4'b0;
            data_present <= 1'b0;
        end else begin
            if (valid_in && ready_out) begin
                mem          <= data_in;
                data_present <= 1'b1;
            end else if (ready_in) begin
                data_present <= 1'b0;
            end
        end
    end

endmodule


module skid_buffer(

input  clk,
input  reset ,

input  [3:0]i_data,
input  i_valid,
output o_ready,

output [3:0]o_data,
output o_valid,
input  i_ready

);

    reg [3:0] data_reg;   // single-beat skid register
    reg       buffer;     // 1 => data_reg holds a stalled beat

    // Ready is purely a function of our own occupancy (breaks the
    // ready->valid->ready combinational loop across stages).
    assign o_ready = ~buffer;
    // When holding a beat, present it; otherwise pass the input through
    // combinationally (zero-latency in the common non-stall case).
    assign o_valid = buffer ? 1'b1     : i_valid;
    assign o_data  = buffer ? data_reg : i_data;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            buffer   <= 1'b0;
            data_reg <= 4'b0;
        end else begin
            if (!buffer) begin
                // empty: absorb the beat only if downstream stalls while a
                // valid input is presented (it would otherwise be lost).
                if (i_valid && !i_ready) begin
                    buffer   <= 1'b1;
                    data_reg <= i_data;
                end
            end else begin
                // full: release the held beat when downstream becomes ready.
                if (i_ready) begin
                    buffer <= 1'b0;
                end
            end
        end
    end

endmodule

`timescale 1ns / 1ps
module sync_serial_communication_tx_rx(
    input clk,                     // Clock signal
    input reset_n,                 // Active low reset signal
    input [2:0] sel,               // Selection signal for TX block
    input [63:0] data_in,          // 64-bit data input for TX block
    output [63:0] data_out,        // 64-bit data output from RX block
    output done                    // Done signal indicating completion
);

// Internal signals
wire tx_out;                       // Serial data output from TX block
wire tx_done;                      // Done signal from TX block
wire serial_clk_in;                // Serial clock generated by TX block

// Instantiate the TX block
tx_block uut_tx_block (
    .clk(clk),                     // Clock input to TX block
    .reset_n(reset_n),             // Reset input to TX block
    .data_in(data_in),             // 64-bit data input to TX block
    .sel(sel),                     // Selection signal to TX block
    .serial_out(tx_out),           // Serial data output from TX block
    .done(tx_done),                // Done signal from TX block
    .serial_clk(serial_clk_in)     // Serial clock output from TX block
);

// Instantiate the RX block
rx_block uut_rx_block (
    .clk(clk),                     // Clock input to RX block
    .serial_clk(serial_clk_in),    // Serial clock input to RX block
    .reset_n(reset_n),             // Reset input to RX block
    .sel(sel),                     // Selection signal to RX block
    .data_in(tx_out),              // Serial data input to RX block
    .data_out(data_out),           // 64-bit data output from RX block
    .done(done)                    // Done signal from RX block
);

endmodule

///// tx_block
module tx_block(
    input clk,               // Clock input
    input reset_n,           // Active-low reset input
    input [63:0] data_in,    // 64-bit parallel data input
    input [2:0] sel,         // Selection input to choose data width
    output reg serial_out,   // Serial data output
    output reg done,         // Done signal indicating completion of transmission
    output serial_clk        // Clock for serial data transmission
);

// Internal registers
reg [63:0] data_reg;         // Register to hold the data being transmitted
reg [6:0] bit_count;         // Counter to track number of bits to transmit
reg [6:0] reg_count;         // Register for counting bits for serial clock control
reg [6:0] temp_reg_count;    // Temporary register to track reg_count

// Area optimization : all TX sequential logic shares the same clock/reset and
// is merged into a single always block (minimizing the number of always blocks)
// while preserving the exact register semantics and functional behavior.
always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        data_reg       <= 64'h0;
        bit_count      <= 7'h0;
        reg_count      <= 7'h0;
        temp_reg_count <= 7'h0;
        serial_out     <= 1'b0;
        done           <= 1'b0;
    end else begin
        // ----- data selection / shift -----
        if (done == 1'b1) begin
            case (sel)
                3'b000: begin
                    data_reg  <= 64'h0;
                    bit_count <= 7'd0;
                end
                3'b001: begin
                    data_reg  <= {56'h0, data_in[7:0]};
                    bit_count <= 7'd7;
                end
                3'b010: begin
                    data_reg  <= {48'h0, data_in[15:0]};
                    bit_count <= 7'd15;
                end
                3'b011: begin
                    data_reg  <= {32'h0, data_in[31:0]};
                    bit_count <= 7'd31;
                end
                3'b100: begin
                    data_reg  <= data_in[63:0];
                    bit_count <= 7'd63;
                end
                default: begin
                    data_reg  <= 64'h0;
                    bit_count <= 7'h0;
                end
            endcase
        end else if (bit_count > 7'h0) begin
            data_reg  <= data_reg >> 1;
            bit_count <= bit_count - 1'b1;
        end
        reg_count <= bit_count;

        // ----- serial-clock gating counter -----
        temp_reg_count <= reg_count;

        // ----- serial output -----
        if (reg_count > 7'h0 || bit_count > 7'h0) begin
            serial_out <= data_reg[0];
        end

        // ----- done flag -----
        if (bit_count == 7'h0) begin
            done <= 1'b1;
        end else begin
            done <= 1'b0;
        end
    end
end

// Generate serial clock based on temp_reg_count
assign  #1 serial_clk = clk && (temp_reg_count !== 7'd0) ;  // To avoid Simulator issue

endmodule

///// rx_block
module rx_block(
    input wire clk,  			    // clock input
    input wire reset_n,			    // Active-low reset
    input wire data_in,			    // Serial input data
    input wire serial_clk,		    // Clock signal for serial data
    input wire [2:0] sel,           // Selection output to choose data width
    output reg done,			    // Done signal to indicate data reception complete
    output reg [63:0] data_out  	// Parallel output data after serial operation

);

    // Internal registers
    reg [63:0] data_reg;		    // Register to hold incoming serial data
    reg [7:0] bit_count;		    // Counter for the number of bits received
    reg [7:0] count;			    // General purpose counter to sync with bit_count


    // Sequential logic block to capture serial data on the rising edge of serial_clk
    always @(posedge serial_clk or negedge  reset_n) begin
        if (!reset_n) begin		    // Reset all registers on reset_n (active low)
            data_reg <= 64'h0;		// Clear the data register
            bit_count <= 8'd0;		// Clear the bit counter
        end else begin
            if(done == 1'b1) begin                   // If done signal is asserted, reset the bit counter and data register
                bit_count <= 8'b0;
                data_reg <= 64'h0;
            end
            else begin
                 bit_count <= bit_count;			 // Maintain the bit counter if not done
            end
                bit_count <= bit_count + 1'b1;	     // Increment bit count
                data_reg[bit_count]<=data_in; 	     // Store the incoming data bit
           end
    end

    // Sequential logic block to monitor the completion of data reception and update outputs
    always@(posedge clk or negedge reset_n) begin
    	if(!reset_n) begin			 	             // Reset all registers on reset_n (active low)
    	   count <= 8'd0;					         // Clear the bit counter
           done <= 1'b0;					         // Deassert done signal
           data_out <= 64'h0;					     // Clear the output data register
        end
        else if(count >= bit_count && count != 8'd0) begin       // When the count reaches the bit_count, assert done and output the data
           done <= 1'b1;				             // Set done to indicate transmission complete
           case(sel)
            3'b000:begin
                data_out <= 64'h0;                   // no bits to transmit
            end
            3'b001:begin
                data_out <= {56'h0,data_reg};        // 8 bits of data_reg
            end
            3'b010:begin
                data_out <= {48'h0,data_reg};        // 16 bits of data_reg
            end
            3'b011:begin
                data_out <= {32'h0,data_reg};        // 32 bits of data_reg
            end
            3'b100:begin
                data_out <= data_reg;                // 64 bits of data_reg
            end
            default:begin
                data_out <= 64'h0;                   // no bits to transmit, default state
            end
           endcase
        end
        else if(bit_count > 8'd0) begin              // If bits are being received, increment the count and deassert done
           count <= count+ 1'b1;				     // Increment count
           done <= 1'b0;					         // Clear done signal while receiving
        end
        else begin  			                     // If no bits have been received, reset the count and deassert done
           count <= 8'd0;					         // Reset count
           done <= 1'b0;					         // Clear done signal
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0]  state, next_state;

    localparam integer IW = $clog2(N);

    // Insertion sort indexing
    reg [IW:0]          i;    // Outer loop index (0..N)
    reg signed [IW+1:0] j;    // Inner loop index (signed to reach -1)
    reg [WIDTH-1:0]     key;  // Element currently being inserted

    // Sub-phases within the SORTING state
    localparam P_ACCESS     = 2'd0; // access the element to be sorted
    localparam P_SHIFT      = 2'd1; // shift larger elements up (and detect complete)
    localparam P_INSERT     = 2'd2; // insert the element at the found spot
    localparam P_DETECT_ALL = 2'd3; // detect all elements sorted
    reg [1:0] phase;

    // FSM: Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = SORTING;
            end
            SORTING: begin
                if (phase == P_DETECT_ALL)
                    next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    integer k, m;

    // FSM: Output and datapath updates
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            i     <= 0;
            j     <= 0;
            key   <= 0;
            phase <= P_ACCESS;
            done  <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load the array from in_data (1 cycle to set up start conditions)
                        for (k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        i     <= 1;          // insertion sort begins at index 1
                        j     <= 0;
                        phase <= P_ACCESS;
                    end
                end

                SORTING: begin
                    case (phase)
                        P_ACCESS: begin
                            // Access the element to be sorted
                            if (i < N) begin
                                key   <= array[i];
                                j     <= $signed({1'b0, i}) - 1;
                                phase <= P_SHIFT;
                            end else begin
                                phase <= P_DETECT_ALL;
                            end
                        end

                        P_SHIFT: begin
                            // One shift per cycle; the failing check is the
                            // "detect iterations complete" cycle.
                            if (j >= 0 && array[j] > key) begin
                                array[j+1] <= array[j];
                                j          <= j - 1;
                            end else begin
                                phase <= P_INSERT;
                            end
                        end

                        P_INSERT: begin
                            // Insert the element at the spot found
                            array[j+1] <= key;
                            if ((i + 1) >= N) begin
                                i     <= i + 1;
                                phase <= P_DETECT_ALL;
                            end else begin
                                i     <= i + 1;
                                phase <= P_ACCESS;
                            end
                        end

                        P_DETECT_ALL: begin
                            // 1 cycle to detect that all elements are sorted
                            phase <= P_ACCESS;
                        end

                        default: begin
                            phase <= P_ACCESS;
                        end
                    endcase
                end

                DONE: begin
                    // 1 cycle to output the sorted array and assert done
                    done <= 1;
                    for (m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                end

                default: begin
                end
            endcase
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    out_data = 0;
  end

endmodule

module brent_kung_adder(
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic carry_in,
    output logic [31:0] sum,
    output logic carry_out
);
    logic [31:0] P1, G1;
    logic [32:1] C;
    logic [15:0] G2, P2;
    logic [7:0] G3, P3;
    logic [3:0] G4, P4;
    logic [1:0] G5, P5;
    logic G6, P6;

    assign P1 = a ^ b;
    assign G1 = a & b;

    genvar i;
    // Bug fix: group generate/propagate for adjacent bit pairs (i+1, i)
    // must index the correct bits, not the constant bit 0.
    generate
        for(i=0; i<=30; i=i+2) begin: second_stage
            assign G2[i/2] = G1[i+1] | (P1[i+1] & G1[i]);
            assign P2[i/2] = P1[i+1] & P1[i];
        end
    endgenerate

    generate
        for(i=0; i<=14; i=i+2) begin: third_stage
            assign G3[i/2] = G2[i+1] | (P2[i+1] & G2[i]);
            assign P3[i/2] = P2[i+1] & P2[i];
        end
    endgenerate

    generate
        for(i=0; i<=6; i=i+2) begin: fourth_stage
            assign G4[i/2] = G3[i+1] | (P3[i+1] & G3[i]);
            assign P4[i/2] = P3[i+1] & P3[i];
        end
    endgenerate

    generate
        for(i=0; i<=2; i=i+2) begin: fifth_stage
            assign G5[i/2] = G4[i+1] | (P4[i+1] & G4[i]);
            assign P5[i/2] = P4[i+1] & P4[i];
        end
    endgenerate

    assign G6 = G5[1] | (P5[1] & G5[0]);
    assign P6 = P5[1] & P5[0];

    assign C[1] = G1[0] | (P1[0] & carry_in);
    assign C[2] = G2[0] | (P2[0] & carry_in);
    assign C[4] = G3[0] | (P3[0] & carry_in);
    assign C[8] = G4[0] | (P4[0] & carry_in);
    assign C[16] = G5[0] | (P5[0] & carry_in);
    assign C[32] = G6 | (P6 & carry_in);

    assign C[3] = G1[2] | (P1[2] & C[2]);
    assign C[5] = G1[4] | (P1[4] & C[4]);
    assign C[6] = G2[2] | (P2[2] & C[4]);
    assign C[7] = G1[6] | (P1[6] & C[6]);

    assign C[9] = G1[8] | (P1[8] & C[8]);
    assign C[10] = G2[4] | (P2[4] & C[8]);
    assign C[11] = G1[10] | (P1[10] & C[10]);
    assign C[12] = G3[2] | (P3[2] & C[8]);
    assign C[13] = G1[12] | (P1[12] & C[12]);
    assign C[14] = G2[6] | (P2[6] & C[12]);
    assign C[15] = G1[14] | (P1[14] & C[14]);

    assign C[17] = G1[16] | (P1[16] & C[16]);
    assign C[18] = G2[8] | (P2[8] & C[16]);
    assign C[19] = G1[18] | (P1[18] & C[18]);
    assign C[20] = G3[4] | (P3[4] & C[16]);
    assign C[21] = G1[20] | (P1[20] & C[20]);
    assign C[22] = G2[10] | (P2[10] & C[20]);
    assign C[23] = G1[22] | (P1[22] & C[22]);
    assign C[24] = G4[2] | (P4[2] & C[16]);
    assign C[25] = G1[24] | (P1[24] & C[24]);
    assign C[26] = G2[12] | (P2[12] & C[24]);
    assign C[27] = G1[26] | (P1[26] & C[26]);
    assign C[28] = G3[6] | (P3[6] & C[24]);
    assign C[29] = G1[28] | (P1[28] & C[28]);
    assign C[30] = G2[14] | (P2[14] & C[28]);
    assign C[31] = G1[30] | (P1[30] & C[30]);

    // Bug fix: sum bit = half-sum XOR carry-into-that-bit (was OR).
    // Carry-in vector is {C[31:1], carry_in} (bit0 carry-in = carry_in).
    assign sum = P1 ^ {C[31:1], carry_in};
    assign carry_out = C[32];

endmodule

module axi_register #(
    parameter ADDR_WIDTH = 32,   // >= 12
    parameter DATA_WIDTH = 32    // >= 8
) (
    // Clock / reset
    input  wire                    clk_i,
    input  wire                    rst_n_i,      // active-low async reset

    // Write address channel
    input  wire [ADDR_WIDTH-1:0]   awaddr_i,
    input  wire                    awvalid_i,
    output reg                     awready_o,

    // Write data channel
    input  wire [DATA_WIDTH-1:0]   wdata_i,
    input  wire                    wvalid_i,
    input  wire [(DATA_WIDTH/8)-1:0] wstrb_i,
    output reg                     wready_o,

    // Write response channel
    output reg  [1:0]              bresp_o,
    output reg                     bvalid_o,
    input  wire                    bready_i,

    // Read address channel
    input  wire [ADDR_WIDTH-1:0]   araddr_i,
    input  wire                    arvalid_i,
    output reg                     arready_o,

    // Read data channel
    output reg  [DATA_WIDTH-1:0]   rdata_o,
    output reg                     rvalid_o,
    output reg  [1:0]              rresp_o,
    input  wire                    rready_i,

    // Application-side signals
    output wire [19:0]             beat_o,
    output wire                    start_o,
    output wire                    writeback_o,
    input  wire                    done_i
);

    // ------------------------------------------------------------------
    // Register offsets and constants
    // ------------------------------------------------------------------
    localparam [11:0] BEAT_ADDR  = 12'h100;
    localparam [11:0] START_ADDR = 12'h200;
    localparam [11:0] DONE_ADDR  = 12'h300;
    localparam [11:0] WB_ADDR    = 12'h400;
    localparam [11:0] ID_ADDR    = 12'h500;
    localparam [31:0] ID_VALUE   = 32'h0001_0001;

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Registers
    // ------------------------------------------------------------------
    reg [19:0] beat_reg;
    reg        start_reg;
    reg        writeback_reg;
    reg        done_reg;

    assign beat_o      = beat_reg;
    assign start_o     = start_reg;
    assign writeback_o = writeback_reg;

    // ------------------------------------------------------------------
    // Write channel FSM
    // ------------------------------------------------------------------
    localparam W_IDLE = 2'd0;
    localparam W_DATA = 2'd1;
    localparam W_RESP = 2'd2;
    reg [1:0]              wstate;
    reg [11:0]            aw_lat;   // latched write address (low 12 bits)

    wire full_strobe = &wstrb_i;    // all byte-enables set -> update

    // clear-done request qualifier (write to DONE with lsb set on a full write)
    wire done_clear = (wstate == W_DATA) && wvalid_i && wready_o &&
                      (aw_lat == DONE_ADDR) && full_strobe && wdata_i[0];

    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            wstate        <= W_IDLE;
            awready_o     <= 1'b0;
            wready_o      <= 1'b0;
            bvalid_o      <= 1'b0;
            bresp_o       <= RESP_OKAY;
            aw_lat        <= 12'd0;
            beat_reg      <= 20'd0;
            start_reg     <= 1'b0;
            writeback_reg <= 1'b0;
        end else begin
            case (wstate)
                W_IDLE: begin
                    bvalid_o  <= 1'b0;
                    awready_o <= 1'b1;   // ready to accept a write address
                    wready_o  <= 1'b0;
                    if (awvalid_i && awready_o) begin
                        aw_lat    <= awaddr_i[11:0];
                        awready_o <= 1'b0;
                        wstate    <= W_DATA;
                    end
                end

                W_DATA: begin
                    wready_o <= 1'b1;    // ready to accept the write data
                    if (wvalid_i && wready_o) begin
                        wready_o <= 1'b0;
                        // Default OKAY, updated below on error conditions
                        bresp_o  <= RESP_OKAY;
                        case (aw_lat)
                            BEAT_ADDR: begin
                                if (full_strobe) beat_reg <= wdata_i[19:0];
                                bresp_o <= RESP_OKAY;
                            end
                            START_ADDR: begin
                                if (full_strobe) start_reg <= wdata_i[0];
                                bresp_o <= RESP_OKAY;
                            end
                            DONE_ADDR: begin
                                // done_reg cleared in the done_reg block
                                bresp_o <= RESP_OKAY;
                            end
                            WB_ADDR: begin
                                if (full_strobe) writeback_reg <= wdata_i[0];
                                bresp_o <= RESP_OKAY;
                            end
                            ID_ADDR:  bresp_o <= RESP_SLVERR; // read-only
                            default:  bresp_o <= RESP_SLVERR; // undefined address
                        endcase
                        bvalid_o <= 1'b1;
                        wstate   <= W_RESP;
                    end
                end

                W_RESP: begin
                    if (bready_i) begin
                        bvalid_o <= 1'b0;
                        wstate   <= W_IDLE;
                    end
                end

                default: wstate <= W_IDLE;
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Done status: set by done_i, cleared by SW write to DONE (lsb=1)
    // ------------------------------------------------------------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i)
            done_reg <= 1'b0;
        else if (done_clear)
            done_reg <= 1'b0;
        else if (done_i)
            done_reg <= 1'b1;
    end

    // ------------------------------------------------------------------
    // Read channel FSM
    // ------------------------------------------------------------------
    localparam R_IDLE = 1'b0;
    localparam R_DATA = 1'b1;
    reg        rstate;
    reg [11:0] ar_lat;

    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            rstate    <= R_IDLE;
            arready_o <= 1'b0;
            rvalid_o  <= 1'b0;
            rresp_o   <= RESP_OKAY;
            rdata_o   <= {DATA_WIDTH{1'b0}};
            ar_lat    <= 12'd0;
        end else begin
            case (rstate)
                R_IDLE: begin
                    rvalid_o  <= 1'b0;
                    arready_o <= 1'b1;
                    if (arvalid_i && arready_o) begin
                        ar_lat    <= araddr_i[11:0];
                        arready_o <= 1'b0;
                        rstate    <= R_DATA;
                        // Prepare read data / response for the accepted address
                        case (araddr_i[11:0])
                            BEAT_ADDR: begin
                                rdata_o <= {{(DATA_WIDTH-20){1'b0}}, beat_reg};
                                rresp_o <= RESP_OKAY;
                            end
                            START_ADDR: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, start_reg};
                                rresp_o <= RESP_OKAY;
                            end
                            DONE_ADDR: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, done_reg};
                                rresp_o <= RESP_OKAY;
                            end
                            WB_ADDR: begin
                                rdata_o <= {{(DATA_WIDTH-1){1'b0}}, writeback_reg};
                                rresp_o <= RESP_OKAY;
                            end
                            ID_ADDR: begin
                                rdata_o <= ID_VALUE;   // auto width-adjusted to DATA_WIDTH
                                rresp_o <= RESP_OKAY;
                            end
                            default: begin
                                rdata_o <= {DATA_WIDTH{1'b0}};
                                rresp_o <= RESP_SLVERR;
                            end
                        endcase
                        rvalid_o <= 1'b1;
                    end
                end

                R_DATA: begin
                    if (rready_i) begin
                        rvalid_o <= 1'b0;
                        rstate   <= R_IDLE;
                    end
                end

                default: rstate <= R_IDLE;
            endcase
        end
    end

endmodule

module binary_multiplier #(
    parameter WIDTH = 32  // Set the width of inputs (min 1)
)(
    input  logic               clk,        // Clock
    input  logic               rst_n,      // Active-low asynchronous reset
    input  logic [WIDTH-1:0]   A,          // Input A
    input  logic [WIDTH-1:0]   B,          // Input B
    input  logic               valid_in,   // Indicates when inputs are valid
    output logic [2*WIDTH-1:0] Product,    // Output Product
    output logic               valid_out   // Output valid (1-cycle pulse)
);

    // Sequential shift-and-add multiplier.
    // Latency contract = WIDTH + 2 cycles:
    //   1 cycle  : latch A/B and assert start
    //   WIDTH    : accumulate one partial product per cycle
    //   1 cycle  : register Product and pulse valid_out
    logic               start;              // busy flag, gates new valid_in
    logic [WIDTH-1:0]   a_reg;              // latched multiplier
    logic [2*WIDTH-1:0] b_ext;              // latched multiplicand, product-width
    logic [2*WIDTH-1:0] acc;                // running accumulator
    logic [31:0]        cnt;                // step counter

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            start     <= 1'b0;
            a_reg     <= '0;
            b_ext     <= '0;
            acc       <= '0;
            cnt       <= '0;
            Product   <= '0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;              // default-low, self-clearing pulse
            if (!start) begin
                if (valid_in) begin
                    a_reg <= A;
                    b_ext <= {{WIDTH{1'b0}}, B};
                    acc   <= '0;
                    cnt   <= '0;
                    start <= 1'b1;
                end
            end else begin
                if (cnt < WIDTH) begin
                    if (a_reg[cnt]) acc <= acc + (b_ext << cnt);
                    cnt <= cnt + 32'd1;
                end else begin
                    // cnt == WIDTH : final register/pulse cycle
                    Product   <= acc;
                    valid_out <= 1'b1;
                    start     <= 1'b0;
                    cnt       <= '0;
                end
            end
        end
    end

endmodule

module compression_engine (
  input   logic        clk,
  input   logic        reset,
  input   logic [23:0] num_i,
  output  logic [11:0] mantissa_o,
  output  logic [3:0]  exponent_o
);

  // --------------------------------------------------------
  // Internal wires and registers
  // --------------------------------------------------------
  logic [23:12] exp_oh;         // One-hot encoded exponent
  logic [3:0]   exp_bin;        // Binary exponent
  logic [3:0]   exponent;       // Adjusted exponent
  logic [11:0]  mantissa;       // Mantissa

  // --------------------------------------------------------
  // One-Hot Encoding of the Exponent
  // --------------------------------------------------------
  assign exp_oh[23] = num_i[23];

  // One-hot encoding of `exp_oh` : exp_oh[i] = num_i[i] & ~|num_i[23:i+1]
  genvar gi;
  generate
    for (gi = 12; gi <= 22; gi = gi + 1) begin : oh_gen
      assign exp_oh[gi] = num_i[gi] & ~(|num_i[23:gi+1]);
    end
  endgenerate

  // Use the `onehot_to_bin` module to convert one-hot to binary exponent
  onehot_to_bin #(
    .ONE_HOT_W(12),
    .BIN_W(4)
  ) exp_oh_bin (
    .oh_vec_i(exp_oh),
    .bin_vec_o(exp_bin)
  );

  assign exponent = (|exp_oh) ? exp_bin + 4'h1 : exp_bin;

  // --------------------------------------------------------
  // Mantissa Extraction Logic
  // --------------------------------------------------------
  // If exponent == 0, mantissa = num_i[11:0].
  // Otherwise, the first set bit (from MSB) is at bit index (exponent+11);
  // the 12 most-significant bits starting there are num_i[exponent+11 : exponent]
  // which equals the low 12 bits of (num_i >> exponent).
  always @(*) begin
    if (exponent == 4'h0)
      mantissa = num_i[11:0];
    else
      mantissa = num_i >> exponent;
  end

  // --------------------------------------------------------
  // Output assignments
  // --------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      exponent_o <= 4'd0;
      mantissa_o <= 12'd0;
    end else begin
      exponent_o <= exponent;
      mantissa_o <= mantissa;
    end
  end

endmodule

module onehot_to_bin #(
  parameter ONE_HOT_W = 32,  // Width of the one-hot input
  parameter BIN_W     = 5    // Width of the binary output
)(
  input   wire [ONE_HOT_W-1:0]  oh_vec_i,  // One-hot encoded input
  output  logic [BIN_W-1:0]     bin_vec_o  // Binary encoded output
);

  integer i;

  // Priority encode: return the index of the set bit in the one-hot vector.
  always @(*) begin
    bin_vec_o = {BIN_W{1'b0}};
    for (i = 0; i < ONE_HOT_W; i = i + 1) begin
      if (oh_vec_i[i])
        bin_vec_o = i[BIN_W-1:0];
    end
  end

endmodule

module apb_controller (
    input  wire        clk,
    input  wire        reset_n,      // active-low async reset
    // event triggers (single-cycle pulses, priority a > b > c)
    input  wire        select_a_i,
    input  wire        select_b_i,
    input  wire        select_c_i,
    input  wire [31:0] addr_a_i,
    input  wire [31:0] data_a_i,
    input  wire [31:0] addr_b_i,
    input  wire [31:0] data_b_i,
    input  wire [31:0] addr_c_i,
    input  wire [31:0] data_c_i,
    input  wire        apb_pready_i,
    // APB master outputs (write only)
    output reg         apb_psel_o,
    output reg         apb_penable_o,
    output reg         apb_pwrite_o,
    output reg  [31:0] apb_paddr_o,
    output reg  [31:0] apb_pwdata_o
);

    localparam [1:0] IDLE   = 2'd0,
                     SETUP  = 2'd1,
                     ACCESS = 2'd2;

    reg [1:0]  state;
    reg [31:0] addr_reg;
    reg [31:0] data_reg;
    reg [3:0]  timeout_cnt;

    // -----------------------------------------------------------------
    // Sequential: state, captured address/data, timeout counter
    // -----------------------------------------------------------------
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state       <= IDLE;
            addr_reg    <= 32'd0;
            data_reg    <= 32'd0;
            timeout_cnt <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    timeout_cnt <= 4'd0;
                    // capture selected event by priority a > b > c
                    if (select_a_i) begin
                        addr_reg <= addr_a_i;
                        data_reg <= data_a_i;
                        state    <= SETUP;
                    end else if (select_b_i) begin
                        addr_reg <= addr_b_i;
                        data_reg <= data_b_i;
                        state    <= SETUP;
                    end else if (select_c_i) begin
                        addr_reg <= addr_c_i;
                        data_reg <= data_c_i;
                        state    <= SETUP;
                    end
                end

                SETUP: begin
                    timeout_cnt <= 4'd0;
                    state       <= ACCESS;
                end

                ACCESS: begin
                    if (apb_pready_i) begin
                        // successful transfer -> return to IDLE
                        timeout_cnt <= 4'd0;
                        state       <= IDLE;
                    end else if (timeout_cnt >= 4'd15) begin
                        // timeout -> abort, return to IDLE
                        timeout_cnt <= 4'd0;
                        state       <= IDLE;
                    end else begin
                        timeout_cnt <= timeout_cnt + 4'd1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    // -----------------------------------------------------------------
    // Combinational APB output generation (correct SETUP/ACCESS phasing)
    // -----------------------------------------------------------------
    always @(*) begin
        // IDLE defaults: all outputs deasserted / zeroed
        apb_psel_o    = 1'b0;
        apb_penable_o = 1'b0;
        apb_pwrite_o  = 1'b0;
        apb_paddr_o   = 32'd0;
        apb_pwdata_o  = 32'd0;
        case (state)
            SETUP: begin
                apb_psel_o    = 1'b1;
                apb_pwrite_o  = 1'b1;
                apb_penable_o = 1'b0;
                apb_paddr_o   = addr_reg;
                apb_pwdata_o  = data_reg;
            end
            ACCESS: begin
                apb_psel_o    = 1'b1;
                apb_pwrite_o  = 1'b1;
                apb_penable_o = 1'b1;
                apb_paddr_o   = addr_reg;
                apb_pwdata_o  = data_reg;
            end
            default: ; // IDLE keeps defaults
        endcase
    end

endmodule

/*
Galois field (2^8) matrix-based encryption/decryption system using AES's polynomial to perform galois field operations
*/

module galois_encryption #(
    parameter NBW_DATA = 'd128,
    parameter NBW_KEY  = 'd32
) (
    input  logic                clk,
    input  logic                rst_async_n,
    input  logic                i_encrypt,
    input  logic                i_valid,
    input  logic [NBW_DATA-1:0] i_data,
    input  logic                i_update_key,
    input  logic [NBW_KEY-1:0]  i_key,
    output logic                o_valid,
    output logic [NBW_DATA-1:0] o_data
);

// ----------------------------------------
// - Internal Parameters
// ----------------------------------------
localparam LATENCY  = 'd3;
localparam NBW_WORD = 'd8;
localparam MOD_POLY = 8'h1B;
localparam LINES    = 'd4;
localparam COLUMNS  = 'd4;

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
logic [LATENCY:0]    valid_ff;
logic [NBW_KEY-1:0]  key_ff;
logic [NBW_WORD-1:0] data_in_ff      [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes2_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes3_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes9_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesB_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesD_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesE_nx [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_out_nx     [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes2_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes3_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes9_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesB_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesD_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimesE_ff [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_out_ff     [LINES][COLUMNS];

logic [NBW_WORD-1:0] data_xtimes2 [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes4 [LINES][COLUMNS];
logic [NBW_WORD-1:0] data_xtimes8 [LINES][COLUMNS];

// ----------------------------------------
// - Control registers
// ----------------------------------------
always_ff @(posedge clk or negedge rst_async_n) begin : ctrl_regs
    if (!rst_async_n) begin
        valid_ff <= 0;
        key_ff   <= 0;
    end else begin
        valid_ff[0]         <= i_valid;
        valid_ff[LATENCY:1] <= valid_ff[LATENCY-1:0];
        if(i_update_key) begin
            key_ff <= i_key;
        end
    end
end

// ----------------------------------------
// - Data registers
// ----------------------------------------
always_ff @(posedge clk) begin : data_regs
    for (int line = 0; line < LINES; line++) begin
        for (int column = 0; column < COLUMNS; column++) begin
            if(i_valid) begin
                if(i_encrypt) begin
                    data_in_ff[line][column] <= i_data[NBW_DATA-1-(line*NBW_WORD + column*NBW_WORD*LINES)-:NBW_WORD];
                end else begin
                    data_in_ff[line][column] <= i_data[NBW_DATA-1-(line*NBW_WORD + column*NBW_WORD*LINES)-:NBW_WORD] ^ key_ff[NBW_KEY-line*NBW_WORD-1-:NBW_WORD];            
                end
            end

            data_xtimes2_ff[line][column] <= data_xtimes2_nx[line][column];
            data_xtimes3_ff[line][column] <= data_xtimes3_nx[line][column];
            data_xtimes9_ff[line][column] <= data_xtimes9_nx[line][column];
            data_xtimesB_ff[line][column] <= data_xtimesB_nx[line][column];
            data_xtimesD_ff[line][column] <= data_xtimesD_nx[line][column];
            data_xtimesE_ff[line][column] <= data_xtimesE_nx[line][column];

            if(valid_ff[1]) begin
                data_out_ff[line][column] <= data_out_nx[line][column];
            end
        end
    end
end

// ----------------------------------------
// - Intermediary steps
// ----------------------------------------

// Calculate GF(2^8) multiplication by 2, 4 and 8
always_comb begin : multiply_gf2_4_8
    for (int line = 0; line < LINES; line++) begin
        for (int column = 0; column < COLUMNS; column++) begin
            data_xtimes2[line][column] = (data_in_ff[line][column]  << 1) ^ (data_in_ff[line][column][7]  ? MOD_POLY : 8'h00);
            data_xtimes4[line][column] = (data_xtimes2[line][column] << 1) ^ (data_xtimes2[line][column][7] ? MOD_POLY : 8'h00);
            data_xtimes8[line][column] = (data_xtimes4[line][column] << 1) ^ (data_xtimes4[line][column][7] ? MOD_POLY : 8'h00);
        end
    end
end

// Calculate GF(2^8) multiplications by the values in the polynomial
always_comb begin : multiply_gf
    for (int line = 0; line < LINES; line++) begin
        for (int column = 0; column < COLUMNS; column++) begin
            data_xtimes2_nx[line][column] = data_xtimes2[line][column];
            if(i_encrypt) begin
                data_xtimes3_nx[line][column] = data_xtimes2[line][column] ^ data_in_ff[line][column];
                data_xtimes9_nx[line][column] = data_xtimes9_ff[line][column];
                data_xtimesB_nx[line][column] = data_xtimesB_ff[line][column];
                data_xtimesD_nx[line][column] = data_xtimesD_ff[line][column];
                data_xtimesE_nx[line][column] = data_xtimesE_ff[line][column];
            end else begin
                data_xtimes3_nx[line][column] = data_xtimes3_ff[line][column];
                data_xtimes9_nx[line][column] = data_xtimes8[line][column] ^ data_in_ff[line][column];
                data_xtimesB_nx[line][column] = data_xtimes8[line][column] ^ data_xtimes2[line][column] ^ data_in_ff  [line][column];
                data_xtimesD_nx[line][column] = data_xtimes8[line][column] ^ data_xtimes4[line][column] ^ data_in_ff  [line][column];
                data_xtimesE_nx[line][column] = data_xtimes8[line][column] ^ data_xtimes4[line][column] ^ data_xtimes2[line][column];
            end
        end
    end
end

// Calculate output matrix
always_comb begin : out_matrix
    if(i_encrypt) begin
        for (int column = 0; column < COLUMNS; column++) begin
            data_out_nx[0][column] = data_xtimes2_ff[0][column] ^ data_xtimes3_ff[1][column] ^ data_in_ff[2][column] ^ data_in_ff[3][column];
            data_out_nx[1][column] = data_xtimes2_ff[1][column] ^ data_xtimes3_ff[2][column] ^ data_in_ff[3][column] ^ data_in_ff[0][column];
            data_out_nx[2][column] = data_xtimes2_ff[2][column] ^ data_xtimes3_ff[3][column] ^ data_in_ff[0][column] ^ data_in_ff[1][column];
            data_out_nx[3][column] = data_xtimes2_ff[3][column] ^ data_xtimes3_ff[0][column] ^ data_in_ff[1][column] ^ data_in_ff[2][column];
        end
    end else begin
        for (int column = 0; column < COLUMNS; column++) begin
            data_out_nx[0][column] = data_xtimesE_ff[0][column] ^ data_xtimesB_ff[1][column] ^ data_xtimesD_ff[2][column] ^ data_xtimes9_ff[3][column];
            data_out_nx[1][column] = data_xtimesE_ff[1][column] ^ data_xtimesB_ff[2][column] ^ data_xtimesD_ff[3][column] ^ data_xtimes9_ff[0][column];
            data_out_nx[2][column] = data_xtimesE_ff[2][column] ^ data_xtimesB_ff[3][column] ^ data_xtimesD_ff[0][column] ^ data_xtimes9_ff[1][column];
            data_out_nx[3][column] = data_xtimesE_ff[3][column] ^ data_xtimesB_ff[0][column] ^ data_xtimesD_ff[1][column] ^ data_xtimes9_ff[2][column];
        end
    end
end

// ----------------------------------------
// - Assign outputs
// ----------------------------------------

// Map output values from lines x columns to a single dimension
always_comb begin : out_mapping
    if(valid_ff[LATENCY-1]) begin
        for (int line = 0; line < LINES; line++) begin
            for (int column = 0; column < COLUMNS; column++) begin
                if(i_encrypt) begin
                    o_data[NBW_DATA-(line*NBW_WORD + column*NBW_WORD*LINES)-1-:NBW_WORD] = data_out_ff[line][column] ^ key_ff[NBW_KEY-line*NBW_WORD-1-:NBW_WORD];
                end else begin
                    o_data[NBW_DATA-(line*NBW_WORD + column*NBW_WORD*LINES)-1-:NBW_WORD] = data_out_ff[line][column];
                end
            end
        end
    end else begin
        o_data = 0;
    end
end

assign o_valid = valid_ff[LATENCY-1];

endmodule : galois_encryption

module hill_cipher (
    input  wire        clk,        // Clock
    input  wire        reset,      // Asynchronous reset (active high)
    input  wire        start,      // Start encryption
    input  wire [14:0] plaintext,  // 3 letters x 5 bits
    input  wire [44:0] key,        // 3x3 matrix x 5 bits
    output reg  [14:0] ciphertext, // 3 letters x 5 bits
    output reg         done        // Encryption complete
);

    // FSM states
    localparam IDLE = 2'd0,
               MUL  = 2'd1,
               MODU = 2'd2,
               EMIT = 2'd3;

    reg [1:0] state;

    // Latched plaintext letters (P0 first)
    reg [4:0] p0, p1, p2;
    // Latched key matrix elements
    reg [4:0] k00, k01, k02, k10, k11, k12, k20, k21, k22;

    // Raw dot products (max ~3*25*25 -> fits in 16 bits)
    reg [15:0] s0, s1, s2;
    // Mod-26 results
    reg [4:0]  c0, c1, c2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            done       <= 1'b0;
            ciphertext <= 15'd0;
            s0 <= 16'd0; s1 <= 16'd0; s2 <= 16'd0;
            c0 <= 5'd0;  c1 <= 5'd0;  c2 <= 5'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Latch inputs
                        p0  <= plaintext[14:10];
                        p1  <= plaintext[9:5];
                        p2  <= plaintext[4:0];
                        k00 <= key[44:40]; k01 <= key[39:35]; k02 <= key[34:30];
                        k10 <= key[29:25]; k11 <= key[24:20]; k12 <= key[19:15];
                        k20 <= key[14:10]; k21 <= key[9:5];   k22 <= key[4:0];
                        state <= MUL;
                    end
                end
                MUL: begin
                    // Matrix multiply (row . plaintext vector)
                    s0 <= (k00 * p0) + (k01 * p1) + (k02 * p2);
                    s1 <= (k10 * p0) + (k11 * p1) + (k12 * p2);
                    s2 <= (k20 * p0) + (k21 * p1) + (k22 * p2);
                    state <= MODU;
                end
                MODU: begin
                    // Modulo 26
                    c0 <= s0 % 16'd26;
                    c1 <= s1 % 16'd26;
                    c2 <= s2 % 16'd26;
                    state <= EMIT;
                end
                EMIT: begin
                    // Assemble ciphertext, signal done
                    ciphertext <= {c0, c1, c2};
                    done       <= 1'b1;
                    state      <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

{"code": [{"rtl/manchester_decoder.sv": ""}, {"rtl/manchester_encoder.sv": "// Manchester encoder module
// Latch-inference fix: the original combinational always_comb left enc_data_out
// unassigned when enc_valid_in was low (only enc_valid_out was driven), inferring
// a latch that held stale encoded data.  The block is registered on clk_in with an
// active-high reset (matching the decoder) and EVERY branch drives both outputs to
// a defined value, so enc_data_out returns to all-zero whenever valid is deasserted.

module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,               // Clock input
    input  logic rst_in,               // Active high reset input
    input  logic enc_valid_in,         // Input valid signal
    input  logic [N-1:0] enc_data_in,  // N-bit input data
    output logic enc_valid_out,        // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    // Sequential logic to generate Manchester encoded data (no inferred latch:
    // reset, active, and idle branches each assign every output).
    always_ff @(posedge clk_in or posedge rst_in) begin
        if (rst_in) begin
            enc_data_out  <= '0;
            enc_valid_out <= 1'b0;
        end else if (enc_valid_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i]     <= 1'b1;
                    enc_data_out[2*i + 1] <= 1'b0;
                end else begin
                    enc_data_out[2*i]     <= 1'b0;
                    enc_data_out[2*i + 1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out  <= '0;   // defined idle value -> no latch, no stale data
            enc_valid_out <= 1'b0;
        end
    end

endmodule"}, {"rtl/top_manchester.sv": ""}]}

module pipelined_modified_booth_multiplier (
    input clk,
    input rst,
    input start,
    input signed [15:0] X,
    input signed [15:0] Y,
    output reg signed  [31:0] result,
    output reg done
);

    reg signed [31:0] partial_products [0:7];
    reg signed [15:0] X_reg, Y_reg;
    reg [4:0] valid_reg; // Extended valid register for more granular state control

    integer i;

    // Registers for pipelining the addition stages
    reg signed [31:0] s1, s2, s3, s4;
    reg signed [31:0] temp_products1, temp_products2;

    always @(posedge clk or posedge rst)
    begin
        if (rst)
        begin
            X_reg <= 16'd0;
            Y_reg <= 16'd0;
            valid_reg <= 5'd0;
            done <= 0;
            for (i = 0; i < 8; i = i + 1)
            begin
                partial_products[i] <= 32'd0;
            end
            s1 <= 0; s2 <= 0; s3 <= 0; s4 <= 0;
            temp_products1 <= 0; temp_products2 <= 0;
            result <= 32'd0;
            done <= 1'b0;
        end
        else
        begin
            if (start && !valid_reg[0]) begin
                X_reg <= X;
                Y_reg <= Y;
                valid_reg[0] <= 1;  // Initiate state 1
            end
            else
              valid_reg[0] <= 0;  // Initiate state 1

            // Process Booth multiplication
            if (valid_reg[0]) begin
                for (i = 0; i < 8; i = i + 1) begin
                    case ({Y_reg[2*i+1], Y_reg[2*i], (i == 0) ? 1'b0 : Y_reg[2*i-1]})
                        3'b000, 3'b111: partial_products[i] <= 32'd0;
                        3'b001, 3'b010: partial_products[i] <= {{16{X_reg[15]}}, X_reg} << (2*i);
                        3'b011: partial_products[i] <= {{16{X_reg[15]}}, X_reg} << (2*i + 1);
                        3'b100: partial_products[i] <= -({{16{X_reg[15]}}, X_reg} << (2*i + 1));
                        3'b101, 3'b110: partial_products[i] <= -({{16{X_reg[15]}}, X_reg} << (2*i));
                        default: partial_products[i] <= 32'd0;
                    endcase
                end
                valid_reg[1] <= 1; // State 1 done, mark State 2 as ready
                valid_reg[0] <= 0; // Reset state 1 active flag
            end
            else
              valid_reg[1] <= 0; // State 1 done, mark State 2 as ready

            // State 3: Partial Summation
            if (valid_reg[1]) begin
                s1 <= partial_products[0] + partial_products[1] + partial_products[2];
                s2 <= partial_products[3] + partial_products[4] + partial_products[5];

                valid_reg[2] <= 1; // State 3 done, mark State 4 as ready
                valid_reg[1] <= 0; // Clear state 2 active flag
            end
            else
              valid_reg[2] <= 0; // State 3 done, mark State 4 as ready

            // State 4: Sum of Sums
            if (valid_reg[2]) begin
                s3 <= s1 + s2;
                s4 <= partial_products[6] + partial_products[7];

                valid_reg[3] <= 1; // State 4 done, mark State 5 as ready
                valid_reg[2] <= 0; // Clear state 3 active flag
            end
            else
              valid_reg[3] <= 0; // State 4 done, mark State 5 as ready


            // State 5: Final Result
            if (valid_reg[3]) begin
                result <= s3 + s4;
                done <= 1;  // Output done signal
                valid_reg[3] <= 0; // Reset state 5 active flag after result computation
            end
            else
            begin
              result <= 0;
              done <= 1'b0;
            end

        end
    end

endmodule

module restoring_division #(
    parameter WIDTH = 6
)(
    input  wire             clk,
    input  wire             rst,       // active-low asynchronous reset
    input  wire             start,
    input  wire [WIDTH-1:0] dividend,
    input  wire [WIDTH-1:0] divisor,
    output reg  [WIDTH-1:0] quotient,
    output reg  [WIDTH-1:0] remainder,
    output reg              valid
);

    localparam CW = $clog2(WIDTH+1);

    reg              busy;
    reg [WIDTH-1:0]  dvd;        // dividend shift register (MSB first)
    reg [WIDTH-1:0]  dsr;        // latched divisor
    reg [WIDTH:0]    rem_reg;    // (WIDTH+1)-bit partial remainder
    reg [WIDTH-1:0]  quo;        // quotient accumulator
    reg [CW-1:0]     count;

    // Combinational datapath for the current iteration.
    // Shift the partial remainder left by one and bring in the next MSB of the
    // dividend, then trial-subtract the zero-extended divisor. The extra MSB of
    // the (WIDTH+1)-bit subtraction is the borrow/sign bit: 0 => divisor fits.
    wire [WIDTH:0] rem_shift = {rem_reg[WIDTH-1:0], dvd[WIDTH-1]};
    wire [WIDTH:0] sub       = rem_shift - {1'b0, dsr};
    wire           fit       = ~sub[WIDTH];

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            valid     <= 1'b0;
            busy      <= 1'b0;
            quotient  <= {WIDTH{1'b0}};
            remainder <= {WIDTH{1'b0}};
            rem_reg   <= {(WIDTH+1){1'b0}};
            quo       <= {WIDTH{1'b0}};
            dvd       <= {WIDTH{1'b0}};
            dsr       <= {WIDTH{1'b0}};
            count     <= {CW{1'b0}};
        end else begin
            valid <= 1'b0;                       // one-cycle strobe by default
            if (!busy) begin
                if (start) begin
                    busy    <= 1'b1;
                    dvd     <= dividend;
                    dsr     <= divisor;
                    rem_reg <= {(WIDTH+1){1'b0}};
                    quo     <= {WIDTH{1'b0}};
                    count   <= {CW{1'b0}};
                end
            end else begin
                // one restoring-division iteration
                if (fit) begin
                    rem_reg <= sub;
                    quo     <= {quo[WIDTH-2:0], 1'b1};
                end else begin
                    rem_reg <= rem_shift;
                    quo     <= {quo[WIDTH-2:0], 1'b0};
                end
                dvd   <= {dvd[WIDTH-2:0], 1'b0};   // advance to next dividend bit
                count <= count + 1'b1;

                if (count == WIDTH-1) begin
                    // final iteration: present the FRESH combinational result the
                    // same cycle valid asserts (so a checker sampling on valid
                    // reads the true quotient/remainder, not a stale copy).
                    busy      <= 1'b0;
                    valid     <= 1'b1;
                    quotient  <= fit ? {quo[WIDTH-2:0], 1'b1}
                                     : {quo[WIDTH-2:0], 1'b0};
                    remainder <= fit ? sub[WIDTH-1:0] : rem_shift[WIDTH-1:0];
                end
            end
        end
    end

endmodule

module run_length
#(
    parameter DATA_WIDTH = 8                        // Width of the output run-length counter
)
(
    input wire clk,                                 // Clock signal
    input wire reset_n,                             // Active-low reset signal
    input wire data_in,                             // Input data stream
    output reg  data_out,                           // Output data to indicate the previous data_in
    output reg [$clog2(DATA_WIDTH):0] run_value,    // Output the run length value
    output reg valid                                // Output valid flag for run length

);
    reg [$clog2(DATA_WIDTH):0] run_length;
    reg prev_data_in;


    // Run-length counting / run_value / previous-input tracking
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            run_length   <= 'b0;
            run_value    <= 'b0;
            prev_data_in <= 1'b0;
        end
        else begin
            prev_data_in <= data_in;

            if (data_in == prev_data_in) begin
                // consecutive identical bit
                if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                    // saturated at DATA_WIDTH : emit the run and restart at 1
                    run_value  <= run_length;
                    run_length <= 1'b1;
                end
                else begin
                    run_length <= run_length + 1'b1;
                end
            end
            else begin
                // transition detected : output the length of the run that just ended
                run_value  <= run_length;
                run_length <= 1'b1;
            end
        end
    end


    // valid pulse and data_out (previous input) generation
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            valid    <= 1'b0;
            data_out <= 1'b0;
        end
        else begin
            if (data_in != prev_data_in) begin
                // new value differs from previous : publish previous value and pulse valid
                data_out <= prev_data_in;
                valid    <= 1'b1;
            end
            else if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                // run reached the maximum length : pulse valid
                valid    <= 1'b1;
            end
            else begin
                valid    <= 1'b0;
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,
    parameter WIDTH = 8
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);
    localparam IDLE = 2'd0,
               LOAD = 2'd1,
               SORT = 2'd2,
               DONE = 2'd3;

    reg [1:0]  state, next_state;
    reg [WIDTH-1:0] data_array [0:N-1];
    reg [$clog2(N+1)-1:0] pass_cnt;
    reg [$clog2(N/2+1)-1:0] pair_idx;

    wire [$clog2(N/2+1)-1:0] pairs_in_this_pass;
    assign pairs_in_this_pass = (pass_cnt[0] == 1'b0) ? (N/2) : ( (N/2) > 0 ? (N/2) - 1 : 0 );

   //Insert code here to implement the Brick Sort Algorithm
    integer i;
    integer base;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            done     <= 1'b0;
            pass_cnt <= 0;
            pair_idx <= 0;
            // out_data intentionally left uninitialized at reset
        end else begin
            case (state)
                //--------------------------------------------------
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                //--------------------------------------------------
                LOAD: begin
                    for (i = 0; i < N; i = i + 1) begin
                        data_array[i] <= in_data[i*WIDTH +: WIDTH];
                    end
                    pass_cnt <= 0;
                    pair_idx <= 0;
                    state    <= SORT;
                end

                //--------------------------------------------------
                // One compare-and-swap per clock cycle.
                //   even pass : compare (0,1),(2,3),...  base = 2*pair_idx
                //   odd  pass : compare (1,2),(3,4),...  base = 2*pair_idx+1
                // After N passes (pass_cnt reaches N) spend one extra cycle
                // transitioning to DONE, matching latency = N*(N-1)/2 + 4.
                //--------------------------------------------------
                SORT: begin
                    if (pass_cnt == N) begin
                        state <= DONE;               // transition-to-DONE cycle
                    end else if (pairs_in_this_pass == 0) begin
                        // empty pass (only for very small N): advance without compare
                        pair_idx <= 0;
                        pass_cnt <= pass_cnt + 1'b1;
                    end else begin
                        base = (pass_cnt[0] == 1'b0) ? (pair_idx << 1)
                                                     : ((pair_idx << 1) + 1);
                        if (data_array[base] > data_array[base+1]) begin
                            data_array[base]   <= data_array[base+1];
                            data_array[base+1] <= data_array[base];
                        end

                        if (pair_idx == pairs_in_this_pass - 1) begin
                            pair_idx <= 0;
                            pass_cnt <= pass_cnt + 1'b1;
                        end else begin
                            pair_idx <= pair_idx + 1'b1;
                        end
                    end
                end

                //--------------------------------------------------
                DONE: begin
                    for (i = 0; i < N; i = i + 1) begin
                        out_data[i*WIDTH +: WIDTH] <= data_array[i];
                    end
                    done  <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end


  // power-up determinism (rtl_hygiene_lint --fix): reset-less registered
  // outputs default to 0 so they are not X at t=0.
  initial begin
    out_data = 0;
  end

endmodule

module ttc_counter_lite (
    input             clk,
    input             reset,        // active-high synchronous reset
    input      [3:0]  axi_addr,
    input      [31:0] axi_wdata,
    input             axi_write_en,
    input             axi_read_en,
    output reg [31:0] axi_rdata,
    output reg        interrupt
);

    // Register-map addresses
    localparam ADDR_COUNT   = 4'h0;
    localparam ADDR_MATCH   = 4'h1;
    localparam ADDR_RELOAD  = 4'h2;
    localparam ADDR_CONTROL = 4'h3;
    localparam ADDR_STATUS  = 4'h4;

    reg [15:0] count;
    reg [15:0] match_value;
    reg [15:0] reload_value;
    reg        enable;
    reg        interval_mode;
    reg        interrupt_enable;

    always @(posedge clk) begin
        if (reset) begin
            count            <= 16'h0;
            match_value      <= 16'h0;
            reload_value     <= 16'h0;
            enable           <= 1'b0;
            interval_mode    <= 1'b0;
            interrupt_enable <= 1'b0;
            interrupt        <= 1'b0;
        end else begin
            // Counter + match/interrupt generation
            if (enable) begin
                if (count == match_value) begin
                    if (interval_mode)
                        count <= reload_value;      // interval: reload on match
                    else
                        count <= match_value;       // non-interval: hold at match
                    if (interrupt_enable)
                        interrupt <= 1'b1;
                end else begin
                    count <= count + 16'h1;
                end
            end

            // Register writes (a status-register write clears the interrupt
            // and takes priority over a same-cycle match set).
            if (axi_write_en) begin
                case (axi_addr)
                    ADDR_MATCH:   match_value  <= axi_wdata[15:0];
                    ADDR_RELOAD:  reload_value <= axi_wdata[15:0];
                    ADDR_CONTROL: begin
                        enable           <= axi_wdata[0];
                        interval_mode    <= axi_wdata[1];
                        interrupt_enable <= axi_wdata[2];
                    end
                    ADDR_STATUS:  interrupt   <= 1'b0;   // write-to-clear
                    default: ;
                endcase
            end
        end
    end

    // AXI-Lite read data (combinational)
    always @(*) begin
        case (axi_addr)
            ADDR_COUNT:   axi_rdata = {16'h0, count};
            ADDR_MATCH:   axi_rdata = {16'h0, match_value};
            ADDR_RELOAD:  axi_rdata = {16'h0, reload_value};
            ADDR_CONTROL: axi_rdata = {29'h0, interrupt_enable, interval_mode, enable};
            ADDR_STATUS:  axi_rdata = {31'h0, interrupt};
            default:      axi_rdata = 32'h0;
        endcase
    end

endmodule
